\section{Formal setup and problem statement}\label{sec:preliminaries}

Throughout the paper, all fields are assumed to be of characteristic zero.

\begin{Definition}[Resultant]
    Let $f_1, \ldots, f_n \in \mathbb{K}[\bx]$ be $n$ homogeneous polynomials in $\bx = (x_1, \ldots, x_n)$.
    By $\Res_{\bx}(f_1, \ldots, f_n)$ we will denote the \emph{resultant} of $f_1, \ldots, f_n$ with respect to $\bx$, that is, the unique (up to a constant factor) irreducible polynomial in the coefficients of $f_1, \ldots, f_n$ with the property
    \[
      \Res_{\bx}(f_1, \ldots, f_n) = 0 \quad \iff \quad \exists \bx^\ast \in \overline{\mathbb{K}}^n\colon \bx^\ast \neq \mathbf{0} \;\&\; f_1(\bx^\ast) = \ldots = f_n(\bx^\ast) = 0,
    \]
    where $\overline{\mathbb{K}}$ denotes the algebraic closure of $\mathbb{K}$.
    For the existence and basic properties of the resultant, we refer to~\cite[Chapter~3, \S2]{CLO}.
\end{Definition}

We will typically compute resultants for polynomials $f_1, \ldots, f_n \in \mathbb{K}[\bx, \by]$ homogeneous with respect to $\bx = (x_1, \ldots, x_n)$ but not necessarily with respect to $\by = (y_1, \ldots, y_m)$ (in other words, $f_1, \ldots, f_n$ are regular functions on $\mathbb{P}^{n - 1} \times \mathbb{A}^m$).
In this case, $\Res_{\bx}(f_1, \ldots, f_n)$ is a polynomial in $\by$ defining the image of the projection of $V(f_1, \ldots, f_n) \subset \mathbb{P}^{n - 1} \times \mathbb{A}^m$ to $\mathbb{A}^m$.

Now we will formally define the ``symbolic perturbaion'' of the resultant we described informally in the introduction.
This particular construction extends the generalized characteristic polynomial introduced by~\cite{Canny90} and can be viewed as a specialization of the toric generalized characteristic polynomial introduced by~\cite{Rojas1999}.

\begin{Definition}[Generalized characteristic polynomial]\label{def:canny}
    Consider polynomials $f_1, \ldots, f_n \in \mathbb{K}[\bx, \by]$ homogeneous with respect to $\bx = (x_1, \ldots, x_n)$.
    We define $d_i := \deg_{\bx} f_i$ for every $1 \leqslant i \leqslant n$ and introduce an extra variable $\varepsilon$.
    Let $\bp \in (\mathbb{K}[\bx])^n$ be a vector \Ra{of} homogeneous polynomials with $\deg_{\bx} p_i = d_i$ for $1 \leqslant i \leqslant n$ such that the only solution of the system $\bp = \mathbf{0}$ over $\overline{\mathbb{K}}$ is $\mathbf{0}$ (we will call such vector \emph{admissible}).
    We set $\widetilde{f}_i := f_i + \varepsilon p_i$ for $1 \leqslant i \leqslant n$.

    Then there exist~\cite[Theorem~2.4]{Rojas1999} a nonnegative integer $s$ and nonzero polynomial $R_s(\by) \in \mathbb{K}[\by]$ such that
    \[
    \Res_\bx(\widetilde{f}_1, \ldots, \widetilde{f}_n) = R_s(\mathbf{y}) \varepsilon^s + \mathcal{O}(\varepsilon^{s + 1}).
    \]
    We will call $R_s(\by)$ the \emph{generalized characteristic polynomial} and denote it by $\CRes_{\bx, \bp}(f_1, \ldots, f_n)$.
\end{Definition}

Let $X := V_{\overline{\mathbb{K}}}(f_1, \ldots, f_n)$ be the zero set of $f_1 = \ldots = f_n = 0$ over $\overline{\KK}$ and consider the projection $\pi \colon \mathbb{P}^{n - 1}_{\overline{\mathbb{K}}} \times \mathbb{A}^m_{\overline{\mathbb{K}}} \to \mathbb{A}^m_{\overline{\mathbb{K}}}$.
A component $C$ of $X$ of the lowest possible dimension $m - 1$ will be called \emph{proper}, other components will be called \emph{excess} components.
The key property of the generalized characteristic polynomial (see~\citep[Theorem~3.2]{Canny90} and~\citep[Theorem~2.4]{Rojas1999}) is the following.
\begin{Proposition}\label{prop:key_prop}
    In the notation above, let $C \subset X$ be a proper component.
    Then $\CRes_{\bx, \bp}(f_1, \ldots, f_n)$ vanishes on $\pi(C)$ for every admissible $\bp$.
\end{Proposition}


\begin{Example}
    We will revisit the system~\eqref{eq:intro_ex}. 
    Replacing $f_1$ and $f_2$ with their homogenizations {\Ra{with respect to}} $x$, we obtain:
    \[
    f_1 := x_1^2 - x_2^2 y^2 + x_1 x_2 - x_2^2y, \quad f_2 := 2 x_1^2 - x_1x_2y - x_2^2y^2.
    \]
    Taking $\bp = (x_1^2, x_2^2)$, we will obtain $\widetilde{f}_1 = f_1 + \varepsilon x_1^2,\; \widetilde{f}_2 = f_2 + \varepsilon x_2^2$ which are exactly the $\widetilde{f}_1$ and $\widetilde{f}_2$ from~\eqref{eq:preturb} after homogenization.
    Therefore, by~\eqref{eq:res1}, we have 
    \[
    \CRes_{\bx, \bp}(f_1, f_2) = -3 y^4 - 6 y^3 + 2 y^2 + 5 y + 2.
    \]
    Likewise, if we consider $\bp = ((x_ 1 + x_2)^2, (x_1 - x_2)^2)$, then we will obtain the homogenizations of $\hat{f}_1$ and $\hat{f}_2$ from~\eqref{eq:perturbed_hat} and, thus, obtain
    \[
    \CRes_{\bx, \bp}(f_1, f_2) = -y^4 - 11 y^3 - 21 y^2 - 5 y + 2.
    \]
\end{Example}

The following lemma formalizes the idea of taking the GCD of two generic GCP's.

\begin{Lemma}\label{lem:double_pert}
    Consider polynomials $f_1, \ldots, f_n \in \mathbb{K}[\bx, \by]$ homogeneous with respect to $\bx = (x_1, \ldots, x_n)$, and denote $d_i = \deg_{\bx}f_i$ for $1 \leqslant i \leqslant n$.
    Let $\Ra{\mathcal{P}}$ be the space of all vectors $\bp \in (\mathbb{K}[\bx])^n$ of homogeneous polynomials with $\deg p_i = d_i$.
    There exists a nonempty Zariski open subset $U \subset \Ra{\mathcal{P}}\times \Ra{\mathcal{P}}$ and a polynomial $R(\by) \in \mathbb{K}[\by]$ such that, for every $(\bp, \bq) \in U$, we have:
    \[
    \operatorname{GCD}(\CRes_{\bx, \bp}(f_1, \ldots, f_n), \; \CRes_{\bx, \bq}(f_1, \ldots, f_n)) = R(\by).
    \]
\end{Lemma}

\begin{proof}
    We introduce two sets of indeterminates $\ba_1$ and $\ba_2$, of cardinality $\dim \Ra{\mathcal{P}}$ each.
    We choose a basis in $\Ra{\mathcal{P}}$, and let $\bp_1$ and $\bp_2$ be vectors of homogeneous polynomials in $(\KK(\ba_1, \ba_2)[\bx])^n$ with $\deg_\bx p_{1, i} = \deg_{\bx} p_{2, i} = d_i$ for every $1 \leqslant i \leqslant n$ with the coordinates in the chosen bases being $\ba_1$ and $\ba_2$, respectively.
    Let $R_1(\ba_1, \by) \in \KK[\ba_1, \by]$ the the lowest $\varepsilon$-degree term in
    $\Res_{\bx}(f_1 + \varepsilon p_{1, 1}, \ldots, f_n + \varepsilon p_{1, n})$.
    Then $R_1(\ba_2, \by) \in \KK[\ba_2, \by]$ is the analogous term in $\Res_{\bx}(f_1 + \varepsilon p_{2, 1}, \ldots, f_n + \varepsilon p_{2, n})$.
    Let $R_0 = \operatorname{GCD}(R(\ba_1, \by), R(\ba_2, \by))$.
    Then $R_0 \in \KK[\by]$, so, 
    for every specialization of $\ba_1$ and $\ba_2$ in $\KK$ such that none of $R_1(\ba_1, \by)$ and $R_1(\ba_2, \by)$ becomes identically zero, the GCD of the specializations is divisible by $R_0$.
    Consider the points $(\ba_1^\ast, \ba_2^\ast) \in \Ra{\mathcal{P}} \times \Ra{\mathcal{P}}$ such that 
    \[
    R_1(\ba_1^\ast, \by)R_1(\ba_2^\ast, \by) \neq 0 \quad \text{ and } \deg_{\by} \operatorname{GCD}(R_1(\ba_1^\ast, \by),\; R_1(\ba_2^\ast, \by)) = \deg_{\by} R_0.
    \]
    Since these conditions can be described by inequations (for the latter, e.g., by setting the intermediate results in the Euclidean algorithm to be nonzero), one can verify that this set contains an open nonempty subset $U \subset \Ra{\mathcal{P}}\times \Ra{\mathcal{P}}$.
    Therefore, we can take $R(\by) = R_0(\by)$ and this $U$.
\end{proof}

Lemma~\ref{lem:double_pert} motivates the following main definition of this paper (which can be viewed as a specialization of the \emph{double toric perturbation} introduced by~\cite{Rojas1999}).

\begin{Definition}[Perturbed resultant]
    In the notation of Lemma~\ref{lem:double_pert}, the polynomial $R(\by)$ will be called \emph{the perturbed resultant} of $f_1, \ldots, f_n$ with respect to $\bx$ and denoted by $\PRes_{\bx}(f_1, \ldots, f_n)$.
\end{Definition}

\begin{Remark}[Computing perturbed resultant]\label{rem:computation}
    Based on the proof of Lemma~\ref{lem:double_pert}, one way to compute $\PRes$ is to compute $\CRes$ with $\bp$ being a vector of polynomials with undetermined coefficients, and then take the factors with coefficients in the ground field $\KK$.
    We used this approach for the examples in Section~\ref{sec:examples}.
    In practice, one can take two random $\bp$'s and compute the GCD as in Lemma~\ref{lem:double_pert}.
    Probability analysis of such an approach is beyond the scope of the present paper.
\end{Remark}

Proposition~\ref{prop:key_prop} implies that the perturbed resultant vanishes on the projection of every proper component whose projection has the same dimension.
One may expect that the zero set of the perturbed resultant will be exactly the union of projections of proper components (see~\cite[Section~5.7]{Rojas1999}).
The examples from Section~\ref{sec:examples} show that the situation is more subtle.
Therefore, the \textbf{main question} studied in this paper is:

\begin{quote}
    \emph{What can be said about the zero set of the perturbed resultant in terms of the zero set of the original system?}
\end{quote}

\section{Main results}\label{sec:results}

The following theorem says that the perturbed resultant may vanish at a point $P$ only in three cases:
\begin{itemize}
    \item $P$ belongs to a projection of a proper component;
    \item one of the preimages of $P$ is a singularity (see Examples~\ref{ex:embedded} and~\ref{ex:twisted});
    \item the preimage of $P$ is infinite (see Examples~\ref{ex:positive}~\Ra{and~\ref{ex:positive2}}).
\end{itemize}

\begin{Theorem}\label{thm:main}
    Consider polynomials $f_1, \ldots, f_n \in \mathbb{K}[\bx, \by]$  in variables $\bx = (x_1, \ldots, x_n)$ and $\by = (y_1, \ldots, y_m)$ homogeneous with respect to $\bx$ such that $\deg_{\bx}f_i > 0$ for every $1 \leqslant i \leqslant n$.
    Let $X$ be the scheme defined by $f_1, \ldots, f_n$ in $\PP^{n - 1}_{\overline{\KK}} \times \AAA^m_{\overline{\KK}}$, and we define $\pi \colon \PP^{n - 1}_{\overline{\KK}} \times \AAA^m_{\overline{\KK}} \to \AAA^m_{\overline{\KK}}$, the canonical projection.

    \Rb{Consider a point $P \in \AAA^m_{\overline{\KK}}$ such that
    \begin{enumerate}
        \item $\pi^{-1}(P) \cap X$ is finite and
        \item for every point $Q \in \pi^{-1}(P) \cap X$, $Q$ is a smooth point of a component of $X$ of dimension~$\geqslant m$.
    \end{enumerate}
    }
    Then $\PRes_{\bx}(f_1, \ldots, f_n)$ does not vanish at $P$.
\end{Theorem}

Furthermore, we provide a complete description of the zeroes of $\PRes_{\bx}(f_1, f_2)$ for the simplest case $n = 2$ and $m = 1$.

\begin{Proposition}\label{prop:planar}
    Consider $f_1, f_2 \in \KK[x_1, x_2, y]$ homogeneous with respect to $x_1, x_2$.
    We write $f_1 = g h_1$ and $f_2 = g h_2$, where $g = \operatorname{GCD}(f_1, f_2)$.
    Then $\PRes_{\bx}(f_1, f_2)$ vanishes at $y^\ast \in \overline{\KK}$ if an only if:
    \begin{itemize}
        \item $y^\ast$ is a $y$-coordinate of a solution of $h_1 = h_2 = 0$;
        \item $g$ is divisible by $y - y^\ast$ \Ra{over $\overline{\KK}$}.
    \end{itemize}
\end{Proposition}

\section{Examples}\label{sec:examples}

The computations for the examples below were carried out using the {\sc Resultants} package by~\cite{Staglian2018} in {\sc Macaulay2}~\citep{M2}. 
\Ra{The package computes multivariate resultant by induction in the number of variabes using the Poisson product formula~\cite[Section~1]{Staglian2018}.}

\begin{Example}[Proper embedded component]\label{ex:embedded}
    Let $n = 2$ and $m = 1$, and take 
    \[
    f_1 = x_1 (x_1 + x_2 y), \quad f_2 = x_1 (x_1 - x_2 y).
    \]
    The zero set $V(f_1, f_2)$ is the line $x_1 = 0$ but the ideal generated by $f_1, f_2$ has an embedded component (double point) at the origin (i.e., point $([0:1], 0)$).
    As described in Remark~\ref{rem:computation}, we compute that $\PRes_{\bx}(f_1, f_2) = y^2$, so the projection of the embedded component is in the zero set of the perturbed resultant.
    This agrees with Proposition~\ref{prop:planar}.
\end{Example}

\begin{Example}[Excess component with non-dominant projection]\label{ex:positive}
    Let $n = 2$, $m = 1$, and $f_1 = f_2 = x_1 y$.
    In this case the variety $V(f_1, f_2)$ will consist of two one-dimensional components $x_1 = 0$ and $y = 0$. 
    However, note that the latter has zero-dimensional image under the projection to the $y$-component.
    As described in Remark~\ref{rem:computation}, we compute $\PRes_{\bx}(f_1, f_2) = y$, and see that the projection of the excess component $y = 0$ is indeed in the zero set of $\PRes$.
    This agrees with Proposition~\ref{prop:planar}.
\end{Example}

\Ra{
\begin{Example}[Excess component with non-dominant projection]\label{ex:positive2}
    Consider the case $n = 3$ and $m = 1$ and take
    \[
    f_1 = yx_1 + x_2 + x_3,\quad f_2 = x_1 + yx_2 + x_3, \quad f_3 = x_1 + x_2 + y x_3.
    \]
    The zero set $V(f_1, f_2, f_3)$ consists of two components: a point $([1:1:1], -2)$ and a line $([a:b:-a-b], 1)$.
    Computing the perturbed resultant, we get
    \[
    \PRes_{\bx}(f_1, f_2, f_3) = (y - 1)^2(y + 2).
    \]
    Therefore, the excess component (the line) with non-dominant projection contributes to the zero set of $\PRes$.
\end{Example}}

\begin{Example}[Singularity, persistent]\label{ex:twisted}
    Let $n = 3$ and $m = 1$.
    We start with a rational curve in $\AAA^3$ parametrized by $s \to (s^3, s^4, s^5)$ in the coordinates $(y, x_1, x_2)$.
    Then we homogenize this curve with respect to $x_1, x_2$, and obtain a curve in $\PP^2\times \AAA$ defined by:
    \begin{equation}\label{eq:twisted}
    f_1 = x_3^2 y^3 - x_1 x_2,\quad f_2 = x_1^2 - x_2 x_3 y, \quad f_3 = x_2^2 - x_1 x_3 y^2.
    \end{equation}
    These three polynomials define a prime ideal of a curve which projects dominantly on the $y$-coordinate.
    However, this curve has a singularity at the origin (i.e., the point $([0:0:1], 0)$) where it is not a locally complete intersection.
    We compute $\PRes_{\bx}(f_1, f_2, f_3)$ as described in Remark~\ref{rem:computation}, and obtain 
    \[
    \PRes_{\bx}(f_1, f_2, f_3) = y.
    \]
    Note that the fact that $\PRes_\bx(f_1, f_2, f_3)$ may only vanish at $y = 0$ follows from Theorem~\ref{thm:main}.
\end{Example}

\begin{Example}[Singularity, not persistent]\label{ex:sing_not_pers}
   Let us show that not all the singularities yield persistent components.
   We consider the case $n = 2, m = 1$ and
   \[
   f_1 = f_2 = x_2^2 y^3 - x_1^2.
   \]
   The variety $V(f_1, f_2)$ is a curve with a singularity at $([0:1], 0)$.
   However, direct computation, as described in Remark~\ref{rem:computation}, shows that $\PRes_{\bx}(f_1, f_2) = 1$ (this could also be deduced from Proposition~\ref{prop:planar}), so the singularity is not reflected in the perturbed resultant.
   We think that the main difference between this example and Example~\ref{ex:twisted} is that in the latter, the curve is not a locally complete intersection at the singularity. This property forces all the syzygies of~\eqref{eq:twisted} to vanish at the singular point \Rb{(see Remark~\ref{rem:Sp} for further details)}.
\end{Example}

\Ra{
\begin{Example}[Singularity, not persistent]
    The previous example featured a curve with a cusp singularity, here we will consider a space curve with a self-intersection.
    We take $n = 3, m = 1$ and
    \[
    f_1 = x_1^2 + x_2^2 - x_3^2(1 - y^2), \quad f_2 = x_1^2 + x_2^2 - x_1 x_3, \quad f_3 = f_1 + f_2.
    \]
    These equations define a curve with a self-intersection at $([1:0:1], 0)$ but this point does not make a contribution to the zero set of the perturbed resultant: direct computation shows that $\PRes_{\bx}(f_1, f_2, f_3) = 1$.
\end{Example}}


