\section{Proofs}\label{sec:proofs}
In this section all the varieties will be considered over the algebraic closure $\overline{\KK}$ of $\KK$ and $\PP$ and $\AAA$ will always mean $\PP_{\overline{\KK}}$ and $\AAA_{\overline{\KK}}$.
Throughout the section, we fix 
\begin{itemize}
    \item two sets of variables $\bx = (x_1, \ldots, x_n)$ and $\by = (y_1, \ldots, y_m)$;
    \item subalgebra $R \subset \KK[\bx, \by]$ of polynomials homogeneous {\Ra{with respect to}} $\bx$;
    \item the canonical projection $\pi\colon \PP^{n - 1}\times \AAA^m \to \AAA^m$ induced by the embedding $\KK[\by] \subset R$;
    \item polynomials $f_1, \ldots, f_n \in R$ with degrees $d_i := \deg_{\bx} f_i$, and we will assume that $d_1, \ldots, d_n$ are positive;
    \item space $\Ra{\mathcal{P}}$ of all vectors $\bp \in (\KK[\bx])^n$ of homogeneous polynomials with $\deg_\bx p_i = d_i$ for $1 \leqslant i \leqslant n$.
\end{itemize}
Our study of the perturbed resultant $\PRes_{\bx}(f_1, \ldots, f_n)$ will proceed via perturbing the whole variety $X := V(f_1, \ldots, f_n)$ defined by $f_1, \ldots, f_n$.
More precisely, let $\bp \in \Ra{\mathcal{P}}$ be an admissible vector of homogeneous polynomials.
As in Definition~\ref{def:canny}, we set $f_{i, \bp} := f_i + \varepsilon p_i$ for $1 \leqslant i \leqslant n$.
Consider the variety 
\[
\widetilde{X}_{\bp} := V(f_{1, \bp}, \ldots, f_{n, \bp}) \subset \PP^{n - 1} \times \AAA^m \times \AAA.
\]
It has a decomposition $\widetilde{X}_{\bp} = Y_{\bp} \cup Z_{\bp}$, where $Y_{\bp}$ is the union of all components of $\widetilde{X}_{\bp}$ contained in $\{ \varepsilon = 0\}$, 
and $Z_{\bp}$ is the union of the remaining components.
We define the perturbed variety $X_{\bp} \subset \PP^{n - 1} \times \AAA^m$ as $Z_{\bp} \cap \{ \varepsilon = 0 \}$.
The following lemma justifies the relevance of this construction to our problem.

\begin{Lemma}\label{lem:Xp}	
    For every $\bp \in \Ra{\mathcal{P}}$, $\pi(X_{\bp}) = V\left( \CRes_{\bx, \bp}(f_1, \ldots, f_n) \right)$.
\end{Lemma}

\begin{proof}
	Let $\widetilde{\pi} \colon \PP^{n - 1} \times \AAA^m \times \AAA  \to \AAA^m \times \AAA$ be the canonical projection.
	From the general property of the resultant, we know that 
    \[
    \widetilde{\pi} \left( \widetilde{X}_{\bp} \right) = V\left( \Res_{\mathbf{x}} (f_{1, \bp}, \ldots, f_{n, \bp}) \right).
    \]
    \Rb{Furthermore, we have $\widetilde{\pi}(\widetilde{X}_{\bp}) = \widetilde{\pi}(Y_\bp \cup Z_{\bp}) = \widetilde{\pi}(Y_{\bp}) \cup \widetilde{\pi}(Z_{\bp})$.
    We factorize
    \[
    \Res_{\bx}(f_{1, \bp}, \ldots, f_{n, \bp}) = \varepsilon^s (\CRes_{\bx, \bp}(f_1, \ldots, f_n) + \mathrm{o}(\varepsilon)).
    \]
    Since $\widetilde{\pi}(Y_{\bp}) \subset V(\varepsilon)$ and none of the components of $\widetilde{\pi}(Z_{\bp})$ belongs to $V(\varepsilon)$, we have
    \[
    \widetilde{\pi}(Z_{\bp}) = V(\CRes_{\bx, \bp}(f_1, \ldots, f_n) + \mathrm{o}(\varepsilon)).
    \]
    Since $\widetilde{\pi}(X_{\bp}) = \widetilde{\pi}(Z_{\bp} \cap \{\varepsilon = 0\}) = \widetilde{\pi}(Z_{\bp}) \cap \{\varepsilon = 0\}$, we have
    \[
    \widetilde{\pi}(X_{\bp}) = V(\varepsilon, \CRes_{\bx, \bp}(f_1, \ldots, f_n) + \mathrm{o}(\varepsilon)) = V(\varepsilon, \CRes_{\bx, \bp}(f_1, \ldots, f_n)).
    \]
    Therefore, $\pi(X_{\bp}) = V(\CRes_{\bx, \bp}(f_1, \ldots, f_n))$.}
    % We note that $I(Z_{\bp}) = I(\widetilde{X}_{\bp}) \colon \varepsilon^\infty$.
    % Since saturation and elimination commute, we have
    % \[
    % \widetilde{\pi}\left( Z_{\bp}  \right) = V\left( \Res_{\mathbf{x}} (f_{1, \bp}, \ldots, f_{n, \bp}) \colon \varepsilon^\infty \right).
    % \]
    % Furthermore, $I(X_\bp) = R \cap (I(Z_\bp) + (\varepsilon))$.
    % Since intersection and projection commute, we have
    % \[
    % \pi(X_\bp) = V\left( \KK[\by] \cap ( (\Res_{\mathbf{x}} (f_{1, \bp}, \ldots, f_{n, \bp}) \colon \varepsilon^\infty) + (\varepsilon) \right).
    % \]
    % Since, for every polynomial $P \in R[\varepsilon]$, $(P \colon \varepsilon^\infty) + (\varepsilon)$ is generated by $\varepsilon$ and the lowest term of $P$ with respect to $\varepsilon$, we obtain
    % \[
    % \pi(X_\bp) = V\left( \CRes_{\mathbf{x}, \bp} (f_{1}, \ldots, f_{n}) \right).\qedhere
    % \]
\end{proof}

Now we can concentrate on studying $X_{\bp}$.
For any admissible $\bp \in (\KK[\bx])^n$, we define
\[
S_{\bp} := \{ g_1p_1 + \ldots + g_n p_n \mid (g_1, \ldots, g_n) \in \operatorname{Syz}(f_1, \ldots, f_n) \},
\]
where $\operatorname{Syz}(f_1, \ldots, f_n)$ denotes the module of syzygies of $f_1, \ldots, f_n$.

\begin{Lemma}\label{lem:syzygy}
    In the notation above, $X_{\bp} \subset V(f_1, \ldots, f_n, S_{\bp})$.
    Furthermore, if none of the components of $V(S_{\bp})$ is contained in $V(f_1, \ldots, f_n)$, then $X_{\bp} = V(f_1, \ldots, f_n, S_{\bp})$.
\end{Lemma}

\begin{Remark}\label{rem:Sp}
    We did not find an example in which a component of $V(S_{\bp})$ would be contained in $V(f_1, \ldots, f_n)$ for generic $\bp$, so we conjecture that this never happens.
    Being established, this would allow to strengthen our main result \Rb{as follows}.
    \Rb{At generic $\bp$, we would have $X_{\bp} = V(f_1, \ldots, f_n, S_{\bp})$, so taking sufficiently many generic $\bp$'s, $X_{\bp_1}\cap \ldots \cap X_{\bp_\ell}$ will be exactly the locus of $V(f_1, \ldots, f_n)$ where all the components of all syzygies vanish.
    This would allow to rule out some of the singularities (for example, as in Example~\ref{ex:sing_not_pers}).}
\end{Remark}

\begin{proof}[Proof of Lemma~\ref{lem:syzygy}]
    Throughout the proof, for a point $P \in \PP^{n - 1} \times \AAA^m$ and a scalar $\alpha \in \KK$, we will denote by $(P, \alpha)$ the point $\PP^{n - 1} \times \AAA^m \times \AAA$ with the $\varepsilon$-coordinate equal to $\alpha$.

    By the construction of $X_\bp$, we have $X_{\bp} \subset V(f_1, \ldots, f_n)$.
    We will now show that $X_{\bp} \subset V(S_{\bp})$.
    Consider a point $P \in X_{\bp}$.
    By definition of $X_{\bp}$ and $Z_{\bp}$, there exists an algebraic curve $\mathcal{C} \subset Z_{\bp}$ such that $P \in \mathcal{C}$ and $\mathcal{C}$ does not belong to $\{\varepsilon = 0\}$.
    Let $(g_1, \ldots, g_n)$ be any syzygy of $(f_1, \ldots, f_n)$.
    Then
    \[
    I(Z_{\bp}) \ni g_1 f_{1, {\bp}} + \ldots + g_n f_{n, \bp} = \varepsilon(g_1 p_1 + \ldots + g_n p_n).
    \]
    Since $\varepsilon$ is not identically zero on $\mathcal{C}$, the polynomial $g_1 p_1 + \ldots + g_n p_n$ vanishes on $\mathcal{C}$ and, thus, it vanishes at $P$.
    Therefore, $X_{\bp} \subset V(f_1, \ldots, f_n, S_{\bp})$.

    Now we will prove the reverse inclusion $X_{\bp} \supset V(f_1, \ldots, f_n, S_{\bp})$ for the case when none of the components of $V(S_{\bp})$ belongs to $V(f_1, \ldots, f_n)$.
    Consider any point $P \in V(f_1, \ldots, f_n, S_{\bp})$.
    It belongs to a component of $V(S_{\bp})$, we denote this component by $Y$.
    Since $Y$ does not belong to $V(f_1, \ldots, f_n)$, there exists $i$ such that $Y \not\subset V(f_i)$.
    Without loss of generality, we will assume $i = 1$.
    Therefore, there exists an irreducible curve $\mathcal{C} \subset Y$ such that $P \in \mathcal{C}$ and $\mathcal{C} \not\subset V(f_1)$.
    Due to the relation $f_j \cdot f_1 + (-f_1) \cdot f_j = 0$, $S_\bp$ contains a polynomial $f_j p_1 - f_1 p_j$ for every $2 \leqslant j \leqslant n$.
    Therefore, 
    \[
    (f_1(Q), p_1(Q)),\; \ldots,\; (f_n(Q), p_n(Q))
    \]
    are linearly dependent for every $Q \in \mathcal{C}$.
    Since the system $\bp = \mathbf{0}$ does not have a solution in $\PP^{n - 1}$, at least one of these vectors is nonzero, so, for every $Q \in \mathcal{C}$, there exists a unique $\varepsilon_Q$ such that $(Q, \varepsilon_Q) \in \widetilde{X}_{\bp}$. 
    This provides us with a bijective lifting of $\mathcal{C}$ to a curve $\mathcal{C}_0 \subset \widetilde{X}_{\bp}$.
    Since $f_1$ does not vanish identically on $\mathcal{C}$, $\varepsilon_Q \neq 0$ on an open subset of $\mathcal{C}_0$, so, by the irreducibility of $\mathcal{C}$ and, thus, $\mathcal{C}_0$, we have $\mathcal{C}_0 \subset Z_{\bp}$.
    Since $(P, 0) \in \mathcal{C}_0$, we deduce that $P \in X_{\bp}$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%

\begin{Proposition}\label{prop:smooth}
    Consider a smooth point $P$ on a component $Y \subset V(f_1, \ldots, f_n)$ (considered as an affine scheme) of dimension $\geqslant m$.
    Then there is an open nonempty subset $U \subset \Ra{\mathcal{P}}$
    such that, for every $\bp \in U$, we have $P \not\in X_\bp$.
\end{Proposition}

\begin{proof}
   Consider the local ring $(\mathcal{O}, \mathfrak{m})$ of the point $P$ considered as a point of the ambient space $\PP^{n - 1} \times \AAA^m$.
   We will denote the images of $f_1, \ldots, f_n$ in $\mathcal{O}$ by the same letters.
   Let $d := \dim Y$.
   The smoothness of $P$ implies that the Jacobian of $f_1, \ldots, f_n$ has rank $c := m + n - 1 - d$ at $P$. 
   By reordering $f$'s if necessary, we will further assume that the rank of the Jacobian of $f_1, \ldots, f_c$ is equal to $c$.
   Since $P$ is a smooth point, $\mathcal{O} / \langle f_1, \ldots, f_n \rangle \mathcal{O}$ is a regular local ring, so~\cite[proof of Proposition~1.10, Chapter VI]{kunz} implies that $\langle f_1, \ldots, f_n\rangle \mathcal{O} = \langle f_1, \ldots, f_c\rangle\mathcal{O}$.
   Since $d \geqslant m$, we have $c < n$, so we can write
   \[
     f_n = a_1 f_1 + \ldots + a_{n - 1}f_{n - 1},
   \]
   where $a_1, \ldots, a_{n - 1} \in \mathcal{O}$.
   By clearing denominators in this equality, we obtain a syzygy
   \[
     b_1 f_1 + \ldots + b_n f_n = 0,
   \]
   where $b_1, \ldots, b_n \in R$ and $b_n(P) \neq 0$.
   Then the condition
   \[
     b_1(P) p_1(P) + \ldots + b_n(P) p_n(P) \neq 0
   \]
   defines an open subset $U \subset \Ra{\mathcal{P}}$.
   In order to show that this subset is not empty, we choose linearly independent linear forms $\ell_1, \ldots, \ell_n$ such that $\ell_1(P) = \ldots = \ell_{n - 1}(P) = 0$ and $\ell_n(P) = 1$.
   Then $(\ell_1^{d_1}, \ldots, \ell_n^{d_n}) \in U$.
   By Lemma~\ref{lem:syzygy}, $P \not\in X_{\bp}$ for every $\bp \in U$.
\end{proof}

\begin{Proposition}\label{prop:main}
    Consider a point $P \in \AAA^m$ such that $\pi^{-1}(P)$ is finite and every point $Q \in \pi^{-1}(P)$ is a smooth point of an excess component of the scheme defined by $f_1, \ldots, f_n$.
    Then $\PRes_{\bx}(f_1, \ldots, f_n)$ does not vanish at $P$.
\end{Proposition}

\begin{proof}
    Let $U_0$ be the Zariski open subset of $\Ra{\mathcal{P}} \times \Ra{\mathcal{P}}$ from Lemma~\ref{lem:double_pert} and $U_1$ be the intersection of the open subsets of $\Ra{\mathcal{P}}$ provided by Proposition~\ref{prop:smooth} applied to the elements of $\pi^{-1}(P)$.
    Let $(\bp, \bq) \in (U_0 \cap (U_1 \times U_1))$.
    By Lemma~\ref{lem:Xp}, we have
    \[
    V(\PRes_\bx(\mathbf{f})) \subset V(\CRes_{\bx, \bp}(\mathbf{f})) \cap V(\CRes_{\bx, \bq}(\mathbf{f})) = \pi(X_{\bp}) \cap \pi(X_{\bq}).
    \]
    Since $\bp, \bq \in U_1$, the latter intersection does not contain $P$, so $\PRes_\bx(\mathbf{f})$ does not vanish on~$P$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
    Follows directly from Proposition~\ref{prop:main}.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:planar}]
    We start with observing that the syzygy module of $f_1, f_2$ is generated by $(h_2, -h_1)$.
    Therefore, $S_{\bp}$ is generated by a single polynomial $s_{\bp} := p_1h_2 - p_2h_1$. 
    Since, for every irreducible divisor $g_0$ of $g$, at least one of $h_1$ and $h_2$ is not divisible by $g_0$,
    there exists an nonempty open subset $U_0 \subset \Ra{\mathcal{P}}$ such that $s_{\bp}$ is coprime with $g$ for $\bp \in U_0$.
    Then Lemma~\ref{lem:syzygy} implies that 
    \[
    X_{\bp} = V(f_1, f_2, s_{\bp})\quad \text{ for }\bp \in U_0.
    \]

    \noindent
    \Ra{\textbf{Case 1:}} \emph{Consider $y^\ast \in \overline{\KK}$ such that $g$ is divisible by $y - y^\ast$}.
    Then 
    \[
    V(f_1, f_2, s_{\bp}) \cap \{y = y^\ast\} = V(s_{\bp}) \cap \{y = y^\ast\}
    \]
    is always nonempty because $s_{\bp}(x_0, x_1, y^\ast)$ will always have a root in $\PP^1$.
    Consider $\bp \in U_0$.
    Then $X_{\bp} \cap \{y = y^\ast\}$ is nonempty, so, by Lemma~\ref{lem:Xp}, $\CRes_{\bx, \bp}(f_1, f_2)$ vanishes at $y^\ast$.
    Then the same is true for $\PRes_\bx(f_1, f_2)$. 

    \noindent
    \Ra{\textbf{Case 2:}} \emph{Consider $y^\ast \in \overline{\KK}$ such that there exist $\bx^\ast \in \PP^1$ with} 
    \[
    h_1(\bx^\ast, y^\ast) = h_2(\bx^\ast, y^\ast) = 0.
    \]
    Consider $\bp \in U_0$.
    Then $s_{\bp}$ vanishes at $(\bx^\ast, y^\ast)$, so $(\bx^\ast, y^\ast) \in X_{\bp}$.
    Then, by Lemma~\ref{lem:Xp}, $\CRes_{\bx, \bp}(f_1, f_2)$ vanishes at $y^\ast$.
    Then the same is true for  $\PRes_\bx(f_1, f_2)$ as well.

    \noindent
    \Ra{\textbf{Case 3:}} \emph{Finally, consider $y^\ast$ which does not fall into neither of the two cases above.}
    Let $\bx_1^\ast, \ldots, \bx_\ell^\ast \in \PP^1$ be the points such that $(\bx_i^\ast, y^\ast)$ is a solution of $f_1 = f_2 = 0$ for every $1 \leqslant i \leqslant \ell$.
    Since $g$ is not divisible by $y - y^\ast$, there are only finitely many such points.
    We take $\bp$ with undetermined coefficients and 
     consider the condition 
    \begin{equation}\label{eq:cond}
    \prod\limits_{i = 1}^\ell (p_1(\bx_i^\ast) h_1(\bx_i^\ast, y^\ast) - p_2(\bx_i^\ast)h_2(\bx_i^\ast, y^\ast)) \neq 0.
    \end{equation}
    By the assumption on $y^\ast$, none of the brackets in the product vanishes identically, so~\eqref{eq:cond} defines a nonempty open subset $U_1 \subset \Ra{\mathcal{P}}$.
    For every $\bp \in U_0 \cap U_1$, none of $(\bx_i^\ast, y^\ast)$ belongs to $X_{\bp}$, so, by Lemma~\ref{lem:Xp}, $\CRes_{\bx, \bp}(f_1, f_2)$ does not vanish on $y^\ast$. 
    Therefore, $\PRes_\bx(f_1, f_2)$ does not vanish on $y^\ast$ as well.
\end{proof}

