\end{figure}

  We denote by $G_i$ the induced subgraph of~$G$ derived from~$H_i$.
  Observe that $$|V(G)|=2q ((|V(H)|-2)(q+2) + |E(H)| - 1)=\Theta(q^2 \nu),$$
  thus $n=\Theta(n^{1-2\beta} \nu)$ and $n = \Theta(\nu^{\frac{1}{2 \beta}})$.
  As $\beta>0$ is a~fixed constant, this defines a~polynomial-time reduction.
  See~\cref{fig:ham-reduction} for illustrations.

  \medskip

  \textbf{Correctness.}
  The reduction relies on the following two claims.
  \begin{claim}\label{clm:ham}
    If $H$ admits an $s$--$t$ Hamiltonian path, then deleting (equivalently, editing) fewer than $q$ edges in $G$ cannot make it non-Hamiltonian.
  \end{claim}
  \begin{proofofclaim}
    Let $G^-$ be any graph obtained from $G$ by deleting at~most~$q-1$ edges.
    We show the following two properties that for every $x_{uv} \neq x_{vw} \in V(G)$
    \begin{compactitem}
    \item there is a~path in $G^-$, starting at~$x_{uv}$, ending at~$x_{vw}$, and whose vertex set is $C_v \cup \{x_{uv},x_{vw}\}$, and
    \item if $v$ has a~third neighbor $y$ (in its copy~$H_i$), then there is a~path in $G^-$, starting at~$x_{uv}$, ending at~$x_{vw}$, and whose vertex set is $C_v \cup \{x_{uv},x_{vw},x_{vy}\}$. 
    \end{compactitem}
    We can then conclude by mimicking an~$s$--$t$ Hamiltonian path $P$ of $H$ in every~$G_i$.
    More precisely, we start at $s_i = x_{s_is'_i}$ (for $i$ going from 1 to $2q$), and obey the following rules, where $P_i$ is the path $P$ in copy~$H_i$.
    When in $x_{uv}$, if the successor of $v$ along $P_i$ is $w$, we continue in $G_i$ with the $x_{uv}$--$x_{vw}$ path of the second item if $v$ has a~third neighbor~$y$ in $H_i$ and $x_{vy}$ was not traversed yet.
    We instead go with the $x_{uv}$--$x_{vw}$ path of the first item, otherwise.

    \medskip

    \textbf{First item.}
    Recall that Ore's theorem~\cite{Ore60} is that every $n$-vertex simple graph such that the sum of the degrees of any two non-adjacent vertices is at~least~$n$ is Hamiltonian.
   This implies that $G^-[C_v]$ is Hamiltonian.
   Indeed, a~non-adjacent pair of vertices in $G^-[C_v]$ has combined degree at~least $2q-(q-2)=q+2$.
   We fix a~Hamiltonian cycle $C$ of $G^-[C_v]$.

   The bipartite graph $G^-[\{x_{uv},x_{vw}\},C_v]$ has at~least $2(q+2)-(q-1)=q+5$ edges.
   This ensures that there are two consecutive vertices $u', w'$ along $C$ such that $x_{uv}u', x_{vw}w'$ are edges of $G^-[C_v \cup \{x_{uv},x_{vw}\}]$.
   If not, $G^-[\{x_{uv},x_{vw}\},C_v]$ would have at~most $q+2$ edges.
   The edge $x_{uv}u'$, the $(q+2)$-vertex path along $C$ from $u'$ to $w'$, and the edge $x_{vw}w'$ define our desired spanning path.

   \medskip

   \textbf{Second item.}
   Observe that $C_v \cup \{x_{vy}\}$ is a~clique on $q+3$ vertices.
   Again by Ore's theorem there is a~Hamiltonian cycle $C$ in $G^-[C_v \cup \{x_{vy}\}]$.
   In $G$, vertices $x_{uv}, x_{vw}$ both have $q+2$ neighbors in $C$.
   Let $s \geqslant 3$ be the number of neighbors of $x_{uv}$ in $C$ remaining in~$G^-$; hence $q+2-s$ edges between $x_{uv}$ and $C_v$ are removed in~$G^-$.
   These $s$ neighbors have themselves a~combined neighborhood~$N$ in~$C - \{x_{vy}\}$ of size at~least $s-1$.
   As at~most $s-3$ edges incident to $x_{vw}$ can be deleted, at~least one vertex of~$N$ is still adjacent to~$x_{vw}$.
   We make the $x_{uv}$--$x_{vw}$ Hamiltonian path in $G^-[C_v \cup \{x_{uv},x_{vw},x_{vy}\}]$ as in the previous paragraph.  
  \end{proofofclaim}

  \begin{claim}\label{clm:no-ham}
    If $H$ has no $s$--$t$ Hamiltonian path, then adding (equivalently, editing) fewer than $q$~edges in $G$ cannot make it Hamiltonian.
  \end{claim}
  \begin{proofofclaim}
    Let $G^+$ be any graph obtained from $G$ by adding at~most~$q-1$ edges.
    By the pigeonhole principle, there is at~least one $G_i$ such that no vertex of $G_i - \{s_i,t_i\}$ is incident to an edge added in~$G^+$.
    Thus the set $\{s_i,t_i\}$ separates $V(G_i) \setminus \{s_i,t_i\}$ from the rest of~$G^+$.
    So, for $G^+$ to be Hamiltonian, it should be that $G_i$ admits an $s_i$--$t_i$ Hamiltonian path.
    We shall then just prove that if $G_i$ admits an $s_i$--$t_i$ Hamiltonian path, then so does $H_i$ (hence $H$ has an $s$--$t$ Hamiltonian path).

    Let $u_1, u_2, \ldots, u_{\nu-2}$ be the vertices of $H_i - \{s_i,t_i\}$ in the order in which the cliques $C_u$ are visited for the first time, in some fixed $s_i$--$t_i$ Hamiltonian path $P$ of~$G_i$.
    For each clique~$C_u$, there is a~vertex subset $X_u$ of size at~most~3 (the up to 3 vertices of the form $x_{u,\bullet}$) that disconnects $C_u$ from the rest of the graph in~$G_i$.
    This implies that $C_u \cup X_u$ cannot be exited and reentered by~$P$.
    In particular, this means that $u_1=s'_i$, $u_{\nu-2}=t'_i$, and for every $j \in [\nu-3]$, $u_ju_{j+1} \in E(H_i)$.
    Therefore~$s_i, u_1, u_2, \ldots, u_{\nu-2}, t_i$ is an $s_i$--$t_i$ Hamiltonian path in~$H_i$.
  \end{proofofclaim}

  Thus, by~\cref{clm:ham,clm:no-ham}, if a~positive (resp.~negative) instance is reported by the algorithm solving \rel$\-($\textsc{Hamiltonian Cycle}$, \diste, n^{\frac{1}{2}-\beta})$, then $H$ has an $s$--$t$ Hamiltonian path (resp. has no~$s$--$t$ Hamiltonian path).
\end{proof}

We observe that pushing the tractability radius for $\diste$ (from $n/3$) down to $n^{.99}$ requires to improve the current polynomial-time approximation factor for \textsc{Longest Path} in Hamiltonian graphs.
The current best polytime algorithm returns paths of length $\Omega(\frac{\log^2 n}{\log^2 \log n})$ in $n$-vertex Hamiltonian graphs~\cite{Vishwanathan04}.
While better guarantees can be obtained in bounded-degree Hamiltonian graphs~\cite{Feder00}, for any $\beta > 0$, no polytime algorithm is known to output paths of length $n^\beta$ even in subcubic Hamiltonian graphs.

\begin{theorem}\label{thm:barrier-longest-path}
  For any $\beta > 0$, a~polynomial-time algorithm for \rel$($\textsc{Hamiltonian Cycle}$, \diste, n^{1-\beta})$ implies a~polynomial-time detection of paths of length $\lfloor n^\beta \rfloor$ in Hamiltonian graphs.
\end{theorem}
\begin{proof}
  We make the same reduction as in~\cref{thm:ham-cycle-hard} with only two copies. 
  Let $H, s, t$ be as in the previous proof, and $\nu$ be the number of vertices of~$H$.
  Let $q := \lfloor n^{1-\beta} \rfloor + 3$.
  We build an $n$-vertex instance $G$ of \rel$($\textsc{Hamiltonian Cycle}$, \diste, n^{1-\beta})$ as shown in~\cref{fig:ham-reduction} with cliques $C_u$ of size $q$ and solely two copies $H_1, H_2$ (and $G_1, G_2$).
  So $s_1=t_2$ and $s_2=t_1$.
  We observe that $G$ has $2((|V(H)|-2)q + |E(H)| - 1) = O(q \nu)$ vertices.
  This implies that $n = O(\nu^{1/\beta})$, so the reduction is indeed polynomial for any fixed $\beta > 0$.

  If the algorithm $\mathcal A$ for \rel$($\textsc{Hamiltonian Cycle}$, \diste, n^{1-\beta})$ outputs a~negative instance (of the form $(G',\nil)$), then we know from the proof of  \cref{thm:ham-cycle-hard} that $H$ has no $s$--$t$ Hamiltonian path, thus $G$ is not Hamiltonian; which does not happen within Hamiltonian graphs.
  The only remaining case is that $\mathcal A$ outputs a~positive instance~$(G',C)$.
  Among the $n$ edges of~$C$, at most $\lfloor n^{1-\beta} \rfloor$ were added to~$G$.
  This still leaves at~least $n^\beta$ consecutive edges of~$G$ in~$C$.
  We thus obtain the sought path of length $\lfloor n^\beta \rfloor$.
\end{proof}

We now move to the \textsc{Dominating Set} problem, where given a~graph $G$ and an integer $k \in [0,|V(G)|]$, one is asked for a~dominating set of size~$k$, or to output $\nil$ if none exists.

\begin{theorem}\label{thm:ds-algo-diste}
  \rel$(\textsc{Dominating Set}, \diste, n/e)$ is in \FP (where $e$ is Euler's number).
\end{theorem}
\begin{proof}
  Let $(G,k)$ be any input of \rel$(\textsc{Dominating Set}, \diste, n/e)$ with $n = |V(G)|$.
  We first run the known polynomial-time $(1-\frac{1}{e})$-approximation algorithm (actually the greedy algorithm) for \textsc{Max $k$-Coverage}~\cite{Nemhauser78}, the problem of picking $k$ sets from a~given list so as to maximize the cardinality of their union, on the closed-neighborhood set system of~$G$, i.e., $\{N_G[v]~:$ $v \in V(G)\}$.

  If this outputs $k$ sets whose union has size less than $(1-\frac{1}{e})n$, we can safely output $((G,k), \nil)$, as this gives a~guarantee that no dominating set of size~$k$ exists in~$G$.
  Otherwise, we obtain a~set $S$ of $k$ vertices such that $X := V(G) \setminus N_G[S]$ is of size at~most~$\frac{n}{e}$.
  Let us fix some $v \in S$.
  Build the graph $H$ by adding $|X|$ edges to $G$: the edge $vx$ for every $x \in X$.
  We can output $((H,k),S)$ as $\diste(G,H) = |X| \leqslant n/e$ and $S$ is a~dominating set of~$H$ of size~$k$.
\end{proof}

The \emph{blow-up} operation (i.e, replacing every vertex by a~clique) provides a~simple robust reduction for \textsc{Dominating Set} under $\diste$. 

\begin{theorem}\label{thm:ds-hardness-diste}
  For any $\beta > 0$, \rel$(\textsc{Dominating Set}, \diste, n^{1-\beta})$ is \NP-hard.
\end{theorem}
\begin{proof}
  Let $H$ be an $\nu$-vertex instance of \textsc{Dominating Set}.
  We build the $n$-vertex graph $G$ by replacing each vertex $v \in V(H)$ by a~clique $C_v$ of size $q := 2 \lfloor n^{1-\beta} \rfloor + 1$.
  Thus, two distinct vertices $x \in C_u, y \in C_v$ are adjacent in $G$ whenever $u = v$ or $uv \in E(H)$.
  We have $n = q \nu$, thus $n = O(\nu^{1/\beta})$.
  This reduction is polynomial for any fixed $\beta > 0$.

  We give to $G$ the same threshold as $H$, say $k$.
  We claim that a~polynomial-time algorithm solving \rel$(\textsc{Dominating}$ $\textsc{Set}, \diste, n^{1-\beta})$ on input $(G,k)$ would also solve \textsc{Dominating Set} on input $(H,k)$.
  The correctness is given by the following two claims.

  \begin{claim}\label{clm:dom}
    If $H$ admits a~dominating set of size $k$, then every graph $G'$ obtained from $G$ by removing at~most~$\lfloor n^{1-\beta} \rfloor$ edges has a~dominating set of size~$k$.
  \end{claim}
  \begin{proofofclaim}
    Note that for every $v \in V(H)$, there is at~least one vertex of $C_v$, say $x_v$, not incident to any edge of $G \triangle G'$ (removed edge).
    This is because $|C_v| = 2 \lfloor n^{1-\beta} \rfloor + 1$.
    Let $S \subseteq V(H)$ be a~dominating set of~$H$, and $S' := \{x_v~:~v \in S\}$.
    By construction, $|S'| = |S|$ and $x_v$ dominates in $G'$ the set $\bigcup_{w \in N_H[v]} C_v$.
    As $S$ is a~dominating set of~$H$, $S'$ is a~dominating set of~$G'$. 
  \end{proofofclaim}

  \begin{claim}\label{clm:no-dom}
    If $H$ has no dominating set of size $k$, then every graph $G'$ obtained from $G$ by adding at~most~$\lfloor n^{1-\beta} \rfloor$ edges has no dominating set of size~$k$.
  \end{claim}
  \begin{proofofclaim} 
    Let $S \subseteq V(G')$ be any set of size~$k$.
    Consider the set $S' := \{v \in V(H)~:~S \cap C_v \neq \emptyset\}$ of size at~most~$k$.
    By assumption, $S'$ is not a~dominating set of~$H$. 
    So there is a~$v \in V(H)$ such that $N_H[v] \cap S' = \emptyset$.
    By the observation in~\cref{clm:dom}, there is a~vertex $x_v \in C_v$ such that $x_v$ is not incident to any edge of $G \triangle G'$ (added edge).
    Vertex $x_v$ is thus not dominated by~$S'$.
  \end{proofofclaim}

  We can conclude as a~positive (resp.~negative) answer to \rel$(\textsc{Dominating}$ $\textsc{Set}, \diste,$ $n^{1-\beta})$ on input $(G,k)$ implies a~positive (resp.~negative) answer to \textsc{Dominating Set} on input $(H,k)$.
\end{proof}

\section{\textsc{Independent Set}, \textsc{Clique}, \textsc{Vertex Cover}, and \textsc{Coloring}}\label{sec:is}

We first show that \textsc{Independent Set} has hardness radius $n^{\frac{1}{2}-o(1)}$ under $\distd$, and $n^{\frac{4}{3}-o(1)}$ under $\diste$.
We recall that \textsc{Independent Set} inputs a~pair $(G,k)$ where $G$ is a~graph and $k$ is a~non-negative integer, and asks for an independent set of size $k$ in~$G$.
We could treat \textsc{Independent Set} purely as a~decision problem (with output in $\{\true, \false\}$).
However all the results presented in this section extend to the setting where the desired output is an actual independent set of size~$k$ in $G$, and $\nil$ if none exists. 

We start by observing that $\sqrt n$ upper bounds the tractability radius for $\distd$.

\begin{theorem}\label{thm:algo-is}
  \rel$($\textsc{Independent Set}$, \distd, n^{\frac{1}{2}})$ is in~\FP.
\end{theorem}
\begin{proof}
  Let $(G,k)$ be the input, with $n = |V(G)|$.
  If $k \leqslant \sqrt n + 1$, fix any subset $S \subseteq V(G)$ of size $\lfloor \sqrt n \rfloor + 1$.
  Build the graph $H$ with vertex set $V(G)$ such that $H[S]$ is an independent set, and $H - S = G - S$.
  By construction, $\distd(G,H) \leqslant \sqrt n$.
  We can thus output $((H,k),S)$.

  If instead $k > \sqrt n + 1$, arbitrarily partition $V(G)$ into $k-1$ parts $V_1, \ldots, V_{k-1}$ of size $\lfloor \frac{n}{k-1} \rfloor$ or $\lceil \frac{n}{k-1} \rceil$.
  Build the graph $H$, obtained from $G$ by turning each $V_i$ into a~clique.
  As $|V_i|-1 \leqslant \sqrt n$, it holds that $\distd(G,H) \leqslant \sqrt n$.
  The partition into $k-1$ cliques $V_1, \ldots, V_{k-1}$ in $H$ implies that $\alpha(H) \leqslant k-1$.
  We can thus output $((H,k),\nil)$.
\end{proof}

Perhaps surprisingly, the easy scheme of~\cref{thm:algo-is} is essentially best possible.
Using the known strong inapproximability of \textsc{Max Independent Set}, we show that the sidestepping problem becomes \NP-hard as soon as the radius gets only slightly smaller.

\begin{theorem}\label{thm:hardness-is}
  For any $\beta > 0$, \rel$($\textsc{Independent Set}$, \distd, n^{\frac{1}{2}-\beta})$ is \NP-hard.
\end{theorem}
\begin{proof}
  For any $\varepsilon \in (0,1/2]$, given $n$-vertex input graphs $G$ satisfying either $\alpha(G) \leqslant n^\varepsilon$ or $\alpha(G) \geqslant n^{1-\varepsilon}$ it is \NP-hard to tell which of the two outcomes holds~\cite{Hastad96,Zuckerman07}.

  Consider inputs $(G,\lfloor \sqrt n \rfloor)$ of \rel$($\textsc{Independent Set}$, \distd,   n^{\frac{1}{2}-\beta})$ with $n = |V(G)|$ and $G$ satisfies the above promise.
  We show that if these instances could be solved in polynomial time, this would contradict, under \P\,$\neq$\,\NP, the latter hardness-of-approximation result with $\varepsilon := \beta/2$.
  Assume that the supposed algorithm returns $((H, \lfloor \sqrt n \rfloor),S)$ such that $\distd(G,H) \leqslant n^{\frac{1}{2}-\beta}$ and $S$ is an independent set of~$H$ of size $\lfloor \sqrt n \rfloor$.
  An important observation is that $G[S]$ has maximum degree at~most $n^{\frac{1}{2}-\beta}$.
  Hence, in polynomial time, one can compute a~subset $S' \subseteq S$ such that $S'$ is an independent set of~$G$ of size at~least
  \[\frac{\lfloor \sqrt n \rfloor}{n^{\frac{1}{2}-\beta}+1} \geqslant \frac{n^\beta}{2} > n^\varepsilon.\]
  For the last inequality to hold, we assume that $n > 2^{1/\varepsilon}$, which we can safely do, as otherwise the instance can be solved by the brute-force approach.
  Therefore $S'$ witnesses that $\alpha(G) \leqslant n^\varepsilon$ does not hold.
  We can thus report that $\alpha(G) \geqslant n^{1-\varepsilon}$.

  Now we assume instead that the algorithm returns $((H, \lfloor \sqrt n \rfloor),\nil)$ such that $\distd(G,H) \leqslant n^{\frac{1}{2}-\beta}$ and $\alpha(H) < \sqrt n$.
  We claim that $\alpha(G) < n^{1-\varepsilon}$.
  Indeed, symmetrically to what has been previously observed, if $G$ had an independent set $S$ of size at~least $n^{1-\frac{\beta}{2}}$, then a~$(n^{\frac{1}{2}-\beta}+1)^{-1}$ fraction of $S$ would form an independent set in~$H$.
  Again, assuming that $n > 2^{1/\varepsilon}$, this would contradict $\alpha(H) < \sqrt n$.
  Hence, we can report that the outcome $\alpha(G) \leqslant n^\varepsilon$ holds.
\end{proof}

We can adapt the proof of~\cref{thm:algo-is} to yield an essentially optimal upper bound for distance~$\diste$.
For that, we simply set the demarcation on the independent-set size at $n^{\frac{2}{3}}$ rather than $\sqrt n$.

\begin{theorem}\label{thm:algo-is-diste}
  \rel$($\textsc{Independent Set}$, \diste, n^{\frac{4}{3}})$ is in~\FP.
\end{theorem}
\begin{proof}
  Let $(G,k)$ be the input, with $n = |V(G)|$.
  If $k \leqslant n^{\frac{2}{3}}$, fix any subset $S \subseteq V(G)$ of size~$n^{\frac{2}{3}}$.
  Remove the at~most ${n^{2/3} \choose 2} \leqslant n^{\frac{4}{3}}$ edges of $G[S]$ from $G$, and let $H$ be the obtained graph.
  We can output $((H,k),S)$ since $\diste(G,H) \leqslant n^{\frac{4}{3}}$ and $S$ is an independent set of size~$k$ in~$H$.

  If instead $k > n^{\frac{2}{3}}$, arbitrarily partition $V(G)$ into $\lfloor n^{\frac{2}{3}} \rfloor$ parts $V_1, \ldots, V_{\lceil n^{2/3} \rceil}$ each of size at~most $\lceil n^{\frac{1}{3}} \rceil +1$.
  Turn each $V_i$ into a~clique, and call the obtained graph~$H$.
  This adds to~$G$ at most $\lfloor n^{2/3} \rfloor \cdot {\lceil n^{1/3} \rceil+1 \choose 2} \leqslant n^{\frac{4}{3}}$ edges, for large enough~$n$.
  Thus we can output $((H,k),\nil)$.
\end{proof}

Finally we show the counterpart of~\cref{thm:hardness-is} for $\diste$.

\begin{theorem}\label{thm:hardness-is-diste}
  For any $\beta > 0$, \rel$($\textsc{Independent Set}$, \diste, n^{\frac{4}{3}-\beta})$ is \NP-hard.
\end{theorem}
\begin{proof}
  As in~\cref{thm:hardness-is}, we use the hardness of distinguishing, for any $\varepsilon \in (0,1/2]$, $n$-vertex graphs $G$ such that $\alpha(G) \leqslant n^\varepsilon$ from those such that $\alpha(G) \geqslant n^{1-\varepsilon}$.

  Consider inputs $(G,\lfloor n^{2/3} \rfloor)$ of \rel$($\textsc{Independent Set}$, \diste, n^{\frac{4}{3}-\beta})$ with $n = |V(G)|$ and $G$ satisfies one of the previous outcomes.
  We show that solving these instances in polynomial time would contradict, unless \P\,$=$\,\NP, the above hardness-of-approximation result with $\varepsilon := \beta/4$.
  Assume that the supposed algorithm returns $((H, \lfloor n^{2/3} \rfloor),S)$ such that $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$ and $S$ is an independent set of~$H$ of size $\lfloor n^{2/3} \rfloor$.

  We observe that $G[S]$ has at~most $n^{\frac{4}{3}-\beta}$ edges.
  Hence every (induced) subgraph of $G[S]$ has a~vertex of degree at~most~$2 (n^{\frac{4}{3}-\beta})^{1/2}=2 n^{\frac{2}{3}-2 \varepsilon}$.
  Thus $G[S]$ has an independent set of size at~least \[\frac{\lfloor n^{2/3} \rfloor}{2 n^{\frac{2}{3} - 2 \varepsilon} + 1} > n^\varepsilon,\]
  for $n$ at~least a~fixed function of~$\varepsilon$.
  Therefore $\alpha(G) \leqslant n^\varepsilon$ cannot hold, so we can conclude that $\alpha(G) \geqslant n^{1-\varepsilon}$.

  We now assume that the algorithm returns instead $((H, \lfloor n^{2/3} \rfloor),\nil)$ such that $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$ and $\alpha(H) < \lfloor n^{2/3} \rfloor$.
  We claim that $\alpha(G) < n^{1-\varepsilon}$.
  Suppose for the sake of contradiction that $G$ has an independent set $S$ of size $n^{1-\frac{\beta}{4}}$.
  Note that $H[S]$ has at~most~$n^{\frac{4}{3}-\beta}$ edges.
  In particular, $H[S]$ has at~most~$n^{1-2 \varepsilon}$ vertices of degree at~least~$2 n^{\frac{1}{3}-2 \varepsilon}$, thus more than $n^{1- \varepsilon} - n^{1-2 \varepsilon}$ vertices of degree less than~$2 n^{\frac{1}{3}-2 \varepsilon}$.
  Therefore $H[S]$ has an independent set of size at~least \[\frac{n^{1-\varepsilon}-n^{1-2\varepsilon}}{2 n^{\frac{1}{3}-2 \varepsilon} + 1} > \frac{1}{10} n^{\frac{2}{3} + \varepsilon} > n^{2/3},\]
  for some large enough~$n$.
  This would contradict that $\alpha(H) < \lfloor n^{2/3} \rfloor$.
  Hence, we can conclude that $\alpha(G) \leqslant n^\varepsilon$ holds.
\end{proof}

We now introduce the necessary formalism to show that all the previous results of this section carry over to \textsc{Clique} and \textsc{Vertex Cover}.

A~\emph{polynomial-time isomorphism} $\varphi$ from $\Pi$ to $\Pi'$ (where $\Pi$ and $\Pi'$ are not necessarily decision problems) is a~bijective map from the inputs of $\Pi$ to the inputs of $\Pi'$ that is a~polynomial-time reduction, with inverse $\varphi^{-1}$ also computable in polynomial time.\footnote{For decision problems, this notion is at the core of the Berman--Hartmanis conjecture stating that there is a~polynomial-time isomorphism between any two \NP-complete languages.}
Specifically when $\Pi$ and $\Pi'$ are function problems, the bijection $\varphi$ is accompanied by a~polynomial-time function $\psi$, called \emph{output pullback} (of $\varphi$), such that for any $x \in \sol_{\Pi'}(\varphi(I))$, it holds that $\psi(x) \in \sol_\Pi(I)$.
Note that if instead $\Pi$ and $\Pi'$ are decision problems the function $\psi$ would simply map $\true$ to $\true$ and $\false$ to $\false$, and can remain implicit.
We say that $\varphi$ is \emph{length-preserving} if for every input $I$ of $\Pi$, $|\varphi(I)|=|I|$.

\begin{theorem}\label{thm:lpi}
  Let $\Pi$ and $\Pi'$ be two problems, $\varphi$, a~length-preserving polynomial-time isomorphism from $\Pi$ to~$\Pi'$, $\psi$, its output pullback, $\dist$, a~metric on the inputs of~$\Pi$, and $\dist'$, a~metric on the inputs of~$\Pi'$ such that for every pair of inputs $I, J$ of $\Pi$ it holds that $\dist(I,J) = \dist'(\varphi(I),\varphi(J))$.

  For any map $d$, if \rel$(\Pi', \dist', d)$ is in \FP, then \rel$(\Pi, \dist, d)$ is in \FP. 
\end{theorem}

\begin{proof}
  The polynomial-time algorithm solving \rel$(\Pi, \dist, d)$ works as follows.
  On input $I$ of $\Pi$, compute the instance $I' := \varphi(I)$ of~$\Pi'$ in polynomial time.
  Run the polynomial-time algorithm for \rel$(\Pi', \dist', d)$ on input~$I'$.
  It outputs $(J',\Pi'(J'))$ with $\dist'(I',J') \leqslant d(|I'|)$.
  Now compute $J := \varphi^{-1}(J')$, and $x := \psi(\Pi'(J'))$.
  Finally output~$(J,x)$.
  By definition of the output pullback, $x$ is indeed a~correct solution to $\Pi$ on~$J$.
  Furthermore, $\dist(I,J) = \dist'(\varphi(I),\varphi(J)) = \dist'(I',J') \leqslant d(|I'|) = d(|\varphi(I)|) = d(|I|)$, since $\varphi$ is length-preserving.
\end{proof}

We now use~\cref{thm:lpi} for \textsc{Clique} and \textsc{Vertex Cover}.
Similarly to \textsc{Independent Set}, \textsc{Clique} (resp.~\textsc{Vertex Cover}) inputs a~pair $(G,k)$ where $G$ is a~graph and $k \in [0,|V(G)|]$, and a~clique of~$G$ (resp.~vertex cover of~$G$) of size $k$ is expected as output, and $\nil$ if none exists. 

\begin{theorem}\label{thm:clique-vc}
  \textsc{Clique} and \textsc{Vertex Cover} also have hardness radius $n^{\frac{1}{2}-o(1)}$ for $\distd$, and $n^{\frac{4}{3}-o(1)}$ for $\diste$.
\end{theorem}

\begin{proof}
  We start with the case of~\textsc{Clique}.
  The map $\varphi: (G,k) \mapsto (\overline G, k)$, where $\overline G$ is the complement of graph~$G$ and $k$ is a~non-negative integer, is a~length-preserving polynomial-time isomorphism from \textsc{Clique} to \textsc{Independent Set} and from \textsc{Independent Set} to \textsc{Clique} (as $\varphi$ is an involution), and output pullback $\psi$ defined as the identity map.
  Indeed $|V(G)|=|V(\overline G)|$, $\overline{\overline G}=G$, and an independent set in $\overline G$ is a~clique in~$G$.
  Moreover $G \triangle H = \overline G \triangle \overline H$, so $\dist((G,k),(H,k')) = \dist(\varphi(G,k),\varphi(H,k'))$ for $\dist \in \{\diste, \distd\}$.

  Thus the assumptions of~\cref{thm:lpi} are met by $\varphi$ and $\psi$ for $$(\Pi,\Pi') \in \{(\textsc{Clique}, \textsc{Independent Set}), (\textsc{Independent Set},\textsc{Clique})\}$$ and $\dist=\dist' \in \{\diste,\distd\}$.
  Hence~\cref{thm:lpi,thm:algo-is,thm:algo-is-diste} imply that \rel$($\textsc{Clique}$,$ $\distd, n^{\frac{1}{2}})$ and \rel$($\textsc{Clique}$, \diste, n^{\frac{4}{3}})$ are in~\FP.
  Now considering the reduction from \textsc{Independent Set} to \textsc{Clique}, \cref{thm:lpi,thm:hardness-is,thm:hardness-is-diste} imply that, for any $\beta > 0$, \rel$($\textsc{Clique}$,$ $\distd, n^{\frac{1}{2}-\beta})$ and \rel$($\textsc{Clique}$, \diste, n^{\frac{4}{3}-\beta})$ are \NP-hard.

  We now deal with~\textsc{Vertex Cover}.
  We define the involutive map $\varphi: (G,k) \mapsto (G, |V(G)|-k)$.
  Map $\varphi$ is a~length-preserving polynomial-time isomorphism from \textsc{Vertex Cover} to \textsc{Independent Set} and from \textsc{Independent Set} to \textsc{Vertex Cover}, with output pullback $\psi$ defined as the involution $X \mapsto V(G) \setminus X$.
  Indeed $X$ is a~vertex cover of $G$ if and only if $V(G) \setminus X$ is an independent set of~$G$.
  We have that $$\dist((G,k),(H,k')) = \dist((G,|V(G)|-k),(H,|V(H)|-k')) = \dist(\varphi(G,k),\varphi(H,k'))$$ for $\dist \in \{\diste, \distd\}$.
  This holds since these distances are infinite if $V(G) \neq V(H)$ or $k \neq k'$, and are equal to $\dist(G,H)$ otherwise.

  Thus \cref{thm:lpi,thm:algo-is,thm:algo-is-diste} imply that \rel$($\textsc{Vertex Cover}$,$ $\distd, n^{\frac{1}{2}})$ and \rel$($\textsc{Vertex Cover}$, \diste, n^{\frac{4}{3}})$ are in~\FP, whereas \cref{thm:lpi,thm:hardness-is,thm:hardness-is-diste} imply that, for any $\beta > 0$, \rel$($\textsc{Vertex Cover}$,$ $\distd, n^{\frac{1}{2}-\beta})$ and \rel$($\textsc{Vertex Cover}$, \diste, n^{\frac{4}{3}-\beta})$ are \NP-hard.
\end{proof}

We finish this section with the case of \textsc{Coloring} and \textsc{Clique Cover}.

We first observe that \cref{thm:algo-is,thm:algo-is-diste} also hold for \textsc{Coloring}, which takes as input a~graph $G$ and an integer~$k \in [0,|V(G)|]$, and asks for a~partition of $V(G)$ into $k$ independent sets if one exists, and to output $\nil$ otherwise.
To do so, one can adapt these theorems for the \textsc{Clique Cover} problem, which boils down to \textsc{Coloring} in the complement graph, and invoke~\cref{thm:lpi}.
Indeed, in the algorithms of \cref{thm:algo-is,thm:algo-is-diste}, the used witnesses of small independence number (negative instances for \textsc{Independent Set}) are vertex-partitions into cliques (positive instances for \textsc{Clique Cover}), whereas a~large independent set (positive instances for \textsc{Independent Set}) is always a~witness that the graph needs a~large number of cliques to be vertex-partitioned (negative instances for \textsc{Clique Cover}).

\begin{theorem}\label{thm:algo-coloring}
  For any $\Pi \in \{\textsc{Coloring}, \textsc{Clique Cover}\}$, \rel$(\Pi, \distd, n^{\frac{1}{2}})$ and \rel$(\Pi, \diste, n^{\frac{4}{3}})$ are in~\FP.
\end{theorem}

\cref{thm:hardness-is,thm:hardness-is-diste} also hold for \textsc{Coloring} (and \textsc{Clique Cover}), but their proofs require a~bit more adjustments.

\begin{theorem}\label{thm:hardness-coloring}
For any $\beta > 0$, \rel$($\textsc{Coloring}$, \distd, n^{\frac{1}{2}-\beta})$ is \NP-hard.
\end{theorem}
\begin{proof}
  For any $\varepsilon \in (0,1/2]$, given $n$-vertex input graphs $G$ satisfying either $\chi(G) \leqslant n^\varepsilon$ or $\chi(G) \geqslant n^{1-\varepsilon}$, it is \NP-hard to tell which of the two outcomes holds~\cite{Hastad96,Zuckerman07}.
 Consider inputs $(G,\lfloor \sqrt n \rfloor)$ of \rel$($\textsc{Coloring}$, \distd, n^{\frac{1}{2}-\beta})$ with $n = |V(G)|$ and $G$ satisfies that $\chi(G) \leqslant n^\varepsilon$ or $\chi(G) \geqslant n^{1-\varepsilon}$.
  We show that a~polynomial-time algorithm for these instances would contradict, unless \P\,$=$\,\NP, the above hardness-of-approximation result with $\varepsilon := \beta/2$.

  Assume that the supposed algorithm returns $((H, \lfloor \sqrt n \rfloor),\mathcal P)$ such that $\distd(G,H) \leqslant n^{\frac{1}{2}-\beta}$ and $\mathcal P$ is a~partition of~$V(H)$ into $\lfloor \sqrt n \rfloor$ independent sets of~$H$.
  As $G' := G-E(H)$ (the graph $G$ deprived of the edges of~$H$) has maximum degree at~most $n^{\frac{1}{2}-\beta}$, there is a~partition $\mathcal Q$ of $V(G') = V(H)$ into $n^{\frac{1}{2}-\beta}+1$ independent sets of~$G'$.
  Partition $\mathcal Q$ refines $\mathcal P$ (split each part of~$\mathcal P$ into its intersections with parts of $\mathcal Q$) into a~partition $\mathcal P'$ of $V(G)=V(H)$ with at~most~$\lfloor \sqrt n \rfloor \cdot (n^{\frac{1}{2}-\beta}+1)$ parts.
  By construction, each part of $\mathcal P'$ is an independent set of~$G$.
  Moreover $\lfloor \sqrt n \rfloor \cdot (n^{\frac{1}{2}-\beta}+1) \leqslant n^{1-\beta} + \sqrt n < n^{1-\varepsilon}$ for large enough~$n$.
  Thus we can report that $\chi(G) \leqslant n^\varepsilon$.

  Now we assume instead that the algorithm returns $((H, \lfloor \sqrt n \rfloor),\nil)$ such that $\distd(G,H) \leqslant n^{\frac{1}{2}-\beta}$ and $\chi(H) > \sqrt n$.
  We claim that $\chi(G) > n^\varepsilon$.
  Assume, for the sake of contradiction, that there is a~partition $\mathcal P$ of~$V(G) = V(H)$ into $\lfloor n^\varepsilon \rfloor$ independent sets of~$G$.
  As $H' := H - E(G)$ has maximum degree at~most $n^{\frac{1}{2}-\beta}$, there is a~partition $\mathcal Q$ of $V(H') = V(H)$ into $n^{\frac{1}{2}-\beta}+1$ independent sets of~$H'$.
  Then the refinement $\mathcal P'$ of~$\mathcal P$ by $\mathcal Q$ is a~partition of $V(H)$ into at~most $\lfloor n^\varepsilon \rfloor \cdot (n^{\frac{1}{2}-\beta}+1) \leqslant n^{\frac{1}{2}-\beta+\varepsilon}+ n^\varepsilon < \sqrt n$ independent sets of~$H$; a~contradiction to $\chi(H) > \sqrt n$.
  Hence, we can report that $\chi(G) \geqslant n^{1-\varepsilon}$ holds.
\end{proof}

We finally adapt~\cref{thm:hardness-is-diste} for \textsc{Coloring}.
We need the following folklore observation.

\begin{observation}\label{obs:m-to-degen}
  Every $m$-edge graph has chromatic number at~most~$\lceil \sqrt{2m} \rceil$.
\end{observation}
\begin{proof}
  It is in fact enough to show that any $m$-edge graph $G$ has a~vertex of degree at~most $\lceil \sqrt{2m} \rceil - 1$.
  If all the vertices of~$G$ have degree at~least $\lceil \sqrt{2m} \rceil$, then $m \geqslant \frac{1}{2} n \lceil \sqrt{2m} \rceil$.
  But also $n \geqslant \lceil \sqrt{2m} \rceil+1$ for a~vertex to possibly have $\lceil \sqrt{2m} \rceil$ neighbors.
  So $m \geqslant \frac{1}{2} \sqrt{2m} (\sqrt{2m}+1)> m$; a~contradiction.
\end{proof}

The main additional difference compared to the adaptation of~\cref{thm:hardness-coloring} is the use of the Cauchy--Schwarz inequality to get better upper bounds on some chromatic numbers.

\begin{theorem}\label{thm:hardness-coloring-diste}
  For any $\beta > 0$, \rel$($\textsc{Coloring}$, \diste, n^{\frac{4}{3}-\beta})$ is \NP-hard.
\end{theorem}
\begin{proof}
  As in~\cref{thm:hardness-coloring}, we rely on the hardness of distinguishing, for any $\varepsilon \in (0,1/2]$, $n$-vertex graphs $G$ such that $\chi(G) \leqslant n^\varepsilon$ from those such that $\chi(G) \geqslant n^{1-\varepsilon}$.
  Consider inputs $(G,\lfloor n^{2/3} \rfloor)$ of \rel$($\textsc{Coloring}$, \diste, n^{\frac{4}{3}-\beta})$ with $n = |V(G)|$ and $G$ satisfies $\chi(G) \leqslant n^\varepsilon$ or $\chi(G) \geqslant n^{1-\varepsilon}$.
  We show that solving these instances in polynomial time would contradict, unless \P\,$=$\,\NP, the above hardness-of-approximation result with $\varepsilon := \beta/4$.

  Assume that the supposed algorithm returns $((H, \lfloor n^{2/3} \rfloor),\mathcal P)$ such that $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$ and $\mathcal P := \{P_1, \ldots, P_t\}$ is a~partition of~$V(H)$ into $t := \lfloor n^{2/3} \rfloor$ independent sets of~$H$.
  Here we need to be more delicate than in the proof of~\cref{thm:hardness-coloring} in upper bounding the chromatic number of~$G$.
  We will rely on~\cref{obs:m-to-degen} and the Cauchy--Schwarz inequality.

  For every $i \in [t]$, let $a_i$ be the number of edges in~$G[P_i]$.
  As $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$, \[\sum\limits_{i \in [t]} a_i \leqslant n^{\frac{4}{3}-\beta}.\]
  By~\cref{obs:m-to-degen}, $G[P_i]$ can be properly colored with at~most $\lceil \sqrt{2a_i} \rceil$ colors.
  Hence the chromatic number of~$G$ is at~most
  $$\sum\limits_{i \in [t]} \lceil \sqrt{2a_i} \rceil \leqslant \sum\limits_{i \in [t]} (\sqrt{2a_i}+1) \leqslant t + \sqrt 2 \sum\limits_{i \in [t]} \sqrt{a_i}.$$
  In $\mathbb R^t$, the Cauchy--Schwarz inequality is that
  \[ \left( \sum\limits_{i \in [t]} x_iy_i \right)^2 \leqslant \left( \sum\limits_{i \in [t]} x_i^2 \right) \left( \sum\limits_{i \in [t]} y_i^2 \right).\]
  Setting $x_i := \sqrt{a_i}$ and $y_i := 1$, we get that
  $$\chi(G) \leqslant t + \sqrt 2 \sqrt{\left( \sum\limits_{i \in [t]} \sqrt{a_i}^2 \right) \left( \sum\limits_{i \in [t]} 1^2 \right)}
  =  t + \sqrt {2 t \left( \sum\limits_{i \in [t]} a_i \right)} \leqslant t + \sqrt{2 t \cdot  n^{\frac{4}{3}-\beta}}.$$
  Thus $$\chi(G) \leqslant \lfloor n^{2/3} \rfloor + \sqrt{2} \cdot n^{1/3} \cdot n^{\frac{2}{3}-2\varepsilon} \leqslant \lfloor n^{2/3} \rfloor + \sqrt{2} n^{1-2\varepsilon} < n^{1-\varepsilon},$$
  for large enough~$n$.
  And we can conclude that $\chi(G) \leqslant n^\varepsilon$.

  We now assume that the algorithm returns instead $((H, \lfloor n^{2/3} \rfloor),\nil)$ such that $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$ and $\chi(H) > n^{2/3}$.
  We claim that $\chi(G) > n^\varepsilon$.
  Suppose for the sake of contradiction that there is a~partition $\mathcal Q := \{Q_1, \ldots, Q_s\}$ of $V(G)$ into $s := \lfloor n^\varepsilon \rfloor$ independent sets of~$G$.
  For every $i \in [s]$, let $b_i$ be the number of edges in $H[Q_i]$.
  As $\diste(G,H) \leqslant n^{\frac{4}{3}-\beta}$, $\sum_{i \in [s]} b_i \leqslant n^{\frac{4}{3}-\beta}$.
  By~\cref{obs:m-to-degen}, we have $\chi(H) \leqslant \sum_{i \in [s]} \lceil \sqrt{2 b_i} \rceil$.
  A~similar application of the Cauchy--Schwarz inequality with $x_i := \sqrt{b_i}$ and $y_i := 1$ yields
  $$ \chi(H) \leqslant s + \sqrt{2 s \cdot  n^{\frac{4}{3}-\beta}} \leqslant \lfloor n^\varepsilon \rfloor + \sqrt{2} \cdot n^{\varepsilon/2} \cdot n^{\frac{2}{3}-2\varepsilon} = \lfloor n^\varepsilon \rfloor + \sqrt{2} \cdot n^{\frac{2}{3}-\frac{3 \varepsilon}{2}} < n^{2/3},$$
  for large enough~$n$; a~contradiction to~$\chi(H) > n^{2/3}$.
  Hence, we can conclude that $\chi(G) \leqslant n^{1-\varepsilon}$ holds.
\end{proof}

One can extend \cref{thm:hardness-coloring,thm:hardness-coloring-diste} to \textsc{Clique Cover} by~\cref{thm:lpi}.
This finishes the proof of~\cref{thm:1/2-4/3}.

