}
\newcommand{\SecProblemDefinitionEqTwo}{
\begin{align}
    \label{eq:dominance and strong dominance relation}
    \begin{aligned}
        \bs{x} \dominateeq \bs{y} & \Leftrightarrow \forall i, f_{i}(\bs{x}) \leq f_{i}(\bs{y}) \land \exists j, f_{j}(\bs{x}) < f_{j}(\bs{y}),\\
        \bs{x} \dominate \bs{y} & \Leftrightarrow \forall i, f_{i}(\bs{x}) < f_{i}(\bs{y}).
    \end{aligned}
\end{align}
}
\newcommand{\SecProblemDefinitionEqThree}{
\begin{align}
    \label{eq:normalized multi-objective function optimization problem}
    \begin{aligned}
        \bs{f}'(\bs{x}) &= (f'_1(\bs{x}), f'_2(\bs{x}), \dots, f'_m(\bs{x}))^\T, \\
        f'_{i}(\bs{x}) &= \frac{f_{i}(\bs{x}) - z^{\text{ideal}}_{i}}{z^{\text{nadir}}_{i} - z^{\text{ideal}}_{i}}, \\
        z^{\text{nadir}}_{i} &= \max_{\bs{x} \in \PS} f_{i}(\bs{x}), ~ z^{\text{ideal}}_{i} = \min_{\bs{x} \in \PS} f_{i}(\bs{x}).
    \end{aligned}
\end{align}
}

