        \IF {$\exists \bs{x}^{\text{tch}}, \bs{x}^{\text{tch}} \dominateeq \bs{x}^{\text{mtch}} \land \nexists \bs{x}^{\text{tch}}, \bs{x}^{\text{mtch}} \dominateeq \bs{x}^{\text{tch}},$\\\hspace{15pt}$\bs{x}^{\text{tch}} \in X^{\text{tch}}, \bs{x}^{\text{mtch}} \in X^{\text{mtch}} $}
            \STATE $X_{0}^{*} = X^{\text{tch}}$
        \ELSIF {$\exists \bs{x}^{\text{mtch}}, \bs{x}^{\text{mtch}} \dominateeq \bs{x}^{\text{tch}} \land \nexists \bs{x}^{\text{mtch}}, \bs{x}^{\text{tch}} \dominateeq \bs{x}^{\text{mtch}},$\\\hspace{34pt}$\bs{x}^{\text{tch}} \in X^{\text{tch}}, \bs{x}^{\text{mtch}} \in X^{\text{mtch}} $}
            \STATE $X_{0}^{*} = X^{\text{mtch}}$
        \ELSE
            \STATE $X_{0}^{*} = \argmax_{X \in \{X^{\text{tch}}, X^{\text{mtch}}\}} V\left(X\right)$
        \ENDIF
    \end{algorithmic}
\end{algorithm}


