% The size of the address set and the initial target point set is given by $|A| = |T^{0}| = \frac{\left(n_{\text{div}} + m - 1\right)!}{n_{\text{div}}! \left(m-1\right)!}$ depending on the number of divisions $n_{\text{div}}$.
% This is the size of the approximate solution set constructed by the proposed method.
The address set $A$ is defined by
\begin{align}
    \label{eq:step2 address set}
    \begin{aligned}
        A &= \left\{ \bs{a} \middle|
            \begin{aligned}
                &\bs{a} \in [0, 1]^{m}, \bs{a} = \frac{1}{n_{\text{div}}} \bs{a}', \bs{a}' = \left(a'_{1}, \ldots, a'_{m}\right)^{\T}, \\
                &a'_{i} \in \N_{\ge 0}, \sum_{i=1}^{m} a'_{i} = n_{\text{div}},
            \end{aligned} \right\},
    \end{aligned}
\end{align}
where $n_{\text{div}}$ is a user parameter representing the number of divisions, and $\N_{\ge 0}$ is the set of non-negative integers.
The $d$-dimensional face address set $A_{d}$ is defined by
\begin{align}
    \label{eq:step2 d-dimensional address set}
    \begin{aligned}
        A_{d} &= \left\{ \bs{a} \in A \middle| \sum_{i = 1}^{m} \delta \left(a'_{i}\right) = m - n - 1 \right\}, \\
        \delta \left(a'_{i}\right) &= \left\{ \begin{aligned}
            &1, &a'_{i} = 0, \\
            &0, &\text{otherwise}.
        \end{aligned}
        \right.
    \end{aligned}
\end{align}
The initial target point set $T^{0}$ is constructed by using the address set $A$ and the affine matrix $\bs{B}$ as follows:
\begin{align}
    \label{eq:step2 initial target point}
    \begin{aligned}
        T^{0} &= \left\{ \bs{t}_{\bs{a}}^{0} | \bs{t}_{\bs{a}}^{0} = \bs{B} \bs{a}, \bs{a} \in A \right\}, \\
        \bs{B} &= \left( \bs{\pi}\left(\bs{f}'\left(\bs{x}_{\bs{a}^{0}_{1}}^{*}\right)\right), \ldots , \bs{\pi}\left(\bs{f}'\left(\bs{x}_{\bs{a}^{0}_{1}}^{*}\right)\right) \right),~ \bs{x}_{\bs{a}^{0}_{i}}^{*} \in X_{0}^{*}.
    \end{aligned}
\end{align}
The size of the address set and the initial target point set is given by $|A| = |T^{0}| = \frac{\left(n_{\text{div}} + m - 1\right)!}{n_{\text{div}}! \left(m-1\right)!}$.


\subsection{Step3: Pareto Front Boundary Search for 1 to (m-2)-dimensional Faces}
\label{subsec:step3}

\begin{figure}[tb]
    \centering
    \includegraphics[keepaspectratio, width=40mm]{figure/pareto_front_boundary_search.pdf}
