    \caption{Pareto front boundary search in a 3-objective problem. The red line is the image of the Pareto front boundary on the target hyperplane, and the red points are the target points generated during the search.}
    \label{fig:pareto front boundary search}
\end{figure}

\begin{algorithm}[tb]
    \caption{ParetoFrontBoundarySearch}
    \label{algorithm:Pareto front boundary search}
    \begin{algorithmic}[1]
        \REQUIRE $\bs{f}'$, $o_{\text{NES}}$, $\bs{t}_{\bs{a}^{d}_{i}}^{0}$, $\epsilon_{t}$
        \ENSURE $\bs{t}^{*}_{\bs{a}^{d}_{i}}, \bs{x}^{*}_{\bs{a}^{d}_{i}}$

        % \IF {$m \equiv 0 \mod 2$}
        %     \STATE $r_{T} = \frac{\sqrt{m}}{2}$
        % \ELSE
        %     \STATE $r_{T} = \frac{1}{2} \sqrt{\frac{m^{2} - 1}{m}}$
        % \ENDIF
        % \STATE $\bs{t}^{\text{head}} = \bs{c} = \pi \left(\bs{0}\right)$
        % \STATE $\bs{t}^{\text{tail}} = \bs{c} + r_{T} \frac{\bs{t}_{\bs{a}^{d}_{i}}^{0} - \bs{c}}{||\bs{t}_{\bs{a}^{d}_{i}}^{0} - \bs{c}||}$
        \STATE Determine $\bs{t}^{\text{head}}$ and $\bs{t}^{\text{tail}}$ by Eq.(\ref{eq:step3 head and tail})
        \WHILE {}
            \STATE $\bs{t}^{\text{mid}} = \frac{1}{2} \left(\bs{t}^{\text{head}} + \bs{t}^{\text{tail}}\right)$
            \IF {$|| \bs{t}^{\text{head}} - \bs{t}^{\text{mid}} || < \epsilon_{t}$}
                \STATE {\bf break}
            \ENDIF
            \STATE $\bs{x}' = o_{\text{NES}} \circ s^{\text{tptd}}\left(\bs{x} | \bs{f}', \bs{t}^{\text{mid}}\right)$
            % \IF {$\left| \left| \bs{f}'\left(\bs{x}'\right) - \bs{t}^{\text{mid}} - \frac{\sum_{i = 1}^{m} \left(f'_{i}\left(\bs{x}'\right) - t^{\text{mid}}_{i}\right) }{m} \bs{1}  \right| \right| \leq \epsilon_{t}$}
            \IF {$\left| \left| \bs{f}'\left(\bs{x}'\right) - \bs{t}^{\text{mid}} - \frac{\sum_{i = 1}^{m} \left(f'_{i}\left(\bs{x}'\right) - t^{\text{mid}}_{i}\right) }{m} \bs{1}  \right| \right| \leq \epsilon_{t}$}
                \STATE $\bs{t}^{\text{head}} = \bs{t}^{\text{mid}}$
                \STATE $\bs{t}^{*}_{\bs{a}^{d}_{i}} = \bs{t}^{\text{mid}}$
                \STATE $\bs{x}^{*}_{\bs{a}^{d}_{i}} = \bs{x}'$
            \ELSE
                \STATE $\bs{t}^{\text{tail}} = \bs{t}^{\text{mid}}$
            \ENDIF
        \ENDWHILE

    \end{algorithmic}
\end{algorithm}

