    \label{eq:guide point}
    \begin{aligned}
        \bs{t}^{*}_{\bs{a}^{m-1}_{i}} &= \bs{t}^{0}_{\bs{a}^{m-1}_{i}} + \eta \sum_{\bs{a}_{g} \in G_{\bs{a}^{m-1}_{i}}} \left( \bs{t}^{*}_{\bs{a}_{g}} - \bs{t}^{0}_{\bs{a}_{g}} \right).
    \end{aligned}
\end{align}
Where, $\eta$ is a user parameter for controlling the amount of movement and $G_{\bs{a}^{m-1}_{i}}$ is called the guide point set and defined by
\begin{align}
    \begin{aligned}
        G_{\bs{a}^{m-1}_{i}} &= \left\{
            \begin{aligned}
                & \emptyset, &\sum_{j=1}^{m} \zeta\left(a_{i,j}^{m-1}\right) = m, \\
                &G_{\bs{a}^{m-1}_{i}}^{\text{vertex}}, &\sum_{j=1}^{m} \zeta\left(a_{i,j}^{m-1}\right) \ge 2, \\
                &G_{\bs{a}^{m-1}_{i}}^{\text{other}}, &\text{otherwise}.
            \end{aligned}
        \right.\\
        \zeta\left(a_{i,j}^{m-1}\right) &= \left\{
            \begin{aligned}
                &1, &a_{i,j}^{m-1} = \min_{j \in \{1, \ldots, m\}} a_{i,j}^{m-1}, \\
                &0, &\text{otherwise},
            \end{aligned}
        \right. \\
        G_{\bs{a}^{m-1}_{i}}^{\text{vertex}} &= \left\{\bs{a}^{k} = \left(a^{k}_{1}, \ldots, a^{k}_{m}\right)^{\T} \middle| \begin{aligned}
            &k \in \{1, \ldots, m\} \backslash \{l\}, \\
            &l = \argmax_{j} a_{i,j}^{m-1}
        \end{aligned} \right\}, \\
        a^{k}_{j} &= \left\{
            \begin{aligned}
                &a_{j} + \frac{1}{n_{\text{div}}}, ~&j = l, \\
                &a_{j} - \frac{1}{n_{\text{div}}}, &j = k, \\
                &a_{j}, &\text{otherwise}.
            \end{aligned}
        \right.\\
        G_{\bs{a}^{m-1}_{i}}^{\text{other}} &= \left\{ \bs{a}^{q} = \left(a^{q}_{1}, \ldots, a^{q}_{m}\right)^{\T} \middle| \begin{aligned}
            &p \in \{1, \ldots, m\} \backslash \{q\},\\
            &q = \argmin_{j} a_{i,j}^{m-1}
        \end{aligned} \right\},\\
        a^{q}_{j} &= \left\{
            \begin{aligned}
                &a_{j} - \frac{1}{n_{\text{div}}}, ~&j = q, \\
                &a_{j} + \frac{1}{n_{\text{div}}}, &j = p, \\
                &a_{j}, &\text{otherwise}.
            \end{aligned}
        \right.
    \end{aligned}
\end{align}

Next, the $(m-1)$-dimensional face approximate solution set $X_{m-1}^*$ is searched by NES using TPTD with $T_{m-1}^*$.




\subsection{Algorithm}
\label{subsec:algorithm}

% \left(初稿\right)
% 提案手法のアルゴリズムをAlgorithm.\ref{algorithm:proposed method}に示す．
% 提案手法は目的関数$\bs{f}$，自然進化戦略$o_{\text{NES}}$，分割数$n_{\text{div}}$，パレートフロントに評価値が存在するか判定用するためのパラメータ$\epsilon_{t}$，再配置の移動量制御用パラメータ$\eta$を入力とし，近似解集合$X^{*}$を出力する．
% 1行目でStep1の$0$次元面探索を実行し，$0$次元面近似集合$X_{0}^{*}$を得る．
% 2行目で正規化目的関数$\bs{f}'$を構築する．
% 3から5行目でStep2のアドレス集合と初期目標点集合を初期化する．
% 6行目で近似解集合$X^{*}$を初期化する．
% 7行目で目的数による場合分けを行い，目的数$m = 2$の場合は8から11行目で初期目標点による$1$次元面探索を行い終了する．
% $m \ge 3$の場合は13から29行目のStep3,Step4を実行する．
% 13行目で確定した目標点の集合$T^{*}$を初期化する．
% 14から20行目でStep3の$1, \ldots, m-2$次元面のパレートフロント境界探索を実行する．
% 21から29行目でStep4の$m-1$次元面探索を実行する．
% 8から11行目，14から20行目，26から29行目は各目標点に対して独立に実行する並列化が可能であることに注意されたい．

The algorithm of the proposed method is shown in Algorithm \ref{algorithm:proposed method}.
The proposed method takes the objective function $\bs{f}$, the NES $o_{\text{NES}}$, the number of divisions $n_{\text{div}}$, the parameter $\epsilon_\text{t}$ for determining whether the objective vector exists on the Pareto front, and the parameter $\eta$ for controlling the amount of movement in the relocation as input, and outputs the approximate solution set $X^{*}$.
Line 1 executes the $0$-dimensional face search in Step 1 and obtains the $0$-dimensional face approximate set $X_{0}^{*}$.
Line 2 constructs the normalized objective function $\bs{f}'$.
Lines 3-5 initialize the address set, $d$-dimensional face address set and the initial target point set in Step 2.
Line 6 initializes the approximate solution set $X^{*}$.
Lines 8-11 executes the $1$-dimensional face search with the initial target points if the number of objectives is $m = 2$.
Lines 13-29 execute Steps 3 and 4 if $m \ge 3$.
Line 13 initializes the set of determined target points $T^{*}$.
Lines 14-20 execute the Pareto front boundary search for $1, \ldots, (m-2)$-dimensional faces in Step 3.
Lines 21-29 execute the $(m-1)$-dimensional face search in Step 4.
Note that lines 8-11, 14-20, and 26-29 can be executed independently for each target point, and can be parallelized.

\begin{algorithm}[tb]
    \caption{ProposedMethod}
    \label{algorithm:proposed method}
    \begin{algorithmic}[1]
        \REQUIRE $\bs{f}$, $o_{\text{NES}}$, $n_{\text{div}}$, $\epsilon_{t}$, $\eta$
        \ENSURE $X^{*}$

        \STATE $X_{0}^{*} =$ Search$0$-dimensionalFaces$\left(\bs{f}, o_{\text{NES}}\right)$
        % \FOR {$i = 1$ {\bf to} $m$}
        %     \STATE $f_{i}^{\text{max}} = \max_{\bs{x} \in X_{0}} f_{i}\left(\bs{x}\right)$
        %     \STATE $f_{i}^{\text{min}} = \min_{\bs{x} \in X_{0}} f_{i}\left(\bs{x}\right)$
        %     \STATE $f'_{i}\left(\bs{x}\right) = \frac{f_{i}\left(\bs{x}\right) - f_{i}^{\text{min}}}{f_{i}^{\text{max}} - f_{i}^{\text{min}}}$
        % \ENDFOR
        % \STATE $\bs{f}'\left(\bs{x}\right) = \left(f'_{1}\left(\bs{x}\right), \ldots, f'_{m}\left(\bs{x}\right)\right)^{\T}$
        \STATE Determine $\bs{f}'$ according to Eq.(\ref{eq:step1 normalized objective function})

        % \STATE $A = \left\{ \bs{a} \middle|
        %     \begin{aligned}
        %         &\bs{a} \in [0, 1]^{m}, \bs{a} = \frac{1}{n_{\text{div}}} \bs{a}', \bs{a}' = \left(a'_{1}, \ldots, a'_{m}\right)^{\T}, \\
        %         &a'_{i} \in \N_{\ge 0}, \sum_{i=1}^{m} a'_{i} = n_{\text{div}}
        %     \end{aligned} \right\}.$
        % \STATE $\bs{B} = \left( \bs{\pi}\left(\bs{f}'\left(\bs{x}_{0, 1}^{*}\right)\right), \ldots , \bs{\pi}\left(\bs{f}'\left(\bs{x}_{0, m}^{*}\right)\right) \right),~ \bs{x}_{0, i}^{*} \in X_{0}^{*}$
        % \STATE $T^{0} = \left\{ \bs{t}_{\bs{a}}^{0} | \bs{t}_{\bs{a}}^{0} = \bs{B} \bs{a}, \bs{a} \in A \right\}.$
        \STATE Determine $A$ according to Eq.(\ref{eq:step2 address set})
        \STATE Determine $A_{d}, ~ d = 1, \ldots, m-1$ according to Eq.(\ref{eq:step2 d-dimensional address set})
        \STATE Determine $T^{0}$ according to Eq.(\ref{eq:step2 initial target point})

        \STATE $X^{*} = X_{0}^{*}$
        \IF {$m = 2$}
            \FOR {$\bs{a}^{1}_{i} \in A_{1}$}
                \STATE $\bs{x}^{*}_{\bs{a}^{1}_{i}} = o_{\text{NES}} \circ s^{\text{tptd}}\left(\bs{x} | \bs{f}', \bs{t}^{0}_{\bs{a}^{1}_{i}}\right)$
                \STATE $X^{*} = X^{*} \cup \{ \bs{x}^{*}_{\bs{a}^{1}_{i}} \}$
            \ENDFOR
        \ELSE
            \STATE $T^{*} = \emptyset$
            \FOR {$d = 1$ {\bf to} $m - 2$}
                \FOR {$\bs{a}^{d}_{i} \in A_{d}$}
                    \STATE $\bs{t}^{*}_{\bs{a}^{d}_{i}}, \bs{x}^{*}_{\bs{a}^{d}_{i}} =$ParetoFrontBoundary\\\hspace{60pt}Search$\left(\bs{f}', o_{\text{NES}}, \bs{t}^{0}_{\bs{a}^{d}_{i}}, \epsilon_{t}\right)$
                    \STATE $T^{*} = T^{*} \cup \{ \bs{t}^{*}_{\bs{a}^{d}_{i}} \}$
                    \STATE $X^{*} = X^{*} \cup \{ \bs{x}^{*}_{\bs{a}^{d}_{i}} \}$
                \ENDFOR
            \ENDFOR

            \FOR {$\bs{a}^{m-1}_{i} \in A_{m-1}$}
                \STATE Determine $G_{\bs{a}^{m-1}_{i}}$ according to Eq.(\ref{eq:guide point set})
                \STATE $\bs{t}^{*}_{\bs{a}^{m-1}_{i}} = \bs{t}^{0}_{\bs{a}^{m-1}_{i}} + \eta \sum_{\bs{a}_{g} \in G_{\bs{a}^{m-1}_{i}}} \left( \bs{t}^{*}_{\bs{a}_{g}} - \bs{t}^{0}_{\bs{a}_{g}} \right).$
