            \ENDFOR
            \FOR {$\bs{a}^{m-1}_{i} \in A_{m-1}$}
                \STATE $\bs{x}^{*}_{\bs{a}^{m-1}_{i}} = o_{\text{NES}} \circ s^{\text{tptd}}\left(\bs{x} | \bs{f}', \bs{t}_{\bs{a}^{m-1}_{i}}^{*}\right)$
                \STATE $X^{*} = X^{*} \cup \{ \bs{x}^{*}_{\bs{a}^{m-1}_{i}} \}$
            \ENDFOR
        \ENDIF

        % For文を目標点調整と探索に分ける．
    \end{algorithmic}
