\title{
Interactive Process Improvement Using Simulation of Enriched Process Trees}
%\thanks{\scriptsize Funded by the Deutsche Forschungsgemeinschaft (DFG, German Research Foundation) under Germany's Excellence Strategy – EXC 2023 Internet of Production- Project ID: 390621612. We also thank the Alexander von Humboldt (AvH) Stiftung for supporting our research.}
\titlerunning {Interactive Process Improvement}
\author{Mahsa Pourbafrani \and 
Wil M. P. van der Aalst}
\authorrunning{M. Pourbafrani and Wil M. P. van der Aalst}
\institute{Chair of Process and Data Science, RWTH Aachen University, Germany \\
 \email{\{mahsa.bafrani, wvdaalst\}@pads.rwth-aachen.de}\\
