\noindent\textbf{6. } \vtextbf{migrate\_pages2().} Our custom implementation (cf. Listing~\ref{lst:migrate_pages2}) enables the DBMS to override the default Linux migration mode, i.e., \verb|MIGRATE_SYNC|. For the \verb|MIGRATE_SYNC| mode, the kernel follows the default blocking path (Line~\ref{mig:choose_mode1}). Consequently, for the rest of the migration modes, the kernel follows the non-blocking path (Line~\ref{mig:choose_mode2}). Beyond the default Linux path, the DBMS now has more precise control over the migration process through different variants of the synchronous migration mode, i.e., \verb|MIGRATE_SYNC_LIGHT| and \verb|MIGRATE_SYNC_NO_COPY|, depending on the workload requirements.
We further extend the functionality of the native \verb|migrate_pages| kernel function by letting the DBMS choose the batch size during 
migration 
% the \verb|MIGRATE_ASYNC| mode 
(Lines~\ref{mig:cut_1},~\ref{mig:cut_2}). 


\begin{lstlisting}[
    caption={Code snippet of \texttt{migrate\_pages2}. 
    % in \texttt{move\_pages2}. 
    The modifications introduced over the original implementation are highlighted.}, 
    label={lst:migrate_pages2}
]
int migrate_pages2(struct list_head *from, new_folio_t get_new_folio, free_folio_t put_new_folio, unsigned long private, @enum migrate_mode mode@, int reason, unsigned int *ret_succeeded, int @nr_max_batched_migration@)
{
again:
  nr_pages = 0;
  // Iterate over the pages in "from"
  list_for_each_entry_safe(folio, folio2, from, lru) { 
    nr_pages += folio_nr_pages(folio);
    if (nr_pages >= @nr_max_batched_migration@) break;(*|\label{mig:cut_1}|*)
  }
  // Divide the pages in "from" into smaller 
  // sub-groups, i.e., "folios" 
  if (nr_pages >= @nr_max_batched_migration@)(*|\label{mig:cut_2}|*)
    list_cut_before(&folios, from, &folio2->lru);
  else
    list_splice_init(from, &folios);
  // Migrate the pages in the sub-group, i.e., "folios"
  @if (migration_mode == MIGRATE_SYNC)(*|\label{mig:choose_mode1}|*)
    rc = migrate_pages_sync(&folios, get_new_folio,
          put_new_folio, private, MIGRATE_SYNC, reason,
          &ret_folios,&split_folios, &stats); 
  else(*|\label{mig:choose_mode2}|*)
    rc = migrate_pages_batch(&folios, get_new_folio,
          put_new_folio, private, mode, reason, 
          &ret_folios, &split_folios, &stats, 
          NR_MAX_MIGRATE_PAGES_RETRY);@
  // Store the non-migrated pages in "ret_folios" for potential retries
  list_splice_tail_init(&folios, &ret_folios);  
  if (rc < 0) {
    rc_gather = rc;
    list_splice_tail(&split_folios, &ret_folios);
    goto out;
  }
  rc_gather += rc;
  // Prepare the next "folios"
  if (!list_empty(from)) 
    goto again;
 out:
  // Move back the non-migrated pages in the current 
  // migration round to "folios" for potential 
  // retry in the next migration round
  list_splice(&ret_folios, from); 
  if (list_empty(from)) 
    rc_gather = 0;
  return rc_gather;
}
\end{lstlisting}

