\end{align*}
where $\mathbf 1(\cdot)$ is the indicator function, i.e., $\mathbf 1(\text{true})=1$ and $\mathbf 1(\text{false})=0$. For simplicity, we will omit $t$ when $t=0$ and denote $(\bm s,0)\models\varphi$ as $\bm s\models\varphi$.
