\subsection{The Task Allocation and Coordination Problem}
Our goal is to find the joint selection vector $\mathbf z$ and the joint temporal profile $\bm\sigma$ that satisfy a given RP-STL specification $\varphi$ and minimizes a given cost function. Let a time-stamped joint progress (TSJP) be a pair $(t_k, \bm \sigma_{(k)})$, where $k \in \{0,1,\ldots,K\}$,  $t_k\in[0,T]$ is a time stamp and $\bm \sigma_{(k)} = [\sigma_{1,(k)},\ldots, \sigma_{N,(k)}]\in\mathbb R_{\geq0}^N$ is a corresponding joint progress. Note that we use bold font and parentheses on $k$ to distinguish $\bm\sigma_{(k)}$ from $\sigma_i$, the latter being the temporal profile of $r_i$. Instead of searching for an accurate joint temporal profile over all possible functions over time, we search for a set of joint temporal profiles constructed from a sequence of TSJPs $\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K$, where $t_k$ is the $k$-th time stamp and $\bm \sigma_{(k)}$ is the $k$-th joint progress, $0=t_0<t_1<\ldots<t_K\leq T$, $\bm 0=\bm \sigma_{(0)}\leq\bm \sigma_{(1)}\leq\ldots\leq\bm \sigma_{(K)}=[[g_1^1,\ldots,g_1^{M_1}]\cdot\mathbf z_1, \ldots, [g_N^1,\ldots,g_N^{M_N}]\cdot\mathbf z_N]$. Note that the equality and inequality signs for $\bm \sigma_{(k)}$ are interpreted element-wise. Specifically, given a sequence of TSJPs and an $\epsilon>0$, we construct a set of joint temporal profiles as
\vspace{-3pt}
\begin{equation}
    \label{eq:S}
    \begin{aligned}
        \mathcal S_\epsilon\Big(\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\Big) &:= \\
        \{\bm\sigma\ |\ \bm\sigma(t_k) &\in B_\infty(\bm \sigma_{(k)},\epsilon),\ k=0,\ldots,K\}.
    \end{aligned}
\end{equation}
Now, our goal becomes finding a joint selection vector $\mathbf z$ and a sequence of TSJPs $\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K$ such that $\forall \bm\sigma\in\mathcal S_\epsilon\big(\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\big)$, $[\mathbf z,\bm\sigma]\models\varphi$, and a cost is minimized.

Since the robots cannot make progress arbitrarily fast, we add the following constraint on the TSJPs for all robots $r_i$:
\begin{equation}
    \label{eq:vmax}
        |\sigma_{i,(k+1)} - \sigma_{i,(k)}|\leq v^{max}_{i}\cdot(t_{k+1}-t_k), k=0,\ldots,K-1,
\end{equation}
where $v^{max}_{i}\in\mathbb R_{\geq0}$ is the maximum speed %on making progress 
for robot $i$, which is assumed to be a constant for different paths of a same robot, but can be different for different robots.
\begin{comment}
Since robots can reach their goals asynchronously, we define the travel time of robot $i$ as:
\begin{equation}
    \label{eq:travel-time}
    T^{(i)} = \inf \{t_k^{(i)}\ |\ s_k^{(i)}=1\},
\end{equation}
which is the first time stamp that the progress of robot $i$ reaches $1$.
\end{comment}
Now we formally state the task allocation and coordination problem.
\begin{problem}
\label{pb}
    Consider a set of $N$ robots. Given a set of reference paths $\{p_i^j\}_{j=1}^{M_i}$ for each robot $r_i$ and an RP-STL specification $\varphi$, find the joint selection vector $\mathbf z$ and a sequence of TSJPs $\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K$ such that $\forall \bm\sigma\in\mathcal S_\epsilon\big(\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\big)$, $[\mathbf z,\bm\sigma]\models\varphi$, and a cost $\mathcal L$ is minimized:
\begin{equation}
    \label{eq:optimization}
    \begin{aligned}
        &\min_{\mathbf z, \{(t_k, \bm \sigma_{(k)})\}_{k=0}^K}\ \mathcal L(\mathbf z, \{(t_k, \bm \sigma_{(k)})\}_{k=0}^K) \\
        &\hspace{+10pt}\text{s.t. } [\mathbf z,\bm \sigma]\models \varphi,\ \forall\bm\sigma\in\mathcal S_\epsilon\big(\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\big),\\
        &\hspace{+10pt}\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\ \text{satisfies}\ \eqref{eq:vmax}, \mathbf z \ \text{satisfies}\  \eqref{eq:milp-ta}.
    \end{aligned}
    \vspace{+5pt}
\end{equation}
\end{problem}

Some examples of the cost function include the makespan $t_K$ or the sum of travel time $\sum_{i=1}^N T_i$ where
\begin{equation}
\label{eq:T_i}
    T_i = \inf \{t_k\ |\ \sigma_{i,(k)}=[g_i^1,\ldots,g_i^{M_i}]\cdot\mathbf z_i\}.
\end{equation}

\section{MILP-Based Solution}
\label{sec:milp}
We solve Problem~\ref{pb} by encoding \eqref{eq:optimization} into a Mixed-Integer Linear Program (MILP), which can be solved efficiently using off-the-shelf solvers such as Gurobi~\cite{gurobi}. 

To encode all constraints in \eqref{eq:optimization} as mixed-integers linear constraints, we first encode these constraints into a Linear and Counting Constraints Formula (LCCF), which is a logic sentence of atomic formulas connected by conjunctions, disjunctions, and counting operators. Each atomic formula is in the form of $\texttt{LE}\geq0$, where $\texttt{LE}$ is a linear expression of the continuous and binary variables, including the TSJPs and the selection vector. Second, we eliminate all the disjunctions and counting operators in the LCCF, which makes the LCCF a conjunction of mixed integer linear constraints. Finally, we add all these constraints into the MILP solver to find the solution. The encoding is inspired by \cite{sun2022multi}, which searches for a piece-wise linear path connecting time-stamped waypoints in the state space to satisfy STL specifications. Different from \cite{sun2022multi}, here we do not require linearity on the segments between TSJPs. We only assume the temporal profile for each robot is monotonically increasing.

\subsection{Constructing the LCCF}
\label{sec:lccf}
\noindent\paragraph{Selection vector encoding}
Since constraints \eqref{eq:milp-ta} are already in the form of $\texttt{LE}\geq0$, we just conjunct them together to form a single LCCF.

\paragraph{RP-STL encoding}
We inductively construct an LCCF that encodes the RP-STL formula $\varphi$ in \eqref{eq:optimization} by constructing an LCCF $z_k^{\varphi}$ for each segment between two adjacent TSJPs such that $z_k^{\varphi}$ is true if and only if $\forall t\in[t_k,t_{k+1}]$ and 
$\forall \bm\sigma\in\mathcal S_\epsilon\big(\{(t_k, \bm \sigma_{(k)})\}_{k=0}^K\big)$, $([\mathbf z,\bm \sigma],t)\models \varphi$. We refer to this property as the soundness property. Then $z_0^\varphi$ will be the LCCF we want. Specifically, $z_k^\varphi$ is recursively encoded as:
\begin{align}
\label{eq:z-mu}
    &z_k^{\mu_i} = (\sigma_{i,(k)}-\bm b_i^\top\bm z_i \geq \epsilon) \land (\sigma_{i,(k+1)}-\bm b_i^\top\bm z_i \geq\epsilon),\\
    \label{eq:z-cnt}
    &z_k^{(\{\varphi_l\}_{l=1}^L, m)} = (\sum_{l=1}^{L}\mathbf 1(z_k^{\varphi_l})\geq m),\\
    & \begin{aligned}
    z_k^{G_{[a,b]}\varphi} &= \bigwedge_{l=0}^{K-1} ([t_l,t_{l+1}]\\&\cap
    [t_k+a-\epsilon_t,t_{k+1}+b]\neq\emptyset\Rightarrow z_l^\varphi),
    \label{eq:z-always}\end{aligned}\\
    &\begin{aligned}z_k^{F_{[a,b]}\varphi} & = (t_{k+1}-t_k\leq b-a-\epsilon_t)\land \bigvee_{l=0}^{K-1} ([t_l,t_{l+1}]\\&\cap[t_{k+1}+a,t_k+b-\epsilon_t]\neq\emptyset\land z_l^\varphi),\label{eq:z-eventually}\end{aligned}
\end{align}
where $\epsilon_t$ is a positive value that adds robustness to the timimg, $\Rightarrow$ is the \emph{implication} operator defined as $\varphi_1\Rightarrow\varphi_2$ iff $\neg\varphi_1\lor\varphi_2$.
The construction laws for \emph{Until} (as a combination of \eqref{eq:z-always} and \eqref{eq:z-eventually}) and Boolean operators are omited and as reported in~\cite{sun2022multi}. 
By using %\eqref{eq:z-mu}-\eqref{eq:z-until},
these and \eqref{eq:z-mu}-\eqref{eq:z-eventually}, we can recursively construct $z_0^\varphi$ that encodes the entire formula $\varphi$.

