\section{Comparison with the assumptions in \citep{hehir2022consistent}}

\label{appendix:assumption}
In this section, we show that our assumptions in Section \ref{subsec:assumption} are at least as general as those in the previous work \citep{hehir2022consistent}. Specifically, any graph that yields a robust clustering result under their algorithm and analysis will also be robustly clustered by our algorithm. While their analysis is restricted to graphs generated from the stochastic block model (SBM) and the degree corrected block model (DCBM), our analysis and algorithm apply to any graph that is well-clustered and has a large minimum degree.

Equation (5.3) of \citep{hehir2022consistent} shows that when each community has size $\Omega(n)$, randomized response followed by standard spectral clustering results in a misclassification error of order $O(1)$, provided that the maximum connection probability between any two nodes is at least $\Omega(1/\sqrt{n})$. The degree distribution in such an SBM follows a binomial distribution, which can be approximated by a Gaussian distribution for large $n$. By that the minimum degree in these graphs is $\tilde{\Omega}(\sqrt{n})$ with probability at least $1 - 1/n$. Therefore, the SBM and DCBM considered in \citep{hehir2022consistent} satisfies Assumption (1).

Regarding Assumption (2), we can infer from \citep{JMLR:v22:20-391} that when the number of nodes $n$ is large, $p$ denotes the probability that two nodes within the same cluster are connected, and $q$ denotes the probability that two nodes from different clusters are connected, then the ratio 
$g = \frac{\lambda_2(B) + 1}{\lambda_3(B) + 1}$
is at least $\frac{2p}{p + q}$. Since typically $p \gg q$, this implies $g \approx 2$, indicating that the graphs generated from SBM satisfies the assumption. Empirically, any well-clustered graph---including those generated by the DCBM or similar models---tends to have a large $g$, and thus also satisfies this assumption.

Any well-clustered graph in which each cluster has size in 
 satisfies the conditions of Proposition \ref{prop:app_eigenvector_components}. Therefore, graphs generated from the SBM and other clustered models satisfy Assumption (3).

\section{Eigenvector components}
\label{appendix:eigenvector}
%\textbf{Note: } Spectral robustness of \citep{mukherjee2023robustness} 
%\[\eta(G)=\frac{\lambda_2}{\lambda_3^2} < 0.0072 \implies \frac{2\lambda_2}{\lambda_3^2} < 0.0144\implies \frac{\sqrt{2\lambda_2}}{\lambda_3} < 0.12\implies t=\frac{\phi}{\lambda_3} \le 0.12\]

In this section, we analyze the Laplacian matrix of the graph \( G \), defined as \( L = I - B \). For each \( i \), let \( \lambda_i(L) = 1 - \lambda_i(B) \). It follows that \( \lambda_i(L) \) is an eigenvalue of \( L \), and the eigenvalues are ordered as \( \lambda_1(L) \leq \dots \leq \lambda_n(L) \). Moreover, the eigenvector \( \mathbf{v}_i(B) \) associated with \( \lambda_i(B) \) is also an eigenvector of \( L \) corresponding to \( \lambda_i(L) \). For simplicity, throughout this section, we denote \( \lambda_i(L) \) by \( \lambda_i \) and \( \mathbf{v}_i(B) \) by \( \mathbf{v}_i = [v_{i,1}, \dots, v_{i,n}]^\intercal \).

%Let \( t = \frac{\alpha(G)}{\lambda_3} \). In this appendix, we assume that \( t \) is small, specifically \( t \leq 0.12 \). This assumption is commonly adopted in mathematical analyses of spectral clustering, as seen in \citep{peng2015partitioning}.

\begin{proposition}
	\label{prop:app_eigenvector_components}
    %Let $\lambda_2$ and $\lambda_3$ be the second and third smallest eigenvalues of the Laplacian $L=I-D^{-1}A$.
    %Suppose $x_2$ is an eigenvector of $\lambda_2$ and $\epsilon,c>0$ are constants such that:
    Assume that

    (i) Let $V(G)=A\sqcup B$ be a bipartition of $G$ with $v_{2,j} \ge 0$ for $v_j \in A$, $v_{2,j}\le 0$ for $v_j \in B$.
    Then, the cut $(A,B)$ has conductance $\phi$ satisfying $\phi/\lambda_3\le 0.12$.

    (ii) Let $\epsilon$ and $c$ be a constant. For a subset $S\subseteq V$ and vertex $v_j\in S$, let us call $v_j$ to be $(\epsilon, S)$-average if $d_j\ge \epsilon d(S)$, where $d(S)=\Vol(S)/|S|$ is the average degree of the vertices in $S$.
    Let $A_\epsilon$ and $B_\epsilon$ denote the set of $(\epsilon,A)$-average nodes of $A$ and $(\epsilon,B)$-average nodes of $B$, respectively.
    Assume that $|A_\epsilon|\ge c|A|$ and $|B_\epsilon|\ge c|B|$.




    Then,
    \begin{equation}
    \label{eq:app_prop_eigenvector_components_1}
        |v_{2,j}|\ge \left\{\begin{array}{cl}\frac{\epsilon^{1/2}c}4\cdot \sqrt{\frac{d_j}{nd(A)}} - 2\sqrt{\frac{\phi}{\lambda_3}}, & v\in A\\
        \frac{\epsilon^{1/2}c}4\cdot \sqrt{\frac{d_j}{nd(B)}} - 2\sqrt{\frac{\phi}{\lambda_3}}, & v\in B
        \end{array}\right.
    \end{equation}

    Consequently, for $v_j\in A_\epsilon\cup B_\epsilon$, which is at least $c$ fraction of the vertices of $G$, we have
    \begin{equation}
    \label{eq:app_prop_eigenvector_components_2}
    	|v_{2,j}|\ge \frac{\epsilon c}{4}\cdot \frac1{\sqrt n} - 2\sqrt{\frac{\phi}{\lambda_3}}.
    \end{equation}
\end{proposition}
\begin{proof}
    Let us define the normalized indicator variables
    \[g_A(j)=\left\{\begin{array}{cl}\frac{d_j^{1/2}}{\Vol(A)^{1/2}}, & v_j\in A\\ 0, & v_j \in B \end{array}\right.\text{ and } g_B(j)=\left\{\begin{array}{cl} 0, & v_j \in A\\\frac{d_j^{1/2}}{\Vol(B)^{1/2}}, & v_j\in B\end{array}\right..\]
    Let the vector $g_A = [g_A(1), \dots, g_A(n)]^\intercal$, $g_B = [g_B(1), \dots, g_B(n)]^\intercal$, and, for any vector $\mathbf{v}$, the Rayleign quotient of $\mathbf{v} = [x_1, \dots, x_n]^\intercal$, denoted by $\mathcal{R}(\mathbf{v})$, is $\frac{\mathbf{v}^\intercal L \mathbf{v}}{\mathbf{v}^\intercal \mathbf{v}}$. We show the following regarding the Rayleigh quotients $\mathcal R_L(g_A)$ and $\mathcal R_L(g_B)$.
    \begin{claim}
    \label{clm:app_Rayliegh_indicators}
        $\phi \ge \max\{\mathcal R_L(g_A), \mathcal R_L(g_B)\}$. 
    \end{claim}
    \textit{Proof of Claim~\ref{clm:app_Rayliegh_indicators}.}
    Observe that the Rayleigh quotient of $L$ satisfies,
    \begin{equation}
    \label{eq:app_Rayleigh_Laplacian}
        \mathcal R_L(\mathbf{v}) 
        = \frac{\mathbf{v}^\intercal L\mathbf{v}}{\mathbf{v}^\intercal \mathbf{v}}
        = 1 - \frac{\sum_{i=1}^n\sum_{j=1}^n \frac{a_{ij}}{d_i}x_ix_j}{\sum_{i=1}^n x_i^2} 
        = 1 - \frac{\sum_{\{i,j\}\in E} \left(\frac1{d_i}+\frac1{d_j}\right)x_ix_j}{\sum_{i=1}^nx_i^2}.
    \end{equation}

    Since $\|g_A\|^2=1$, we have
    \[
    \begin{aligned}
        \mathcal R_L(g_A)=1-\sum_{\{i,j\}\in E}\left(\frac1{d_i}+\frac1{d_j}\right)g_A(i)g_A(j)&=1-\sum_{\{i,j\}\in E(A)} \left(\frac1{d_i}+\frac1{d_j}\right)\cdot \frac{\sqrt{d_id_j}}{\Vol(A)}\\
        &\le 1 - \sum_{\{i,j\}\in E(A)}\frac{2}{\Vol(A)} = \frac{\Vol(A) - 2e(A)}{\Vol(A)}\\
        & = \frac{e(A,B)}{\Vol(A)} \le \phi.
    \end{aligned}
    \]
    Similarly, we have $\mathcal R_L(g_B)\le \phi$, completing the proof of Claim~\ref{clm:app_Rayliegh_indicators}.\hfill{$\blacksquare$}

    For the rest of the proof, let us denote $t:=\phi/\lambda_3$. Recall that $\mathbf{v}_1 = [1/\sqrt n, \ldots, 1/\sqrt n]^\intercal$.
    %Let $x_1 = (1/\sqrt n, \ldots, 1/\sqrt n)$ be the normalized eigenvector corresponding to eigenvalue $\lambda_1=0$ of $L$.
    We will make use of the following lemmas from the structure theorem (Theorem 3.1) of \citep{peng2015partitioning}, but with a different notation and error estimates.
    \begin{lemma}
    \label{lem:app_PengLem1}
        Let $\hat g_A$, $\hat g_B$ be the projections of $g_A$, $g_B$ onto the space spanned by the first two eigenvectors $\{\mathbf{v}_1, \mathbf{v}_2\}$ of $L$.
        Then, 
        \begin{equation}
            \max\{\|\hat g_A-g_A\|^2, \|\hat g_B-g_B\|^2\}\le t.
        \end{equation}
    \end{lemma}
    \textit{Proof of Lemma~\ref{lem:app_PengLem1}.}
    Let $\mathbf{v}_3,\ldots, \mathbf{v}_n$ be normalized eigenvectors of $\lambda_3,\ldots,\lambda_n$ of $L$.
    Say $g_A = \alpha_1 \mathbf{v}_1 + \cdots + \alpha_n \mathbf{v}_n$ and $g_B=\beta_1\mathbf{v}_1+\cdots+\beta_n\mathbf{v}_n$ are representations of $g_A$ and $g_B$ in the $L$-eigenbasis.
    Clearly $\hat g_A=\alpha_1\mathbf{v}_1+\alpha_2\mathbf{v}_2$ and $\hat g_B = \beta_1\mathbf{v}_1+\beta_2\mathbf{v}_2$.
    Then, note that as $\mathbf{v}^\intercal_i\mathbf{v}_j=0$ for every $i\neq j$, 
    \[\mathcal R_L(g_A) = \sum_{i=1}^n\alpha_i\mathbf{v}_i^\intercal\cdot L \cdot \sum_{i=1}^n\alpha_i\mathbf{v}_i=\sum_{i=1}^n \alpha_i^2 \mathbf{v}_i^\intercal L\mathbf{v}_i = \sum_{i=1}^n\alpha_i^2\lambda_i.\]
    But $\lambda_1=0$, leading us to $\mathcal R_L(g_A)\ge \alpha_2^2\lambda_2 + (\alpha_3^2+\cdots+\alpha_n^2)\lambda_3=\alpha_2^2\lambda_2 + \|\hat g_A-g_A\|^2\lambda_3\ge \|\hat g_A-g_A\|^2\lambda_3$.
    Thus, $\|\hat g_A-g_A\|^2\le \mathcal R_L(g_A)/\lambda_3 \le \phi/\lambda_3$ by Claim~\ref{clm:app_Rayliegh_indicators}.
    The proof for $\|\hat g_B-g_B\|^2$ is exactly analogous.\hfill{$\blacksquare$}

    One of the main ideas used in  \citep{peng2015partitioning} is that if $\hat g_A$ and $\hat g_B$ are independent, then $\text{Span}(\{\mathbf{v}_1, \mathbf{v}_2\})=\text{Span}(\{\hat g_A, \hat g_B\})$, implying that $\mathbf{v}_1$ and $\mathbf{v}_2$ can be written as linear combinations of the projected indicator vectors $\hat g_A$ and $\hat g_B$, say $\mathbf{v}_2 = \eta_1\hat g_A+\eta_2\hat g_B$, implying that $\|\mathbf{v}_2-\eta_1g_A-\eta_2g_B\|$ is small.

    Let us now continue with the argument.
    \begin{claim}
        \label{clm:app_LinearInd_indicatorprojections}
        $\hat g_A$ and $\hat g_B$ are linearly independent.
    \end{claim}
    \textit{Proof of Claim~\ref{clm:app_LinearInd_indicatorprojections}}.
    By Lemma~\ref{lem:app_PengLem1}, we have $\|\hat g_A\|^2\ge 1-t$ and $\|\hat g_B\|^2\ge 1-t$.
    On the other hand,
    \begin{equation}
    \label{eq:app_hat_gA-hat_gB-dotproduct}
    \begin{aligned}
        |\langle \hat g_A,\hat g_B\rangle| &= |\langle \hat g_A-g_A+g_A,\hat g_B-g_B+g_B\rangle| \\
        &\le |\langle \hat g_A-g_A, \hat g_B-g_B\rangle| + |\langle g_A,\hat g_B-g_B\rangle| + |\langle \hat g_A-g_A, g_B\rangle| \\
        & \le \|\hat g_A-g_A\|\|\hat g_B-g_B\|+\|\hat g_A-g_A\|+\|\hat g_B-g_B\|\\
        & \le t + 2\sqrt{t}.
    \end{aligned}
    \end{equation}
    Since $t\le0.12<\frac12(2-\sqrt3)$, we have $t+2\sqrt t < 1-t$, implying $|\langle \hat g_A, \hat g_B\rangle| < \|\hat g_A\|\|\hat g_B\|$.
    As this implies a strict inequality in the Cauchy-Schwarz inequality, we have $\hat g_A\nparallel \hat g_B$.\hfill{$\blacksquare$}

    As discussed earlier, Claim~\ref{clm:app_LinearInd_indicatorprojections} implies that there exist $\eta_1,\eta_2\in\mathbb R$ such that $\mathbf{v}_2 = \eta_1\hat g_A + \eta_2\hat g_B$.
    Suppose $\mathbf{v}'_2 = \eta_1g_A+\eta_2g_B$, and $\eta=\|\mathbf{v}'_2\|=\sqrt{\eta_1^2+\eta_2^2}$.
    Note that, using (\ref{eq:app_hat_gA-hat_gB-dotproduct}),
    \[
    \begin{aligned}
    1 = \|\mathbf{v}_2\|^2 & \ge \eta_1^2\|\hat g_A\|^2 + \eta_2^2\|\hat g_B\|^2 - 2|\eta_1\eta_2\langle \hat g_A, \hat g_B\rangle| \\
    & \ge \eta_1^2(1-t) + \eta_2^2(1-t) - (\eta_1^2+\eta_2^2) (t+2\sqrt t)\\
    & = \eta^2(1-2t-2\sqrt{t}).
    \end{aligned}
    \]
    Moreover, since $t\le 0.12$, we have
    \begin{equation}
        \label{eq:app_eta_bounds}
        \eta^2 \le \frac{1}{1-2t-2\sqrt t} < 16.
    \end{equation}
    Moreover, by the triangle inequality and Cauchy-Schwarz inequality, 
    \begin{equation}
    \begin{aligned}
        \|\mathbf{v}_2-\mathbf{v}'_2\|^2 &= \|\eta_1(\hat g_A-g_A)+\eta_2(\hat g_B-g_B)\|^2 \\
        &\le \left(|\eta_1|\sqrt t+|\eta_2|\sqrt t\right)^2\\
        & \le 2t\eta^2
    \end{aligned}
    \end{equation}
    Therefore, we have that
    \[
    2\eta \langle \mathbf{v}_2, \textstyle\frac1\eta \mathbf{v}'_2\rangle=2\langle \mathbf{v}_2,\mathbf{v}'_2\rangle= \|\mathbf{v}_2\|^2+\|\mathbf{v}'_2\|^2-\|\mathbf{v}_2-\mathbf{v}_2'\|^2\ge 1+\eta^2-2t\eta^2,
    \]
    leading us to
    \begin{equation}
    \label{eq:app_projection_onto_x2}
        \langle \mathbf{v}_2, \textstyle\frac1\eta \mathbf{v}'_2\rangle\ge \frac{1+\eta^2}{2\eta} - \eta t \ge 1 - \eta t.
    \end{equation}

    Basically, this means that $\mathbf{v}_2$ is closely aligned with the normalized vector $\frac1\eta \mathbf{v}'_2$.
    We now show a lemma that relates the components of two such vectors.

    \begin{lemma}
        \label{lem:app_componentsEig}
        Let $\mathbf{v} = [u_1, \dots, u_n]^\intercal$ be a unit eigenvector of $L$ and $\mathbf{v}' = [u'_1, \dots, u'_n]^\intercal$ be any unit vector with $\langle \mathbf{v}, \mathbf{v}'\rangle \ge 1-\epsilon^2$ for some $\epsilon>0$.
        Then, for each $1\le j\le n$, we have
        \[
        |u'_j|\le |u_j|+\epsilon.
        \]
    \end{lemma}
    \textit{Proof of Lemma~\ref{lem:app_componentsEig}.}
    Let $\{\mathbf{v},\mathbf{z}_1,\ldots \mathbf{z}_{n-1}\}$ be a orthonormal basis of eigenvectors of $L$, and, for all $i$, let $\mathbf{z}_i = [z_{i,1}, \dots, z_{i,n}]^\intercal$.
    Since $\mathbf{v}'=\langle \mathbf{v}, \mathbf{v}'\rangle\cdot \mathbf{v} + \sum_{i=1}^{n-1}\langle \mathbf{v}', \mathbf{z}_i\rangle \cdot \mathbf{z}_i$, this implies that for any $1\le j\le n$,
    \[
    \begin{aligned}
        |u'_j| &\le |\langle \mathbf{v},\mathbf{v}'\rangle| |u_j| + \sum_{i=1}^{n-1}|\langle \mathbf{v}', \mathbf{z}_i\rangle| |z_{i,j}|\\
        &\le |u_j| + \left(\sum_{i=1}^{n-1}\langle \mathbf{v}', \mathbf{z}_i\rangle^2\right)^{1/2}\left(\sum_{i=1}^{n-1}z_{i,j}^2\right)^{1/2}\\
        & \le |u_j|+\epsilon,
    \end{aligned}
    \]
    where the last step follows from the fact that $\sum_{i=1}^{n-1}\langle \mathbf{v}',\mathbf{z}_i\rangle^2+\langle \mathbf{v}',\mathbf{v}\rangle^2=\|\mathbf{v}'\|^2=1$, and $\sum_{i=1}^{n-1}z_{i,j}^2+u_j^2=1$.\hfill{$\blacksquare$}

    Hence, by virtue of Lemma~\ref{lem:app_componentsEig}, (\ref{eq:app_eta_bounds}) and (\ref{eq:app_projection_onto_x2}), we obtain
    \begin{equation}
    \label{eq:app_abs_x2_v_geq_midway}
        |v_{2,j}| \ge \frac1\eta|v'_{2,j}|-\sqrt{\eta t} = \frac 1\eta |\eta_1g_A(j)+\eta_2g_B(j)| - \sqrt{\eta t} = 
        \left\{\begin{array}{cl}\frac{|\eta_1|}\eta\cdot \frac{d_j^{1/2}}{\Vol(A)^{1/2}} - \sqrt{\eta t}, & v_j\in A \\
        \frac{|\eta_2|}\eta\cdot \frac{d_j^{1/2}}{\Vol(B)^{1/2}} - \sqrt{\eta t}, & v_j\in B\end{array}\right.
    \end{equation}

    Finally, we need to show that $\min\{|\eta_1|,|\eta_2|\}\ge \epsilon^{1/2}c$.
    For this part of the proof, we shall use the assumption (ii) of our proposition.

    \begin{claim}
    \label{clm:app_eta_i_big}
        $|\eta_1|\ge c\cdot \left(\frac{\epsilon|A|}n\right)^{1/2}$ and $|\eta_2|\ge c\cdot \left(\frac{\epsilon|B|}n\right)^{1/2}$.
    \end{claim}
    \textit{Proof of Claim~\ref{clm:app_eta_i_big}.}
    Recall from the proof of Lemma~\ref{lem:app_PengLem1} that $\hat g_A=\alpha_1\mathbf{v}_1+\alpha_2\mathbf{v}_2$ and $\hat g_B=\beta_1\mathbf{v}_1+\beta_2\mathbf{v}_2$.
    These equations, along with $\mathbf{v}_2=\eta_1\hat g_A+\eta_2\hat g_B$, allow us to solve exactly for $\eta_1$ and $\eta_2$ as,
    \[\eta_1=\frac{\beta_1}{\alpha_2\beta_1-\alpha_1\beta_2}\mbox{ and }\eta_2=\frac{-\alpha_1}{\alpha_2\beta_1-\alpha_1\beta_2}.\]
    First, we note that $|\alpha_2\beta_1-\alpha_1\beta_2|\le(\alpha_1^2+\alpha_2^2)^{1/2}(\beta_1^2+\beta_2^2)^{1/2}\le \|g_A\|\|g_B\|=1$, so it suffices to lower bound $|\alpha_1|$ and $|\beta_1|$.
    We have that:
    \[
    \begin{aligned}
    |\alpha_1|=|\langle g_A, \mathbf{v}_1\rangle| = \frac{1}{\sqrt n}\sum_{v_j \in A}\frac{d_j^{1/2}}{\Vol(A)^{1/2}} &\geq \frac1{\sqrt n}\sum_{v_j \in A_\epsilon}\frac{d_j^{1/2}}{(|A|d(A))^{1/2}}\\
    &\ge \frac1{\sqrt n}\cdot |A_\epsilon|\cdot \left(\frac{\epsilon}{|A|}\right)^{1/2}\\
    &\ge c\cdot \left(\frac{\epsilon|A|}n\right)^{1/2}.
    \end{aligned}
    \]
    By a similar argument, we have $|\beta_1|\ge c\cdot \left(\frac{\epsilon|B|}n\right)^{1/2}$, finishing the proof of Claim~\ref{clm:app_eta_i_big}.
    \hfill{$\blacksquare$}

    Claim~\ref{clm:app_eta_i_big}, (\ref{eq:app_abs_x2_v_geq_midway}) and $\eta\le 4$ leads us to, for $v_j \in A$,
    \[
    |v_{2,j}|\ge \frac{c}4\cdot \frac{\epsilon^{1/2}|A|^{1/2}}{n^{1/2}}\cdot \frac{d_j^{1/2}}{\Vol(A)^{1/2}}-2\sqrt t = \frac{c\epsilon^{1/2}}{4}\cdot \sqrt{\frac{d_j}{nd(A)}} - 2\sqrt t,
    \]
    which proves the inequality (\ref{eq:app_prop_eigenvector_components_1}) for $v_j \in A$.
    The argument for $v_j \in B$ is analogous.

    Finally, the inequality (\ref{eq:app_prop_eigenvector_components_2}) directly follows (\ref{eq:app_prop_eigenvector_components_1}) via the definitions of $A_\epsilon$ and $B_\epsilon$.

\end{proof}


\section{Elimination of the leading eigenvector} 
\label{appendix:elimination}

The following proposition shows that the third term in the calculation at Line 6 of Algorithm \ref{alg:private_modified_PIC} eliminates the leading eigenvector of \( W \). Consequently, the leading eigenvector of \(\tilde{W}\) becomes the second eigenvector of \( W \).

\begin{proposition}
\label{lem:delete_largest_eigval}
    Let $W=\frac12(I+D^{-1}A)$ be the lazy random walk matrix for a graph on $n$ vertices.
    %Suppose $u=\left(\frac1n, \frac1n, \ldots, \frac1n\right)^\intercal$ and $v=\left(\frac {d_1}{2m}, \frac {d_2}{2m}, \ldots, \frac{d_n}{2m}\right)^\intercal$ are the right and left eigenvectors of $W$, respectively.
    Let $J = (\mathsf{j}_{i,j})_{1 \leq i,j \leq n}$ be a matrix such that $\mathsf{j}_{i,j} = 1$ for all $i,j$. Define $\tilde{W}=W-\frac1nJ$.
    Then, for all \(i \geq 1\), \(\lambda_i(\tilde{W}) = \lambda_{i+1}(W)\) and \(\mathbf{v}_n(\tilde{W}) = \mathbf{v}_1(W)\). Additionally, \(\mathbf{v}_n(\tilde{W}) = \mathbf{v}_1(W) = [\frac1{\sqrt{n}}, \dots, \frac1{\sqrt{n}}]^\intercal\) and \(\lambda_n(\tilde{W}) = 0\).
\end{proposition}
\begin{proof}
Recall that \(\mathbf{v}_1(W) = \left[ \frac{1}{\sqrt{n}}, \dots, \frac{1}{\sqrt{n}} \right]^\intercal\) and \(\lambda_1(W) = 1\). We have:
\begin{eqnarray*}
\tilde{W} \cdot \mathbf{v}_1(W) & = & W \cdot \mathbf{v}_1(W) - \frac{1}{n} J \mathbf{v}_1(W)  = \mathbf{v}_1(W) - \left[ \frac{1}{\sqrt{n}}, \dots, \frac{1}{\sqrt{n}} \right]^\intercal = \mathbf{0}.    
\end{eqnarray*}

Therefore, the vector \(\left[ \frac{1}{\sqrt{n}}, \dots, \frac{1}{\sqrt{n}} \right]^\intercal\) is an eigenvector of \(\tilde{W}\) with eigenvalue \(0\). Since \(0\) is the minimum eigenvalue of \(\tilde{W}\), it follows that \(\mathbf{v}_n(\tilde{W}) = \mathbf{v}_1(W)\) and \(\lambda_n(\tilde{W}) = 0\).

Next, let us consider $\mathbf{v}_i(W)$ for $i \geq 2$. Since, $\mathbf{v}_i(W) \perp \mathbf{v}_1(W)$, we obtain that the sum of all elements in $\mathbf{v}_i(W)$ is zero.
Thus,
\[
\tilde{W} \mathbf{v}_i(W) = W \mathbf{v}_i(W) - \frac{1}{n} J \mathbf{v}_i(W) = \lambda_i(W) \mathbf{v}_i(W).
\]
This implies that, for all \(i \geq 2\), \(\mathbf{v}_i(W)\) is also an eigenvector of \(\tilde{W}\) with the same eigenvalue. Consequently, as the largest eigenvalue of \(W\) becomes the smallest eigenvalue of \(\tilde{W}\), we have \(\lambda_{i - 1}(\tilde{W}) = \lambda_i(W)\) and \(\mathbf{v}_{i - 1}(\tilde{W}) = \mathbf{v}_i(W)\).
\end{proof}

\section{Privacy}
\label{sec:privacy}
The following theorem discuss our algorithm's privacy. \begin{theorem}
    Algorithm \ref{alg:private_modified_PIC} is $\epsilon$-edge LDP.
\end{theorem}
\begin{proof}
We perform \(T + 1\) edge-local Laplacian queries to all users: one at Line 1 and \(T\) queries at Line 6. At Line 1, the degree \(d_i\) has a sensitivity of one. Since the Laplace noise is set to \(10/\epsilon\), the privacy budget for the publication at Line 1 is \(\epsilon / 10\).

When any \(a_{i,j}\) is changed, the value of \(x_i^{(t)}\) calculated at Line 6 changes by at most \(\frac{1}{2} \max_j \frac{|x_j^{(t-1)}|}{d_j}\). Therefore, the sensitivity of the publication at Line 6 is \(\frac{1}{2} \max_j \frac{|x_j^{(t-1)}|}{d_j} \leq \frac{1}{2} \max_j \frac{|x_j^{(t-1)}|}{\delta}\). The privacy budget for each publication at Line 6 is \(\frac{9}{10} \cdot \frac{\epsilon}{T}\).
Since there are \(T\) publications at Line 6, the total privacy budget of Algorithm \ref{alg:private_modified_PIC} is \(\frac{\epsilon}{10} + T \cdot \frac{9}{10} \cdot \frac{\epsilon}{T} = \epsilon\).
\end{proof}

\section{Minimum degree estimation}
\label{appendix:minimumDegree}
We will now demonstrate that the value of \(\delta\) computed in Line 2 of Algorithm \ref{alg:private_modified_PIC} has a low probability of overestimating the minimum degree of the input graph. This implies that, with large probability, we do not need to modify the input graph in Line 3 of the algorithm.
\begin{proposition}
    With probability at least $1 - \zeta$, we have $\delta < \min_i d_i$.  
\end{proposition}
\begin{proof}
    We have $\delta > \min_i d_i$ only if there is $\tilde{d}_i$ such that $\tilde{d}_i - \frac{10}{\epsilon} \log \frac{n}{2\zeta} > d_i$. This implies that the value sampled from the Laplace distribution at Line 1, denoted by $\mathsf{l}_i$ is larger than $\frac{10}{\epsilon} \log \frac{n}{2\zeta}$. By the property of the Laplace distribution, for all $i$, we have that:
    \begin{eqnarray*}
        \Pr\left[\mathsf{l}_i > \frac{10}{\epsilon} \log \frac{n}{2\zeta}\right] & = & \frac{1}{2} \exp\left( - \frac{10}{\epsilon} \log \frac{n}{2\zeta} / \frac{10}{\epsilon} \right)  = \zeta / n.
    \end{eqnarray*}
    Then, by the union bound, the probability that there is an index $i$ such that $\mathsf{l}_i > \frac{10}{\epsilon} \log \frac{n}{2\zeta}$ is not greater than $\zeta$.
\end{proof}

Suppose that $\zeta = \frac{1}{n}$.
In the next proposition, we shown that $\delta \geq \sqrt{n} \log^4 n$ with large probability.
\begin{proposition}
    Assuming that the input graph $G$ satisfies Assumption~(1), i.e., its minimum degree is at least $2\sqrt{n} \log^4 n$, it holds that
\[
\Pr[\delta < \sqrt{n} \log^4 n] \leq \frac{1}{2n}.
\] \label{prop:delta}
\end{proposition}
\begin{proof}
   In Line 2 of Algorithm \ref{alg:private_modified_PIC}, Laplacian noise with a scale of \(\frac{10}{\epsilon}\) is added. It follows that \(\tilde{d}_i < d_i - \frac{20}{\epsilon} \log n\) if the noise added to \(d_i\) is less than \(-\frac{20}{\epsilon}\). This event occurs with probability 
\[
\frac{1}{2} \exp\left(-\frac{20/\epsilon \cdot \log n}{10/\epsilon}\right) = \frac{1}{2n^2}.
\]

Using the union bound, we have:
\[
\Pr\left[\min_i \tilde{d}_i < \min_i d_i - \frac{20}{\epsilon} \log n \right] \leq \Pr\left[\tilde{d}_i < d_i - \frac{20}{\epsilon} \log n \text{ for some } i \right] \leq \frac{1}{2n}.
\]

Given that \(\delta = \min_i \tilde{d}_i - \frac{10}{\epsilon} \log \frac{n}{2\zeta}\), and under the assumption in Section \ref{subsec:assumption} that the minimum degree of the network is at least \(2 \sqrt{n} \log^4 n\), we can bound:
\[
\Pr\left[\delta < \sqrt{n} \log^4 n \right] \leq \Pr\left[\delta < \min_i d_i - \frac{20}{\epsilon} \log n - \frac{10}{\epsilon} \log \frac{n}{2\zeta}\right] \leq \frac{1}{2n},
\]
for sufficiently large \(n\).
\end{proof}

\section{Size of Laplace noise}
\label{appendix:sizeofnoise}
In this section, we analyze the effect of adding the Laplace noise at Line 6 of the algorithm. Let the noise added by the node $i$ at the iteration $t$ is $y_{i}^{(t)}$. Define the vector $\mathbf{y}^{(t)}$ as $[y^{(t)}_1, \dots, y^{(t)}_n]^\intercal$. Also, for all $i,t$, let $e_{i}^{(t)}$ be a real number such that $\mathbf{y}^{(t)} = e_1^{(t)} \mathbf{v}_1(\tilde{W}) + \dots + e_n^{(t)} \mathbf{v}_n(\tilde{W})$.

Let the initial vector denoted by $\mathbf{x}^{(0)} = c_1 \mathbf{v}_1(\tilde{W}) + \dots + c_n \mathbf{v}_n(\tilde{W})$, and the final vector is denoted by $\mathbf{x}^{(T)}$. We obtain the following lemma by the notation.
\begin{lemma}
    Let $\tilde{c}_1, \dots, \tilde{c}_n$ be numbers such that $\mathbf{x}^{(T)} = \tilde{c}_1 \mathbf{v}_1(\tilde{W}) + \dots + \tilde{c}_n \mathbf{v}_n(\tilde{W})$. We obtain that $\tilde{c}_i = c_i\lambda_i(\tilde{W})^T + e_i^{(1)} \lambda_i(\tilde{W})^{T - 1} + \dots + e_i^{(T)}$. \label{lem:e} 
\end{lemma}
\begin{proof}
    To prove the statement, let \(\mathsf{c}_i^{(t)} = c_i\lambda_i(\tilde{W})^t + e_i^{(1)} \lambda_i(\tilde{W})^{t - 1} + \dots + e_i^{(t)}\). We proceed by induction on \(t\) to show that, for all \(t \geq 0\), \(\mathbf{x}^{(t)} = \mathsf{c}^{(t)}_1 \mathbf{v}_1(\tilde{W}) + \dots + \mathsf{c}^{(t)}_n \mathbf{v}_n(\tilde{W})\).
When \(t = 0\), \(\mathsf{c}_i^{(0)} = c_i\), so the statement holds directly by the definition of the notation.
Assume the statement is true for \(t - 1\); that is, \(\mathbf{x}^{(t - 1)} = \mathsf{c}^{(t - 1)}_1 \mathbf{v}_1(\tilde{W}) + \dots + \mathsf{c}^{(t - 1)}_n \mathbf{v}_n(\tilde{W})\). Then, for \(\mathbf{x}^{(t)}\), we have
\[
\mathbf{x}^{(t)} = \tilde{W} \cdot \mathbf{x}^{(t - 1)} + \mathbf{y}^{(t)}.
\]
Expanding this using the induction hypothesis gives
$$\mathbf{x}^{(t)} = (\mathsf{c}^{(t - 1)}_1 \lambda_1(\tilde{W}) + e_1^{(t)}) \mathbf{v}_1(\tilde{W}) + \dots + (\mathsf{c}^{(t - 1)}_n \lambda_n(\tilde{W}) + e_n^{(t)}) \mathbf{v}_n(\tilde{W}).$$
Thus, we obtain \(\mathbf{x}^{(t)} = \mathsf{c}^{(t)}_1 \mathbf{v}_1(\tilde{W}) + \dots + \mathsf{c}^{(t)}_n \mathbf{v}_n(\tilde{W})\), completing the induction.
\end{proof}
From now, let $\mathbf{v}_i(\tilde{W}) = [v_{i,1}, \dots, v_{i,n}]^\intercal$. We will now calculate the size of each variable. Recall from Line 4 of Algorithm \ref{alg:private_modified_PIC} that $x_i^{(0)}$ is sampled from the Gaussian distribution with expected value $0$ and standard deviation $1$.
\begin{lemma}
   For each \( i \), the variable \( c_i \) is a normal random variable with mean \( 0 \) and standard deviation \( 1 \). Furthermore, for $i \neq j$, $c_i$ is independent to $c_j$.\label{lem:c}
\end{lemma}
\begin{proof}
    Since, for all $i$, the eigenvector $\mathbf{v}_i(\tilde{W})$ is a unit vector and $c_i=\langle\mathbf{x}^{(0)},\mathbf{v}_i(\tilde{W})\rangle$, we have that $c_i = \sum_j v_{i,j} x_j^{(0)}$. Because $c_i$ is a linear combination of normal random variables, $c_i$ is a normal random variable. Furthermore, 
    $$\mathbb{E}[c_i] = v_{i,1} \mathbb{E}[x^{(0)}_1] + \cdots + v_{i,n} \mathbb{E}[x^{(0)}_n] = 0,$$
    and
        $$\mathrm{Var}(c_i) = v_{i,1}^2 \mathrm{Var}[x^{(0)}_1] + \cdots + v_{i,n}^2 \mathrm{Var}[x^{(0)}_n] = v_{i,1}^2 + \cdots v_{i,n}^2 = 1.$$ 

    Since \(\mathbf{v}_i(\tilde{W})\) is orthogonal to \(\mathbf{v}_j(\tilde{W}) \) for \(i \neq j\), the coefficients \(c_i\) and \(c_j\), which are the dot products of \(\mathbf{x}^{(0)}\) with \(\mathbf{v}_i(\tilde{W})\) and \(\mathbf{v}_j(\tilde{W})\) respectively, are independent of each other.
\end{proof}
Next, we give analyze the variables $e_i^{(t)}$. We observe that, although the random variable is a linear combination of the Laplace variables \( y_j^{(t)} \), it is not itself Laplace-distributed.
\begin{lemma} For all $t$ and $i$, we have $\mathbb{E}[e_i^{(t)}] = 0$.
    Furthermore, for all $t$ and all $i \neq j$, $\mathrm{Cov}(e_i^{(t)}, e_j^{(t)}) = 0$.
    \label{lem:eprop}
\end{lemma}
\begin{proof}
According to Line 6 of Algorithm \ref{alg:private_modified_PIC}, for all \( t \) and \( i \neq j \), the variables \( y_i^{(t)} \) and \( y_j^{(t)} \) are independent, with \( \mathbb{E}(y_i^{(t)}) = \mathbb{E}(y_j^{(t)}) = 0 \) and \( \mathrm{Var}(y_i^{(t)}) = \mathrm{Var}(y_j^{(t)}) \). The variable \( e_i^{(t)} \) is defined as the dot product between \( \mathbf{v}_i(\tilde W) \) and \( \mathbf{y}^{(t)} \). Specifically, if \( \mathbf{v}_i(\tilde{W}) = [v_{i,1}, \dots, v_{i,n}]^\intercal \), then \( e_i^{(t)} = \sum_j v_{i,j} y_j^{(t)} \). Consequently, \( \mathbb{E}(e_i^{(t)}) = \sum_j v_{i,j} \mathbb{E}[y_j^{(t)}] = 0 \). 

Next, for \( i \neq j \), we examine the covariance between \( e_i^{(t)} \) and \( e_j^{(t)} \), denoted as \( \mathrm{Cov}(e_i^{(t)}, e_j^{(t)}) \). Since \( \mathbb{E}(e_i^{(t)}) = \mathbb{E}(e_j^{(t)}) = 0 \), $\{y_1^{(t)},\ldots,y_n^{(t)}\}$ are independent with mean $0$, and \( \mathbf{v}_i \) is orthogonal to \( \mathbf{v}_j \), we have:
    \begin{align*}
        \mathrm{Cov}(e_i^{(t)}, e_j^{(t)})  &=  \mathbb{E}\left[\sum_{i',j'} v_{i,i'} y_{i'}^{(t)} v_{j,j'} y_{j'}^{(t)}\right] 
         \\ &=  \sum_{i',j' } v_{i,i'} v_{j,j'} \mathbb{E}[y_{i'}^{(t)}y_{j'}^{(t)}] \\ &=\sum_{k} v_{i,k}v_{j,k}\mathbb{E}[(y_k^{(t)})^2] \\&= \mathbb E[(y_1^{(t)})^2]\cdot\sum_{k} v_{i,k}v_{j,k}\\ &= 0.
    \end{align*}
\end{proof}
Let \( C_t \) represent the scale of the Laplace noise in Line 6 during the \( t \)-th iteration of Algorithm \ref{alg:private_modified_PIC}. By definition, $\mathrm{Var}(y_i^{(t)})=2C_t^2$ for every $i$. The variance of $e_i^{(t)}$ is discussed in the following lemma. Our proof draws on ideas from the paper \citep{li2023tail}.
\begin{lemma}
    For all $i$ and $t$, the variance of $e_i^{(t)}$ is $2 \cdot C_t^2$. Furthermore, $\Pr[e_i^{(t)} \geq \sqrt{2} C_t \log n] \leq \frac{e}{n}$.
    \label{lem:eprop2}
\end{lemma}
\begin{proof}
Based on the argument in the proof of Lemma \ref{lem:eprop}, we have \( e_i^{(t)} = \sum_j v_{i,j} y_j^{(t)} \). Consequently, \( \mathrm{Var}(e_i^{(t)}) = \sum_j v_{i,j}^2 \mathrm{Var}(y_j^{(t)}) \) for all $i$ and $t$. Since \( y_j^{(t)} \) is a Laplace variable with scale \( C_t \) and each \( \mathbf{v}_i(\tilde{W}) \) is a unit vector, it follows that \( \mathrm{Var}(e_j^{(t)}) = 2 \cdot C_t^2 \).

Using the Chernoff bound and the moment generating function of the Laplacian distribution, we obtain that
\begin{align*}
    \Pr[e_i^{(t)} \geq \sqrt{2} C_t \log n] \leq e^{-\log n} \cdot \mathbb{E}\left[\exp\left({\frac{\sum_j v_{i,j} y_j^{(t)}}{\sqrt{2} C_t}}\right)\right] &= \frac{1}{n} \prod_j \mathbb E\left[\exp\left(\frac{v_{i,j}y_j^{(t)}}{\sqrt2C_t}\right)\right]\\
    &=\frac{1}{n} \prod_j \mathbb E\left[\exp\left(\frac{v_{i,j}}{\sqrt2}\cdot\mathrm{Lap}\left(0,1\right)\right)\right]\\
    &=\frac 1n\prod_j\frac{1}{1 - \frac12v_{i,j}^2}\\
    & \leq \frac{1}{n} \exp{\sum_j v_{i,j}^2} = \frac{e}{n}.
\end{align*}
\end{proof}

Let \( h \) be a positive integer. We discuss the property of the vector $\tilde{W}^h \mathbf{y}^{(t)} := [\gamma_1^{(h,t)}, \dots, \gamma_n^{(h,t)}]^\intercal$ in the next lemma. 
\begin{lemma}
For all \( i,h,t \), the probability that \( |\gamma_i^{(h,t)}| \geq 3\sqrt{2} \cdot \lambda_1(\tilde{W})^h \cdot C_t \cdot \log n  \) is at most \( 2e/n^3 \). \label{lem:sizeofnoise}
\end{lemma}
\begin{proof}
From the definition of \( \gamma_i^{(h,t)} \) and the argument in Lemma~\ref{lem:e}, we find that \( \gamma_i^{(h,t)} = \sum_j \lambda_j(\tilde{W})^h \cdot v_{j,i} \cdot e_j^{(t)} \). According to Lemma \ref{lem:eprop}, $\mathrm{Cov}(e_j^{(t)}, e_{j'}^{(t)}) = 0$ for $j \neq j'$. Therefore, by Lemma \ref{lem:eprop2},
\begin{eqnarray*}
    \mathrm{Var}(\gamma_i^{(h,t)}) & = &  \sum_j \lambda_j(\tilde{W})^{2h} \cdot v_{j,i}^2 \cdot \mathrm{Var}(e_j^{(t)}) \\ & = & 2 C_t^2 \cdot \sum_j \lambda_j(\tilde{W})^{2h} \cdot v_{j,i}^2 \\ & \leq & 2 C_t^2 \cdot \lambda_1(\tilde{W})^{2h} \cdot \sum_j v_{j,i}^2 \\ & = & 2 C_t^2 \cdot \lambda_1(\tilde{W})^{2h}.
\end{eqnarray*}

Since $e_j^{(t)}$ is a linear combination of Laplace variables, $\gamma_i^{(h,t)}$ is also a linear combination of the Laplace variable $y_j^{(t)}$. Let $\mathsf{a}_1, \dots, \mathsf{a}_n$ be real numbers such that $\gamma_i^{(h,t)} = \sum_j \mathsf{a}_j y_j^{(t)}$. We obtain that $\mathrm{Var}(\gamma_i^{(h,t)}) = 2\cdot C_t^2 \sum_j \mathsf{a}_j^2 \leq 2C_t^2 \cdot \lambda_1(\tilde{W})^{2h}$, and $\sum_j \mathsf{a}_j^2 \leq \lambda_1(\tilde{W})^{2h}$. Using the Chernoff bound, we obtain that 
\begin{eqnarray*}
     \Pr[\gamma_i^{(h,t)} \geq 3\sqrt{2} \cdot \lambda_1(\tilde{W})^h \cdot C_t \cdot \log n] 
    & \leq & e^{-3\log n} \cdot \mathbb{E}\left[\exp\left(\frac{\gamma_i^{(h,t)} }{\sqrt{2} \cdot \lambda_1(\tilde{W})^h \cdot C_t} \right)\right] \\
    & \leq & \frac{1}{n^3} \mathbb{E}\left[\exp\left(\frac{\sum_j \mathsf{a}_j \cdot \mathrm{Lap}(0,1)}{\sqrt{2} \cdot \lambda_1(\tilde{W})^h } \right)\right] \\
    & = & \frac{1}{n^3} \prod_j \frac{1}{1 - \frac{\mathsf{a}_j^2}{2\lambda_1(\tilde{W})^{2h}}} \\
    & \leq & \frac{1}{n^3}\exp\left(\frac{1}{2\lambda_1(\tilde{W})^{2h}}\sum_j{\mathsf{a}_j^2}\right) \leq \frac{1}{n^3} \exp(1).
\end{eqnarray*}
% Observe that $\gamma_i^{(h,t)} = \sum_j \lambda_j(\tilde{W})^h \cdot v_{j,i} \cdot e_j^{(t)}=\sum_j \lambda_j(\tilde{W})^h \cdot v_{j,i} \sum_k v_{k,j} y_k^{(t)} = \sum_k \left(\sum_j\lambda_j(\tilde W)^h\cdot v_{j,i}v_{k,j}\right)y_k^{(t)}$. So, $\mathsf a_j = \sum_k\lambda_j(\tilde W)^h\cdot v_{k,i}v_{j,k}$ implying $\sum_j \mathsf a_j^2 \le \lambda_1(\tilde W)^{2h} \|v_i\|^2$ Nice!!
%\begin{align*}
%    \Pr[\gamma_i^{(h,t)} \geq 3\sqrt{2} \cdot \lambda_1(\tilde{W})^h \cdot C_t \cdot \log n] &   \le e^{-3\log n}\cdot \prod_k\mathbb E\left[\exp\left(\frac{\sum_j\lambda_j(\tilde W)^h\cdot v_{j,i}v_{k,j}}{\sqrt2\lambda_1(\tilde W)^hC_t}\cdot y_k^{(t)}\right)\right]\\
%    & = \frac1{n^3}\cdot \prod_k\mathbb E\left[\exp\left(\frac{\sum_j\lambda_j(\tilde W)^h\cdot v_{j,i}v_{k,j}}{\sqrt2\lambda_1(\tilde W)^h}\cdot \Lap(0,1) \right)\right]\\
%    & = \frac1{n^3}\cdot \prod_k \frac1{1-(\frac{\sum_j\lambda_j(\tilde W)^h\cdot v_{j,i}v_{k,j}}{\sqrt2\lambda_1(\tilde W)^h})^2}
%\end{align*}
The lemma statement follows from the fact that the probability distribution of $\gamma_{h,t}$ is symmetric about $0$.
\end{proof}

In the next lemma, we analyze the size of the  noise added in the algorithm. Recall that the variable $\delta$ is the noisy minimum degree published at Line 2 of Algorithm~\ref{alg:private_modified_PIC}. In Proposition \ref{prop:delta}, we show that $\delta \geq \sqrt{n} \log^4 n$ with probability at least $1 - \frac{1}{n}$. We denote the event that $\delta \geq \sqrt{n} \log^4 n$ by $\mathcal{E}_\delta$.
\begin{lemma}
    Recall that $C_t$ is the scale of the noise added at Line 6 of Algorithm \ref{alg:private_modified_PIC}. Under Assumptions (2) and (4) in Section~\ref{subsec:assumption}, which state that the spectral gap $g$ is constant and the number of nodes $n$ exceeds any fixed constant $C$, we have
    \begin{eqnarray*}\Pr \left[ C_t \leq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2n} \text{ for all $1 \leq t \leq T$ } \mid \mathcal{E}_\delta\right]  \geq 1 - \frac{8eT^2}{n^2}.\end{eqnarray*} \label{lem:Ct}
\end{lemma}
\begin{proof}
Since \( x_i^{(0)} \) is drawn from a Gaussian distribution with mean \( 0 \) and standard deviation \( 1 \), it follows from the properties of a normal random variable that \( \Pr[|x_i^{(0)}| \geq \log n \cdot \log g] \leq \frac{1}{n^3} \). By applying the union bound, we then have \( \Pr[\max_i |x_i^{(0)}| \geq \log n \cdot \log g] \leq \frac{1}{n^2} \).


We will prove this lemma by induction on the number of iterations \( t \). For \( t = 1 \), recall from Line~6 of the algorithm that the noise \( y_i^{(t)} \) is drawn from a Laplace distribution with scale parameter \( \frac{5 \cdot T}{9 \cdot \epsilon} \cdot \frac{\max_i |x_i^{(t - 1)}|}{\delta} \), where \( \epsilon \) is the privacy budget and \( \delta \) is the minimum degree of the input graph. In the event $\mathcal{E}_\delta$, the variable \( \delta \geq \sqrt{n} \log^4 n \). Recall that we set \( T = 2\frac{\log n}{\log g} \) in our algorithm. 
Consequently, the noise scale in the first iteration is larger than \( \frac{10}{9\epsilon} \frac{\log n}{\log g} \cdot \frac{\log n \cdot \log g}{\sqrt{n} \log^4 n}  = \frac{10}{9 \epsilon \cdot \sqrt{n} \log^2 n} \) with probability not larger than \( 1/n^2 \) when $n$ is large enough.

Next, assume that, in the event $\mathcal{E}_\delta$, with probability not smaller than \( 1 - \frac{2e \cdot (2t - 2)^2}{n^2}  \), for all \( t' < t \), the noise (denoted by \( y_i^{(t')} \)) is sampled from a Laplace distribution with a scale no more than \( \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t' - 1}}{\sqrt{n} \log^2 n} \). From our previous calculations, it follows that \( \mathbf{x}^{(t)} = \tilde{W}^{t} \mathbf{x}^{(0)} + \tilde{W}^{t - 1} \mathbf{y}^{(1)} + \dots + \mathbf{y}^{(t)} \). Let $\tilde{W}^{t} \mathbf{x}^{(0)} = [\mathsf{x}_1^{(t)}, \dots, \mathsf{x}_n^{(t)}]^\intercal$ and, for all $t' \leq t$, $\tilde{W}^{t - t'} \mathbf{y}^{(t')} = [\mathsf{y}_1^{(t,t')}, \dots, \mathsf{y}_n^{(t,t')}]^\intercal$. The value of $\max_i |x_i^{(t - 1)}|$, which decides the noise scale of $\mathbf{y}^{(t)}$, is equal to $\max_i \left|\mathsf{x}_i^{(t - 1)} + \sum\limits_{t' = 1}^{t - 1} \mathsf{y}_i^{(t - 1,t')}\right|$.

Let us first consider the vector \( [\mathsf{x}^{(t - 1)}_1, \dots, \mathsf{x}^{(t - 1)}_n]^\intercal \). Recall that \( \mathbf{v}_i(\tilde{W}) = [v_{i,1}, \dots, v_{i,n}]^\intercal \). By the notation, we have \( \mathsf{x}_{i}^{(t - 1)} = \sum_j \lambda_j(\tilde{W})^{t - 1} v_{j,i} c_j \).

Since, by Lemma \ref{lem:c}, $c_j$ and $c_{j'}$ are independent for $j \neq j'$, we obtain:
\begin{eqnarray*}
\mathbb{E}[\mathsf{x}_{i}^{(t - 1)}] & = & \sum_j \lambda_j(\tilde{W})^{t - 1} v_{j,i} \cdot \mathbb{E}[c_j] = 0, \\
\mathrm{Var}[\mathsf{x}_{i}^{(t - 1)}] & = & \sum_j \lambda_j(\tilde{W})^{2t - 2} v_{j,i}^2 \mathrm{Var}[c_j] \leq \lambda_1(\tilde{W})^{2t - 2} \mathrm{Var}\left[\sum_j v_{j,i} c_j\right]  \\ & = &  \lambda_1(\tilde{W})^{2t - 2} \mathrm{Var}\left[x_i^{(0)}\right] = \lambda_1(\tilde{W})^{2t - 2}.
\end{eqnarray*}
Also, since $\mathsf{x}_i^{(t - 1)}$ is a linear combination of the normal random variable $c_j$, we can conclude that $\mathsf{x}_i^{(t - 1)}$ is also normal. By the property of the normal variable, we have $\Pr\left[|\mathsf{x}_i^{(t - 1)}| \geq \frac{1}{2} \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1}\right] \leq \frac{1}{n^3}$ for all $i$. By the union bound, $\Pr\left[\max_i |\mathsf{x}_i^{(t - 1)}| \geq \frac{1}{2} \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1}\right] \leq \frac{1}{n^2}$. 

Let us reconsider the variable \(\gamma_i^{(h,t)}\) from Lemma \ref{lem:sizeofnoise}. Note that \(\mathsf{y}_i^{(t - 1, t')} = \gamma^{(t - t' - 1, t')}\). Let $\mathcal{E}$ denote the event that \(C_{t'} \leq \frac{10}{9\epsilon} \cdot \frac{\lambda_1^{t' - 1}(\tilde{W})}{\sqrt{n} \log^2 n}\) for all \(t' < t\).
In the event $\mathcal{E}$ and $\mathcal{E}_\delta$, Lemma \ref{lem:sizeofnoise} implies that, for all \(i, t, t'\),  
\begin{eqnarray*}
\left| \mathsf{y}_i^{(t - 1, t')} \right|& \geq & 3\sqrt{2} \cdot \lambda_1^{t - t' - 1}(\tilde{W}) \cdot \frac{10}{9\epsilon} \cdot \frac{\lambda_1^{t' - 1}(\tilde{W})}{\sqrt{n} \log^2 n}  = \frac{30\sqrt{2}}{9\epsilon} \cdot \frac{\lambda_1^{t - 2}(\tilde{W})}{\sqrt{n} \log^2 n} 
\end{eqnarray*}
with probability at most \(\frac{2e}{n^3}\).

By applying the union bound, we deduce that for all \(t, t'\),  
\[
\max_i |\mathsf{y}_i^{(t - 1, t')}| \geq \frac{30\sqrt{2}}{9\epsilon} \cdot \frac{\lambda_1^{t - 2}(\tilde{W})}{\sqrt{n} \log^2 n}
\]  
with probability at most \(\frac{2e}{n^2}\). By Lemma 4.4 of \citep{mohar1989isoperimetric}, we have that $\lambda_2(B) \geq 0$ and $\lambda_1(\tilde{W}) \geq \frac{1}{2}$. 
When \(n\) is sufficiently large, it follows that, for all \(t, t'\),  
\[
\max_i |\mathsf{y}_i^{(t - 1, t')}| \geq \frac{  \lambda_1^{t - 1}(\tilde{W}) \log g}{4 \log n} \geq \frac{30 \sqrt{2}}{9\epsilon}\frac{\lambda_1^{t - 2}(\tilde{W})}{\sqrt{n} \log^2 n}
\]  
with probability at most \(\frac{2e}{n^2}\). We finally obtain  
$$\Pr\left[\sum_{t' \leq t - 1} \max_i |\mathsf{y}_i^{(t - 1, t')}| \geq \frac{1}{2} \cdot \lambda_1^{t - 1}(\tilde{W}) \mid \mathcal{E}, \mathcal{E}_\delta \right] \leq \frac{2et}{n^2}.$$  

Because, for all $i$ and $t$, the variables $\mathsf{x}_i^{(t - 1)}$ do not depends on the scale of the Laplacian noise and the event $\mathcal{E}$, we obtain that:
\begin{eqnarray*}
& & \Pr\left[\max_i \left|x_i^{(t-1)}\right| \geq \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1} \mid \mathcal{E}, \mathcal{E}_\delta \right] \\
    & = & \Pr\left[\max_i \left|\mathsf{x}_i^{(t - 1)} + \sum_{t' \leq t - 1} \mathsf{y}_i^{(t - 1,t')}\right| \geq \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1} \mid \mathcal{E}, \mathcal{E}_\delta\right] \\
    & \leq & \Pr\left[\max_i \left|\mathsf{x}_i^{(t - 1)}\right| + \sum_{t' \leq t - 1} \max_i \left| \mathsf{y}_i^{(t - 1,t')}\right| \geq \log n \cdot \log g\cdot \lambda_1(\tilde{W})^{t - 1} \mid \mathcal{E}, \mathcal{E}_\delta\right] \\
    & \leq & \Pr \left[\max_i \left|\mathsf{x}_i^{(t - 1)}\right| \geq \frac{1}{2} \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1} \right] \\ & & ~~~~ + \Pr \left[\sum_{t' \leq t - 1} \max_i \left|\mathsf{y}_i^{(t - 1,t')}\right| \geq \frac{1}{2}\lambda_1(\tilde{W})^{t - 1} \mid \mathcal{E}, \mathcal{E}_\delta \right] \\ & \leq & \frac{(2et + 1)}{n^2}.
\end{eqnarray*}
In the event $\mathcal{E}$ and $\mathcal{E}_\delta$, $\max_i |x_i^{(t-1)}| \geq \log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1}$ with probability at most $\frac{2et + 1}{n^2}$. In the event of $\mathcal{E}$ and $\mathcal{E}_\delta$, the noise scale at the iteration $t$, denoted by $C_t$, is at most $\frac{10}{9\epsilon} \frac{2\log n}{\log g}  \frac{\log n \cdot \log g \cdot \lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^4 n} = \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n}$ with probability at least $1 - \frac{2et + 1}{n^2}$. As a result,
\begin{eqnarray*}
 \Pr\left[C_t \geq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n} \text{ or } \bar{\mathcal{E}} \mid \mathcal{E}_\delta \right] 
& \leq & \Pr\left[C_t \geq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n} \text{ and } \mathcal{E} \mid \mathcal{E}_\delta \right] + \Pr[\bar{\mathcal{E}} \mid \mathcal{E}_\delta] \\
& \leq & \Pr\left[C_t \geq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n} \mid \mathcal{E}, \mathcal{E}_\delta \right] +  \frac{2e(2t - 2)^2}{n^2} \\
& \leq & \frac{2et + 1}{n^2} + \frac{2e(2t - 2)^2}{n^2} \leq \frac{2e(2t)^2}{n^2}.
\end{eqnarray*}
This completes the induction step. We can conclude that, for all $t \in \{1, \dots, T \}$, 
$C_{t'} \leq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t' - 1}}{\sqrt{n} \log^2 n}$ for all $t' \leq t$ with probability at least
$1 - \frac{2e(2t)^2}{n^2}$ when $\delta \geq \sqrt{n} \log^4 n$.
\end{proof}

We will leverage the previous lemma to demonstrate that the outcome of Algorithm \ref{alg:private_modified_PIC} closely aligns with the results obtained through spectral clustering. Recall Lemma \ref{lem:e} that the final vector $x_i^{(T)} = \sum_{j = 1}^n \tilde{c}_j v_{j,i}$ when $\tilde{c}_j = c_j \lambda_j(\tilde{W})^T + \sum_{t = 1}^T e_j^{(t)} \lambda_j(\tilde{W})^{T - t}$.
\begin{theorem}
   Under Assumptions (1)–(4) in Section~\ref{subsec:assumption}, which state that (1) the minimum degree is at least $2\sqrt{n} \log^4 n$, (2) the spectral gap $g$ is constant, (3) there exist constants $\delta \approx 1$ and $\gamma < 1$ such that the components of $\mathbf{v}_2(B)$ satisfy $\left|\left\{i : |\nu_i| > \frac{\gamma}{\sqrt{n}} \right\}\right| \geq \delta \cdot n$, and (4) the number of nodes $n$ exceeds any fixed constant $C$, it follows that for any node $i$ with $|v_{1,i}| \geq \frac{\gamma}{\sqrt{n}}$, and sufficiently large $n$, we have
        $$\Pr\left[\left|c_1 \lambda_1(\tilde{W})^T v_{1,i}\right| > \left|\sum_{t =1}^Te_1^T\lambda_1(\tilde{W})^{T - t}v_{1,i} + \sum_{j = 2}^n \tilde{c}_j v_{j,i} \right| \right] \geq 0.95 - o(1).$$
    \label{thm:precision}
\end{theorem}
\begin{proof}
    We first obtain that
\begin{eqnarray}
    & & \Pr\left[\left|c_1 \lambda_1(\tilde{W})^T v_{1,i}\right| > \left|\sum_{t =1}^Te_1^T\lambda_1(\tilde{W})^{T - t}v_{1,i} + \sum_{j = 2}^n \tilde{c}_j v_{j,i} \right| \right] \nonumber \\ & \geq & \Pr\left[\left|c_1 \lambda_1(\tilde{W})^T v_{1,i}\right| > \left|\sum_{t =1}^Te_1^T\lambda_1(\tilde{W})^{T - t}v_{1,i}\right| + \left|\sum_{j = 2}^n \tilde{c}_j v_{j,i} \right| \right] \nonumber \\
   & \geq & \Pr \Bigg[ |v_{1,i}| \left( |c_1  \lambda_1(\tilde{W})^T| - \left| \sum_{t = 1}^T e_1^{(t)} \lambda_1(\tilde{W})^{T - t}  \right| \right) \nonumber \\ & & ~~~~~~~~~ > \left|\sum_{j = 2}^n c_j v_{j,i} \lambda_j(\tilde{W})^T \right|  + \left| \sum_{j = 2}^{n} \sum_{t = 1}^T e_j^{(t)} \lambda_j(\tilde{W})^{T - t}v_{j,i}\right| \Bigg] \nonumber. \label{eqn:33} \end{eqnarray}
 Recall from Lemma \ref{lem:c} that $c_i$ is a normal random variable with mean 0 and standard deviation 1. We obtain that:
 \begin{equation}
 \Pr\left[ \left|c_1 \lambda_1(\tilde{W})^T\right| \geq \frac{\lambda_1(\tilde{W})^T}{16} \right] > 0.95. \label{eqn:0.95}
 \end{equation}

 Recall from Lemma \ref{lem:eprop2} that $\Pr\left[e_1^{(t)} \geq \sqrt{2} C_t \log n\right] \leq \frac{e}{n}$.
 Let $\mathcal{E}$ be the event that $\max_t C_t \leq \frac{10}{9\epsilon}\cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n}$ and $\mathcal{E}_\delta$ be the event that $\delta \geq \sqrt{n} \log^4 n$. We obtain that $\Pr\left[e_1^{(t)} \geq \frac{10\sqrt{2}}{9\epsilon} \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log n} 
 | \mathcal{E}, \mathcal{E}_\delta \right] \leq \frac{e}{n}$. Denote $\sum_{t = 1}^{T} e_j^{(t)} \lambda_1(\tilde{W})^{T - t}$ by $\eta$. By the union bound,
 \begin{eqnarray*}
 \Pr\left[\eta \geq \frac{\lambda_1(\tilde{W})^T}{32} | \mathcal{E} \right]
 \leq \Pr\left[\eta \geq \frac{10 \sqrt{2} \cdot T}{9\epsilon} \frac{\lambda_1(\tilde{W})^{T - 1}}{\sqrt{n} \log n} | \mathcal{E} \right]  \leq \frac{e T}{n},
 \end{eqnarray*}
 for sufficiently large $n$. Recall the event $\mathcal{E}_\delta$, which is the event when $\delta \geq \sqrt{n} \log^4 n$. By Lemma \ref{lem:Ct}, we know that $\Pr[\mathcal{E} \mid \mathcal{E}_\delta] \geq 1 - \frac{8eT^2}{n^2}$. Also, by Proposition \ref{prop:delta}, we know that $\Pr[\bar{\mathcal{E}_\delta}] \leq \frac{1}{2n}$. As a result, when $n$ is large enough,
 \begin{eqnarray*}
\Pr\left[\eta \geq \frac{\lambda_1(\tilde{W})^T}{32} \right] \nonumber
& \leq & \Pr\left[\eta \geq \frac{\lambda_1(\tilde{W})^T}{32} \text{ and } \mathcal{E} \text{ and } \mathcal{E}_\delta \right]  + \Pr[\bar{\mathcal{E}} \text{ and } \mathcal{E}_\delta] + \Pr[\bar{\mathcal{E}_\delta}] \nonumber \\
& \leq & \Pr\left[ \eta \geq \frac{\lambda_1(\tilde{W})^T}{32} \mid \mathcal{E}, \mathcal{E}_\delta \right] +  \Pr[\bar{\mathcal{E}} \mid \mathcal{E}_\delta] + \frac{1}{2n} \nonumber = o(1). 
\end{eqnarray*}
Since the distribution of $\eta$ is symmetric around 0, we have that
\begin{equation}
    \Pr\left[|\eta| \geq \frac{\lambda_1(\tilde{W})^T}{32}  \right] = o(1).
    \label{eqn:eta}
\end{equation}
By combining (\ref{eqn:0.95}) and (\ref{eqn:eta}) and using the fact that $|v_{1,i}| \geq \frac{\gamma}{\sqrt{n}}$, we obtain that:
\begin{equation}
\Pr\left[ |v_{1,i}| \left( |c_1  \lambda_1(\tilde{W})^T| - \left| \eta  \right| \right) \geq \frac{\gamma \lambda_1(\tilde{W})^T}{32 \sqrt{n}}\right] > 0.95 - o(1) \label{eqn:left-side}
\end{equation}

By the assumption that $\lambda_2(\tilde{W}) \leq \frac{\lambda_1(\tilde{W})}{g}$, we have that $\left| \sum_{j = 2}^n c_j v_{j,i} \lambda_j(\tilde{W})^T  \right| \leq \left| \frac{\lambda_1(\tilde{W})^T}{g^T} \cdot \sum_{j = 2}^n c_j \right|$. Since $\sum_{j = 2}^n c_j v_{j,i} \lambda_j(\tilde{W})^T$ is a normal random variable with mean 0 and standard deviation at most $\frac{\sqrt{n} \cdot \lambda_1(\tilde{W})^T}{g^T}$, we have the following.
 \begin{equation*}
 \Pr\left[ \left|\sum_{j = 2}^n c_j v_{j,i} \lambda_j(\tilde{W})^T\right| \geq \frac{\sqrt{n} \log n \cdot \lambda_1(\tilde{W})^T}{g^T} \right] < \frac{1}{n^2}.
 \end{equation*}
 When $T = \frac{2 \log n}{\log g}$ and $n$ is large enough, we obtain that $\frac{\sqrt{n} \log n}{g^T} < \frac{\gamma}{65 \sqrt{n}}$. Hence,
 \begin{equation}
 \Pr\left[ \left|\sum_{j = 2}^n c_j v_{j,i} \lambda_j(\tilde{W})^T\right| \geq \frac{\gamma \cdot \lambda_1(\tilde{W})^T}{65 \sqrt{n}} \right] < \frac{1}{n^2}. \label{eqn:right-side-1}
 \end{equation}

 Consider the summation $\sum_{j = 2}^n \sum_{t = 1}^T e_j^{(t)} \lambda_j(\tilde{W})^{T - t} v_{j,i}$. Denote the summation as $\beta_t$. By Lemma~\ref{lem:eprop}, we know that $\mathbb{E}[e_j^{(t)}] = 0$ for all $j, t$. As a result, $\mathbb{E}[\beta_t] = \mathbb{E}\left[\sum_{j = 2}^n e_j^{(t)} \lambda_j(\tilde{W})^{T - t} v_{j,i}\right] = 0$ for all $t$. Furthermore, by $\lambda_j(\tilde{W}) \leq \frac{\lambda_1(\tilde{W})}{g}$ for all $j \geq 2$,
 \begin{eqnarray}
      \mathrm{Var}\left[\beta_t\right] \nonumber & \leq & \sum_{j = 2}^n \lambda_j(\tilde{W})^{2T - 2t} v_{j,i}^2 \mathrm{Var}(e_j^{(t)})\nonumber \\ & \leq & \sum_{j = 1}^n  \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}} v_{j,i}^2 \mathrm{Var}(e_j^{(t)}) \nonumber \\
     & = & \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}} \mathrm{Var}\left[\sum_j v_{j,i} e_j^{(t)}\right] \nonumber \\
     & = & \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}} \mathrm{Var}\left[y_i^{(t)}\right] \nonumber \\ & = & 2 \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}} C_t^2. \label{eqn:5}
 \end{eqnarray}
We observe that both \(e_j^{(t)}\) and \(\beta_t = \sum_{j=2}^n e_j^{(t)} \lambda_j(\tilde{W})^{T-t} v_{j,i}\) can be written as linear combinations of \(y_1^{(t)}, \dots, y_n^{(t)}\). Let \(\mathsf{b}^{(t)}_1, \dots, \mathsf{b}^{(t)}_n\in\mathbb{R}\) be such that
$\beta_t
\,=\,
\sum_{j=1}^n \mathsf{b}^{(t)}_j\,y_j^{(t)}$. By~(\ref{eqn:5}), $\mathrm{Var}\left[\beta_t \right]
\,=\,
2 \sum_{j=1}^n \mathsf{b}_j^2 C_t^2 \leq 2 \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}} C_t^2$ and $\sum_{j=1}^n \mathsf{b}_j^2 \leq \frac{\lambda_1(\tilde{W})^{2T - 2t}}{g^{2T - 2t}}$. Using the Chernoff bound and the moment generating function of the Laplacian distribution, we obtain that
\begin{eqnarray*}
    \Pr\left[\beta_t \geq \sqrt{2} \log n \cdot \frac{\lambda_1^{T-t}(\tilde{W})}{g^{T - t}} \cdot C_t\right] 
    & \leq & e^{-\log n} \cdot \mathbb{E}\left[\exp \left(\frac{\beta_t}{\sqrt{2} \cdot \frac{\lambda_1^{T-t}(\tilde{W})}{g^{T - t}} \cdot C_t} \right) \right] \\
    & \leq & \frac{1}{n} \mathbb{E}\left[\exp \left( \frac{\sum_j \mathsf{b}_j \mathrm{Lap}(0,1)}{\sqrt{2} \cdot \frac{\lambda_1^{T-t}(\tilde{W})}{g^{T - t}}}\right)\right] \\
    & = & \frac{1}{n} \prod_j \frac{1}{1 -  \mathsf{b}_j^2 / \left(2 \cdot \frac{\lambda_1^{2T-2t}(\tilde{W})}{g^{2T - 2t}}\right) } \\
    & \leq & \frac{1}{n}\exp\left(\frac{g^{2T - 2t}}{\lambda_1^{2T-2t}(\tilde{W})}\sum_j{\mathsf{b}_j^2}\right) \leq \frac{e}{n}.
\end{eqnarray*}

 Let $\mathcal{E}$ be the event that $\max_t C_t \leq \frac{10}{9\epsilon} \cdot \frac{\lambda_1(\tilde{W})^{t - 1}}{\sqrt{n} \log^2 n}$. For large $n$ such that $\log n \geq \frac{650 \sqrt{2}}{9\epsilon} \cdot \frac{g}{g - 1} \cdot \frac{1}{\gamma}$,
 \begin{eqnarray*}
     \Pr\left[ \beta_t \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65 \cdot \frac{g}{g-1} \sqrt{n} g^{T - t}} \mid \mathcal{E} \right]  \leq \Pr\left[\beta_t \geq \frac{10\sqrt{2}}{9\epsilon} \cdot \frac{ \lambda_1^{T-1}(\tilde{W})}{\log n \sqrt{n} g^{T - t}} \mid \mathcal{E} \right]  \leq \frac{e}{n}.
 \end{eqnarray*}
 Recall that $\mathcal{E}_\delta$ is the event such that $\delta \geq \sqrt{n} \log^4 n$. By Lemma \ref{lem:Ct}, we know that $\Pr[\mathcal{E} \mid \mathcal{E}_\delta] = 1 - \frac{8eT^2}{n^2}$, and, by Proposition \ref{prop:delta}, we know that $\Pr[\bar{\mathcal{E}_\delta}] \leq \frac{1}{2n}$.
 As a result, when $n$ is large enough,
\begin{eqnarray*}
\Pr\left[\beta_t \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65 \cdot \frac{g}{g-1}\sqrt{n} g^{T - t}}\right] \nonumber 
& \leq & \Pr\left[\beta_t \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65 \cdot \frac{g}{g-1}\sqrt{n}g^{T - t}} \text{ and } \mathcal{E} \text{ and } \mathcal{E}_\delta \right] \\ & & ~~~~ + \Pr[\bar{\mathcal{E}} \text{ and } \mathcal{E}_\delta] + \Pr[\mathcal{E}_\delta] \nonumber \\
& \leq & \Pr\left[ \beta_t \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65 \cdot \frac{g}{g-1}\sqrt{n}g^{T - t}} \mid \mathcal{E} \right] + \Pr\left[\bar{\mathcal{E}} \mid \mathcal{E}_\delta \right] + \frac{1}{2n} \nonumber \\ & = & O\left(\frac{1}{n}\right). 
\end{eqnarray*}
 By the union bound and by $\sum_{t = 1}^T \frac{1}{g^{T - t}} = \frac{1}{g^T} \sum_{t = 1}^{T} g^{t} = \frac{1}{g^T} \frac{g^{T + 1} - 1}{g - 1} = \frac{gn^2 - 1}{gn^2 - n^2} \leq \frac{g}{g - 1}$, we obtain that 
 \begin{eqnarray*}
     \Pr\left[\sum_{t = 1}^{T} \beta_t \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65\sqrt{n}} \right] 
      \leq \Pr\left[\sum_{t = 1}^{T} \beta_t \geq \sum_{t = 1}^T \frac{\gamma  \lambda_1(\tilde{W})^T}{65 \cdot \frac{g}{g-1} \cdot \sqrt{n} g^{T - t}} \right] = O\left(\frac{\log n}{n}\right). 
 \end{eqnarray*}
 As $\sum_{t = 1}^T \beta_t$ is a linear combination of Laplacian random variable, we know that the distribution of the summation is symmetric around $0$. Hence, 
 \begin{equation}
     \Pr\left[\left| \sum_{j = 2}^n \sum_{t = 1}^T e_j^{(t)} \lambda_j(\tilde{W})^{T - t} v_{j,i} \right| \geq \frac{\gamma  \lambda_1(\tilde{W})^T}{65\sqrt{n}} \right] = o(1). \label{eqn:right-side-2}
 \end{equation}


We then obtain the lemma statement by combining (\ref{eqn:left-side}) with inequalities (\ref{eqn:right-side-1}) and (\ref{eqn:right-side-2}).
\end{proof}


