\paragraph{Initializing Offsets.} 
We observed that during training, the offsets $\Delta_i$ naturally tend to point toward the surface. To accelerate convergence, we propose an initialization strategy inspired by the mean-shift algorithm, which is traditionally used for locating the maxima of a density function. In our context, the surface points represent regions of high density. Therefore, we leverage mean-shift to initialize the offsets $\Delta_i$,
\begin{equation}
    \Delta_i = \frac{\sum^N_n\left[
        \exp\left(-100 \left\|\colorkey{\mathbf{k}_i}-\mathbf{s}_n\right\|^2\right)\cdot\mathbf{s}_n
        \right]}{\sum^N_n \exp\left(-100 \left\|\colorkey{\mathbf{k}_i}-\mathbf{s}_n\right\|^2\right)} - \colorkey{\mathbf{k}_i},
\end{equation}
where $\mathbf{s}_n$ is a surface point and we use $N=16384$ surface points in almost all the experiments. The initialization serves as guidance to identify regions where details are required. Some other works~\cite{ohtake2023mpu,liu2021deep, wang2022dual,he2024dmp} employ octrees to locate the near-surface regions.
An illustration can be found in~\cref{fig:pc}.


\subsection{Fitting}\label{sec:fitting}
We aim to fit SDFs using the proposed representations. The training set is a collection of point-distance pairs, $\{(\colorquery{\mathbf{q}_j}, o_j)\}_j^J$.
The mean squared error (MSE) loss function is minimized as follows:
\begin{equation}\label{eq:loss}
    \mathcal{L}\left(
        \{(\colorquery{\mathbf{q}_j}, o_j)\}_j^J;\boldsymbol\theta
    \right) = \frac{1}{J}\sum_j^J(\mathcal{O}(\colorquery{\mathbf{q}_j}) - o_j)^2.
\end{equation}
In practice, similar to neural networks, we optimize the loss within a small batch size $J_B$ rather than the full dataset size $J$, using stochastic gradient descent methods such as Adam. To avoid notation clutter, we retain the symbol $J$ in subsequent sections.
% where $o_j$ represents the ground-truth signed distance corresponding to the query point $\mathbf{q}_j$.

\subsection{Forward algorithm}\label{sec:forward}
The computation of all the terms $\exp(-\beta_i\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2) f(\colorquery{\mathbf{q}_j}, \colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)$ ($i=[1,\dots, I]$ and $j=[1,\dots, J]$) requires memory of complexity $\Theta(I\cdot J)$. This poses significant challenges when using PyTorch’s built-in automatic differentiation, particularly with large batch sizes and high-resolution grids. To address this, we developed optimized algorithms for both the forward and backward passes.
A key observation is that the individual terms
$\exp(-\beta_i\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2) f(\colorquery{\mathbf{q}_j}, \colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)$
do not need to be explicitly stored. Instead, the computation requires only their summation,
$\sum^I_i\exp(-\beta_i\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2) f(\colorquery{\mathbf{q}_j}, \colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)$. 
By focusing solely on this summation, the memory complexity is reduced to $\Theta(J)$, making the computation more efficient.

The algorithm is summarized in \cref{alg:forward}. Leveraging this approach, we implemented a fused CUDA forward kernel. The summations in the algorithm are further optimized using a fast maximum-reduce operator, supported by modern CUDA architectures. Given the similarity of $\mathcal{O}$ in design to the Attention~\cite{vaswani2017attention} mechanisms, our fused algorithm bears a resemblance to FlashAttention~\cite{dao2022flashattention}, which proposed a fused CUDA kernel for Attention.

Notably, the gradient $\frac{\partial \mathcal{O}}{\partial \colorquery{\mathbf{q}}}$ in~\cref{eq:func-normal} exhibits a similar structure. As a result, the same algorithm in \cref{alg:forward} is adapted with minimal modifications to compute the gradient efficiently. We show the diagram of the algorithm in~\cref{fig:cuda}.

\begin{algorithm}[tb]
\caption{Forward}\label{alg:forward}
\KwData{$\{\colorkey{\mathbf{k}_i}, \beta_i, \boldsymbol{\phi}_i\}^I_i$ and $\colorquery{\mathbf{q}_j}$}
\KwResult{$\mathcal{O}(\colorquery{\mathbf{q}_j})$, $e_j$}
$e_j=0$\;
$m_j=0$\;
\For{$i\in[1,\cdots, I]$}{
    $l\leftarrow \exp(-\beta_i\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2)$\;
    $e_j\leftarrow e_j + l$ \Comment*[r]{denominator}
    % $f\leftarrow f(\mathbf{q}_j-\mathbf{k}_i;\boldsymbol{\phi}_i)$\;
    $m_j\leftarrow m_j + l\cdot \colorvalue{f}(\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)$ \Comment*[r]{numerator}
}
$\mathcal{O}(\colorquery{\mathbf{q}_j})=m_j/e_j$ \Comment*[r]{save $e_j$ for backward}
\end{algorithm}

\begin{figure}
    \centering
    \includegraphics[width=1\linewidth]{images/cuda.pdf}
    \vspace{-20pt}
    \caption{Diagram for the forward and backward pass algorithm.}
    \label{fig:cuda}
\end{figure}
\subsection{Backward algorithm}\label{sec:backward}
As discussed earlier, existing automatic differentiation frameworks require substantial memory for this task. To overcome this limitation, the gradients of the loss function
$\mathcal{L}$ with respect to all the parameters $\{\colorkey{\mathbf{k}_i}, \beta_i, \boldsymbol{\phi}_i\}^I_i$ are computed manually. 
By the chain rule, for any loss function $\mathcal{L}$, we have
\begin{equation}
    \begin{aligned}
        \frac{\partial \mathcal{L}}{\partial \colorkey{\mathbf{k}_i}} & = \sum^J_{j=1}\frac{\partial \mathcal{L}}{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})} \frac{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})}{\partial \colorkey{\mathbf{k}_i}}, \\
        \frac{\partial \mathcal{L}}{\partial \beta_i} & = \sum^J_{j=1}\frac{\partial \mathcal{L}}{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})} \frac{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})}{\partial \beta_i}, \\
        \frac{\partial \mathcal{L}}{\partial \boldsymbol\phi_i} & = \sum^J_{j=1}\frac{\partial \mathcal{L}}{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})} \frac{\partial \mathcal{O}(\colorquery{\mathbf{q}_j})}{\partial \boldsymbol\phi_i}.
    \end{aligned}
\end{equation}


\begin{algorithm}[tb]
\caption{Backward}\label{alg:backward}
\KwData{$\{\colorkey{\mathbf{k}_i}, \beta_i, \boldsymbol{\phi}_i\}^I_i$, and $\displaystyle\left\{\colorquery{\mathbf{q}_j}, \mathcal{O}(\colorquery{\mathbf{q}_j)}, e_j, \frac{\partial\mathcal{L}}{\partial\mathcal{O}(\colorquery{\mathbf{q}_j})}\right\}_j^J$}
% , $\{\mathcal{O}(\mathbf{q}_j)\}^J_j$, and $\{e_j\}^J_j$}
\KwResult{$\displaystyle\left\{
\frac{\partial \mathcal{L}}{\partial \colorkey{\mathbf{k}_i}},
\frac{\partial \mathcal{L}}{\partial \beta_i},
\frac{\partial \mathcal{L}}{\partial \boldsymbol{\phi}_i}
\right\}_i^I$}
% $e_j=0$\;
% $m_j=0$\;
% Initialize gradients with zeros\;
$\partial \mathcal{L}/\partial \colorkey{\mathbf{k}_i}\leftarrow 0$\;
$\partial \mathcal{L}/\partial \beta_i\leftarrow 0$\;
$\partial \mathcal{L}/\partial \boldsymbol{\phi}_i\leftarrow 0$\;
\For{$j\in[1,\cdots, J]$}{
    $l\leftarrow \exp(-\beta_i\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2)/e_j$ \Comment*[r]{softmax}
    $\displaystyle \colorvalue{f}_i \leftarrow \colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)$ \Comment*[r]{evaluate $\colorvalue{f}$}
    $\displaystyle \partial \colorvalue{f}/\partial \colorkey{\mathbf{k}_i} \leftarrow \frac{\partial \colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)}{\partial \colorkey{\mathbf{k}_i}}$ \;
    % \Comment*[r]{grad w.r.t. \mykey}
    $\displaystyle \partial \colorvalue{f}/\partial \boldsymbol{\phi}_i \leftarrow \frac{\partial \colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)}{\partial \boldsymbol{\phi}_i}$ \;
    % \Comment*[r]{grad w.r.t. \myvalue}
    \Comment*[h]{grad w.r.t. $\colorkey{\mathbf{k}_i}$} \;
    $\partial\mathcal{O}/\partial\colorkey{\mathbf{k}_i}\leftarrow l \cdot \left\{\partial \colorvalue{f}/\partial \colorkey{\mathbf{k}_i} + 2\beta_i\left[\colorvalue{f_i}-\mathcal{O}(\colorquery{\mathbf{q}_j})\right](\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i})\right\}$\;
    $\partial \mathcal{L}/\partial \colorkey{\mathbf{k}_i}\leftarrow \partial \mathcal{L}/\partial \colorkey{\mathbf{k}_i} + \partial\mathcal{L}/\partial\mathcal{O}(\colorquery{\mathbf{q}_j}) \cdot \partial\mathcal{O}/\partial\colorkey{\mathbf{k}_i}$\;
    \Comment*[h]{grad w.r.t. $\beta_i$} \;
    $\partial\mathcal{O}/\partial\beta_i\leftarrow l \cdot \left\{-\left\|\colorquery{\mathbf{q}_j}-\colorkey{\mathbf{k}_i}\right\|^2\left[\colorvalue{f_i}-\mathcal{O}(\colorquery{\mathbf{q}_j})\right]\right\}$\;
    $\partial \mathcal{L}/\partial \beta_i\leftarrow \partial \mathcal{L}/\partial \beta_i + \partial\mathcal{L}/\partial\mathcal{O}(\colorquery{\mathbf{q}_j}) \cdot \partial\mathcal{O}/\partial\beta_i$\;
    \Comment*[h]{grad w.r.t. $\boldsymbol{\phi}_i$} \;
    $\partial\mathcal{O}/\partial\boldsymbol{\phi}_i\leftarrow l \cdot \left\{\partial \colorvalue{f}/\partial \boldsymbol{\phi}_i\right\}$\;
    $\partial \mathcal{L}/\partial \boldsymbol{\phi}_i\leftarrow \partial \mathcal{L}/\partial \boldsymbol{\phi}_i + \partial\mathcal{L}/\partial\mathcal{O}(\colorquery{\mathbf{q}_j}) \cdot \partial\mathcal{O}/\partial\boldsymbol{\phi}_i$\;
}
% $\mathcal{O}(\mathbf{q}_j)=m_j/e_j$\;
\end{algorithm}
The gradient of the function $\mathcal{O}$ with respect to the parameters are
\begin{equation}
    \begin{aligned}
        \frac{\partial \mathcal{O}(\colorquery{\mathbf{q}})}{\partial \colorkey{\mathbf{k}_i}} &=&& 
        \colorweight{\mathrm{softmax}}(-\beta_i\left\|\colorquery{\mathbf{q} - \colorkey{\mathbf{k}_i}}\right\|^2)% \frac{\exp\left(-\beta_i\left\|\mathbf{q}-\mathbf{k}_i\right\|^2\right)}{\sum^I_i \exp\left(-\beta_i\left\|\mathbf{q} -\mathbf{k}_i\right\|^2\right)}
        \\
        &&& \cdot \left\{\frac{\partial \colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)}{\partial \colorkey{\mathbf{k}_i}}+2\beta_i(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i})\left[\colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i))-\mathcal{O}(\colorquery{\mathbf{q}})\right]\right\},
    \end{aligned}
\end{equation}
\begin{equation}
    \begin{aligned}
        \frac{
            \partial \mathcal{O}(\colorquery{\mathbf{q}})
        }{
            \partial \beta_i
        } &=&& 
        \colorweight{\mathrm{softmax}}(-\beta_i\left\|\colorquery{\mathbf{q} - \colorkey{\mathbf{k}_i}}\right\|^2)
        % \frac{\exp\left(-\beta_i\left\|\mathbf{q}-\mathbf{k}_i\right\|^2\right)}{\sum^I_i \exp\left(-\beta_i\left\|\mathbf{q} -\mathbf{k}_i\right\|^2\right)} 
        \\
        &&& \cdot \left\{-\left\|\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i}\right\|^2 \cdot [\colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)-\mathcal{O}(\colorquery{\mathbf{q}})]\right\},
    \end{aligned}
\end{equation}

\begin{equation}
    \begin{aligned}
        \frac{\partial \mathcal{O}(\colorquery{\mathbf{q}})}{\partial \boldsymbol{\phi}_i} &= &&
        \colorweight{\mathrm{softmax}}(-\beta_i\left\|\colorquery{\mathbf{q} - \colorkey{\mathbf{k}_i}}\right\|^2) % \frac{\exp\left(-\beta_i\left\|\mathbf{q}-\mathbf{k}_i\right\|^2\right)}{\sum^I_i \exp\left(-\beta_i\left\|\mathbf{q} -\mathbf{k}_i\right\|^2\right)}
        \frac{\partial \colorvalue{f}(\colorquery{\mathbf{q}}-\colorkey{\mathbf{k}_i};\boldsymbol{\phi}_i)}{\partial \boldsymbol{\phi}_i}.
    \end{aligned}    
\end{equation}
It is important to note that all calculations require the denominator
$\sum^I_i \exp\left(-\beta_i\left\|\colorquery{\mathbf{q}} -\colorkey{\mathbf{k}_i}\right\|^2\right)$. 
Therefore, this value is directly utilized from the forward pass algorithm. The complete implementation is detailed in~\cref{alg:backward}. Furthermore, all computations are efficiently fused into a single CUDA kernel for optimal performance. 



