&
\cB[A_0] & \cB[A_0+1] & \cB[\dots] & \cB[A_1-1]
&
\cC[\dots]
&
\cD[A_{n-2}] & \cD[A_{n-2}+1] & \cD[\dots] & \cD[A_{n-1}-1]
\\
F
&
\Block{1-4}{A_0} & ~ & ~ & ~
&
\Block{1-4}{A_1} & ~ & ~ & ~
&
\dots
&
\Block{1-4}{A_{n-1}} & ~ & ~ &
% \Block[borders={bottom,right,top,tikz={draw=white}}]{1-1}{~}
\CodeAfter
  \OverBrace[shorten,yshift=4pt]{1-1}{1-4}{a_0}
  \OverBrace[shorten,yshift=4pt]{1-5}{1-8}{a_1}
  \OverBrace[shorten,yshift=4pt]{1-10}{1-13}{a_{n-1}}
  \UnderBrace[shorten,yshift=4pt]{1-1}{2-4}{X=0}
