  \OverBrace[shorten,yshift=4pt]{1-10}{1-13}{a_{n-1}}
\end{NiceArray}\,.
\\[5pt]
\end{align*}
%
The top array shows all possible values of $U\sim \Uniform[0,A_{n-1})$
and the bottom array shows the lookup table $T$.
%
Since $T$ has length $A \equiv A_{n-1}$ and must be stored in memory,
lookup table sampling scales exponentially with the number of bits needed
to encode $P$.

