%     \[
%         \forall \mathcal{M}. \quad \arg\max_{\pi} J_{\mathcal{M} \mid_L \mathcal{M}_{D_{\Sigma, n}}}(\pi) = \arg\max_{\pi_\mathcal{Z} \circ \phi} J_{\mathcal{M} \mid_L \mathcal{M}_{D_{\Sigma, n}}}(\pi_{\mathcal{Z}} \circ \phi),
%     \]
%     where $\pi_{\mathcal{Z}} \circ \phi (s, \mathcal{A}) = \pi_\mathcal{Z}(s, \phi(\mathcal{A}))$.
% \end{problem}

\begin{assumption}\label{assume:capacity}
    $\phi: D_{\Sigma, n} \to \mathcal{Z}$ has enough capacity to represent DFAs in its domain.
    That is, the learnable encoder $\phi$ has a parametrization that can map distinct DFAs in $D_{\Sigma, n}$ to unique~embeddings.
\end{assumption}

Intuitively, we want a policy conditioning on the latent representations of DFAs (rather than DFAs themselves) to be equivalent to the theoretical formulation given in \Cref{defn:dfa-rl}, i.e., one finds the optimal solution whenever the other does so.
Observe that even under \Cref{assume:capacity}, one does not get such a guarantee directly since the claim is not only an expressivity argument but also involves proving that the training procedure of the encoder provides such representations.
In the following, we present a training technique for such encoders and prove that it solves \Cref{problem:main}.
Our method involves learning a \emph{bisimulation metric} over the induced MDP of a given DFA space.
Therefore, we first define bisimulation metrics and then show how they can be computed in deterministic MDPs.

