\section{Goal-Conditioned Reinforcement Learning}\label{sec:gcrl}

Here, for reference, we present the standard Goal-Conditioned Reinforcement Learning (GCRL) problem. We start by defining the environment model for conditioning on \emph{goals}, usually given as sets of states or continuous regions, as done by~\cite{schaul2015universal,liu2022goal}.

% Goal-Conditioned MDP Extension
\begin{my_definition}[Goal-Conditioned MDP]
A goal-conditioned MDP extends the standard MDP by incorporating a goal space given by a goal distribution $\mathcal{G} \in \Delta(2^S)$, where $\mathcal{G}$ is a distribution over sets of states, and therefore a goal is a set of states.
It is defined as the tuple
\[
\mathcal{M}_\mathcal{G} = \langle S, A, P, R_\mathcal{G}, \iota_{\mathcal{G}}, \gamma \rangle,
\]
where:
\begin{itemize}
    \item $R_\mathcal{G}: S \times A \times G \to \mathbb{R}$ is the goal-conditioned reward function, and
    \item $\iota_\mathcal{G} : S \times G \to [0, 1]$ is the initial state-goal distribution defined by $\iota_\mathcal{G}(s, g) = \iota(s) \mathcal{G}(g)$.
\end{itemize}
\end{my_definition}

Given a goal-conditioned MDP, the standard GCRL problem is to find a policy that achieves a given goal, which was first introduced by~\cite{schaul2015universal}.

% Goal-Conditioned RL Problem
\begin{my_definition}[Goal-Conditioned Reinforcement Learning]\label{defn:gcrl}
Given a goal-conditioned MDP $\mathcal{M}_\mathcal{G}$, the \textbf{Goal-Conditioned Reinforcement Learning} (GCRL) problem is to find a policy
\[
\pi: S \times G \to \Delta(A),
\]
which maps a state-goal pair $(s,g)$ to a distribution over actions, that maximizes the expected cumulative discounted reward:
\[
J_{\mathcal{M}_\mathcal{G}}(\pi) = \mathbb{E}_{s_0, g \sim \iota_\mathcal{G}} \left[ \sum_{t=0}^{s_t \in g} \gamma^t R_\mathcal{G}(s_t, a_t, g) \right],
\]
where trace \(\{(s_t, a_t)\}_{t\ge0}\) is generated by $a_{t} \sim \pi(s_t)$ and $s_{t+1} \sim P(s_t,a_t)$ until $s_t \in g$ is reached.
The objective is to solve
\[
\pi^* = \arg\max_{\pi} J_{\mathcal{M}_\mathcal{G}}(\pi).
\]
\end{my_definition}

The standard GCRL formulation doesn't inherently allow for specifying temporally extended tasks since the goals are defined as sets of states.
In theory, one can extend the state definition to a product state and specify temporal tasks within that product state; however, such approaches limit the scalability of the GCRL framework.
On the other hand, our DFA-conditioned RL formulation given in \Cref{defn:dfa-rl} allows for specifying temporal tasks and enables optimal multi-task policy learning.
% Therefore, to specific temporally extended tasks to a policy, we will use a formal model encoding the temporal task and give a new problem formulation.

\section{Pseudometrics and Metrics}\label{sec:metric}

\begin{my_definition}[Pseudometric and Metric]
Let \(X\) be a nonempty set. A function \(d: X \times X \to [0,\infty)\) is called a \textbf{pseudometric} on \(X\) if for all \(x, y, z \in X\) the following conditions hold:
\begin{enumerate}
    \item \textbf{Non-negativity:} \(d(x,y) \ge 0\).
    \item \textbf{Identity on the diagonal:} \(d(x,x) = 0\).
    \item \textbf{Symmetry:} \(d(x,y) = d(y,x)\).
    \item \textbf{Triangle Inequality:} \(d(x,z) \le d(x,y) + d(y,z)\).
\end{enumerate}
If \(d(x,y) = 0\) implies \(x = y\), then \(d\) is a \textbf{metric}.
% $\mathbb{M}_X$ is the set of all pseudometrics on a set $X$, i.e.,
% \[
% \mathbb{M}_X \triangleq \{ d: X \times X \to [0,\infty) \mid_L d \text{ is a pseudometric on } X \}.
% \]
\end{my_definition}

Essentially, a metric is a function measuring the distance between any two points in a space, satisfying non-negativity, symmetry, the triangle inequality, and it equals zero if and only if the two points are identical. A pseudometric, on the other hand, allows distinct points to have a distance of zero, meaning it might not fully distinguish between different points in the space.

\section{Proofs of Theorems and Lemmas}

\pac*
\begin{proof}
    A DFA-conditioned MDP $\mathcal{M} \mid_L \mathcal{M}_{D_{\Sigma, n}}$ is defined over the state space \(S \times D_{\Sigma,n}\), where \(D_{\Sigma,n}\) is a DFA space. Since \(D_{\Sigma,n}\) is finite (as all DFAs in \(D_{\Sigma,n}\) has a finite alphabet $\Sigma$ and at most $n$ states), the product state space has size \(|S|\cdot|D_{\Sigma,n}|\) and is an MDP. Thus, any PAC-MDP algorithm that works for MDPs with state space size \(|S|\) will also work on the product MDP with state space size \(|S|\cdot|D_{\Sigma,n}|\), with sample complexity increasing by at most a factor polynomial in \(|D_{\Sigma,n}|\).
\end{proof}

\nobisim*
\begin{proof}
    If $\mathcal{A} \sim \mathcal{A}'$, then they must agree on acceptance, by~\Cref{defn:dfa-bisim}.
    We have \(R_{D_{\Sigma, n}}(\mathcal{A}) = 1\) if and only if \(\mathcal{A} = \mathcal{A}_\top\).
    Since \(\mathcal{A}\) and \(\mathcal{A}'\) are bisimilar, \(\mathcal{A} = \mathcal{A}_\top \iff \mathcal{A}' = \mathcal{A}_\top\).
    The same reasoning for the $-1$ reward case gives \(R_{D_{\Sigma, n}}(\mathcal{A}) = R_{D_{\Sigma, n}}(\mathcal{A}')\), i.e.,
    \(\mathcal{A}\) and \(\mathcal{A}'\) satisfy reward equivalence in \(\mathcal{M}_{D_{\Sigma, n}}\).
    For any \(a \in \Sigma\), \(T_{D_{\Sigma, n}}(\mathcal{A}, a)\) results in a DFA bisimilar to \(T_{D_{\Sigma, n}}(\mathcal{A}', a)\) due to \Cref{defn:dfa-bisim}. By induction on the structure of \(\mathcal{A}\) and \(\mathcal{A}'\), their transitions preserve bisimilarity, satisfying the transition equivalence.
    % Thus, \(T_{D_{\Sigma, n}}(\mathcal{A}, a) \sim_{\mathcal{M}_{D_{\Sigma, n}}} T_{D_{\Sigma, n}}(\mathcal{A}', a)\), satisfying the transition equivalence.
    Therefore, we have \(\mathcal{A} \sim \mathcal{A}' \implies \mathcal{A} \sim_{\mathcal{M}_{D_{\Sigma, n}}} \mathcal{A}'\).

    If $\mathcal{A} \sim_{\mathcal{M}_{D_{\Sigma, n}}} \mathcal{A}'$, then \(R_{D_{\Sigma, n}}(\mathcal{A}) = R_{D_{\Sigma, n}}(\mathcal{A}')\).
    Thus, $\mathcal{A}$ and $\mathcal{A}'$ must agree on acceptance by \Cref{defn:dfa-mdp}.
    For every \(a \in \Sigma\), \(T_{D_{\Sigma, n}}(\mathcal{A}, a) \sim_{\mathcal{M}_{D_{\Sigma, n}}} T_{D_{\Sigma, n}}(\mathcal{A}', a)\) by \Cref{defn:dfa-mdp}. By induction on the DFA transition structure (which is finite), \(T_{D_{\Sigma, n}}(\mathcal{A}, a)\) and \(T_{D_{\Sigma, n}}(\mathcal{A}', a)\) are bisimilar. As transitions under all \(a \in \Sigma\) preserve bisimilarity, the initial states \(q_0\) and \(q_0'\) must be related under the bisimulation relation. Thus, \(\mathcal{A}\) and \(\mathcal{A}'\) are bisimilar, i.e., \(\mathcal{A} \sim \mathcal{A}' \impliedby \mathcal{A} \sim_{\mathcal{M}_{D_{\Sigma, n}}} \mathcal{A}'\).
\end{proof}

\operator*
\begin{proof}
    Let $\mathcal{M} = \langle S, A, P, R, \iota, \gamma \rangle$ be an MDP. Define
    \[
        d^{k}(s, t)
        \gets
        \arg\max_{a\in A}
        \left\{
        \left|
        R(s, a) - R(t, a)
        \right|
        +
        \gamma
        \mathcal{W}_1(d)
        \left(
        P(s, a), P(t, a)
        \right)
        \right\},
    \]
    where $\mathcal{W}_1$ is the 1-Wasserstein metric.
    \cite{ferns2004metrics} showed that this operator has a unique fixed point $d^{*}$, and $d^{*}$ is a bisimulation metric.
    Later, \cite{castro2020scalable} proved that if $\mathcal{M}$ is deterministic, with transition function $T$, then the 1-Wasserstein metric above implies as follows:
    \[
        \mathcal{W}_1(d)
        \left(
        P(s, a), P(s, a)
        \right)
        =
        d
        \left(
        T(s, a), T(s, a)
        \right).
    \]
    We write the distance and the policy update separately since we want to learn the $\arg\max$--hard to compute directly.
    However, then we need to prove that the distance metric still has a unique fixed point when updated with actions from a policy being simultaneously learned.
    A useful result due to \cite{zhang2020learning} (which we present by combining with the result of \cite{castro2020scalable} and our notation) shows that given a continuously improving policy $\pi$, the following operator:
    \[
        d^{k}(s, t)
        \gets
        \left|
        R(s, \pi(s, t)) - R(t, \pi(s, t))
        \right|
        +
        \gamma
        d
        \left(
        T(s, \pi(s, t)), T(s, \pi(s, t))
        \right)
    \]
    has a unique fixed point $d^*$, and $d^*$ is a $\pi^*$-bisimulation metric.
    In our case, $\pi^*$ is the $\arg\max$ policy and therefore the unique fixed point $d^*$ is a bisimulation metric.


\end{proof}

\unique*
\begin{proof}
By \Cref{thm:operator}, $d^*(\mathcal{A}, \mathcal{A}') = \| \hat{\phi}^*(\mathcal{A}) - \hat{\phi}^*(\mathcal{A}') \|_2$ is a bisimulation metric.
Therefore, $d^*(\mathcal{A}, \mathcal{A}') = 0 \implies \mathcal{A} \sim_{\mathcal{M}_{D_{\Sigma, n}}} \mathcal{A}'$ by \Cref{defn:bisim-metric} and thus, by \Cref{lemma:no-bisim}, we have $\mathcal{A} \sim \mathcal{A}'$.
As $d^*(\mathcal{A}, \mathcal{A}') = 0$ implies $\phi^*(\mathcal{A}) = \phi^*(\mathcal{A}')$,
we have $\mathcal{A} \sim \mathcal{A}' \iff \phi^*(\mathcal{A}) = \phi^*(\mathcal{A}')$.
The forward direction is true since if $\mathcal{A} \sim \mathcal{A}'$, then $d^*(\mathcal{A}, \mathcal{A}') = 0$ by \Cref{defn:bisim-metric}; thus, $\phi^*(\mathcal{A}) = \phi^*(\mathcal{A}')$.
\end{proof}

\main*
\begin{proof}
    The optimal encoder $\phi^*$ maps two DFAs to the same latent representation if and only if they are bisimilar by \Cref{thm:unique}. So, every unique task in $D_{\Sigma, n}$ is represented in $\mathcal{Z}$.
    Therefore, the problem given in \Cref{defn:dfa-rl} can be equivalently reformulated over \( \mathcal{Z} \), which solves \Cref{problem:main}.
\end{proof}

