	\item[] $(u,\varepsilon)\theta (v,\varepsilon')$ iff $u = v$,%The partition of the set $U'$ has as classes the subsets of the form $\{(u,0), (u,1)\}$, for each $u \in U$.

	\item[] $f(x) = (e(x),0)$,

	\item[] For any $n$-ary predicate letter $R$ in $L$, a relation $R^{\sigma} \in (U')^n$ given by 
	\begin{eqnarray*}
