\section{Quasi-stratified orders}
\label{sect-qso}

As far as we are aware
the next definition introduces a new class of partial 
orders, positioned in-between stratified and
interval orders.

\begin{definition}[\textsc{qs}-order]
\label{def-qso} 
\emph{Quasi-stratified orders} (or \textsc{qs}-orders) 
are the smallest set $\QSO$ such that $\FA{\es,\es}\in\QSO$ and the following hold, 
for all $\qso=\FA{\Delta,\prec}$ and $\qso'=\FA{\Delta',\prec'}$ in $\QSO$:
\begin{itemize} 
\item 
 If $x\notin \Delta$,
 then $ \qso[x]=\FA{\Delta\cup\{x\},\prec}$ belongs to $\QSO$.
\item 
 If $\Delta\cap\Delta'=\es$, then
$\qso\circ\qso'=\FA{\Delta\cup \Delta', 
(\prec\cup\prec')\cup (\Delta\times \Delta')}$ belongs to $\QSO$.
\end{itemize}
Moreover, $\qso\in \QSO$ is a \textsc{qso}-stratum
if there are $\qso'\in\QSO$ and $x$ such that $\qso=\qso'[x]$.
\eod
\end{definition} 

\begin{proposition}
\label{prop-uqiqef}
Let $\qso=\FA{\Delta,\prec}\in\QSO$. Then:
\begin{enumerate}
 \item 
 $\qso\circ\FA{\es,\es}=\FA{\es,\es}\circ\qso=\qso$.
 \item
 $\qso|_\Phi=\FA{\Phi,\prec|_{\Phi\times\Phi}}\in\QSO$, for every $\Phi\subseteq \Delta$; 
 \ie \textsc{qs}-orders are projection-closed.  

\item 
$\qso$ is a \textsc{qso}-stratum iff 
$\qso\neq\FA{\es,\es}$ and there is 
$x\in\Delta_\qso$ such that 
$x\not\prec_\qso z\not\prec_\qso x$, for every $z\in\Delta_\qso\setminus\{x\}$.

\item 
If $\qso\neq\FA{\es,\es}$, then there is a unique
sequence $\qso_1,\dots,\qso_n$ ($n\geq 1$)
of \textsc{qso}-strata 
such that $\qso=\qso_1\circ\dots\circ\qso_n$.
\end{enumerate} 
\end{proposition}
\begin{proof}
All parts follows directly from Definition~\ref{def-qso}. We only note that
`$\circ$' is an associative operation, and
$ 
 (\qso'\circ\qso'')|_\Psi= \qso'|_{\Psi\cap\Delta_{\qso'}}\circ\qso''|_{\Psi\cap\Delta_{\qso''}}$, 
 for all $\qso',\qso''\in\QSO$ with disjoint domains and
 $\Psi\subseteq \Delta_{\qso'}\cup \Delta_{\qso''}$.
\end{proof}

The following result provides an axiomatic characterisation of \textsc{qs}-orders, 
similar to those given for stratified and interval orders.

\begin{theorem}
\label{prop-axioms_qso}
Let $\rs=\FA{\Delta, \prec}$, where $\prec$ is a binary relation over 
a finite set $\Delta$.
Then $\rs\in\QSO$ iff the following hold, for all $x,y,z,t\in \Delta$:
\begin{equation*}
\label{axioms-qso}
\begin{array}{lll@{~~~}c@{~~~}l@{~~~~~}l@{~~~}lr@{~~~}c@{~~~}l@{~~~~~}l@{~~~}l}
 \textsc{qso{:}1}
 &:
 & 
 x\not\prec x 
 \\ 
 \textsc{qso{:}2} 
 & :
 &
 x\prec y \land z \prec t
 & \Longrightarrow
 & x\prec t \land z\prec y \,~\lor~\,x\prec z \land x\prec t \,~\lor~\,
 %\\
 %&& &&
 z\prec x \land z\prec y \,~\lor~\, 
 t\prec y \land z\prec y \,~\lor~\, 
 y\prec t \land x\prec t 
\end{array}
\end{equation*} 
\end{theorem}
\begin{proof}
($\Longrightarrow$) 
We proceed by induction on the derivation of $\rs\in\QSO$ (see Definition~\ref{def-qso}).

First, we observe that $\rs=\FA{\es,\es}$ trivially satisfies \textsc{qso{:}1,2}.
In the inductive case, we consider the following two cases.

\emph{Case 1:}
$\rs=\qso[x]$, where $\qso\in\QSO$ and $x\notin\Delta$. Then, by the induction 
hypothesis, $\qso$ satisfies \textsc{qso{:}1,2}. Hence,
$\rs$ also satisfies \textsc{qso{:}1,2} as we neither introduced nor 
removed any relationships.

\emph{Case 2:}
$\rs=\qso'\circ\qso''$, where $\qso'=\FA{\Delta',\prec'}\in\QSO$ and 
$\qso''=\FA{\Delta'',\prec''}\in\QSO$ satisfy 
$\Delta'\cap\Delta''=\es$.
Then we may additionally assume that $\Delta'\neq\es\neq\Delta''$ as $\qso'=\FA{\es,\es}$ 
(or $\qso''=\FA{\es,\es}$) implies $\rs=\qso''$ (resp.\ $\rs=\qso'$). As a result, by the 
induction hypothesis, both $\qso'$ and $\qso''$ satisfy \textsc{qso{:}1,2}.
Hence, $\rs$ satisfies \textsc{qso{:}1} as we introduced new relationships only between disjoint sets $\Delta'$ and $\Delta''$. 
\\
To show that \textsc{qso{:}2} is satisfied by $\rs$, we take any $x,y,z,t\in\Delta'\cup\Delta''$ such that $x\prec y$ and $z\prec t$. 
As 
$y\in\Delta'$ / $t\in\Delta'$ / $x\in\Delta''$ / $z\in\Delta''$
implies
$x\in\Delta'$ / $z\in\Delta'$ / $y\in\Delta''$ / $t\in\Delta''$, respectively,
we have the following cases to consider (after omitting the symmetric ones):
\begin{itemize}
\item 
 $x,y,z,t\in\Delta'$ or $x,y,z,t\in\Delta''$. Then
 \textsc{qso{:}2} is satisfied as
 it holds for both $\qso'$ and $\qso''$.

\item 
 $x\in\Delta'$ and $y,z,t\in\Delta''$. Then we have $x\prec z$ and $x\prec t$.

\item 
 $x,y,z\in\Delta'$ and $t\in\Delta''$. Then 
 we have $z\prec y$ and $t\prec y$.

\item 
 $x,y\in\Delta'$ and $z,t\in\Delta''$. Then 
 we have $x\prec z$ and $x\prec t$.

\item 
 $x,z\in\Delta'$ and $y,t\in\Delta''$. Then 
 $x\prec t$ and $z\prec y$.
\end{itemize}
Hence $\rs$ satisfies \textsc{qso{:}2}. 

($\Longleftarrow$) 
Suppose that $\rs=\FA{\Delta,\prec}$ satisfies \textsc{qso{:}1,2}.
We first observe that $\rs$ is an interval order (and so also a partial order). 
Indeed, since \textsc{qso{:}1}
holds for $\rs$, 
all we need to show is that $x\prec y \wedge z\prec t$ implies $x\prec t \wedge z\prec y$. 
And this, clearly, follows from \textsc{qso{:}2}.

We then prove 
the ($\Longleftarrow$) implication by induction on $|\Delta|$.
To start with, if $|\Delta|\leq 1$ then, by \textsc{qso{:}1}, $\rs\in\QSO$.
In the inductive case $|\Delta|>1$ and we consider the following two cases.

\emph{Case 1:}
There is $x\in\Delta$ such that $x\not\prec y\not\prec x$,
 for every $y\in\Delta$. 
 Then, by the induction hypothesis, 
 $\rs' = \FA{\Delta\setminus\{x\},\prec}$ is an \textsc{qs}-order.
 Moreover, $\rs = \rs'[x]$ and so,
 by Definition~\ref{def-qso}, $\rs$ also is an \textsc{qs}-order.

\emph{Case 2:}
 For every $x\in\Delta$ there is $y\in\Delta$ such that $x\prec y$ or $y\prec x$ ($\dagger$).
Then, let 
\[
M=\{x\in\Delta\mid \neg\exists y\in\Delta:~y\prec x\}
~~\mbox{and}~~
B=\{x\in M \mid \forall z\in M :~ |N_x|\leq |N_z|\}\;,
\]
 where $N_z=\{w\in\Delta \mid z\prec w\}$, for every $z\in\Delta$.
 We observe that $M\neq\es$ as $\rs$ is a finite partial
 order (note that \textsc{po{:}2} follows from \textsc{qso{:}1,2}),
 and so also $B\neq\es$.
 Moreover, for every $z\in M$, we have $N_z\neq \es$, by 
 $z\in M$ and ($\dagger$). 
 (Intuitively, from the set $M$ of topologically minimal elements 
 of $\rs$ we distinguished the minimal ones w.r.t.\ the out-degree; the set of such 
 elements is the root of the \textsc{qs}-sequence corresponding to $\rs'$ defined below.) 

 We first observe that $N_x\subseteq N_w$, for all $w\in M$ and $x\in B$ ($\ddagger$). 
 Indeed, if this is not true, then $N_x\setminus N_w\neq \es$. Moreover, by the definition of $B$,
 $|N_x|\leq |N_w|$. Hence, $N_w\setminus N_x\neq \es$. 
 Therefore, there are $y,t\in\Delta$ such that
 $x\prec y$, $w\prec t$, $x\not\prec t$, and $w\not\prec y$,
 yielding to a contradiction with \textsc{qso{:}2}.

 Let $x$ be any element of $B\neq\es$, $N=N_x$, and $P = \Delta\setminus N_x$. 

 Moreover, $(N\times P)\cap\prec=\es$ ($\dagger\dagger$). Indeed, if $a\in N$ and $b\in P$
 such that $a\prec b$, then $x\prec a\prec b$, and so $x\prec b$.
 This, however, means that $b\in N$, a contradiction.

 Both $P$ and $N$ are nonempty disjoint sets ($P\neq\es$ as $x\notin N_x$).
 Hence, 
 by the induction hypothesis, 
 $\rs'=\rs|_P$ and $\rs''=\rs|_N$ are \textsc{qs}-orders.

 Suppose that $\rs \neq \rs' \circ \rs''$.
 Then, by Definition~\ref{def-qso} and ($\dagger\dagger$), there are $a\in P$ and $b\in N$ such that $a\not\prec b$.
 By ($\ddagger$), $a\in P\setminus M$ and, since $\prec$ is transitive, there is $c\in M$ such that $c\prec a$. 
 Also, $x\prec b$. Therefore, by \textsc{qso{:}2}, one of the following five cases must hold.
\begin{itemize}
\item $x\prec a$ and $c\prec b$. Then $a\in N$, a contradiction.
\item $x\prec c$ and $x\prec a$. Then $c\notin M$, a contradiction.
\item $c\prec x$ and $c\prec b$. Then $x\notin M$, a contradiction.
\item $b\prec a$ and $x\prec a$. Then $a\in N$, a contradiction.
\item $a\prec b$ and $c\prec b$. Then we obtain a contradiction as we assumed $a\not\prec b$.
\end{itemize}
As a result, $\rs = \rs' \circ \rs''$ and so, by Definition~\ref{def-qso}, $\rs$ is a \textsc{qs}-order. 
\end{proof}

We can now show that

\begin{proposition}
\label{prop-vrev}
All stratified orders are 
\textsc{qs}-orders, and all \textsc{qs}-orders are interval orders.
\end{proposition}
\begin{proof}
To show the first inclusion,
let $\rs=\FA{\Delta,\prec}\neq \FA{\es,\es}$ be a stratified order and
$\Delta_1,\dots,\Delta_n$ ($n\geq 1$) be a partition of $\Delta$ such that 
$\prec$ is equal to $\bigcup_{1\leq i<j\leq n}\Delta_i\times\Delta_j$.
Let $\rs_i=\FA{\Delta_i,\es}$, for every $1\leq i \leq n$.
By Definition~\ref{def-qso}, $\rs_i\in \QSO$, for every $1\leq i \leq n$.
Hence, if $n=1$, we obtain $\rs=\rs_1\in\QSO$.
Otherwise, again by Definition~\ref{def-qso},
$\rs=(\dots(\rs_1\circ \rs_2)\circ \dots )\circ\rs_n\in \QSO$.

The second inclusion
follows directly from Theorem~\ref{prop-axioms_qso}($\Rightarrow$) and 
the observation made at the beginning of the proof of
Theorem~\ref{prop-axioms_qso}($\Leftarrow$). 
\end{proof}

