In this section, we introduced quasi-stratified orders which, we believe,
provide a faithful representation of behaviours for a range of concurrent computing 
systems. In fact, we provided two different ways of defining \textsc{qs}-orders, and
the decision which one to use will typically depend on 
the context.

\section{Quasi-stratified sequences}

To explain the rationale behind the adjective in `quasi-stratified order',
we need an auxiliary notion of
a \emph{quasi-stratified sequences} (or \textsc{qs}-sequences).

\begin{definition}[\textsc{qs}-sequence and \textsc{qss}-stratum]
\label{def-qss} 
\emph{Quasi-stratified sequences} (or \textsc{qs}-sequences) 
and \emph{quasi-stratified sequence strata} (or \textsc{qss}-strata)
are the smallest sets, $\QSS$ and $\QSSS$, respectively, 
such that the following hold
(below we also define the domain $\delta_\qss$ of each $\qss\in\QSS$):
\begin{itemize} 

\item
 $\Delta\in\QSS\cap\QSSS$, for every finite nonempty set $\Delta$.
 Moreover, $\delta_\Delta=\Delta$. 

\item
 $\qsss_1\dots\qsss_n\in\QSS$,
 for every $n\geq 2$ and all \textsc{qss}-strata $\qss_1,\dots,\qss_n$    
 with mutually disjoint domains.
 Moreover,
 $\delta_{\qsss_1\dots\qsss_n}=\delta_{\qsss_1}\cup\dots\cup\delta_{\qss_n}$. 

 \item 
 $\FA{\Delta,\qsss_1\dots\qsss_n}\in\QSS\cap\QSSS$,
 for every  $n\geq 2$, every finite nonempty set $\Delta$,   
 and all \textsc{qss}-strata $\qss_1,\dots,\qss_n$    
 with mutually disjoint domains satisfying 
 $\Delta\cap\delta_{\qsss_1\dots\qsss_n}=\es$. 
 Moreover,
 $\delta_{\FA{\Delta,\qsss_1\dots\qsss_n}}=
 \Delta\cup\delta_{\qsss_1\dots\qsss_n}$.
\eod 
\end{itemize}   
\end{definition} 
Clearly, \textsc{qss}-strata are also \textsc{qs}-sequences.    
Using a `tree-based methapor', each \textsc{qs}-sequence can be thought of as an ordered forest of trees whose
nodes are disjoint nonempty finite sets; moreover, 
each node either has no direct descendants or the direct descendants form an ordered sequence of 
at least two such trees. 

One can verify that \textsc{qs}-sequences are in a strict correspondence with 
nonempty \textsc{qs}-orders, through the mapping $\mathfrak{G}$ defined thus
(see Definitions~\ref{def-qso} and~\ref{def-qss}): 
\begin{enumerate} 
 \item 
 $\mathfrak{G}(\Delta)=\FA{\Delta,\es}$.

 \item
 $\mathfrak{G}(\qsss_1\dots\qsss_n)=\mathfrak{G}(\qsss_1)\circ \dots\circ\mathfrak{G}(\qsss_n)$.

 \item
 $\mathfrak{G}(\FA{\{x_1,\dots,x_k\},\qsss_1\dots\qsss_n})
 =\mathfrak{G}(\qsss_1\dots\qsss_n)[x_1]\dots[x_k]$. 
\end{enumerate} 
Note that in (2) and (3) above the order of application of the operations 
on the rhs does not matter.



We first show the soundness of the mapping $\mathfrak{G}$.

\begin{proposition}
\label{prop-ciue}
$\mathfrak{G}(\qss)\in \QSO$ and $\delta_\qss=\Delta_{\mathfrak{G}(\qss)}$, 
for every \textsc{qs}-sequence $\qss$.   
Moreover,
$\qss$ is a \textsc{qss}-stratum iff
$\mathfrak{G}(\qss)$ is a \textsc{qso}-stratum.
\end{proposition}
\begin{proof}
We proceed by induction on the syntax of \textsc{qs}-sequences.

In the base case, $\qss=\Delta=\{x_1,\dots,x_n\}$ ($n\geq 1$). Then
$\mathfrak{G}(\qss)=(\Delta,\es)=\FA{\es,\es}[x_1]\dots[x_n]\in\QSO$.
Moreover, $\delta_\qss=\Delta=\Delta_{\mathfrak{G}(\qss)}$.

In the inductive case we have the following:

\emph{Case 1:}  $\qss=\qsss_1\dots\qsss_n$ ($n\geq 2$). 
Then, by the induction hypothesis, $\mathfrak{G}(\qsss_i)\in \QSO$
and $\delta_{\qsss_i}=\Delta_{\mathfrak{G}(\qsss_i)}$,
for every $1\leq i\leq n$. Hence, we also have
$\delta_{\mathfrak{G}(\qsss_i)}\cap\delta_{\mathfrak{G}(\qsss_j)}$,
for all $1\leq i< j\leq n$.
Therefore,  by
Definitions~\ref{def-qso} and~\ref{def-qss}, 
$\mathfrak{G}(\qss)=\mathfrak{G}(\qsss_1)\circ\dots\circ\mathfrak{G}(\qsss_n)\in\QSO$
and $\delta_\qss=\Delta_{\mathfrak{G}(\qss)}$.

\emph{Case 2:}  $\qss=\FA{\Delta,\qss'}$
and $\Delta=\{x_1,\dots,x_k\}$, where  $k\geq 1$.
Then, by the induction hypothesis, $\mathfrak{G}(\qss')\in \QSO$
and  $\delta_{\qss'}=\Delta_{\mathfrak{G}(\qss')}$.
Hence, $\Delta\cap\Delta_{\mathfrak{G}(\qss')}=\es$.
Therefore, by Definition~\ref{def-qso},
$\mathfrak{G}(\qss)=\mathfrak{G}(\qss')[x_1]\dots[x_k]\in\QSO$
and $\delta_\qss=\Delta\cup\delta_{\qss'}=
\Delta\cup \Delta_{\mathfrak{G}(\qss')}=\Delta_{\mathfrak{G}(\qss)}$.

To show the second part, suppose that $\qss$ is a \textsc{qss}-stratum.
Then there is $x\in\Delta_{\mathfrak{G}(\qss)}$ such that 
$x\not\prec_{\mathfrak{G}(\qss)}z\not\prec_{\mathfrak{G}(\qss)}x$, for all
$z\in \Delta_{\mathfrak{G}(\qss)}\setminus\{x\}$.
Hence $\mathfrak{G}(\qss)$ is a \textsc{qso}-stratum.
Conversely, if $\mathfrak{G}(\qss)$ is a \textsc{qso}-stratum, then
there is $x\in\Delta_{\mathfrak{G}(\qss)}$ such that 
$x\not\prec_{\mathfrak{G}(\qss)}z\not\prec_{\mathfrak{G}(\qss)}x$, for all
$z\in \Delta_{\mathfrak{G}(\qss)}\setminus\{x\}$.
Hence, $\qss$ has to be of the form $\FA{\Delta,\qss'}$, and so
$\qss$ is a \textsc{qss}-stratum.
\end{proof} 

\begin{proposition}
\label{prop-ciuess}
$\mathfrak{G}:\QSS\to\QSO\setminus\{\FA{\es,\es}\}$
is an injective mapping.   
\end{proposition}
\begin{proof}
By Proposition~\ref{prop-ciue}, $\mathfrak{G}$ is well-defined
(note that $\Delta_{\FA{\es,\es}}=\es$).

Suppose that $\qss,\qss'\in\QSS$ are such that
$\mathfrak{G}(\qss)=\mathfrak{G}(\qss')=\qso=\FA{\Delta,\prec}\in\QSO$. To show
$\qss=\qss'$ we proceed by induction of $|\Delta|$.

In the base case, $|\Delta|=1$, we have $\qss=\qss'=\Delta$.
In the inductive case, suppose that $|\Delta|>1$ and consider two cases.

\emph{Case 1:} There is 
$x\in\Delta$ such that 
$x\not\prec z\not\prec x$, for all
$z\in \Delta \setminus\{x\}$.
Then, $\qss=\FA{\Delta_o,\qss_o}$ and $\qss'=\FA{\Delta'_o,\qss'_o}$.
Moreover, 
$\Delta_o=\{y\in\Delta\mid \forall z\in\Delta\setminus\{y\}: y\not\prec z \not\prec\}
=\Delta'_o$.
We therefore have $\Delta_o =\Delta'_o$ and $\mathfrak{G}(\qss_o)=\mathfrak{G}(\qss'_o)$.
Thus, by the induction hypothesis, $\qss_o=\qss'_o$, and so $\qss=\qss'$. 
\end{proof}

To show a one-to-one relationship between nonempty \textsc{qso}-orders 
and \textsc{qs}-sequences, we introduce a mapping 
\[\mathfrak{I}:\QSO\setminus\{\FA{\es,\es}\}\to\QSS\] such that, 
for every $\qso\in\QSO\setminus\{\FA{\es,\es}\}$, $\mathfrak{I}(\qso)$
is defined as follows:
\begin{itemize}
\item 
If $\qso$ is a \textsc{qs}-stratum then 
$\qso=\qso'[x_1]\dots[x_n]$, where $n\geq 1$.
Then $\mathfrak{I}(\qso)=\{x_1,\dots,x_n\}$ if $\qso'=\FA{\es,\es}$,
and
$\mathfrak{I}(\qso)=\FA{\{x_1,\dots,x_n\},\mathfrak{I}(\qso')}$ if $\qso'\neq\FA{\es,\es}$.


\item
If $\qso$ is not a \textsc{qs}-stratum, then there are \textsc{qso}-strata
$\qso_1,\dots,\qso_n$ ($n\geq 2$) such that 
$\qso=\qso_1\circ\dots\circ\qso_n$.
Then 
$\mathfrak{I}(\qso)=\mathfrak{I}(\qso_1)\dots \mathfrak{I}(\qso_n)$. 
\end{itemize} 

\begin{theorem}
\label{th-eic}
$\mathfrak{G}:\QSS\to\QSO\setminus\{\FA{\es,\es}\}$ and 
$\mathfrak{I}:\QSO\setminus\{\FA{\es,\es}\}\to\QSS$
are inverse bijections.
\end{theorem}
\begin{proof}
By Propositions~\ref{prop-ciue} and~\ref{prop-ciuess}, it suffices to show
that $\mathfrak{I}(\mathfrak{G}(\qss))=\qss$, for every $\qss\in\QSS$.
\end{proof}

\begin{remark}[\textsc{qs}-sequences]
\label{rem-3}
Using the notion of \textsc{qs}-sequence, the following is an alternative
definition of a nonempty \textsc{qs}-order: 
\begin{quote}
$\FA{\Delta,\prec}$ is a \textsc{qs}-order if there is a \textsc{qs}-sequence
$\qss=\qsss_1 \dots \qsss_n$ ($n\geq 1$) such that each $\qsss_i$ is a \textsc{qs}-stratum,
$\delta_{\qsss_1},\dots, \delta_{\qsss_n}$
form a partition of $\Delta$, 
and $\prec=\prec_{\mathfrak{G}(\qss)}$.
\end{quote} 
Intuitively, this means that the intervals corresponding to events can be 
partitioned into \textsc{qs}-strata (each being represented by 
a tree whose root is the `base' of a stratum). 
Note that if $\qsss_1=\Delta_1,\dots,\qsss_n=\Delta_n$, then the above   
coincides with
the alternative definition of stratified orders (see Section~\ref{subs-1}).
%\qed
\end{remark}

\section{Quasi-stratified structures}
\label{sect-qscs}

We are now ready to introduce relational structures which will be suitable 
as specifications of concurrent behaviours modelled by \textsc{qs}-orders.
Before that we introduce auxiliary notions.


\begin{definition}[\textsc{csc}-subset]
\label{def-oernier}
Let $\rs=\FA{\Delta,\prec,\sq}$ be a structure and $\Phi\subseteq\Delta$ be a nonempty set.
\begin{itemize}
\item 
$\Phi$ is a \emph{combined strongly connected subset} (or \textsc{csc}-subset)
if 
$\FA{\Phi,(\sq{\cup}\prec)|_{\Phi\times \Phi}}$ 
is a strongly connected directed graph. 
\item 
A \emph{pre-dominant} of $\Phi$ 
is any $x\in\Phi$ such that 
there is no $y\in\Phi$ satisfying $x\prec y$ or $y\prec x$.
We denote this by $x\in \predominants_\rs(\Phi)$.
\end{itemize} 
All \textsc{csc}-subsets of $\rs$ are denoted by $\CSCS(\rs)$, and
all \textsc{csc}-subsets of $\rs$ without
any pre-dominants by $\BCSCS(\rs)$. \EOD
\end{definition}
Intuitively, a \textsc{csc}-subset with pre-dominant $x$ is a potential
candidate for a nested stratum where $x$ belongs to the base (cf.\ Remark~\ref{rem-3}). 

\begin{definition}[\textsc{qsa}-structure]
\label{def-qsas} 
A structure 
is \emph{quasi-stratified acyclic} (or \textsc{qs}-acyclic) if it has no 
\textsc{csc}-subset without pre-dominant.
Then, a \emph{quasi-stratified acyclic structure} (or \textsc{qsa}-structure)
is a relational structure which is \textsc{qs}-acyclic.
All \textsc{qsa}-structures are denoted by $\QSAS$.
\EOD
\end{definition}

In the context of the discussion on `acyclicity' in Remark~\ref{rem-2},
in the case of \textsc{qsa}-structures, the role of `forbidden' 
cyclic substructures is played by 
\textsc{csc}-subsets without pre-dominants. The reason why such substructures are 
inadmissible can be explained in the following way. 
Suppose that $\Phi\in\BCSCS(\rs)$ and $\qso$ is a \textsc{qs}-order execution 
in which all events $\Phi$ are executed.
By definition, $\qso$ is either of the form $\qso'[x]$ or of the form 
$\qso'\circ\qso''$. The first case is not possible as then $x$ would be
pre-dominant of $\Phi$, contradicting $\Phi\in\BCSCS(\rs)$.
In the second case, 
all the events in $\Delta_{\qso'}$ must precede all the events in $\Delta_{\qso''}$,
but then, by $\Phi\in\BCSCS(\rs)$ and the strong connectivity property, 
there is a pair of events, $x\in\Delta_{\qso'}$ and $y\in\Delta_{\qso''}$,
such that $y\sq_\rs x$ or $y\prec_\rs x$, yielding to a contradiction with $x\prec_\qso y$. 

We end this section providing some basic properties of relational structures related with quasi-stratified acyclicity.

\begin{proposition}
\label{prop-jngserub}
Let $\rs$ and $\rs'$ be structures such that $\rs\pref\rs'$, and $\Phi\subseteq\Delta_\rs$.
Then:
\begin{enumerate}
 \item 
 $\CSCS(\rs)\subseteq\CSCS(\rs')$ and
 $\BCSCS(\rs)\subseteq\BCSCS(\rs')$.
 \item 
 $\CSCS(\rs|_\Phi)\subseteq\CSCS(\rs)$ and
 $\BCSCS(\rs|_\Phi)\subseteq\BCSCS(\rs)$.
\end{enumerate}
\end{proposition}
\begin{proof}
(1) follows directly from the definitions and the fact that 
adding additional arcs maintains the property of being a strongly connected subgraph,
and the fact that $\prec_\rs\subseteq\prec_{\rs'}$.

(2) follows from from the fact the all relationships
between the elements of $\Phi$
in $\rs|_\Phi$ are the same as in $\rs$.
\end{proof}


\begin{proposition}
\label{prop-radgih}
\textsc{qsa}-structures are projection-closed and intersection-closed.
\end{proposition}
\begin{proof}
It follows directly from Proposition~\ref{prop-jngserub}.
\end{proof}



\section{Maximal QS-structures}
\label{sec-max}

In this section we provide alternative definitions of maximal \textsc{qs}-structures together with some useful properties.

\begin{definition}[\textsc{qsm}-structure]
\label{def-qsms} 
A \emph{quasi-stratified maximal structure} (or \textsc{qsm}-structure) 
is a structure $\qsms = \FA{\Delta,\prec,\sq}$ such that the following hold, for all $x,y,z,t\in \Delta$:
\begin{equation*}
\label{axioms-maxqso}
\begin{array}{llr@{~~~}c@{~~~}l@{~~~~~}l@{~~~}lr@{~~~}c@{~~~}l@{~~~~~}l@{~~~}l}
 \textsc{qsms{:}1}
 &: 
 & x\not\sq x
 \\ 
 \textsc{qsms{:}2}
 & :
 &
 x\prec y
 & \Longleftrightarrow
 & x\sq y\not\sq x 
 \\ 
 \textsc{qsms{:}3}
 & :
 &
 x\neq y
 & \Longleftrightarrow
 & x\prec y \,~\lor~\,y\prec x \,~\lor~\,x\sq y \sq x 
 \\ 
 \textsc{qsms{:}4}
 &:
 &
 x\prec y \land z \prec t
 & \Longrightarrow
 & x\prec t \land z\prec y \,~\lor~\, x\prec z \land x\prec t ~~\lor 
 ~~z\prec x \land z\prec y  
 \,~\lor~\,t\prec y \land z\prec y \,~\lor~\, y\prec t \land x\prec t 

\end{array}
\end{equation*} 
All \textsc{qsm}-structures are denoted by $\QSMS$. 
\EOD
\end{definition}
Note that \textsc{qsms{:}4} corresponds to \textsc{qso{:}2} which
is a key axiom characterising \textsc{qs}-orders. Moreover,
 \textsc{qsm}-structures are projection-closed. 

