The next result clarifies the relationship between 
\textsc{qs}-orders and \textsc{qsm}-structures.
Basically, we will show that $\rho(\QSO)=\QSMS$ (see Section~\ref{subs-2}).

\begin{proposition}
\label{prop-siveiv}
 A structure $\qsas = \FA{\Delta,\prec,\sq}$ belongs to $\QSMS$ iff 
\begin{subequations}
\begin{align}
&\FA{\Delta,\prec}\in\QSO ~~\textit{and}
\label{eq-efi-a} 
\\
&\sq=\{\FA{x,y}\in\Delta\times \Delta\mid y\not\prec x\neq y\}\;.
\label{eq-efi-b} 
\end{align}
\end{subequations} 
\end{proposition}
\begin{proof}
In the proof, we rely on the characterisation of \textsc{qs}-orders given in 
Theorem~\ref{prop-axioms_qso}.

$(\Longrightarrow)$
We observe that Eq.\eqref{eq-efi-a} holds as \textsc{qso{:}1} follows from
\textsc{qsms{:}1,2}, and \textsc{qso{:}2} is 
\textsc{qsms{:}4}.
To prove Eq.\eqref{eq-efi-b}, suppose that $x\sq y$.
Then, $x\neq y$ by \textsc{qsms{:}1}, and $y\not\prec x$ by \textsc{qsms{:}2}.
To show the opposite inclusion, suppose that $x,y\in\Delta$ are such that
$y\not\prec x\neq y$. Then, by \textsc{qsms{:}2}, we have
$x\prec y$ or $x\sq y\sq x$. Moreover, $x\prec y$ implies $x\sq y$,
by \textsc{qsms{:}2}. 

$(\Longleftarrow)$
We observe that \textsc{qsms{:}1} follows from Eq.\eqref{eq-efi-b}.
To show \textsc{qsms{:}2}, suppose that $x\prec y$. 
Then, by $\FA{\Delta,\prec}\in\QSO$, $x\neq y$ and $y\not\prec x$.
Hence, by Eq.\eqref{eq-efi-b}, $x\sq y\not\sq x$.
To show \textsc{qsms{:}3}, suppose that $x,y\in\Delta$ and $x\neq y$.
If $x\not\prec y\not\prec x$ then, by Eq.\eqref{eq-efi-b}, $x\sq y \sq x$.
Finally, \textsc{qsms{:}4} is 
\textsc{qso{:}2}. 
\end{proof}

We are now in a position to show that 
\textsc{qsa}-structures are a suitable specification device 
for behaviours represented by \textsc{qs}-orders.

\begin{theorem}
\label{prop-grtger}
$\QSMS =\QSAS^\sat$.
\end{theorem}
\begin{proof}
$(\subseteq)$
Let $\qsms=\FA{\Delta,\prec,\sq}\in\QSMS$ and $\qso=\FA{\Delta,\prec}$. 
By Proposition~\ref{prop-siveiv}, $\qso\in\QSO$.
We first show that $\qsms\in\QSAS$, proceeding by induction on structure of
$\qso$ (see Definition~\ref{def-qso}). 
If $\qso=\FA{\es,\es}$ then, clearly, $\qsms\in\QSAS$.
In the inductive step, we consider two cases.

\emph{Case 1:} 
$\qso=\qso'[x]$, where $\qso'\in\QSO$. Then, by the induction hypothesis, 
$\qsms'=\qsms|_{\Delta\setminus\{x\}}\in\QSAS$.
We then observe that, by Proposition~\ref{prop-siveiv}, 
$\CSCS(\qsms)\setminus\CSCS(\qsms')=
\{\Phi\in\CSCS(\qsms) \mid x\in\Phi \}$.
And so, $x\in\predominants_\qsms(\Phi)$, for every 
$\Phi\in\CSCS(\qsms)\setminus\CSCS(\qsms')$. Hence $\qsms\in\QSAS$

\emph{Case 2:} 
$\qso=\qso'\circ\qso''$, where $\Delta_{\rs'}\neq\es\neq\Delta_{\rs''}$.
Then, by the induction hypothesis, we have $\qsms'=\qsms|_{\Delta_{\rs'}}\in\QSAS$
and $\qsms''=\qsms|_{\Delta_{\rs''}}\in\QSAS$.
Moreover, $(\prec\cup\sq)\cap (\Delta_{\rs''}\times\Delta_{\rs'})=\es$,
which means that 
$\CSCS(\qsms)=\CSCS(\qsms')\cup\CSCS(\qsms'')$.

Hence $\qsms\in\QSAS$. Moreover, by Proposition~\ref{prop-siveiv}, for all $x\neq y\in\Delta$,
$x\not\prec y$ implies $\{x,y\}\in \BCSCS(\qsms{\adding{x}{\prec}{y}})$ and 
$x\not\sq y$ implies $\{x,y\}\in \BCSCS(\qsms{\adding{x}{\sq}{y}})$.
Hence $\qsms\in\QSAS^\sat$.

$(\supseteq)$
Since \textsc{qsa}-structures are finite and
we have already proved that $\QSMS\subseteq\QSAS$, it suffices to show that $\Ext{\QSMS}{\qsas}\neq\es$,
for every $\qsas=\FA{\Delta,\prec,\sq}\in\QSAS$.
We proceed by induction on the size of the domain of $\qsas$.
Clearly, $\FA{\es,\es,\es}\in\Ext{\QSMS}{\FA{\es,\es,\es}}$
and $\FA{\{x\},\es,\es}\in\Ext{\QSMS}{\FA{\{x\},\es,\es}}$. In
the inductive step $|\Delta|>1$ and we consider two cases.

\emph{Case 1:} $\Delta\in\CSCS(\qsas)$. Then, by $\qsas\in\QSAS$, there is $x\in\predominants_\qsas(\Delta)$.
Let $\Delta'=\Delta\setminus\{x\}$.
As \textsc{qsa}-structures are projection-closed, by Proposition~\ref{prop-radgih}, $\qsas|_{\Delta'}\in\QSAS$.
Hence, by the induction hypothesis, there is 
$\FA{\Delta',\prec',\sq'}\in\Ext{\QSMS}{\qsas|_{\Delta'}}$.
It is straightforward to check that 
$ 
\FA{\Delta,\prec',\sq'\cup(\Delta'\times\{x\})\cup(\{x\}\times\Delta')}
$
belongs to $\Ext{\QSMS}{\qsas}$.

\emph{Case 2:} $\Delta\notin\CSCS(\qsas)$. Then $\Delta$ can be partitioned
as $\Delta'\uplus \Delta''$ in such a way that 
we have $(\Delta''\times\Delta')\cap(\prec\cup\sq)=\es$.
As \textsc{qsa}-structures are projection-closed, $\qsas|_{\Delta'}\in\QSAS$ and $\qsas|_{\Delta''}\in\QSAS$.
Hence, by the induction hypothesis, there are
$\qsms'\in \Ext{\QSMS}{\qsas|_{\Delta'}}$ and 
$\qsms''\in\Ext{\QSMS}{\qsas|_{\Delta''}}$.
It is straightforward to check that 
$
\FA{\Delta,(\prec_{\qsms'}\cup\prec_{\qsms''})\cup(\Delta'\times\Delta''),
(\sq_{\qsms'}\cup\sq_{\qsms''})\cup(\Delta'\times\Delta'')}
$
belongs to $\Ext{\QSMS}{\qsas}$. 
\end{proof}

Having at least one \textsc{qsm}-structure extension yields an alternative 
characterisation of \textsc{qsa}-structures.

\begin{proposition}
\label{prop-regrehere}
A structure is a \textsc{qsa}-structure iff one of its extensions 
is a \textsc{qsm}-structure.
\end{proposition}
\begin{proof}
Let $\rs=\FA{\Delta,\prec,\sq}$ be a structure. 

($\Longrightarrow$)
If $\rs\in\QSAS$, then $\Ext{\QSMS}{\rs}\neq\es$ 
follows from the finiteness of $\rs$ and Theorem~\ref{prop-grtger}.

($\Longleftarrow$) 
Suppose that $\rs\notin\QSAS$. As $\Ext{\QSMS}{\rs}\neq\es$ and 
\textsc{qsms{:}1,2}, $\rs$ is a relational structure. 
Hence there is $\Phi\in\CSCS(\rs)$
such that $\predominants_\rs(\Phi)=\es$.
Suppose then that $\qsms\in\Ext{\QSMS}{\rs}$. 
Then $\Phi\in\BCSCS(\qsms)$, yielding a contradiction 
with $\QSMS\subseteq\QSAS$ proved in Theorem~\ref{prop-grtger}. 
\end{proof}

The next result captures some cases where extending a \textsc{csa}-structure
may (or may not) lead outside \textsc{csa}-structures. 
This way we provide a recipe to properly saturate non-maximal \textsc{qsa}-structures. 

\begin{proposition}
\label{prop-rgih}
Let $\qsas = \FA{\Delta,\prec,\sq}\in\QSAS$ and
$x\neq y\in\Delta$. Then:

\begin{enumerate}

\item
$x\prec y$ implies $\qsas{\adding{y}{\sq}{x}}\notin\QSAS$.

\item
$x\sq y$ implies $\qsas{\adding{y}{\prec}{x}}\notin\QSAS$.

\item 
$\qsas{\adding{x}{\prec}{y}}\in\QSAS$ 
or 
$\qsas{\adding{y}{\sq}{x}}\in\QSAS$.

\item 
$\qsas{\adding{x}{\prec}{y}}\notin\QSAS$ 
implies 
$\qsas{\adding{y}{\sq}{x}}\in\QSAS$
and $\satmap_\QSAS(\qsas{\adding{y}{\sq}{x}})=\satmap_\QSAS(\qsas)$.

\item 
$\qsas{\adding{x}{\sq}{y}}\notin\QSAS$ 
implies 
$\qsas{\adding{y}{\prec}{x}}\in\QSAS$
and $\satmap_\QSAS(\qsas{\adding{y}{\prec}{x}})=\satmap_\QSAS(\qsas)$.

\end{enumerate}
\end{proposition}
\begin{proof} 
(1) follows from $\{x,y\}\in\BCSCS(\qsas{\adding{y}{\sq}{x}})$.

(2) follows from $\{x,y\}\in\BCSCS(\qsas{\adding{y}{\prec}{x}})$.

(3) 
 We will proceed by contradiction. Suppose that 
 $\rs=\qsas{\adding{x}{\prec}{y}}\notin\QSAS$ and
 $\rs'=\qsas{\adding{y}{\sq}{x}}\notin\QSAS$.
 As both $\rs$ and $\rs'$ are relational structures,
 there are $\Phi\in\BCSCS(\rs)$ and $\Psi\in\BCSCS(\rs')$.
 From $\qsas\in\QSAS$ it follows that $x,y\in \Phi\cap\Psi$. Moreover, 
 $\Phi\in\BCSCS(\rs)$ implies
 that there is a path, using $\prec$ and $\sq$, from $y$ to $x$ in $\qsas$ going through the elements of $\Phi$,
 and
 $\Psi\in\BCSCS(\rs')$ implies
 that there is a path, using $\prec$ and $\sq$, from $y$ to $x$ in $\qsas$ going through the elements of $\Psi$.
 Hence $\Phi\cup\Psi\in\CSCS(\qsas)$, and so from $\qsas\in\QSAS$ it follows 
 that there is $z\in\predominants_\qsas(\Phi\cup\Psi)$.
 It then follows that $z\neq x$, as otherwise we would have 
 $x\in\predominants_{\rs'}(\Psi)$, contradicting $\Psi\in\BCSCS(\rs')$.
 Similarly, $z\neq y$.
 Then, if $z\in\Phi$,
 we obtain a contradiction with $\Phi\in\BCSCS(\rs)$, and 
 if $z\in\Psi$,
 we obtain a contradiction with $\Psi\in\BCSCS(\rs')$. 
 Hence $\rs\in\QSAS$ or $\rs'\in\QSAS$.

 (4)
 By part (3), $\qsas{\adding{y}{\sq}{x}}\in\QSAS$. 
 Clearly, $\satmap_\QSAS(\qsas{\adding{y}{\sq}{x}})\subseteq\satmap_\QSAS(\qsas)$.
 Suppose that $\qsms\in \satmap_\QSAS(\qsas)\setminus \satmap_\QSAS(\qsas{\adding{y}{\sq}{x}})$.
 Then we must have $y\not\sq_\qsms x$, and so $x \prec_\qsms y$.
 As a result, $\qsms\in \satmap_\QSAS(\qsas{\adding{x}{\prec}{y}})$.
 Hence, by Proposition~\ref{prop-regrehere}, $\qsas{\adding{x}{\prec}{y}}\in\QSAS$, a contradiction.

 (5) Similarly as for part (4).
\end{proof}

Note that Proposition~\ref{prop-rgih}(4) or Proposition~\ref{prop-rgih}(5) 
implies  Proposition~\ref{prop-rgih}(3), but we preferred to carry out the proof
in smaller steps.  

\section{Closed QS-structures}
\label{sec-inv}

\textsc{qsa}-structures can be regarded as 
suitable specifications of \textsc{qs}-order behaviours.
In this section, we will look closer at \textsc{qsa}-structures
which are particularly suitable for, \eg property verification or 
causality analysis in concurrent behaviours.
In the general theory expounded in~\cite{DBLP:series/sci/2022-1020}, a special place is occupied 
by the following structures which enjoy 
properties of this kind.

\begin{definition}[closed \textsc{qsa}-structure]
\label{def-closed-qsas} 
A \textsc{qsa}-structure $\qsas\in\QSAS$ is \emph{closed} if     
\[\qsas=\FA{\Delta_\qsas,\prec_{\satmap_\QSAS(\qsas)},\sq_{\satmap_\QSAS(\qsas)}}\}\;\]
where
\[
\begin{array}{rcl}
\makebox[3cm][r]{\mbox{$\prec_{\satmap_\QSAS(\qsas)}$}} 
&=&\bigcap\{\prec_\qsms\mid\qsms\in\satmap_\QSAS(\qsas)\}
\\
\sq_{\satmap_\QSAS(\qsas)}&=&\bigcap\{\sq_\qsms\mid\qsms\in\satmap_\QSAS(\qsas)\}\;. 
\end{array}
\]
All closed \textsc{qsa}-structures are denoted by $\QSAS^\closed$. 
\EOD
\end{definition}

From the general results presented in~\cite{DBLP:series/sci/2022-1020} (Prop.7.5), 
and the fact that $\QSAS$ is a 
set of intersection closed relational structures, it follows that there is a \emph{structure closure}
mapping $\cls_\QSAS:\QSAS\to\QSAS^\closed$
such that the following hold.
\begin{itemize}
\item 
 A closed \textsc{qsa}-structure is the largest \textsc{qsa}-structure 
 which generates a given set of \textsc{qsm}-structures, \ie
 for all $\rs\in\QSAS^\closed$ and $\qsas\in\QSAS$:
\begin{equation}
 \rs\pref \qsas~\wedge~ \rs \neq\qsas
 \implies
 \satmap_\QSAS(\qsas)\neq\satmap_\QSAS(\rs)\;.
\end{equation}

\item
 $\cls_\QSAS$ is a closure mapping in the usual sense, \ie
 for every $\qsas\in\QSAS$:
\begin{equation} 
 \qsas\pref\cls_\QSAS(\qsas) =\cls_\QSAS(\cls_\QSAS(\qsas))\;.
\end{equation}

\item
 Structure closure preserves the
 generated \textsc{qsm}-structures, \ie
 for every $\qsas\in\QSAS$:
\begin{equation}  
 \satmap_\QSAS(\qsas)=\satmap_\QSAS(\cls_\QSAS(\qsas)) \;.
\end{equation}

\item
 Generating the same \textsc{qsm}-structures is equivalent to having the same closure, \ie
 for all $\qsas,\qsas'\in\QSAS$:  
\begin{equation}
\label{hhddh} 
\satmap_\QSAS(\qsas)=\satmap_\QSAS(\qsas') \iff \cls_\QSAS(\qsas)=\cls_\QSAS(\qsas')\;.
\end{equation}

\item
 Structure closure is monotonic, \ie for all $\qsas,\qsas'\in\QSAS$: 
\begin{equation}
\qsas\pref\qsas'\implies \cls_\QSAS(\qsas)\pref\cls_\QSAS(\qsas') \;.
\end{equation}

\item
The structure closure of a given $\qsas\in\QSAS$ is given by:
\begin{equation}
    \cls_\QSAS(\qsas) = \FA{\Delta_\qsas,\prec_{\satmap_\QSAS(\qsas)},\sq_{\satmap_\QSAS(\qsas)}}\;.
\end{equation}

\end{itemize}


The above, generic, characterisation of closed \textsc{qsa}-structures 
is not a practical one because it directly refers
to potentially (very) large set of maximal extensions of \textsc{qsa}-structures. 
To address this, we will now present an alternative algebraic characterisation 
of $\QSAS^\closed$ and $\cls_\QSAS$. 
We start by introducing an alternative definition of $\QSAS^\closed$
which will then be shown to coincide with $\QSAS^\closed$. 

\begin{definition}[\textsc{qsc}-structure]
\label{def-rrrrrs5}
A \emph{quasi-stratified closed structure} (or \textsc{qsc}-structure) 
is a structure 
$\qscs = \FA{\Delta,\prec,\sq}$ such that the following hold, for all $x\neq y\in \Delta$:
\begin{equation*}
\label{axioms-nevnr}
\begin{array}{llr@{~~~}c@{~~~}r@{~~~~~}l@{~~~}lr@{~~~}c@{~~~}l@{~~~~~}l@{~~~}l}
 \textsc{qscs{:}1}
 &:
 & 
 x\not\sq x \not\prec x 
 \\ 
 \textsc{qscs{:}2}
 &:
 &
 x\prec y
 & \Longrightarrow
 & y\not\sq x 
 \\ 
 \textsc{qscs{:}3}
 &:
 &
 \BCSCS(\qscs{\adding{x}{\prec}{y}}) \neq\es
 & \Longrightarrow
 & y\sq x 
 \\ 
 \textsc{qscs{:}4}
 &:
 &\BCSCS(\qscs{\adding{x}{\sq}{y}}) \neq\es
 & \Longrightarrow
 & y\prec x 
\end{array}
\end{equation*} 
All \textsc{qsc}-structures are denoted by $\QSCS$. \EOD
\end{definition}
In the rest of this section, we show that $\QSCS=\QSAS^\closed$.

