The next result identifies two ways in which 
\textsc{qscs}-structures can be extended to \textsc{qsas}-structures.

\begin{proposition}
\label{prop-rju}
Let $\qscs=\FA{\Delta,\prec,\sq}\in\QSCS$ and $x\neq y\in\Delta$. Then: 
\begin{enumerate}

\item $x\not\prec y$ implies $\qscs{\adding{y}{\sq}{x}}\in\QSAS$.

\item $x\not\sq y$ implies $\qscs{\adding{y}{\prec}{x}}\in\QSAS$.
\end{enumerate}
\end{proposition}

\begin{proof} 
(1) 
If $\qscs{\adding{y}{\sq}{x}}\notin\QSAS$, then 
$\BCSCS(\qscs{\adding{y}{\sq}{x}})\neq\es$. 
Hence, by \textsc{qscs{:}4}, we obtain $x\prec y$, yielding a contradiction.

(2)
If $\qscs{\adding{y}{\prec}{x}}\notin\QSAS$, then 
$\BCSCS(\qscs{\adding{y}{\prec}{x}})\neq\es$. 
Hence, by \textsc{qscs{:}3}, we obtain $x\sq y$, yielding a contradiction. 
\end{proof}

We will now define a mapping which is intended to provided an alternative
definition of the structure closure mapping for \textsc{qsa}-structures.
To start with, let 
$\mathfrak{F}:\QSAS\to\QSAS$ be a mapping such that, for every $\qsas=\FA{\Delta,\prec,\sq}\in\QSAS$: 
\[
\begin{array}{rcl}
\mathfrak{F}(\qsas)&=&\FA
{\Delta,
\prec\cup\prec',
\sq\cup \sq'
} ~~~~~~~ 
\mbox{where:}
\\[2mm]
\prec'&=&
\{\FA{y,x}\in\Delta\times\Delta\mid x\neq y
~\wedge~ y\not\prec x~\wedge ~
\BCSCS(\qscs{\adding{x}{\sq}{y}})\neq \es\}
\\
\sq'&=&
\{\FA{y,x}\in\Delta\times\Delta\mid x\neq y~\wedge~ 
y\not\sq x~\wedge~\BCSCS(\qscs{\adding{x}{\prec}{y}})\neq \es\}\;.
\end{array}
\]

\begin{proposition}
\label{prop-fheif}
 $\mathfrak{F}$ is a well-defined function such that, for every $\qsas\in\QSAS$:
 \begin{enumerate}
 \item 
$\qsas\pref\mathfrak{F}(\qsas)\pref \cls_\QSAS(\qsas)$.
 \item
 $\mathfrak{F}(\qsas)=\qsas$ iff $\qsas\in\QSCS$.
 \end{enumerate}
\end{proposition}

\begin{proof}
(1)
Suppose that $x\prec'y$. Then $x\neq y$ and 
$\BCSCS(\qsas{\adding{y}{\sq}{x}})\neq\es$.
Hence, by 
Proposition~\ref{prop-rgih}(5), 
\[
\qsas{\adding{x}{\prec}{y}}\in\QSAS 
~~\mbox{and}~~  \satmap_\QSAS(\qsas{\adding{x}{\prec}{y}})=\satmap_\QSAS(\qsas)\;.
\]
Thus, by Eq.\eqref{hhddh}, 
%$(N\times P)\cap\prec=\es$, %but what is N and P - probably 
we have
\[
\qsas{\adding{x}{\prec}{y}}\pref \cls_\QSAS(\qsas{\adding{x}{\prec}{y}})=\cls_\QSAS(\qsas)\;. 
\]
Similarly, we may show that $x\sq'y$ implies 
$\qsas{\adding{x}{\sq}{y}}\pref \cls_\QSAS(\qsas)$.
As result, we have $\qsas\pref\mathfrak{F}(\qsas)\pref \cls_\QSAS(\qsas)$.
Thus $\mathfrak{F}(\qsas)\in\QSAS$, and so $\mathfrak{F}$ is well-defined.

(2) Follows directly from Definition~\ref{def-rrrrrs5} and the definition of $\mathfrak{F}$.
\end{proof}


\begin{theorem} 
\label{th-trwrt} 
 The mapping $\qsasTOqscs:\QSAS\to\QSCS$, 
 for every $\qsas\in\QSAS$ given by: 
 \[
 \qsasTOqscs(\qsas)
 =\mathfrak{F}^{2\cdot|\Delta_\qsas|^2}(\qsas)
 \]
is the structure closure of $\QSAS$, \ie 
$\QSCS=\QSAS^\closed$ and 
$\qsasTOqscs=\cls_\QSAS$. 
\end{theorem}

\begin{proof} 
The number of relationships which the successive applications 
of $\mathfrak{F}$ can add is equal to $2\cdot|\Delta_\qsas|^2$.
Hence, $\mathfrak{F}(\qsasTOqscs(\qsas))=\qsas$,
Hence, by Proposition~\ref{prop-fheif}(2), $\qsasTOqscs(\qsas)\in\QSCS$
and is $\qsasTOqscs$ is well-defined.

The theorem is proven by applying a general result 
--- allowing one to deal with the closure operation and closed relational structures 
without referring to intersections of the
maximal extensions of structures --- 
formulated in~\cite{DBLP:series/sci/2022-1020} as Prop.7.8 
and reproduced below.

\begin{quote}  
\emph{
Let $\RR$ be an intersection-closed set of relational structures,
$\SSS\subseteq \RR$, and $f:\RR\to\SSS$
be a monotonic (\ie $\rs\pref\rs'\implies f(\rs)\pref f(\rs')$)
and 
non-decreasing (\ie $\rs\pref f(\rs)$) function.
Moreover, for all $\rs=\FA{\Delta,\prec,\sq}\in\SSS$ and $x\neq y\in\Delta$,
we have:
\begin{itemize}
\item 
$f(\rs)\pref \rs$.
\item 
If $x\not \prec y$ (or $x\not \sq y$), then there is 
$\overline{\rs}\in \satmap_\RR(\rs)$
such that $x\not \prec_{\overline{\rs}}y$ (resp.\ $x\not \sq_{\overline{\rs}} y$).
\end{itemize}
Then $f$ is the structure closure of $\RR$,
\ie $\SSS=\RR^\closed$ and $f(\rs)=\cls_\RR(\rs)$, for every $\rs\in\RR$. 
}
\end{quote}

We can apply the above result after observing the following: 
\begin{itemize} 
 \item 
 $\QSAS$ are intersection-closed by Proposition~\ref{prop-radgih}.

\item 
 $\QSCS\subseteq\QSAS$ by Proposition~\ref{prop-inclusions}.

\item
 $\qsasTOqscs$ is monotonic 
 (\ie $\qsas\pref\qsas'\implies \qsasTOqscs(\qsas)\pref \qsasTOqscs(\qsas')$)
 by Proposition~\ref{prop-jngserub}.

\item 
 $\qsasTOqscs$ is non-decreasing (\ie $\qsas\pref \qsasTOqscs(\qsas)$)
 by Proposition~\ref{prop-fheif}(1).

\item 
 For every $\qscs\in\QSCS$,
we have 
$\qsasTOqscs(\qscs)\pref\qscs$, as $\qsasTOqscs(\qscs)=\qscs$ because in such a case $\prec'=\sq'=\es$
in the definition of $\mathfrak{F}$.

\item 
 For all $\qscs=\FA{\Delta,\prec,\sq}\in\QSCS$ and $x\neq y\in\Delta$,
if $x\not \prec y$ (or $x\not \sq y$), then there is 
$\qsms\in \satmap_\QSAS(\qscs)$
such that $x\not \prec_\qsms y$ (resp.\ $x\not \sq_\qsms y$).
This follows from Theorem~\ref{prop-grtger} and Proposition~\ref{prop-rju}.
\end{itemize}
Hence, $\QSCS=\QSAS^\closed$ and 
$\qsasTOqscs=\cls_\QSAS$.
\end{proof} 

Theorem~\ref{th-trwrt} is a generalisations of Szpilrajn's Theorem~\cite{Szp30} 
stating that a partial order is the intersection of all
its total order extensions.
Note the complete algebraic characterisation of $\QSAS^\closed$ given in
Definition~\ref{def-rrrrrs5} admits redundant axioms. 
Although it is an open problem what might constitute a minimal 
and complete axiomatisation, the next result can be seen as a precursor for the development of
a minimal complete axiomatisation of closed \textsc{qsa}-structures.


\begin{proposition}
\label{prop-nevnr}
Let $\qscs = \FA{\Delta,\prec,\sq}\in\QSCS$ 
and $x,y,z,t\in \Delta$.
Then:
\begin{subequations}
\begin{align} 
\makebox[5cm][r]{\mbox{$x\prec y$}} 
~\Longrightarrow~ 
x\sq y 
\label{props-nevnr-b} 
\\
\makebox[5cm][r]{\mbox{$x\prec y \sq z \prec t$}} 
~\Longrightarrow~ 
x\prec t 
\label{props-nevnr-c}
\\
\makebox[5cm][r]{\mbox{$x\sq y\prec z ~\vee~ x\prec y\sq z$}} 
~\Longrightarrow~ 
x\sq z 
\label{props-nevnr-d}
\\
\makebox[5cm][r]{\mbox{$x\sq y\prec z\sq t\neq x$}} 
~\Longrightarrow~ x\sq t 
\label{props-nevnr-e}
\\
\makebox[5cm][r]{\mbox{$x\sq z\prec y\sq x $}} 
~\Longrightarrow~ z\sq x\sq y 
\label{props-nevnr-f}
\\
\makebox[5cm][r]{\mbox{$t\prec x\sq z\prec y\sq x$}} 
~\Longrightarrow~ 
t\prec z~\wedge~t\prec y 
\label{props-nevnr-g}
\\
\makebox[5cm][r]{\mbox{$ x\sq z\prec y\sq x\prec t$}} 
~\Longrightarrow~ 
z\prec t ~\wedge~ y\prec t 
\label{props-nevnr-h} 
\\
%\makebox[5cm][r]{\mbox{$x\neq t\sq z\prec y\sq x\sq z ~\vee~x\neq t\sq y \sq x \sq z\prec y$}} 
\makebox[5cm][r]{\mbox{$x\neq t\sq y \sq x \sq z\prec y$}} 
~\Longrightarrow~ 
t\sq x 
\label{props-nevnr-i} 
\\
%\makebox[5cm][r]{\mbox{$z\prec y\sq x\sq z\sq t\neq x ~\vee~y \sq x \sq z\prec y\sq t\neq x$}}
\makebox[5cm][r]{\mbox{$z\prec y\sq x\sq z\sq t\neq x$}}
~\Longrightarrow~ 
x\sq t 
\label{props-nevnr-j} 
\\
\makebox[5cm][r]{\mbox{$x\prec z\sq y ~\wedge~ x\sq t\prec y$}} 
~\Longrightarrow~ 
x\prec y 
\label{props-nevnr-l} 
\end{align}
\end{subequations} 
\end{proposition}

\begin{proof} 
The proofs of (\ref{props-nevnr-h}) and (\ref{props-nevnr-j}) are
similar to the proofs of (\ref{props-nevnr-g}) and (\ref{props-nevnr-i}), respectively.
\begin{itemize}[leftmargin=+.4in]
\item[(\ref{props-nevnr-b})] 
 By \textsc{qscs{:}1}, $x\neq y$. 
 Then 
 $\{x,y\}\in\BCSCS(\qscs{\adding{y}{\prec}{x}})$. 
 Hence, by \textsc{qscs{:}3}, $x\sq y$.

\item[(\ref{props-nevnr-c})] 
 By Proposition~\ref{prop-inclusions}, $x\neq t$. Then 
 $\{x,y,z,t\} \in\BCSCS(\qscs{\adding{t}{\sq}{x}})$. 
 Hence, by \textsc{qscs{:}4}, $x\prec t$.

\item[(\ref{props-nevnr-d})] 
 By \textsc{qscs{:}2}, $x\neq z$. 
 Then 
 $\{x,y,z\} \in\BCSCS(\qscs{\adding{z}{\prec}{x}})$. 
 Hence, by \textsc{qscs{:}3}, $x\sq z$.

\item[(\ref{props-nevnr-e})] 
 Then
 $\{x,y,z,t\} \in\BCSCS(\qscs{\adding{t}{\prec}{x}})$. 
 Hence, by \textsc{qscs{:}3}, $x\sq t$.

\item[(\ref{props-nevnr-f})] 
 By \textsc{qscs{:}1}, $x\neq y$.
 Then 
 $\{x,z,y\}\in \BCSCS(\qscs{\adding{y}{\prec}{x}})$. 
 Hence, by \textsc{qscs{:}3}, $x\sq y$. \\
 Similarly, we can show that $z\sq x$.

\item[(\ref{props-nevnr-g})] 
 By \textsc{qscs{:}2}, $t\neq z$. 
 Then
 $\{x,y,z,t\}\in\BCSCS(\qscs{\adding{z}{\sq}{t}})$. 
 Hence, by \textsc{qscs{:}4}, $t\prec z$.\\
 Similarly, we can show that $t\prec y$.

\item[(\ref{props-nevnr-i})] 
 Since $t\neq x$,
 $\{x,y,z,t\}\in\BCSCS(\qscs{\adding{x}{\prec}{t}})$. 
 Hence, by \textsc{qscs{:}3}, $t\sq x$.

\item[(\ref{props-nevnr-l})] 
 By \textsc{qscs{:}2}, $x\neq y$.
 Then
 $\{x,y,z,t\} \in\BCSCS(\qscs{\adding{y}{\sq}{x}})$. 
 Hence, by \textsc{qscs{:}3}, $x\prec y$. 
\end{itemize}
\end{proof}

For example, Eqs.\eqref{props-nevnr-b}--\eqref{props-nevnr-e}
are part of the axiomatisation of complete relational structures in~\cite{JKKM-PN2024}.
We hypothesise that \textsc{qscs{:}1,2} together with
Eqs.\eqref{props-nevnr-b}--\eqref{props-nevnr-l} constitute 
a minimal and complete set of axioms which use up to four events.

\begin{remark}
Consider again the \textsc{qsa}-structure from Example~\ref{ex-max}, and analyse all its \textsc{qsm}-structure extensions (saturations) together with their representations
both as set of intervals and as \textsc{qs}-sequences (see Figure~\ref{fig-allmax}).
It is easy to check that in all the saturations we have an additional relationship $a\prec d$, which is consistent with the definition of the closure and Example~\ref{ex-closed}.
Moreover, relationship between $c$ and $d$ varies 
depending on the saturation, and takes all possible values. 
The set of \textsc{qsm}-structure extensions additionally verifies the generalisation of Szpilrajn's Theorem, demonstrating that the closure of a \textsc{qsa}-structure is the intersection of all its saturations.
