    \centering
    \includegraphics[scale=0.48]{fig1.pdf}
    \caption{An illustration of the vehicle's load when serving customer $v_i$ in each of the four cases.}
    \label{fig1}
\end{figure}


After trying to satisfy all customers using the above strategy,  due to Case~3.2, there may be still a set of \emph{unsatisfied} customers $\{v_i\mid d_i>\lambda\}$. Then, for each such customer $v_i$, since its demand has been recorded, the vehicle will load exactly $d_i$ units of goods at the depot, go to satisfy $v_i$, and then return to the depot.

The details of $ALG.1(\lambda,\delta)$ is shown in Algorithm~\ref{alg1}.

\begin{algorithm}[ht]
\caption{An algorithm for unsplittable Cu-VRPSD ($ALG.1(\lambda,\delta)$)}
\label{alg1}
\small
\vspace*{2mm}
\textbf{Input:} An instance of unsplittable Cu-VRPSD, and two parameters $\lambda\in(0,1]$ and $\delta\in[0,\lambda/{2}]$.\\
%$0\leq\delta\leq\lambda-\delta\leq\lambda\leq 1$. \\
\textbf{Output:} A feasible solution $\T$ to unsplittable Cu-VRPSD.

\begin{algorithmic}[1]
\State\label{tsptour} Obtain an $\alpha$-approximate TSP tour $T^*$ using an $\alpha$-approximation algorithm for metric TSP, orient $T^*$ in either clockwise or counterclockwise direction, and denote $T^*=v_0v_1v_2\dots v_n v_0$ by renumbering the customers following the direction.

\State Load the vehicle with $S_0\coloneqq (L_0,\delta)$ units of goods, including $L_0$ units of normal goods and $\delta$ units of backup goods, where $L_0\sim U[0,\lambda-\delta)$.

\State Initialize $i\coloneqq 1$ and $V^*\coloneqq\emptyset$.

\While{$i\leq n$}

\State Go to customer $v_i$.

\If {$d_{i}\leq L_{i-1}$}
\State\label{case1ofalg1} Deliver $(d_i,0)$ units of goods to $v_i$, and update $S_i\coloneqq(L_i,\delta)$, where $L_{i}\coloneqq L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i= L_{i-1}-d_i$.

\ElsIf{$L_{i-1}<d_i\leq L_{i-1}+\delta$}
\State\label{case1ofalg1+}\label{addone} Deliver $(L_{i-1},d_i-L_{i-1})$ units of goods to $v_i$, goes to the depot, load the vehicle with $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,d_i-L_{i-1})$ units of goods, and update $S_i\coloneqq(L_i,\delta)$, where $L_{i}\coloneqq L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i= L_{i-1}+(\lambda-\delta)-d_i$.

\ElsIf{$L_i+\delta<d_i\leq 1$}
\If{$\delta<d_i\leq\lambda$}
\State\label{addtwo1} Return to the depot, load the vehicle with $(d_i-L_{i-1}-\delta,0)$ units of goods, go to customer $v_i$, and deliver $(d_i-\delta,\delta)$ units of goods to $v_i$.
\State\label{addtwo2}\label{case1ofalg1++} Return to the depot, load the vehicle with $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)$ units of goods, go to customer $v_i$, and update $S_i\coloneqq(L_i,\delta)$, where $L_{i}\coloneqq L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i$. \Comment{
The vehicle returns to $v_i$ for the sake of analysis; however, it could directly proceed to $v_{i+1}$.}

\ElsIf{$\lambda<d_i\leq 1$}
\State\label{case2ofalg1} Record $v_i$'s demand, and update $V^*\coloneqq V^*\cup \{v_i\}$ and $S_i\coloneqq(L_i,\delta)$, where $L_i\coloneqq L_{i-1}$.
\EndIf
\EndIf
\State $i \coloneqq i+1$.
\EndWhile

\State Go to the depot.

\For{$v_i\in V^*$}
\State\label{clean} Load the vehicle with $d_i$ units of goods, go to customer $v_i$, and deliver $d_i$ units of goods to $v_i$.
\State Go to the depot.
\EndFor
\end{algorithmic}
\end{algorithm}

Compared to the previous strategy in~\citep{gaur2020improved}, there are two main differences. The first is that we specially handle each customer $v_i$ with $d_i>\lambda$ in Case~3.2. Note that if we satisfy $v_i$ as the method in Case~3.1, since $L_{i-1}+\delta<\lambda$ (we will prove it in Lemma~\ref{l0}), the vehicle must incur two visits to the depot, which will cost too much. 
The second is that we ensure that the vehicle always carries $\delta$ units of backup goods when traveling along the TSP tour. The advantage is that each customer $v_i$ with $d_i\leq \delta$ incurs at most one visit to the depot while if $\delta=0$, every customer $v_i$ with $d_i\leq \lambda$ has the potential to incur two visits to the depot. However, since $\delta>0$ clearly increases the cumulative cost of the vehicle when it travels along the TSP tour, we need to carefully set the value of $\delta$. 

We also remark that the previous algorithm in~\citep{gaur2020improved} orients $T^*$ by choosing one of the two possible orientations uniformly at random, and its analysis uses this property. However, this randomness is not necessary in our analysis, which is also why $T^*$ can be oriented in either clockwise or counterclockwise direction in Line~\ref{tsptour}.

Although we require that $\lambda>0$ in $ALG.1(\lambda,\delta)$, it can be extended to the case of $\lambda=0$. In this scenario, the vehicle simply travels along the TSP tour with an empty carry to record each customer's demand, and then satisfies each customer within a single tour, as described in Case~3.2. Interestingly, if \( a = 0 \), this algorithm becomes an exact algorithm for unsplittable Cu-VRPSD, as the cumulative cost is \(b \cdot \sum_{i\in[n]}d_i \cdot l_i \), which matches the lower bound $LB$ in Lemma~\ref{mid}. 
The running time can reach $O(n)$ since all TSP tours have the same performance.
%Hence, we have the following result.
However, it may be useless for $a>0$. Hence, we mainly focus on $\lambda>0$ in the following.

\begin{lemma}\label{a=0}
Unsplittable Cu-VRPSD with $a=0$ can be solved in $O(n)$ time.
\end{lemma}

