\begin{lemma}\label{t1}
For unsplittable Cu-VRPSD with any $\lambda\in(0,1]$ and $\delta\in[0,\lambda/{2}]$, conditioned on $\chi=d$, $ALG.1(\lambda,\delta)$ generates a solution $\T$ with an expected cumulative cost of
\[
\frac{A+B}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB,
\]
where $A\coloneqq\gamma\cdot\lra{\alpha\cdot\sigma+\int^{\delta}_0\frac{x}{\lambda-\delta}dF(x)+\int^{\lambda-\delta}_{\delta}\frac{2x-\delta}{\lambda-\delta}dF(x)+\int^\lambda_{\lambda-\delta}\frac{x+\lambda-2\delta}{\lambda-\delta}dF(x)+\int_\lambda^11dF(x)}$, and $B\coloneqq\lra{\frac{\lambda+\delta}{2}\cdot\alpha\cdot\sigma+\int^{\delta}_0\frac{(\lambda+\delta)x-x^2}{2(\lambda-\delta)}dF(x)+\int^{\lambda-\delta}_{\delta}\frac{x^2+(\lambda-\delta)x}{2(\lambda-\delta)}dF(x)+\int^\lambda_{\lambda-\delta}\frac{2x^2-(\lambda+\delta)\cdot x+\lambda^2-\delta^2}{2(\lambda-\delta)}dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}$.
\end{lemma}
\begin{proof}
By Lemma~\ref{l1}, the expected cumulative cost of the vehicle for traveling the edges on the TSP tour $T^*$ is 
$
\sum_{e\in E(T^*)}\lra{a\cdot w(e)+b\cdot\frac{\lambda+\delta}{2}\cdot w(e)}=a\cdot w(T^*)+b\cdot\frac{\lambda+\delta}{2}\cdot w(T^*)\leq a\cdot\alpha\cdot\tau+b\cdot\frac{\lambda+\delta}{2}\cdot\alpha\cdot\tau,
$
where the inequality follows from $w(T^*)\leq \alpha\cdot\tau$ since $T^*$ is an $\alpha$-approximate TSP tour.

Define the set of \emph{small customers} as $V_s\coloneqq\{v_i\mid 0<d_i\leq \delta\}$, \emph{big customers} as $V_b\coloneqq\{v_i\mid \delta<d_i\leq \lambda-\delta\}$, \emph{large customers} as $V_l\coloneqq\{v_i\mid \lambda-\delta<d_i\leq \lambda\}$, and \emph{huge customers} as $V_h\coloneqq\{v_i\mid \delta<\lambda\leq 1\}$.

By Lemma~\ref{l2}, when serving customers in $V'$, the expected cumulative cost due to the possible additional visit(s) to $v_0$ is $a\cdot\lra{\sum_{v_i\in V_s}\frac{2d_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b}\frac{4d_i-2\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_l}\frac{2d_i+2\lambda-4\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_h}2\cdot l_i}+b\cdot\lra{\sum_{v_i\in V_s}\frac{(\lambda+\delta)\cdot d_i-d^2_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b}\frac{d^2_i+(\lambda-\delta)\cdot d_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_l}\frac{2d^2_i-(\lambda+\delta)\cdot d_i+\lambda^2-\delta^2}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_h}d_i\cdot l_i}$.

Therefore, $ALG.1(\lambda,\delta)$ generates a solution $\T$ with an expected cumulative cost of
\begin{align*}
&\frac{a\cdot\lrA{\alpha\cdot\tau+\sum_{v_i\in V_s}\frac{2d_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b}\frac{4d_i-2\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_l}\frac{2d_i+2\lambda-4\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_h}2\cdot l_i}}{LB}\cdot LB\\
&\quad+\frac{b\cdot\lrA{\frac{\lambda+\delta}{2}\cdot\alpha\cdot\tau+\sum_{v_i\in V_s}\frac{(\lambda+\delta)\cdot d_i-d^2_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b}\frac{d^2_i+(\lambda-\delta)\cdot d_i}{\lambda-\delta}\cdot l_i}}{LB}\cdot LB\\
&\quad+\frac{b\cdot\lrA{\sum_{v_i\in V_l}\frac{2d^2_i-(\lambda+\delta)\cdot d_i+\lambda^2-\delta^2}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_h}d_i\cdot l_i}}{LB}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\delta}_0\frac{x}{\lambda-\delta}dF(x)+\int^{\lambda-\delta}_{\delta}\frac{2x-\delta}{\lambda-\delta}dF(x)+\int^\lambda_{\lambda-\delta}\frac{x+\lambda-2\delta}{\lambda-\delta}dF(x)+\int_\lambda^11dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&\quad+\frac{\lrA{\frac{\lambda+\delta}{2}\cdot\alpha\cdot\sigma+\int^{\delta}_0\frac{(\lambda+\delta)x-x^2}{2(\lambda-\delta)}dF(x)+\int^{\lambda-\delta}_{\delta}\frac{x^2+(\lambda-\delta)x}{2(\lambda-\delta)}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&\quad+\frac{\lrA{\int^\lambda_{\lambda-\delta}\frac{2x^2-(\lambda+\delta)\cdot x+\lambda^2-\delta^2}{2(\lambda-\delta)}dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB,
\end{align*}
where the equality follows from dividing both the numerator and denominator by $b\cdot\eta$, using $\gamma=a/b$, $\sigma=\tau/\eta$, and $LB=a\cdot\max\{\tau, \eta\}+b\cdot\frac{1}{2}\cdot\eta$ by Lemma~\ref{lb}, and equitation (\ref{int}).
\end{proof}

\subsubsection{The application}
Next, we use $ALG.1(\lambda,\delta)$ to deign approximation algorithms for $a,b>0$, i.e., $\gamma>0$. 

\textbf{An $(\alpha+2)$-approximation algorithm.}
When the vehicle traveling along each edge of the TSP tour in $ALG.1(\lambda,\delta)$, it always carries at least $\delta$ units of goods in total, resulting in a large cumulative cost for the case where $\gamma$ is small. 
Hence, intuitively, if $\gamma$ is small, we simply set $\delta=0$. We may first analyze $ALG.1(\lambda,\delta)$ under the simplified setting where $\delta=0$.
Surprisingly, even setting $\delta=0$, we find that $ALG.1(\lambda, \delta)$ can be used to obtain an $(\alpha+2)$-approximation algorithm for unsplittable Cu-VRPSD. The algorithm is shown in Algorithm~\ref{APP0}.

\begin{algorithm}[ht]
\caption{An $(\alpha+2)$-approximation algorithm for unsplittable Cu-VRPSD}
\label{APP0}
\small
\vspace*{2mm}
\textbf{Input:} An instance of unsplittable Cu-VRPSD. \\
\textbf{Output:} A feasible solution to unsplittable Cu-VRPSD.

\begin{algorithmic}[1]
\State Obtain a solution $\T$ by calling $ALG.1(\lambda, 0)$, where $\lambda=\min\{1,4\gamma/\alpha\}$.
\State Return $\T$.
\end{algorithmic}
\end{algorithm}

%We first introduce our first algorithm, denoted as $ALG.1(\lambda, \delta)$, which can be used to obtain an $(\alpha+2)$-approximation algorithm for unsplittable Cu-VRPSD. 

\begin{theorem}\label{unttt0}
For unsplittable Cu-VRPSD, there is a randomized $(\alpha+2)$-approximation algorithm.
\end{theorem}
\begin{proof}
Algorithm~\ref{APP0} calls $ALG.1(\lambda, 0)$. By Lemma~\ref{t1}, the approximation ratio of $ALG.1(\lambda, 0)$ is at most
\begin{equation}\label{eqs}
\begin{split}
&\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)+\int^1_{\lambda}1dF(x)}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2+\lambda\cdot x}{2\cdot \lambda}dF(x)+\int^1_{\lambda}\frac{x}{2}dF(x)\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)+\int^1_{\lambda}\frac{2x}{\lambda}dF(x)}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{\lambda\cdot x+\lambda\cdot x}{2\cdot \lambda}dF(x)+\int^1_{\lambda}xdF(x)\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{split}
\end{equation}
where the inequality follows from $\int^1_{\lambda}1dF(x)\leq \int^1_{\lambda}\frac{2x}{\lambda}dF(x)$, $\int^{\lambda}_{0}\frac{x^2+\lambda\cdot x}{2\cdot \lambda}dF(x)\leq\int^{\lambda}_{0}\frac{\lambda\cdot x+\lambda\cdot x}{2\cdot \lambda}dF(x)$, and $\int^1_{\lambda}\frac{x}{2}dF(x)\leq \int^1_{\lambda}xdF(x)$ by (\ref{intineq}).

Since $\lambda=\min\{1,4\gamma/\alpha\}$, we consider the following two cases.

\textbf{Case~1: $4\gamma/\alpha\geq 1$.} We have $\lambda=1$ and we further consider the following two cases. 
%By (\ref{eqs}), the approximation ratio of $ALG.1(\lambda, 0)$ is at most 
% \begin{align*}
% \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+2}+\left(\frac{1}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}.
% \end{align*}

\textbf{Case~1.1: $\sigma\leq 1$.} By (\ref{eqs}), the approximation ratio of $ALG.1(\lambda, 0)$ is at most 
\begin{align*}
\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+2}+\left(\frac{1}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5} &\leq\frac{\gamma\cdot\lrA{\alpha+2}+\left(\frac{1}{2}\cdot\alpha+1\right)}{\gamma+0.5}=\alpha+2,
\end{align*}
where the first inequality follows from $\sigma\leq 1$ and $\max\{\sigma,1\}=1$.

\textbf{Case~1.2: $\sigma\geq 1$.} By (\ref{eqs}), the approximation ratio of $ALG.1(\lambda, 0)$ is at most 
\begin{align*}
\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+2}+\left(\frac{1}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5} &=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+2}+\left(\frac{1}{2}\cdot\alpha\cdot\sigma\cdot\frac{1}{\sigma}+\frac{1}{2}\cdot\alpha\cdot\sigma\cdot\lrA{1-\frac{1}{\sigma}}+1\right)}{\gamma\cdot\sigma+0.5}\\
&\leq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+2}+\left(
\frac{1}{2}\cdot\alpha+\frac{2}{\alpha}\cdot\gamma\cdot\alpha\cdot\sigma\cdot\lrA{1-\frac{1}{\sigma}}+1\right)}{\gamma\cdot\sigma+0.5}\\
&=\frac{\gamma\cdot\sigma\cdot\lrA{\alpha+2}+\left(\frac{1}{2}\cdot\alpha+1\right)}{\gamma\cdot\sigma+0.5}=\alpha+2,
\end{align*}
where the first equality follows from $\sigma\geq 1$ and the first inequality from $\frac{1}{2}\leq \frac{2}{\alpha}\cdot\gamma$ by the definition of Case~1.

\textbf{Case~2: $4\gamma/\alpha\leq 1$.} We have $\lambda=4\gamma/\alpha$. Similarly, by (\ref{eqs}), the approximation ratio of $ALG.1(\lambda, 0)$ is at most 
\begin{align*}
\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\left(\frac{\lambda}{2}\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{\alpha}{2}\cdot\frac{1}{\gamma}}+\left(\frac{2}{\alpha}\cdot\gamma\cdot\alpha\cdot\sigma+1\right)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\frac{\gamma\cdot\sigma\cdot(\alpha+2)+\frac{1}{2}(\alpha+2)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\leq\alpha+2,
\end{align*}
where the inequality follows from $\sigma\leq \max\{\sigma,\ 1\}$.

Therefore, Algorithm~\ref{APP0} is a randomized $(\alpha+2)$-approximation algorithm. Moreover, its running time is dominated by computing an $\alpha$-approximate TSP tour.
\end{proof}

\textbf{Further Improvements.}
Next, we aim to design better approximation algorithms. 

%We observe that
As shown in the proof of Theorem~\ref{unttt0}, if we call $ALG.1(\lambda,\delta)$ with $\delta=0$ and $\lambda$ being a unique value, in the worst case we may have $\int^\lambda_0x^2dF(x)=\int^\lambda_0\lambda\cdot xdF(x)$, i.e., almost all customers $v_i$ with $l_i>0$ and $d_i\leq\lambda$ have a demand of $d_i=\lambda$. Consequently, we may obtain $\int^{\theta\cdot\lambda}_0xdF(x)=0$ for any fixed $\theta\in(0,1)$, as will be shown in Lemma~\ref{a1}, and then $ALG.1(\theta\cdot \lambda,\delta)$ with $\delta=0$ and some $\theta\in(0,1)$ may generate a better solution. This suggests an improved approximation algorithm for unsplittable Cu-VRPSD shown in Algorithm~\ref{APP1}, denoted as $APPROX.1(\lambda,\theta,p)$. 

\begin{remark}
In $APPROX.1(\lambda,\theta,p)$, wejust use a two-point distributed algorithm deployment because it is easier to analyze, though it may perform worse than a multi-point distributed algorithm deployment. Further discussion on this choice will be provided at the end of this section.
\end{remark}

\begin{algorithm}[ht]
\caption{An approximation algorithm for unsplittable Cu-VRPSD ($APPROX.1(\lambda,\theta,p)$)}
\label{APP1}
\small
\vspace*{2mm}
\textbf{Input:} An instance of unsplittable Cu-VRPSD, and three parameters $\lambda\in(0,1]$, $\theta\in(0,1)$ and $p\in(0,1)$.\\
\textbf{Output:} A feasible solution to unsplittable Cu-VRPSD.
\begin{algorithmic}[1]
\State Call $ALG.1(\lambda,0)$ with a probability of $p$ and call $ALG.1(\theta\cdot\lambda,0)$ with a probability of $1-p$.
\end{algorithmic}
\end{algorithm}

Then, our goal is to find $(\lambda,\theta,p)$ minimizing the approximation ratio of $APPROX.1(\lambda,\theta,p)$.
%

\begin{lemma}\label{a1}
For any $\theta\in(0,1)$, we have $\int^{\theta\cdot\lambda}_0 xdF(x)\leq \frac{1}{\lambda-\theta\cdot\lambda}\lra{\int^\lambda_0\lambda\cdot xdF(x)-\int^\lambda_0x^2dF(x)}$.   
\end{lemma}
\begin{proof}
By (\ref{int}) and (\ref{intineq}), we have 
\begin{align*}
\int^\lambda_0x^2dF(x)&=\int^{\theta\cdot\lambda}_0x^2dF(x)+\int^\lambda_{\theta\cdot\lambda} x^2dF(x)\\
&\leq \theta\cdot\lambda\cdot \int^{\theta\cdot\lambda}_0 xdF(x)+\lambda\cdot\int^\lambda_{\theta\cdot\lambda} xdF(x)=\lambda\cdot\int^{\lambda}_0 xdF(x)-(\lambda-\theta\cdot\lambda)\cdot \int^{\theta\cdot\lambda}_0 xdF(x)   
\end{align*}
Hence, we have $\int^{\theta\cdot\lambda}_0 xdF(x)\leq \frac{1}{\lambda-\theta\cdot\lambda}\lra{\int^\lambda_0\lambda\cdot xdF(x)-\int^\lambda_0x^2dF(x)}$.
\end{proof}

\begin{theorem}\label{t2}
For unsplittable Cu-VRPSD, under $\alpha=1.5$, we can find $(\lambda,\theta,p)$ such that the approximation ratio of $APPROX.1(\lambda,\theta,p)$ is bounded by $10/3$ for any $\gamma\in(0,0.375]$ and $3.456$ for any $\gamma\in(0.375,1.444]$.
\end{theorem}
\begin{proof}
If we call $ALG.1(\lambda,\delta)$ with $\delta=0$ and $\lambda$ being a unique value, as shown in the proof of Theorem~\ref{unttt0}, a good choice for $\lambda$ is $\min\{1, 4\gamma/\alpha\}$. 
For the sake of analysis, we directly set $\lambda=\min\{1, 4\gamma/\alpha\}$.

If $\int^\lambda_0xdF(x)=0$, we can obtain $\int^\lambda_0x^2dF(x)\leq \lambda\cdot \int^\lambda_0xdF(x)=0$.
Hence, we define $\mu\coloneqq0$ if $\int^\lambda_0xdF(x)=0$, and $\mu\coloneqq\frac{\int^\lambda_0x^2dF(x)}{\int^\lambda_0xdF(x)}$ otherwise.

By Lemmas~\ref{mid} and \ref{t1}, the approximation ratio of $ALG.1(\lambda,0)$ is at most
\begin{align*}
&\max_{\sigma\geq0}\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)+\int_\lambda^1 1dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2+\lambda\cdot x}{2\lambda}dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\max_{\sigma\geq0}\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\int_{\lambda}^{1}1dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1+\mu/\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{\lambda}\cdot\int_{\lambda}^{1}xdF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1+\mu/\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{\lambda}}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{\mu/\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{\mu/\lambda+1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{align*}
where the first equality follows from the definition of $\mu$, the second equality from $\int^1_0xdF(x)=1$ by (\ref{int}), the first inequality from $\int_{\lambda}^{1}1dF(x)\leq \frac{1}{\lambda}\cdot\int_{\lambda}^{1}xdF(x)$ by (\ref{intineq}), and the second inequality from $\int_{0}^{\lambda}xdF(x)\leq \int_{0}^{1}xdF(x)=1$.

Since $\int_{0}^{\lambda}xdF(x)\leq \int_{0}^{1}xdF(x)=1$, by Lemma~\ref{a1}, we have 
\begin{equation}\label{eq1}
\begin{split}
\int^{\theta\cdot\lambda}_0 xdF(x)&\leq \frac{1}{\lambda-\theta\cdot\lambda}\cdot\lrA{\int^\lambda_0\lambda\cdot xdF(x)-\int^\lambda_0x^2dF(x)}=\frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}\cdot\int^\lambda_0xdF(x)\leq \frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}  
\end{split}
\end{equation}

Similarly, the approximation ratio of $ALG.1(\theta\cdot\lambda,0)$ is at most
\begin{align*}
&\max_{\sigma\geq0}\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int_{0}^{\theta\cdot\lambda}\frac{2x}{\theta\cdot\lambda}dF(x)+\int_{\theta\cdot\lambda}^{1}1dF(x)}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\int_{0}^{\theta\cdot\lambda}\frac{x^2+\theta\cdot\lambda\cdot x}{2\cdot\theta\cdot\lambda}dF(x)+\int_{\theta\cdot\lambda}^{1}\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\theta\cdot\lambda}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{\theta\cdot\lambda}\cdot\int_{\theta\cdot\lambda}^{1}xdF(x)}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\theta\cdot\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{2}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\cdot\frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}+\frac{1}{\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{2}\cdot\frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\max_{\sigma\geq0} \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\mu-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{2}\cdot\frac{2\lambda-\mu-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{align*}
where the first inequality follows from 
%$\int_{\theta\cdot\lambda}^{1}1dF(x)\leq \frac{1}{\theta\cdot\lambda}\cdot\int^1_{\theta\cdot\lambda}xdF(x)$ and $\int_{0}^{\theta\cdot\lambda}x^2dF(x)\leq \int_{0}^{\theta\cdot\lambda}\theta\cdot\lambda\cdot xdF(x)$ by 
(\ref{intineq}), the second inequality from (\ref{eq1}), and the first equality from $\int^1_0xdF(x)=1$ by (\ref{int}).

Recall that in $APPROX.1(\lambda,\theta,p)$, we call $ALG.1(\lambda,0)$ (resp., $ALG.1(\theta\cdot\lambda,0)$) with a probability of $p$ (resp., $1-p$). Hence, to erase the items related to $\mu$ in the numerators of the approximation ratios of $ALG.1(\lambda,0)$ and $ALG.1(\theta\cdot\lambda,0)$, we need to set $p$ such that 
\[
p\cdot\frac{1}{2}\cdot\frac{1}{\lambda}+(1-p)\cdot\lrA{\gamma\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{-1}{\lambda-\theta\cdot\lambda}+\frac{1}{2}\cdot\frac{-1}{\lambda-\theta\cdot\lambda}}=0.
\]
Then, we can obtain $p=\frac{\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}{\frac{1}{2\lambda}+\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}$. Clearly, we have $p\in[0,1]$. Hence, the approximation ratio is $\max_{\sigma\geq 0} R(\sigma)$,
where
\begin{equation}\label{ratio1}
\begin{split}
&R(\sigma)\coloneqq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+p\cdot\frac{2}{\lambda}+(1-p)\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{\frac{p\cdot\lambda+(1-p)\cdot\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{2}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}.
\end{split}
\end{equation}

It can be verified that $\max_{\sigma\geq 0} R(\sigma)=\max_{\sigma\geq 1} R(\sigma)$. Moreover, since the function $\frac{a'x+b'}{c'x+d'}$ with $x\geq 1$ and $a',b',c',d'>0$ attains the maximum value only if $x=1$ or $x=\infty$, we know that the approximation ratio is bounded by 
$
\max\{R(1),\ R(\infty)\}.
$
Recall that $\lambda=\min\{1, 4\gamma/\alpha\}$ and $p=\frac{\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}{\frac{1}{2\lambda}+\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}$. Assume $\alpha=1.5$, then we have $\alpha/4=0.375$. By calculation, we have the following results.
\begin{itemize}
    \item When $\gamma\in(0,0.375]$, setting $\theta=0.5$, we have $\max\{R(1),\ R(\infty)\}\equiv 10/3$;
    \item When $\gamma\in[0.375,1.444]$, setting $\theta=0.6677$, we have $\max\{R(1),\ R(\infty)\}\leq 3.456$.
\end{itemize}

The values of $\max\{R(1),\ R(\infty)\}$ under $\lambda=\min\{1,4/\gamma/\alpha\}$, $p=\frac{\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}{\frac{1}{2\lambda}+\frac{1}{2(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}$, and different values of $\theta$ can be found in Figure~\ref{fig2}.\footnote{We computed the values and generated this figure (along with others in the paper) using Python. The source code is available at \url{https://github.com/JingyangZhao/Cu-VRPSD}.} %Note that for any $\gamma$, 

