\begin{lemma}[*]\label{t5}
For unsplittable Cu-VRP with any $\lambda\in(0,1]$, $\delta\in(0,\lambda/2]$, and $1/\delta\in\mathbb{N}$, $ALG.3(\lambda,\delta)$ generates a solution $\T$ with an expected cumulative cost of
\[
\ln2\cdot Cu(\T^*)+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\]
\end{lemma}


\begin{theorem}\label{t6}
For unsplittable Cu-VRP with any constant $\gamma_0>0$ and  some small $\varepsilon>0$, there is a randomized $(\alpha+1+\ln2+\varepsilon<3.194)$-approximation algorithm for $\gamma>\gamma_0$.
\end{theorem}
\begin{proof}
Let $\lambda=\min\{1,2\gamma/\alpha\}$. 
%We have $\gamma/\lambda\leq $
By Lemma~\ref{t5}, for any $\lambda\in(0,1]$ and constant $\varepsilon>0$, setting $0<\delta\leq\frac{\lambda\cdot\varepsilon'}{1+\varepsilon'}$ satisfying $(1+\alpha)\cdot \varepsilon'\leq \varepsilon$, $\delta\in(0,\lambda/2]$ and $1/\delta\in\mathbb{N}$, $ALG.3(\lambda,\delta)$ generates a solution $\T$ with an expected approximation ratio of
\begin{equation}\label{eqt}
\begin{split}
\ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}&\leq \ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}+\gamma\cdot\frac{\varepsilon'}{\lambda}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}+\frac{\lambda}{2}\cdot\frac{\varepsilon'}{\lambda}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}+\varepsilon,
\end{split}
\end{equation}
where the first inequality follows from $\frac{1}{\lambda-\delta}\leq \frac{1}{\lambda}+\frac{\varepsilon'}{\lambda}$ since $\delta\leq\frac{\lambda\cdot\varepsilon'}{1+\varepsilon'}$, and the second from $\lra{\frac{\gamma}{\lambda}+0.5}\cdot\varepsilon'\leq \lra{\gamma\cdot \max\{\sigma,1\}+0.5}\cdot\lra{1+\alpha}\cdot\varepsilon'\leq \varepsilon$ since $\lambda=\min\{1,2\gamma/\alpha\}$ and $(1+\alpha)\cdot \varepsilon'\leq \varepsilon$.

Next, by using an analysis similar to the one in the proof of Theorem~\ref{unttt0},  we show that the approximation ratio is bounded by $\alpha+1+\ln2+\varepsilon$.

\textbf{Case~1: $\gamma\geq\alpha/2$.} We have $\lambda=1$ and we further consider the following two cases.

\textbf{Case~1.1: $\sigma\leq1$.} By (\ref{eqt}), the approximation ratio is at most 
\begin{align*}
&\ln2+\frac{\gamma\cdot\lrA{\alpha+1}+\frac{1}{2}\cdot\lrA{\alpha+1}}{\gamma+0.5}+\varepsilon=\alpha+1+\ln2+\varepsilon.
\end{align*}

\textbf{Case~1.2: $\sigma\geq1$.} By (\ref{eqt}), the approximation ratio is at most 
\begin{align*}
\ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+1}+\frac{1}{2}\cdot\lrA{\alpha\cdot\sigma+1}}{\gamma\cdot\sigma+0.5}+\varepsilon&= \ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+1}+\frac{1}{2}\cdot\lrA{\alpha\cdot\sigma\cdot\lrA{\frac{1}{\sigma}+1-\frac{1}{\sigma}}+1}}{\gamma\cdot\sigma+0.5}+\varepsilon\\
&\leq\ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+1}+\frac{1}{2}\cdot\alpha+\gamma\cdot\sigma\cdot\lrA{1-\frac{1}{\sigma}}+0.5}{\gamma\cdot\sigma+\frac{1}{2}}+\varepsilon\\
&=\alpha+1+\ln2+\varepsilon,
\end{align*}
where the inequality follows from $\alpha/2\leq \gamma$ by the definition of Case~1.

\textbf{Case~2: $\gamma\geq\alpha/2$.} We have $\lambda=2\gamma/\alpha$. By (\ref{eqt}), the approximation ratio is at most 
\begin{align*}
\ln2+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{2\gamma/\alpha}}+\frac{2\gamma/\alpha}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{2\gamma/\alpha}}}{\gamma\cdot\max\{\sigma,\ 1\}+0.5}+\varepsilon&=\ln2+\frac{\gamma\cdot\alpha\cdot\sigma+\alpha/2+\gamma\cdot\sigma+1/2}{\gamma\cdot\max\{\sigma,\ 1\}+0.5}+\varepsilon\\
&=\ln2+(\alpha+1)\cdot\frac{\gamma\cdot\sigma+1/2}{\gamma\cdot\max\{\sigma,\ 1\}+0.5}+\varepsilon\\
&\leq\alpha+1+\ln2+\varepsilon.
\end{align*}

Let $\varepsilon$ be a sufficiently small constant and $\alpha=\frac{3}{2}$. We can set $\delta=\frac{1}{\ceil{\frac{1+\varepsilon'}{\lambda\cdot\varepsilon'}}}$, where $\varepsilon'=\frac{\varepsilon}{1+\alpha}$. Since $\lambda\leq 1$, the running time is $n^{O(1/\delta)}=n^{O(1/(\min\{\gamma,1\}\cdot \varepsilon))}$, dominated by solving the linear program of weighted set cover, and the approximation ratio is at most $2.5+\ln2+\varepsilon<3.194$. 
\end{proof}

