    \item $a\cdot\frac{2d_i+2\lambda-4\delta}{\lambda-\delta}\cdot l_i+b\cdot \frac{2d^2_i-(\lambda+\delta)\cdot d_i+\lambda^2-\delta^2}{\lambda-\delta}\cdot l_i$ if $\lambda-\delta<d_i\leq\lambda$;
    \item $a\cdot2\cdot l_i+b\cdot d_i\cdot l_i$ if $\lambda<d_i\leq 1$.
\end{itemize}
\end{lemma}
\endgroup
\begin{proof}
If $d_i>\lambda$, By Lines~\ref{case2ofalg1} and \ref{clean}, the vehicle incurs one additional visit to $v_0$, where the vehicle carries $d_i$ units of goods from $v_0$ to $v_i$ and $0$ units of goods from $v_i$ to $v_0$. So, the expected cumulative cost is $a\cdot2\cdot l_i+b\cdot d_i\cdot l_i$.
%If $d_i>\lambda$, By Lines~\ref{case2ofalg1} and \ref{clean}, the vehicle incurs an additional visit to $v_0$ if $d_i>\lambda$. 
Next, we consider $d_i\leq\lambda$. 

By Lemma \ref{l0}, the vehicle carries $(L_{i-1},\delta)$ units of goods when traveling along $v_{i-1}v_i$ in $ALG.1(\lambda,\delta)$, and it holds that $L_{i-1}\sim U[0,\lambda-\delta)$.
%Hence, the vehicle incurs one additional visits to $v_0$ with a probability of $\PP{d_i-\delta\leq L_{i-1}=x<d_i}=\int_{\max\{0,d_i-\delta\}}^{\min\{d_i, \lambda-\delta\}}\frac{1}{\lambda-\delta}dx=\int_{0}^{d_i}\frac{1}{\lambda-\delta}dx=\frac{d_i}{\lambda-\delta}$, and incurs two additional visits to $v_0$ with a probability of $\PP{L_{i-1}=x<d_i-\delta}=\int_{0}^{\min\{d_i,\lambda-\delta\}}\frac{1}{\lambda-\delta}dx=\int_{0}^{d_i}\frac{1}{\lambda-\delta}dx=\frac{d_i}{\lambda-\delta}$.
Hence, the vehicle incurs one additional visits to $v_0$ with a probability of $\PP{d_i-\delta\leq L_{i-1}=x<d_i}$, and incurs two additional visits to $v_0$ with a probability of $\PP{0\leq L_{i-1}=x<d_i-\delta}$ (recall Figure~\ref{fig1}). We consider the following three cases.

\textbf{Case~1: $d_i\leq\delta$.} The vehicle incurs at most one additional visit to $v_0$.
If the vehicle incurs one additional visit to $v_0$, By Line~\ref{addone}, the vehicle carries $(0,\delta-(d_i-L_{i-1}))$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)=(L_{i-1}+(\lambda-\delta)-d_i,\delta)$ units of goods from $v_0$ to $v_i$. 
So, the cumulative cost is $a\cdot 2\cdot l_i + b\cdot (\delta-(d_i-L_{i-1})+L_{i-1}+(\lambda-\delta)-d_i+\delta)\cdot l_i=a\cdot 2\cdot l_i + b\cdot (2L_{i-1}-2d_i+\lambda+\delta)\cdot l_i$. Since $L_{i-1}\sim U[0,\lambda-\delta)$ and $d_i\leq\delta\leq\lambda-\delta$, the expected cumulative cost is
\begin{align*}
&\int_{0}^{\min\{d_i, \lambda-\delta\}}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx\\
&=\int_{0}^{d_i}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx=a\cdot\frac{2d_i}{\lambda-\delta}\cdot l_i+b\cdot \frac{(\lambda+\delta)\cdot d_i-d^2_i}{\lambda-\delta}\cdot l_i.    
\end{align*}

\textbf{Case~2: $\delta<d_i\leq\lambda-\delta$.} The vehicle incurs at most two additional visits to $v_0$. Similarly, if the vehicle incurs one additional visit to $v_0$, By Line~\ref{addone}, the vehicle carries $(0,\delta-(d_i-L_{i-1}))$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)=(L_{i-1}+(\lambda-\delta)-d_i,\delta)$ units of goods from $v_0$ to $v_i$, and the cumulative cost is $a\cdot 2\cdot l_i + b\cdot (\delta-(d_i-L_{i-1})+L_{i-1}+(\lambda-\delta)-d_i+\delta)\cdot l_i=a\cdot 2\cdot l_i + b\cdot (2L_{i-1}-2d_i+\lambda+\delta)\cdot l_i$. If the vehicle incurs two additional visits to $v_0$, By Lines~\ref{addtwo1} and~\ref{addtwo2}, the vehicle carries $(L_{i-1},\delta)$ units of goods from $v_i$ to $v_0$, $(d_i-\delta,\delta)$ units of goods from $v_0$ to $v_i$, $(0,0)$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)=(L_{i-1}+(\lambda-\delta)-d_i,\delta)$ units of goods from $v_0$ to $v_i$, and the cumulative cost is $a\cdot 4\cdot l_i + b\cdot (L_{i-1}+\delta+d_i+0+L_{i-1}+(\lambda-\delta)-d_i+\delta)\cdot l_i=a\cdot 4\cdot l_i + b\cdot (2L_{i-1}+\lambda+\delta)\cdot l_i$. Hence, the expected cumulative cost is
\begin{align*}
&\int_{d_i-\delta}^{\min\{d_i, \lambda-\delta\}}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx+\int_{0}^{d_i-\delta}\frac{a\cdot 4\cdot l_i + b\cdot (2x+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx\\
&=\int_{d_i-\delta}^{d_i}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx+\int_{0}^{d_i-\delta}\frac{a\cdot 4\cdot l_i + b\cdot (2x+\lambda+\delta)\cdot l_i}{\lambda-\delta}dx\\
&=\frac{a\cdot2\cdot\delta\cdot l_i+b\cdot\lambda\cdot\delta\cdot l_i}{\lambda-\delta}+\frac{a\cdot4\cdot(d_i-\delta)\cdot l_i+b\cdot(d^2_i+(\lambda-\delta)\cdot d_i-\delta\cdot\lambda)\cdot l_i}{\lambda-\delta}\\
&=a\cdot\frac{4d_i-2\delta}{\lambda-\delta}\cdot l_i+b\cdot \frac{d^2_i+(\lambda-\delta)\cdot d_i}{\lambda-\delta}\cdot l_i.    
\end{align*}

\textbf{Case~3: $\lambda-\delta<d_i\leq\lambda$.} The vehicle incurs at most two additional visits to $v_0$. If the vehicle incurs one additional visit to $v_0$, By Line~\ref{addone}, the vehicle carries $(0,\delta-(d_i-L_{i-1}))$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)$ units of goods from $v_0$ to $v_i$, and the cumulative cost is $a\cdot 2\cdot l_i + b\cdot (\delta-(d_i-L_{i-1})+L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot(\lambda-\delta)-d_i+\delta)\cdot l_i=a\cdot 2\cdot l_i + b\cdot (2L_{i-1}-2d_i+2\delta+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot(\lambda-\delta))\cdot l_i$. If the vehicle incurs two additional visits to $v_0$, By Lines~\ref{addtwo1} and~\ref{addtwo2}, the vehicle carries $(L_{i-1},\delta)$ units of goods from $v_i$ to $v_0$, $(d_i-\delta,\delta)$ units of goods from $v_0$ to $v_i$, $(0,0)$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot (\lambda-\delta)-d_i,\delta)$ units of goods from $v_0$ to $v_i$, and the cumulative cost is $a\cdot 4\cdot l_i + b\cdot (L_{i-1}+\delta+d_i+0+L_{i-1}+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot(\lambda-\delta)-d_i+\delta)\cdot l_i=a\cdot 4\cdot l_i + b\cdot (2L_{i-1}+2\delta+\ceil{\frac{d_i-L_{i-1}}{\lambda-\delta}}\cdot(\lambda-\delta))\cdot l_i$. Hence, the expected cumulative cost is
\begin{align*}
&\int_{d_i-\delta}^{\min\{d_i, \lambda-\delta\}}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+2\delta+\ceil{\frac{d_i-x}{\lambda-\delta}}\cdot(\lambda-\delta))\cdot l_i}{\lambda-\delta}dx\\
&\quad+\int_{0}^{d_i-\delta}\frac{a\cdot 4\cdot l_i + b\cdot (2x+2\delta+\ceil{\frac{d_i-x}{\lambda-\delta}}\cdot(\lambda-\delta))\cdot l_i}{\lambda-\delta}dx\\
&=\int_{d_i-\delta}^{\lambda-\delta}\frac{a\cdot 2\cdot l_i + b\cdot (2x-2d_i+2\delta+1\cdot(\lambda-\delta))\cdot l_i}{\lambda-\delta}dx\\
&\quad+\int_{0}^{d_i+\delta-\lambda}\frac{a\cdot 4\cdot l_i + b\cdot (2x+2\delta+2\cdot(\lambda-\delta))\cdot l_i}{\lambda-\delta}dx\\
&\quad+\int_{d_i+\delta-\lambda}^{d_i-\delta}\frac{a\cdot 4\cdot l_i + b\cdot (2x+2\delta+1\cdot(\lambda-\delta))\cdot l_i}{\lambda-\delta}dx\\
&=\frac{a\cdot2\cdot (\lambda-d_i)\cdot l_i+b\cdot(d^2_i+(\delta-3\lambda)\cdot d_i+(2\lambda^2-\lambda\cdot\delta))}{\lambda-\delta}\\
&\quad+\frac{a\cdot 4\cdot (d_i+\delta-\lambda)\cdot l_i+b\cdot(d^2_i+2\delta\cdot d_i+\delta^2-\lambda^2)}{\lambda-\delta}\\
&\quad+\frac{a\cdot4\cdot(\lambda-2\delta)\cdot l_i+b\cdot((2\lambda-4\delta)\cdot d_i+\delta\cdot\lambda-2\delta^2)}{\lambda-\delta}\\
&=a\cdot\frac{2d_i+2\lambda-4\delta}{\lambda-\delta}\cdot l_i+b\cdot \frac{2d^2_i-(\lambda+\delta)\cdot d_i+\lambda^2-\delta^2}{\lambda-\delta}\cdot l_i,  
\end{align*}
where the first equality follows from that $\ceil{\frac{d_i-x}{\lambda-\delta}}=1$ if $d_i+\delta-\lambda\leq x\leq \lambda-\delta$ and $\ceil{\frac{d_i-x}{\lambda-\delta}}=2$ if $0\leq x<d_i+\delta-\lambda$ since in our setting $\delta\leq \lambda-\delta$ and in this case $\lambda-\delta<d_i\leq\lambda$.
\end{proof}

\subsection{Proof of Lemma~\ref{pr}}
\begingroup
\def\thelemma{\ref{pr}}
\begin{lemma}
It holds that $\EE{Cu(\S')}\leq \ln2\cdot Cu(\T^*)$, $\PP{v\notin V^{**}}=1$ for any $v\in V\setminus V^*$, and $\PP{v\notin V^{**}}\leq 1/2$ for any $v\in V^*$.
\end{lemma}
\endgroup
\begin{proof}
Since the linear program is a relaxation of unsplittable Cu-VRP, we have $\sum_{S\in\S}Cu(S)\cdot x_S\leq\OPT$. Moreover, since each $S\in\S$ is selected into $\S'$ with a probability of $\min\{\ln2\cdot x_S,1\}$, we can obtain $\EE{Cu(\S')}=\sum_{S\in\S}Cu(S)\cdot \min\{\ln2\cdot x_S,1\}\leq\ln2\cdot\sum_{S\in\S}Cu(S)\cdot x_S\leq\ln2\cdot\OPT$.

Since randomized rounding is used only for customers in $V^{*}$, we have $\PP{v\notin V^{**}}=1$ for any $v\in V\setminus V^*$. Next, we consider $v\in V^*$.

Since $\PP{v\notin V^{**}}=\prod_{S\in \S: v\in S}\PP{S\notin\S'}$, we may assume that $\min\{\ln2\cdot x_S,1\}=\ln2\cdot x_S$ for any $S\in \S$ with $v\in S$ since otherwise $\PP{v\notin V^{**}}=0\leq1/2$ holds trivially. Then, we have $\PP{v\notin V^{**}}=\prod_{S\in \S: v\in S}(1-\ln2\cdot x_S)\leq e^{-\sum_{S\in \S: v\in S}\ln2\cdot x_S}\leq e^{-\ln2}=1/2$ since $1-x\leq e^{-x}$ for any $x\in[0,1]$ and we have $\sum_{\substack{S\in \S: v\in S}}x_S \geq 1$ for any $v\in V^*$ by the linear program.
\end{proof}

\subsection{Proof of Lemma~\ref{t5}}
\begingroup
\def\thelemma{\ref{t5}}
\begin{lemma}
For unsplittable Cu-VRP with any $\lambda\in(0,1]$, $\delta\in(0,\lambda/2]$, and $1/\delta\in\mathbb{N}$, $ALG.3(\lambda,\delta)$ generates a solution $\T$ with an expected cumulative cost of
\[
\ln2\cdot Cu(\T^*)+\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
