\endgroup
\begin{proof}
Recall that $\T=\T'\cup\T'''$. The set of tours $\T'$ are obtained by the selected sets in $\S'$ and $Cu(\T')\leq Cu(\S')$ by the triangle inequality. By Lemma~\ref{pr}, we have $\EE{Cu(\T')}\leq \ln2\cdot\OPT$. Next, we consider $\T''$, which is obtained by calling $ALG.1(\lambda,\delta)$ for customers in $V'\setminus V^{**}$.

Define small customers $V_s\coloneqq\{v_i\in V'\mid 0<d_i\leq \delta\}$, big customers $V_b\coloneqq\{v_i\in V'\mid \delta<d_i\leq \lambda-\delta\}$, large customers $V_l\coloneqq\{v_i\in V'\mid \lambda-\delta<d_i\leq \lambda\}$, and huge customers $V_h\coloneqq\{v_i\in V'\mid \delta<\lambda\leq 1\}$. Note that $V^*=V_b\cup V_l\cup V_h$. 

By Lemma~\ref{pr}, we know that $\PP{v\in V_s\cap (V'\setminus V^{**})}=\PP{v\notin V^{**}}=1$ for each $v\in V_s$, and
$\PP{v\in V_b\cap (V'\setminus V^{**})}=\PP{v\notin V^{**}}\leq 1/2$ for each $v\in V_b$. Similarly, we have $\PP{v\in V_l\cap (V'\setminus V^{**})}\leq1/2$ for each $v\in V_l$ and $\PP{v\in V_h\cap (V'\setminus V^{**})}\leq1/2$ for each $v\in V_h$.

By $ALG.1(\lambda,\delta)$, there are two kinds of tours in $\T''$, where the first kind of tour satisfying customers in Lines~\ref{case1ofalg1}, \ref{case1ofalg1+}, \ref{addtwo1}, and \ref{addtwo2} delivers at most $\lambda$ units of goods, and the second tour satisfying a customer $v_i$ in Line~\ref{clean} delivers exactly $d_i$ units of goods. Denote the set of the first kind and the second kind of tours by $\T''_1$ and $\T''_2$, respectively. By Lemma~\ref{t1}, the expected vehicle cost of $\T''_1$ is
\begin{equation}\label{eq3}
\begin{split}
&\EEE{Cu_1(\T''_1)}\\
&=\frac{\EEE{a\cdot\lrA{\alpha\cdot\tau+\sum_{v_i\in V_s\cap (V'\setminus V^{**})}\frac{2d_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b\cap (V'\setminus V^{**})}\frac{4d_i-2\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_l\cap (V'\setminus V^{**})}\frac{2d_i+2\lambda-4\delta}{\lambda-\delta}\cdot l_i}}}{LB}\cdot LB\\
&\leq\frac{{a\cdot\lrA{\alpha\cdot\tau+\sum_{v_i\in V_s}\frac{2d_i}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_b}\frac{2d_i-\delta}{\lambda-\delta}\cdot l_i+\sum_{v_i\in V_l}\frac{d_i+\lambda-2\delta}{\lambda-\delta}\cdot l_i}}}{LB}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\delta}_0\frac{x}{\lambda-\delta}dF(x)+\int^{\lambda-\delta}_{\delta}\frac{x-\delta/2}{\lambda-\delta}dF(x)+\int^\lambda_{\lambda-\delta}\frac{x/2+\lambda/2-\delta}{\lambda-\delta}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&\leq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\delta}_0\frac{x}{\lambda-\delta}dF(x)+\int^{\lambda}_{\delta}\frac{x}{\lambda-\delta}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB,
\end{split}
\end{equation}
where the first inequality follows from $\PP{v\in V_s\cap (V'\setminus V^{**})}=1$ for each $v\in V_s$,
$\PP{v\in V_b\cap (V'\setminus V^{**})}\leq 1/2$ for each $v\in V_b$, and $\PP{v\in V_l\cap (V'\setminus V^{**})}\leq 1/2$ for each $v\in V_l$ by the previous analysis.

The expected cumulative cost of $\T''_2$ is
\begin{equation}\label{eq4}
\begin{split}
&\EEE{Cu(\T''_2)}=\frac{\EEE{a\cdot{\sum_{v_i\in V_h}2\cdot l_i}+b\cdot\sum_{v_i\in V_h}d_i\cdot l_i}}{LB}\cdot LB\\
&\leq\frac{{a\cdot{\sum_{v_i\in V_h}l_i}+b\cdot\sum_{v_i\in V_h}\frac{ d_i}{2}\cdot l_i}}{LB}\cdot LB=\frac{\gamma\cdot\int^1_{\lambda}\frac{1}{2}dF(x)+\int^1_{\lambda}\frac{x}{4}dF(x)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\end{split}
\end{equation}

The set of tours $\T'''$ is obtained by optimizing the set of tours $\T''$. 
Denote the set of the optimized tours in $\T''_1$ by $\T'''_1$ and in $\T''_2$ by $\T'''_2$. Thus, we have $\T'''=\T'''_1\cup \T'''_2$.

\begin{claim}\label{claim}
It holds that $Cu(\T'''_2)=Cu(\T''_2)$, and $Cu(\T'''_1)\leq \lrA{1+\frac{\lambda}{2\gamma}}\cdot Cu_1(\T''_1)$.
%$Cu(\T''')\leq \lrA{1+\frac{\lambda}{2}}\cdot Cu_1(\T'')\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB$.
\end{claim}
\begin{proof}[Claim proof]
The second kind of tour in $\T''_2$ can not be improved using the optimization method in Line~\ref{opt} since it is a single tour satisfying a single customer. Hence, we have $Cu(\T'''_2)=Cu(\T''_2)$. Next, we consider the first kind of tour.

For each tour $T=v_0v_{1}\dots v_{k}v_0\in \T''_1$, Line~\ref{opt} ensures that the load of the vehicle equals the delivered units of goods on $T$. Hence, the vehicle carries $\sum_{j=1}^{i-1}d_j$ units of goods when traveling along the edge $v_{i-1}v_{i\bmod (k+1)}$ for each $i\in[k+1]$, and then we have 
\[
Cu(T)=a\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})+b\cdot\sum_{i=1}^{k+1}\lrA{\sum_{j=1}^{i-1}d_j}\cdot w(v_{i-1},v_{i\bmod (k+1)}).
\]

Consider the tour with the opposite direction, i.e., $T'=v_0v_{k}\dots v_{i}v_0\in \T''$. we have 
\[
Cu(T')=a\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})+b\cdot\sum_{i=1}^{k+1}\lrA{\sum_{j=1}^{k}d_j-\sum_{j=1}^{i-1}d_j}\cdot w(v_{i-1},v_{i\bmod (k+1)}).
\]

Therefore, the better one has a cumulative cost of at most 
\begin{align*}
&a\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})+b\cdot\frac{1}{2}\cdot\sum_{j=1}^{k}d_j\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})\\
&\leq a\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})+b\cdot\frac{\lambda}{2}\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})=\lrA{1+\frac{\lambda}{2\gamma}}\cdot Cu_1(T),
\end{align*}
where the inequality follows from that the first kind of tour delivers at most $\lambda$ units of goods, and the equality from $\gamma=a/b$ and $Cu_1(T)=a\cdot\sum_{i=1}^{k+1}w(v_{i-1},v_{i\bmod (k+1)})$.

Therefore, we have $Cu(\T'''_1)\leq \lrA{1+\frac{\lambda}{2\gamma}}\cdot Cu_1(\T''_1)$.
\end{proof}

By (\ref{eq3}), (\ref{eq4}), and the Claim~\ref{claim}, the expected cumulative cost of $\T'''$ is at most 
\begin{align*}
&\lrA{1+\frac{\lambda}{2\gamma}}\cdot\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB+\frac{\gamma\cdot\int^1_{\lambda}\frac{1}{2}dF(x)+\int^1_{\lambda}\frac{x}{4}dF(x)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)+\int^1_{\lambda}\frac{1}{2}dF(x)}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)+\int^1_{\lambda}\frac{\lambda\cdot x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)+\int^1_{\lambda}\frac{x}{\lambda-\delta}dF(x)}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_0\frac{x}{\lambda-\delta}dF(x)+\int^1_{\lambda}\frac{x}{\lambda-\delta}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda-\delta}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB,
\end{align*}
where the inequality follows from $\frac{\lambda\cdot x}{2}\leq \frac{1}{2}\leq \frac{x}{\lambda-\delta}$ for any $x\in[\lambda, 1]$.
\end{proof}
\subsection{Proof of Lemma~\ref{t7}}
\begingroup
\def\thelemma{\ref{t7}}
\begin{lemma}
For unsplittable Cu-VRP with any $\lambda\in(0,1]$, $ALG.4(\lambda)$ generates a solution $\T$ with an expected cumulative cost of
\[
\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)+\int_\lambda^1 1dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2/2+\lambda\cdot x}{2\lambda}dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\]
\end{lemma}
\endgroup
\begin{proof}
Firstly, $ALG.4(\lambda)$ calls $ALG.1(\lambda,0)$ to obtain a set of tours $\T'$. As in the proof of Lemma~\ref{t5}, there are two kinds of tours in $\T'$, where the first kind of tour satisfying customers in Lines~\ref{case1ofalg1}, \ref{case1ofalg1+}, \ref{addtwo1}, and \ref{addtwo2} delivers at most $\lambda$ units of goods, and the second tour satisfying a customer $v_i$ in Line~\ref{clean} delivers exactly $d_i$ units of goods. Denote the set of the first kind and the second kind of tours by $\T'_1$ and $\T'_2$, respectively.

By Lemma~\ref{t1}, we can obtain 
\begin{align*}
\EEE{Cu(\T'_1)}\leq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2+\lambda\cdot x}{2\lambda}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB,
\end{align*}
and 
\begin{equation}\label{eq5}
\EEE{Cu(\T'_2)}\leq\frac{\gamma\cdot\int_\lambda^1 1dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\end{equation}


The set of tours $\T$ is obtained by optimizing the set of tours $\T'$. 
Denote the set of the optimized tours in $\T'_1$ by $\T_1$ and in $\T'_2$ by $\T_2$. 

\begin{claim}\label{claim+}
It holds that $Cu(\T_2)=Cu(\T'_2)$ and 
\[\EEE{Cu(\T'_1)}\leq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2/2+\lambda\cdot x}{2\lambda}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\]
\end{claim}
\begin{proof}[Claim proof]
By the proof of Claim~\ref{claim}, we can obtain $Cu(\T_2)=Cu(\T'_2)$. To prove the inequality, we need a different method from that used in Claim~\ref{claim}.

Recall Case~2 in the proof Lemma~\ref{l2}.
Since $\delta=0$, if the vehicle incurs some additional visits to $v_0$ when serving a customer $v_i$, it must incur two additional visits to $v_0$. Moreover, the trips by the additional visits to $v_0$ belong to some tours in $\T'_1$.
If the vehicle incurs two additional visits, %by the proof Lemma~\ref{l2}, 
the vehicle carries $(L_{i-1},0)$ units of goods from $v_i$ to $v_0$, $(d_i,0)$ units of goods from $v_0$ to $v_i$, $(0,0)$ units of goods from $v_i$ to $v_0$, and $(L_{i-1}+\lambda-d_i,0)$ units of goods from $v_0$ to $v_i$, and the cumulative cost is $a\cdot 4\cdot l_i + b\cdot (L_{i-1}+d_i+0+L_{i-1}+\lambda-d_i)\cdot l_i=a\cdot 4\cdot l_i + b\cdot (2L_{i-1}+\lambda)\cdot l_i$. 
Specifically, we can assume that the vehicle carries $(0,0)$ instead of $(L_{i-1},0)$ units of goods from $v_i$ to $v_0$ in the first visit to $v_0$, as we will optimize the tours in $\T'_1$ so that the load of the vehicle equals the delivered units of goods. Hence, the cumulative cost reduces to $a\cdot 4\cdot l_i + b\cdot (0+d_i+0+L_{i-1}+\lambda-d_i)\cdot l_i=a\cdot 4\cdot l_i + b\cdot (L_{i-1}+\lambda)\cdot l_i$. Then, following the proof of Lemma~\ref{t1}, we can obtain 
\[\EEE{Cu(\T_1)}\leq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2+2\lambda\cdot x}{4\lambda}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\]
This finishes the proof.
\end{proof}
By (\ref{eq5}) and Claim~\ref{claim+}, the theorem is proved.
\end{proof}

\subsection{Proof of Theorem~\ref{t8}}
\begingroup
\def\thetheorem{\ref{t8}}
\begin{theorem}
For unsplittable Cu-VRP, when $\alpha=1.5$, we can find $(\lambda,\theta,p)$ such that the approximation ratio of $APPROX.4(\lambda,\theta,p)$ is bounded by $3.163$ for any $\gamma\in(0,0.428]$. 
Moreover, for any $\alpha\in[1,1.5]$, we can find $(\lambda,\theta,p)$ such that the approximation ratio of $APPROX.4(\lambda,\theta,p)$ is bounded by $\alpha+1+\ln2-0.029$ for any $\gamma\in(0,0.285]$.
\end{theorem}
\endgroup
\begin{proof}
By Lemma~\ref{t7}, the approximation ratio of $ALG.4(\lambda,0)$ is at most
\begin{align*}
&\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{2x}{\lambda}dF(x)+\int_\lambda^1 1dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int^{\lambda}_{0}\frac{x^2/2+\lambda\cdot x}{2\lambda}dF(x)+\int_\lambda^1\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\int_{\lambda}^{1}1dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1+\mu/2\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{\lambda}\cdot\int_{\lambda}^{1}xdF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1+\mu/2\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&= \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{\lambda}}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{\mu/2\lambda}{2}\cdot\int_{0}^{\lambda}xdF(x)+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\lambda}}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\frac{\mu/2\lambda+1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{align*}
where the first equality follows from the definition of $\mu$, the second equality from $\int^1_0xdF(x)=1$ by (\ref{int}), the first inequality from $\int_{\lambda}^{1}1dF(x)\leq \frac{1}{\lambda}\cdot\int_{\lambda}^{1}xdF(x)$, and the second inequality from $\int_{0}^{\lambda}xdF(x)\leq \int_{0}^{1}xdF(x)=1$.

By Lemma~\ref{t7}, the approximation ratio of $ALG.4(\theta\cdot\lambda,0)$ is at most
\begin{align*}
&\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int_{0}^{\theta\cdot\lambda}\frac{2x}{\theta\cdot\lambda}dF(x)+\int_{\theta\cdot\lambda}^{1}1dF(x)}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\int_{0}^{\theta\cdot\lambda}\frac{x^2/2+\theta\cdot\lambda\cdot x}{2\cdot\theta\cdot\lambda}dF(x)+\int_{\theta\cdot\lambda}^{1}\frac{x}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{2}{\theta\cdot\lambda}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{\theta\cdot\lambda}\cdot\int_{\theta\cdot\lambda}^{1}xdF(x)}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{3}{4}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{2}\cdot\int_{\theta\cdot\lambda}^{1}xdF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&= \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{4}\cdot\int_{0}^{\theta\cdot\lambda}xdF(x)+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\leq \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\cdot\frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}+\frac{1}{\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{4}\cdot\frac{\lambda-\mu}{\lambda-\theta\cdot\lambda}+\frac{1}{2}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&= \frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\mu-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{\frac{\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+\frac{1}{4}\cdot\frac{3\lambda-\mu-2\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{align*}
where the first inequality follows from $\int_{0}^{\theta\cdot\lambda}x^2dF(x)\leq \int_{0}^{\theta\cdot\lambda}\theta\cdot\lambda\cdot xdF(x)$, the second inequality from (\ref{eq1}), and the first equality from $\int^1_0xdF(x)=1$ by (\ref{int}).

Recall that in $APPROX.4(\lambda,\theta,p)$ we call $ALG.4(\lambda,0)$ (resp., $ALG.4(\theta\cdot\lambda,0)$) with a probability of $p$ (resp., $1-p$). Hence, to erase the items related to $\mu$ in the numerators of the approximation ratios of $ALG.4(\lambda,0)$ and $ALG.4(\theta\cdot\lambda,0)$, we need to set $p$ such that 
\[
p\cdot\frac{1}{4}\cdot\frac{1}{\lambda}+(1-p)\cdot\lrA{\gamma\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{-1}{\lambda-\theta\cdot\lambda}+\frac{1}{4}\cdot\frac{-1}{\lambda-\theta\cdot\lambda}}=0.
\]
Then, we can obtain $p=\frac{\frac{1}{4(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}{\frac{1}{4\lambda}+\frac{1}{4(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}$, and the approximation ratio is $\max_{\sigma\geq 0} R(\sigma)$, where
\begin{equation}\label{ratio2}
\begin{split}
&R(\sigma)\coloneqq\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+p\cdot\frac{2}{\lambda}+(1-p)\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{\frac{p\cdot\lambda+(1-p)\cdot\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma+p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{4}\cdot\frac{3\lambda-2\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\frac{\lrA{\gamma\cdot\alpha\cdot\sigma+\frac{p\cdot\lambda+(1-p)\cdot\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma}+\lrA{\gamma\cdot\lrA{p\cdot\frac{2}{\lambda}+(1-p)\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{4}\cdot\frac{3\lambda-2\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}
\end{split}
\end{equation}

When $\alpha=1.5$, $\gamma\in(0,0.428]$, and $\lambda=\min\{3.5\gamma/\alpha,1\}$, we have the following result.
\begin{itemize}
    \item When $\gamma\in(0,0.428]$, setting $\theta=0.5043$, we have $\max_{\sigma\geq 0} R(\sigma)<3.163$.
\end{itemize}

\begin{claim}
When $\gamma\in(0,0.428]$, setting $\theta=0.5043$, we have $\max_{\sigma\geq 0} R(\sigma)\leq 3.163$.
\end{claim}
\begin{proof}[Claim proof]
Note that $\lambda=\min\{1, 3.5\gamma/\alpha\}=3.5\gamma/\alpha$ and $\alpha=1.5$. Setting $\theta=0.5043$, we can obtain $\gamma\cdot\alpha\cdot\sigma+\frac{p\cdot\lambda+(1-p)\cdot\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma\leq 3.163\cdot\gamma\cdot\sigma$ and $\gamma\cdot\lra{p\cdot\frac{2}{\lambda}+(1-p)\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lra{p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{4}\cdot\frac{3\lambda-2\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}\leq 1.5811<3.163/2$. Hence, by (\ref{ratio2}), we have 
\begin{align*}
&R(\sigma)\leq \frac{3.163\cdot\gamma\cdot\sigma+3.163/2}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\leq 3.163\cdot\frac{\gamma\cdot\sigma+0.5}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\leq 3.163,
\end{align*}
which finishes the proof.
\end{proof}

Note that $\frac{1}{3.5}\approx 0.2857$. We can obtain the following result for any $1\leq \alpha\leq 1.5$.
\begin{itemize}
    \item When $\gamma\in(0,0.285]$, setting $\theta=0.5$, we have $\max_{\sigma\geq 0} R(\sigma)\leq \alpha+1+\ln2-0.029$ for any $1\leq \alpha \leq 1.5$.
\end{itemize}
\begin{claim}
When $\gamma\in(0,0.285]$, setting $\theta=0.5$, we have $\max_{\sigma\geq 0} R(\sigma)\leq \alpha+1+\ln2-0.029$ for any $1\leq \alpha \leq 1.5$.
\end{claim}
\begin{proof}[Claim proof]
We set $\lambda=\min\{1, 3.5\gamma/\alpha\}=3.5\gamma/\alpha$ and $\theta=1/2$. We can obtain that
\begin{equation}\label{thep}
p=\frac{\frac{1}{4(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}{\frac{1}{4\lambda}+\frac{1}{4(\lambda-\theta\cdot\lambda)}+\frac{\gamma}{\theta\cdot\lambda(\lambda-\theta\cdot\lambda)}}=\frac{\frac{1}{4(1-\theta)}+\frac{\alpha}{3.5}\cdot \frac{1}{\theta(1-\theta)}}{\frac{1}{4}+\frac{1}{4(1-\theta)}+\frac{\alpha}{3.5}\cdot\frac{1}{\theta(1-\theta)}}=\frac{8\alpha+3.5}{8\alpha+5.25},
\end{equation}
where the first equality follows from $\lambda=\min\{1, 3.5\gamma/\alpha\}=3.5\gamma/\alpha$ and the second from $\theta=1/2$.

One one hand, we have
\begin{equation}\label{ratio2-1}
\begin{split}
\gamma\cdot\alpha\cdot\sigma+\frac{p\cdot\lambda+(1-p)\cdot\theta\cdot\lambda}{2}\cdot\alpha\cdot\sigma &=\gamma\cdot\alpha\cdot\sigma\cdot\lrA{1+\frac{p+(1-p)\cdot\theta}{2}\cdot\frac{3.5}{\alpha}}\\
&=\gamma\cdot\sigma\cdot\lrA{\alpha+\frac{1+\frac{8\alpha+3.5}{8\alpha+5.25}}{2}\cdot\frac{3.5}{2}}\\
&<\gamma\cdot\sigma\cdot\lrA{\alpha+1+\ln2-0.03}\\
&\leq\gamma\cdot\max\{\sigma,\ 1\}\cdot\lrA{\alpha+1+\ln2-0.029},
\end{split}
\end{equation}
where the first equality follows from $\lambda=3.5\gamma/\alpha$, the second equality from (\ref{thep}) and $\theta=0.5$,
the first inequality from $\alpha+\frac{1+\frac{8\alpha+3.5}{8\alpha+5.25}}{2}\cdot\frac{3.5}{2}\leq \alpha+1+\ln2-0.029$ for any $1\leq \alpha\leq 1.5$, and the second inequality from $\sigma\leq\max\{\sigma,\ 1\}$.

On the other hand, by (\ref{thep}), we have
\begin{equation}\label{ratio2-2}
\begin{split}
&\gamma\cdot\lrA{p\cdot\frac{2}{\lambda}+(1-p)\cdot\frac{1}{\theta\cdot\lambda}\cdot\frac{2\lambda-\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}+\lrA{p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{4}\cdot\frac{3\lambda-2\theta\cdot\lambda}{\lambda-\theta\cdot\lambda}}\\
&=\frac{\alpha}{3.5}\cdot\lrA{2p+(1-p)\cdot\frac{1}{\theta}\cdot\frac{2-\theta}{1-\theta}}+p\cdot\frac{1}{2}+(1-p)\cdot\frac{1}{4}\cdot\frac{3-2\theta}{1-\theta}\\
&=\frac{\alpha}{3.5}\cdot\lrA{2+\frac{7}{8\alpha+5.25}}+\frac{4\alpha+3.5}{8\alpha+5.25}\\
&<\frac{1}{2}\cdot\lrA{\alpha+1+\ln2 -0.029},
\end{split}
\end{equation}
where the first equality follows from $\lambda=3.5\gamma/\alpha$, the second equality from (\ref{thep}) and $\theta=0.5$, and
the inequality from $\frac{\alpha}{3.5}\cdot\lrA{2+\frac{7}{8\alpha+5.25}}+\frac{4\alpha+3.5}{8\alpha+5.25}\leq \frac{1}{2}\cdot\lrA{\alpha+1+\ln2 -0.029}$ for any $1\leq \alpha\leq 1.5$.

Therefore, by (\ref{ratio2}), (\ref{ratio2-1}), and (\ref{ratio2-2}), we have 
\begin{align*}
&R(\sigma)<\frac{\gamma\cdot\max\{\sigma,\ 1\}\cdot\lrA{\alpha+1+\ln2-0.029}+\frac{1}{2}\cdot\lrA{\alpha+1+\ln2 -0.029}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}=\alpha+1+\ln2 -0.029,
\end{align*}
which finishes the proof.
\end{proof}

This finishes the proof.
\end{proof}

\subsection{Proof of Lemma~\ref{sl2}}
\begingroup
\def\thelemma{\ref{sl2}}
\begin{lemma}
Conditioned on $\chi=d$, when serving each customer $v_i$ in $ALG.S(\lambda)$, the expected cumulative cost of the vehicle due to the possible additional visit(s) to $v_0$ is $a\cdot 2\cdot \frac{d_i}{\lambda}\cdot l_i+b\cdot d_i\cdot l_i$.
\end{lemma}
\endgroup
\begin{proof}
We first consider $d_i\leq\lambda$. In this case, the vehicle can satisfy $v_i$ using at most one additional visit to $v_0$.

By Lemma~\ref{sl0}, the vehicle carries $L_{i-1}$ units of goods during the vehicle's travel from $v_{i-1}$ to $v_i$, where $L_{i-1}\sim U[0,\lambda)$. Hence, the vehicle incurs one additional visit to $v_0$ with a probability of $\PP{L_{i-1}=x<d_i}=\int_{0}^{d_i}\frac{1}{\lambda}dx=\frac{d_i}{\lambda}$.

If the vehicle incurs an additional visit to $v_0$, by $ALG.S(\lambda)$, the vehicle will carry $0$ units of goods from $v_i$ to $v_0$ and $\lambda$ units of goods from $v_0$ to $v_i$. So, the cumulative cost of this additional visit will be $a\cdot 2\cdot l_i + b\cdot \lambda\cdot l_i$. Since $L_{i-1}\sim U[0,\lambda)$ and $d_i\leq \lambda$, the expected cumulative cost of this additional visit conditioned on the demand realization is 
$
\int_{0}^{d_i}\frac{a\cdot 2\cdot l_i + b\cdot \lambda\cdot l_i}{\lambda}dx=a\cdot 2\cdot \frac{d_i}{\lambda}\cdot l_i+b\cdot d_i\cdot l_i.
$

Next, we consider $d_i>\lambda$.

In this case, we may implicitly split each customer $v_i$ with $d_i>\lambda$ into a set of customers at the same place, denoted as $V_i$, with each having a demand of at most $\lambda$ and all having a total demand of $d_i$. Define $l_v\coloneqq w(v_0,v)$ for each $v\in V_i$. Hence, $l_i=l_v$ for each $v\in V_i$ and $d_i\cdot l_i=\sum_{v\in V_i} d_v\cdot l_v$. 
Denote the original instance and the new instance by $I$ and $I'$, respectively. The TSP tour in $I'$, denoted as $v_0p_1\dots p_nv_0$ where $p_i$ can be any permutation of customers in $V_i$, has the same cost as the TSP tour $T^*=v_0v_1\dots v_nv_0$ in $I$.
It can be verified that based on the greedy strategy, $ALG.S(\lambda)$ generates two equivalent solutions for $I$ and $I'$ with the same cumulative cost. 
Moreover, the expected cumulative cost of the possible additional visits when visiting $v_i$ in $I$ equals to the total expected cumulative cost of the possible additional visits when visiting all customers in $V_i$ in $I'$.

Since the demand of each customer in $I'$ is at most $\lambda$, by the previous analysis of the case where $d_i\leq\lambda$, the expected cumulative cost of the possible additional visits to $v_i$ conditioned on the demand realization is 
\[
\sum_{v\in V_i}\lrA{a\cdot 2\cdot \frac{d_v}{\lambda}\cdot l_v+b\cdot d_v\cdot l_v}=a\cdot 2\cdot\sum_{v\in V_i} \frac{d_v}{\lambda}\cdot l_i+b\cdot \lambda\cdot\sum_{v\in V_i} d_v\cdot l_i=a\cdot 2\cdot \frac{d_i}{\lambda}\cdot l_i+b\cdot d_i\cdot l_i,
\]
which finishes the proof.
\end{proof}

\subsection{Proof of Lemma~\ref{t9}}
\begingroup
\def\thelemma{\ref{t9}}
\begin{lemma}
For splittable Cu-VRPSD with any $\lambda\in(0,1]$, conditioned on $\chi=d$, $ALG.S(\lambda)$ generates a solution $\T$ with an expected cumulative cost of
\[
\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB.
\]
\end{lemma}
\endgroup
\begin{proof}
By Lemma~\ref{sl1}, the expected cumulative cost of the vehicle for traveling the edges on the TSP tour $T^*$ is 
$
\sum_{e\in E(T^*)}\lra{a\cdot w(e)+b\cdot\frac{\lambda}{2}\cdot w(e)}=a\cdot w(T^*)+b\cdot\frac{\lambda}{2}\cdot w(T^*)\leq a\cdot\alpha\cdot\tau+b\cdot\frac{\lambda}{2}\cdot\alpha\cdot\tau,
$
where the inequality follows from $w(T^*)\leq \alpha\cdot\tau$ since $T^*$ is an $\alpha$-approximate TSP tour.

By Lemma~\ref{sl2}, when serving customers in $V'$, the expected cumulative cost due to the possible additional visit(s) to $v_0$ is
\[
\sum_{v_i\in V'}\lrA{a\cdot 2\cdot \frac{d_i}{\lambda}\cdot l_i+b\cdot d_i\cdot l_i}=a\cdot\sum_{v_i\in V'} 2\cdot \frac{d_i}{\lambda}\cdot l_i+b\cdot\sum_{v_i\in V'} d_i\cdot l_i.
\]

Therefore, $ALG.S(\lambda)$ generates a solution $\T$ with an expected cumulative cost of
\begin{align*}
&\frac{a\cdot\lrA{\alpha\cdot\tau+\sum_{v_i\in V'} 2\cdot \frac{d_i}{\lambda}\cdot l_i}+b\cdot\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\tau+\sum_{v_i\in V'} d_i\cdot l_i}}{LB}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int_{0}^{1} \frac{1}{\lambda}dF(x)}+\lrA{\frac{\lambda}{2}\cdot\alpha\cdot\sigma+\int_{0}^{1} \frac{1}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}+\frac{\lambda}{2}\cdot\lrA{\alpha\cdot\sigma+\frac{1}{\lambda}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\cdot LB
\end{align*}
where the equality follows from dividing both the numerator and denominator by $b\cdot\eta$, using $\gamma=a/b$, $\sigma=\tau/\eta$, and $LB=a\cdot\max\{\tau, \eta\}+b\cdot\frac{1}{2}\cdot\eta$ by Lemma~\ref{lb}, and equitation (\ref{int}).
\end{proof}

\section{Numerical Evaluation of the Approximation Ratio of APPROX.2}\label{tightness}
Let $N$ be a multiple of 3, saying $N=300$. 
For any $i\in\{0,1,2\}$ and $j\in[N]$, we set 
\begin{equation}\label{N1}
r^i_j=\int_{0}^{\frac{j}{N}}x^idF(x).
\end{equation}

By (\ref{int}), for any $i\in\{1,2\}$ and $j\in[t]$, we have 
\begin{equation}\label{N2}
\frac{j-1}{N}\cdot (r^{i-1}_j-r^{i-1}_{j-1})\leq (r^i_j-r^i_{j-1})\leq \frac{j}{N}\cdot (r^{i-1}_j-r^{i-1}_{j-1})\quad\quad\mbox{and}\quad\quad r^1_N=1.
\end{equation}


By the proof of Theorem~\ref{t4}, the approximation ratio of $ALG.1(1,1/3)$ is at most
\begin{equation}\label{N3}
\begin{split}
&\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\frac{1}{3}}_0\frac{3x}{2}dF(x)+\int^\frac{2}{3}_{\frac{1}{3}}\frac{6x-1}{2}dF(x)+\int^1_\frac{2}{3}\frac{3x+1}{2}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\quad+\frac{\lrA{\frac{2}{3}\cdot\alpha\cdot\sigma+\int^{\frac{1}{3}}_0\frac{4x-3x^2}{4}dF(x)+\int^\frac{2}{3}_{\frac{1}{3}}\frac{3x^2+2x}{4}dF(x)+\int^1_\frac{2}{3}\frac{9x^2-6x+4}{6}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{3}{2}r^1_{\frac{1}{3}N}+3(r^1_{\frac{2}{3}N}-r^1_{\frac{1}{3}N})-\frac{1}{2}(r^0_{\frac{2}{3}N}-r^0_{\frac{1}{3}N})+\frac{3}{2}(r^1_{N}-r^1_{\frac{2}{3}N})+\frac{1}{2}(r^0_{N}-r^0_{\frac{2}{3}N})}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}\\
&\quad+\frac{\lrA{\frac{2}{3}\cdot\alpha\cdot\sigma-\frac{3}{4}r^2_{\frac{1}{3}N}+r^1_{\frac{1}{3}N}+\frac{3}{4}(r^2_{\frac{2}{3}N}-r^2_{\frac{1}{3}N})+\frac{1}{2}(r^1_{\frac{2}{3}N}-r^1_{\frac{1}{3}N})+\frac{3}{2}(r^2_{N}-r^2_{\frac{2}{3}N})-(r^1_{N}-r^1_{\frac{2}{3}N})+\frac{2}{3}(r^0_{N}-r^0_{\frac{2}{3}N})}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},
\end{split}
\end{equation}
where the equality follows from (\ref{N1}).

Moreover, the approximation ratio of $ALG.2(1,1/3)$ is at most
\begin{equation}\label{N4}
\begin{split}
&\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\int^{\frac{1}{3}}_0\frac{3x}{2}dF(x)}+\lrA{\frac{2}{3}\cdot\alpha\cdot\sigma+\int^{\frac{1}{3}}_0\frac{4x-3x^2}{4}dF(x)}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}+\min\lrC{\frac{\int^{1}_\frac{1}{3}\frac{2\gamma+x}{2}dF(x)}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},\ 1}\\
&=\frac{\gamma\cdot\lrA{\alpha\cdot\sigma+\frac{3}{2}r^1_{\frac{1}{3}N}}+\lrA{\frac{2}{3}\cdot\alpha\cdot\sigma-\frac{3}{4}r^2_{\frac{1}{3}N}+r^1_{\frac{1}{3}N}}}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5}+\min\lrC{\frac{
\frac{1}{2}(r^1_{N}-r^1_{\frac{1}{3}N})+\gamma\cdot(r^0_{N}-r^0_{\frac{1}{3}N})}{\gamma\cdot\max\lrC{\sigma,\ 1}+0.5},\ 1},
\end{split}
\end{equation}
where the equality follows from (\ref{N1}).

We have the following two cases.

\textbf{Case~1: $\frac{1}{2}(r^1_{N}-r^1_{\frac{1}{3}N})+\gamma\cdot(r^0_{N}-r^0_{\frac{1}{3}N})\leq \gamma\cdot\max\lrC{\sigma,\ 1}+0.5$.}

Recall that in $APPROX.2$ we call $ALG.1(1,1/3)$ (resp., $ALG.2(1,1/3)$) with a probability of $0.5$ (resp., $0.5$). By (\ref{N1})-(\ref{N4}), the approximation ratio of $APPROX.2$ is at most the value of the following linear program, where $\gamma$, $\sigma$, and $N$ are all fixed parameters.
