	\item For each edge $(x_i, c^j)$ in $\cB_{\cX,\cC}$, we add the two parallel edges $(u_i^{\sigma_{x_i}^{-1}(c^j)}, \hat{v}_{\sigma_{c^j}^{-1}(x_i)}^j)$ and $(\hat{u}_i^{\sigma_{x_i}^{-1}(c^j)}, v_{\sigma_{c^j}^{-1}(x_i)}^j)$ to the graph. Recall that $\sigma_{v}^{-1}(u)$ returns the index of a neighbor $u$ in the neighborhood of $v$ in $\cB_{\cX, \cC}$. This link between a clause and a variable gadget is illustrated in Figure \ref{fig:graphConstruction}.

	\item Finally we define $T(I_{\cX, \cC})$ to be the union of the $T(X_i)$ and $T(C^j)$ for all $i\in \{1,...,n\}$ and $j\in \{1,...,m\}$.
\end{itemize}


