\caption{Possible $T(I_{\cX, \cC})$-odd orientation of $E(C)$}
\label{fig:C_orientation}
\end{figure}

\end{proof}


\subsection{Proof of the reduction} \label{sec:correction}

\noindent In this section, we establish the following result expressing the reduction from Planar-3-SAT to Problem \ref{prob:PDAOP}.\newline

\noindent Recall that the acyclic $T$-odd orientation problem is in NP. Given an orientation, one can verify in polynomial time whether it satisfies the parity constraints for each vertex and whether the orientation is acyclic.


\begin{theorem}\label{thm:equiv}
	Let $(\cX, \cC)$ be a Planar-3-SAT instance and $I_{\cX, \cC} = (G,T)$ be the corresponding instance of Problem \ref{prob:PDAOP}.\newline
	$I_{\cX, \cC}$ has an acyclic $T$-odd orientation if and only if  $(\cX, \cC)$ has a $True$ assignment.
\end{theorem}

\begin{proof}
\noindent Let $(\cX, \cC)$ be a Planar-3-SAT instance and $I_{\cX, \cC} = (G,T)$ be the corresponding instance of Problem \ref{prob:PDAOP}.\newline

\noindent Let $\alpha$ be an assignment of $(\cX, \cC)$ and $O$ be a $T$-odd orientation of $I_{\cX, \cC}$ such that $O(\Gamma_{X_i})$ is acyclic for all $i\in \{1,...,n\}$. We say that $\alpha$ (or respectively $O$) is {\bf compatible} to $O$ (respectively $\alpha$) when, for all $i\in \{1,...,n\}$, we have that :
$$\alpha(x_i)= True \ \hbox{if and only if} \ O(\Gamma_{X_i})=O(\Gamma_{X_i})_{out}.$$

\noindent  Observe that, by Corollary \ref{cor:variableGadget}, if $\alpha$ and $O$ are compatible, then we also have, for all $i=1,...,n$, that: $$\alpha(x_i)= False \ \hbox{if and only if} \ O(\Gamma_{X_i})=O(\Gamma_{X_i})_{in}.$$

\noindent Notice also, from Corollary \ref{cor:variableGadget}, that any $T$-odd orientation $O$ of $I_{\cX, \cC}$ such that $O(\Gamma_{X_i})$ is acyclic for all $i\in \{1,...,n\}$ has a compatible assignement of $(\cX, \cC)$, and from Lemma \ref{lem:clauseGadget}, that any assignement of $(\cX, \cC)$ has a compatible orientation of $I_{\cX, \cC}$.\newline

\noindent Moreover, by Lemma \ref{lem:clauseGadget}, a $T$-odd orientation $O$ of $I_{\cX, \cC}$ such that $O(\Gamma_{X_i})$ is acyclic for all $i\in \{1,...,n\}$ is acyclic if and only if $O(\Gamma_{C^j})$ satisfies $\delta^-(W_{C^j}) \neq \emptyset$ for all $j \in \{1, \dots, m\}$.

\noindent And a $True$ assignment of $(\cX, \cC)$ is an assignment which satisfy each clause in $\cC$.

\noindent Hence to prove Theorem \ref{thm:equiv}, it is enough to check that for any $\alpha$ and $O$ compatibles and any clause $c^j$, we have that~: $$\alpha \ \hbox{satisfies} \ c^j \ \hbox{if and only if} \ \delta^-(W_{C^j}) \neq \emptyset \ \hbox{in} \ O(I_{\cX, \cC}).$$

\noindent Let $c^j\in \cC$. Without loss of generality, one may assume that $c^j= l_1\vee l_2\vee l_3$ with either $l_i=x_i$ or $l_i=\neg x_i$, for $i=1, ...,3$. By definition of the disjonction $\vee$, we have~:

$$c^j \text{ is  satisfied by }\alpha \iff \exists l_i\in c^j, \begin{cases}
l_i=x_i \text{ and } \alpha(x_i)=True, \text{ or }\\
l_i=\neg x_i \text{ and } \alpha(x_i)=False.
\end{cases}
$$

\noindent By construction of $I_{\cX, \cC}$ and since $O$ is compatible to $\alpha$, this is equivalent to~:

$$ \exists i, \begin{cases}
v^j_i \in T(I_{\cX, \cC}) \text{ and } O(\hat{u}_i^{\sigma^{-1}_{x_i}(c^j)}v^j_i)=\dir{\hat{u}_i^{\sigma^{-1}_{x_i}(c^j)}v^j_i}  \text{ or }\\
v^j_i \in V(I_{\cX, \cC})\setminus T(I_{\cX, \cC}) \text{ and } O(\hat{u}_i^{\sigma^{-1}_{x_i}(c^j)}v^j_i)=\ldir{\hat{u}_i^{\sigma^{-1}_{x_i}(c^j)}v^j_i}.
\end{cases}
$$

\noindent By a forcing argument due to parity condition on the in-degree of $v^j_i$, this is equivalent to~:

$$\exists i, O(v^j_iw_i^j)=\dir{v_i^jw_i^j}.$$

\noindent This is precisely $\delta^-(W_{C^j})\neq \emptyset$ in $O(I_{\cX, \cC})$. \newline
Thus, for $(O,\alpha)$ two compatible orientation and assignment, $O$ is an acyclic $T$-odd orientation of $I_{\cX, \cC}$ if and only if $\alpha$ is a $True$ assignment of $(\cX, \cC)$.
\
\end{proof}

\noindent One can check that the construction of $I_{(\cX, \cC)}$ from $(\cX, \cC)$ can be done in polynomial time. Thus, our main result, Theorem \ref{thm:main}, is a direct consequence of Theorems \ref{thm:equiv} and \ref{thm:P3SAT}.


\section{Conclusion}
\noindent We proved that finding an acyclic $T$-odd orientation in a partially directed graph is NP-complete, even when $G$ is planar of max degree 3, and vertices in $V(G)-T$ have degree 2. Also, in our construction, from $(\cX, \cC)$ a Planar-3-SAT instance and $I_{\cX, \cC} = (G,T)$ its corresponding instance of Problem \ref{prob:PDAOP}, any vertex $v\in T$ of degree $2$ could be contracted into a single edge resulting in an equivalent instance $I'_{\cX, \cC} = (G',T')$ where each $v\in V(G')$ has degree $3$ if $v\in T'$ and degree $2$ otherwise. We observe also that, from any acyclic $T'$-odd orientation of $I'_{\cX, \cC}$, by flipping the orientation of all edges, we can obtain an acyclic $\emptyset$-odd orientation of $I'_{\cX, \cC}$. Thus, even finding acyclic $\emptyset$-odd orientation on partially directed planar graphs of max degree $3$ is NP-complete. While on the other hand, we exposed a polynomial-time algorithm to determine whether $G$ admits an acyclic $T$-odd orientation whenever $G$ is planar and $|T| = |V(G)|-1$. 
Overall, this work strongly emphasizes the interest of this class of instances for Problem \ref{prob:AOP} and presents it as a promising candidate for a polynomial-time algorithm. Moreover, in our reduction from planar-3-SAT to Problem \ref{prob:PDAOP}, the constructed graph contains a linear number of arcs, which raises questions about the complexity of Problem \ref{prob:PDAOP} when parameterized by the number of arcs.



