\noindent With some extra work, we can drop the requirement that $u$ and $v$ are on the convex hull of $S$. 

\begin{corollary}\label{Cor: stars}
    Let $u$ and $v$ be arbitrary vertices of $S$. Then both $\starat(u)$ and $\starat(v)$ are connected to any double star with centers at $u$ and $v$.
\end{corollary}
\begin{proof}
    The line through $u$ and $v$ divides $S$ into two point sets $T,T'$ such that $u$ and $v$ are adjacent on the convex hull of both $T$ and $T'$. We then apply Lemma \ref{Thm: starsanddoublestars} on the double star with centers $u,v$ in $T$ and $T'$. $\qed$
\end{proof}

 Using Corollary \ref{Cor: stars}, we prove Theorem \ref{Thm: wellseparated}.

\begin{proof}[of Theorem \ref{Thm: wellseparated}]
    We first prove that $C$ can be transformed into a star. Denote the vertices of the spine of $C$ by $v_1,v_2,\dots, v_k$. We proceed by induction on $k$. The case $k=1$ is covered by Corollary \ref{Cor: stars}. Now, as $C$ is well-separated, we know that the convex hull of $S_{1,2}$ is disjoint from the rest of $S$. Thus we can apply Corollary \ref{Cor: stars} to $S_{1,2}$ and reduce the length of the spine of $C$ by one. Then the result follows by induction and Corollary \ref{Cor: stars}. $\qed$
\end{proof}

Before proving Theorem \ref{thm: sliidesconnnected}, we need the following slight strengthening of Corollary \ref{Cor: stars}.

\begin{lemma}
    Let $S$ be a set of points in the plane and $C$ a plane spanning caterpillar on $S$ with spine consisting of three vertices. Then, there is a slide sequence transforming $C$ to a star. 
\end{lemma}\label{Lem: triplestartostar}

\begin{proof}
    Let $v_1$, $v_2$ and $v_3$ be the three spine vertices of $C$, where $v_2$ is the central one. We will show that there exists a sequence of slides which shortens the spine to the vertices $v_2$ and $v_3$. Then, by Corollary \ref{Cor: stars}, $C$ will be connected to both $\starat(v_2)$ and $\starat(v_3)$. Consider the set $S_{1,2}$. If its convex hull contains no points connected to $v_3$, we are done. Otherwise, let $u$ be the first such point we encounter when rotating the edge $v_2v_3$ with $v_3$ fixed. If the triangle defined by $\{u,v_2,v_3\}$ contains no points connected to $v_1$, by Lemma \ref{Thm: starsanddoublestars}, we may slide $uv_3$ to $uv_2$. Otherwise, let $w$ be such a point. Since $u$ was chosen to be minimal, the triangle of $\{w,v_1,v_2\}$ contains no points connected to $v_3$, and thus by Lemma \ref{Thm: starsanddoublestars} we can slide $wv_1$ to $wv_2$, see Figure \ref{fig:3starsto2stars} for the visualization of the entire process. By repeating this process, we are left with no points connected to $v_3$ inside the convex hull of $S_{1,2}$ and thus can slide all leaves connected to $v_1$ into leaves connected to $v_2$, finishing the proof. $\qed$

\end{proof}

