    \centering
    \includegraphics[scale = 0.6]{figures/rotations.eps}
    \caption{Algorithm described in the proof of Proposition \ref{prop: rotations}, spine edges are dash-dotted in the picture. Each phase lasts until all of the red edges are rotated.}
    \label{Fig:prop1}
\end{figure}


\section{Connected Components in the Flip Graph of Plane Paths}\label{Sec: flips}

In this section, we shift our focus and consider the flip graph of plane spanning paths, particularly we study the sizes of connected components of this graph.  Recall that, for a point set $S$ in general position, we denote the set of all plane spanning paths by $\mathcal{P}(S)$ and the corresponding flip graph by $G_{\mathcal{P}}(S)$. We say that a plane spanning path $P=v_1,\dots, v_n$ is a \emph{generalized peeling path} if $v_1$ is a vertex of the convex hull of $S$ and for $i>1$, the vertex $v_i$ is a vertex of the convex hull of $S_i = S\setminus \{v_1,\dots, v_{i-1}\}$ and it is visible from $v_{i-1}$ (so, no edge of the convex hull of $S_i$ blocks it). For an illustration, see Figure \ref{Fig: Generalizedpeels}. Obviously, this definition is dependent on the way we orient the path. For example, if we reverse the path on the left of Figure \ref{Fig: Generalizedpeels} it is not a generalized peeling path. It is not hard to see that for each point set $S$, there are at least $2^{n-1}$ generalized peeling paths. This is because at every step of constructing a generalized peeling path, we have at least two choices for the next vertex along the path (except at the last step). Therefore, to prove Theorem \ref{Thm: largecomponent} we only need to prove that generalized peeling paths lie in a single component of $G_\mathcal{P}(S)$. 


\begin{figure}[h]
    \centering
    \includegraphics[scale = 0.6]{figures/Generalizedpeelingpaths.eps}
    \caption{The path on the left is a generalized peeling path, the path on the right is not due to the edge $v_3v_4$ crossing into the convex hull of $\{v_4,\dots, v_9\}$.}
    \label{Fig: Generalizedpeels}
\end{figure}

As mentioned before, we move the proof of Theorem \ref{Thm: largecomponent} to the appendix. Instead, we will use the generalized peeling paths to estimate the number of well-separated caterpillars.

One can easily observe that any generalized peeling path on $k$ vertices is also a well-separated caterpillar on $k$ vertices when the orientation is reversed. Further, if $S$ is a point set on $n$ points and $S' \subseteq S$ is a subset of $k\le n$ points then it is easily seen that any generalized peeling path on $S'$ defines at least one well-separated caterpillar on $S$, again with spine having reverse orientation of the original path. Therefore, we get a lower bound on the number of well-separated caterpillars as follows. If $\text{GP}(k)$ is the number of generalized peeling paths on $k$ vertices and $\text{WS}(n)$ is the number of well-separated caterpillars on $n$ vertices, then

$$ \text{WS}(n) \ge \sum_{k=1}^n \binom{n}{k}\text{GP}(k)\ge  \sum_{k=1}^n \binom{n}{k}2^{k-1} = \frac{1}{2}(3^n-1).$$
Therefore, we have proven that $G_{\mathcal{C}}^{\text{slide}}(S)$ has a connected component of size at least $\frac{1}{2}(3^n-1)$.


 In order to prove Theorem \ref{thm: smallcomponents} we first need to collect some results regarding the flip graph of all plane spanning paths with a fixed endpoint $u\in S$, denoted by $G_{\mathcal{P}}^u(S)$. 

\begin{lemma} \label{Lem: girth}
    The graph $G_{\mathcal{P}}^u(S)$ has girth of at least six.
\end{lemma}

\begin{proof}
         In $G_{\mathcal{P}}^u(S)$ any flip that changes both endpoints of a path is forbidden. Thus, any allowed flip can be viewed as a suffix reversal of the path, changing a path of the form $u,v_2,\dots, v_n$ to $u,v_2,\dots,v_{k-1},v_n,v_{n-1},\dots, v_k$ for a choice of $v_k$ which keeps the resulting path plane. Therefore, $G_{\mathcal{P}}^u(S)$ can be considered as a subgraph of the corresponding suffix reversal graph (also known as the pancake graph), which is well known to have girth 6~\cite{GirthOfPancakeGraphs}. $\qed$
\end{proof}

\begin{lemma} \label{Lem: no isolated paths}
    The graph $G_{\mathcal{P}}^u(S)$ has no isolated vertices.
\end{lemma}

\begin{proof}
        Assume that $P=u,v_2,\dots, v_{n-1},v_n$ is isolated in $G_{\mathcal{P}}^u(S)$. This means that $v_n$ sees no vertex of $S$ other than $v_{n-1}$. However, the first vertex seen when rotating $v_nv_{n-1}$ towards $v_{n-2}$ is either on the interior of the triangle $v_n,v_{n-1},v_{n-2}$ or $v_{n-2}$, and is therefore always visible from $v_n$. $\qed$

\end{proof}

The following lemma characterizes vertices of degree one in $G_{\mathcal{P}}^u(S)$. The proof is technical and involved so we move it to the appendix. 
\begin{lemma}\label{Lem: Paths of degree one}
    If $P=u,v_2,\dots,v_n$ is a path of degree one in $G_{\mathcal{P}}^u(S)$, then $v_{n-1}$, $v_n$ and $v_{n-2}$ are consecutive vertices of the convex hull of $S$ and the interior of the triangle $v_{n-1},v_n,v_{n-2}$ is disjoint from $S$.
 \end{lemma}


 \begin{figure}[ht]
     \centering
     \includegraphics[scale =0.5]{figures/Pathsofdegreeone.eps}
     \caption{Path of degree one and effect of the single flip on it.}
     \label{Fig: paths of degree one}
 \end{figure}

We put everything together in the following proposition. 

\begin{proposition}\label{prop: smallcomps}
    Let $S$ be a set of points in general position and $u$ a vertex of $S$. Then $G_\mathcal{P}^{u}(S)$ does not have a connected component on at most $4$ vertices.
\end{proposition}

\begin{proof}
       By Lemma \ref{Lem: no isolated paths}, the graph $G_{\mathcal{P}}^u(S)$ has no isolated vertices. Further, if $P=u,\dots,p_{n-1},p_n$ and $Q= u,\dots, q_{n-1},q_n$ are two distinct paths of degree one in $G_{\mathcal{P}}^u(S)$ then they admit a single flip which transforms them to $P'=u,\dots,p_{n},p_{n-1}$ and $Q'=u,\dots,q_n,q_{n-1}$ respectively. And as $P\neq Q$, it follows that $P'\neq Q'$.   This forbids $K_{1,3},P_2$ and $P_3$ as connected components of $G_{P}^u(S)$, see Figure \ref{Fig: paths of degree one}. By Lemma \ref{Lem: girth}, cycles of length $3$ and $4$ are also forbidden. Therefore, the only remaining graph on $4$ vertices that may be a connected component is $P_4$. The proof of this fact is rather technical and moved to the appendix. $\qed$
\end{proof}

Finally, we prove Theorem \ref{thm: smallcomponents}. 

\begin{proof}[of Theorem \ref{thm: smallcomponents}]
    Assume that $G_{\mathcal{P}}(S)$ contains a connected component on $7$ vertices. Call these vertices $P_1,P_2,\dots P_7$. Consider $P_1$, a plane spanning path on $S$ with endpoints $u,v$. By Proposition \ref{prop: smallcomps}, we know that if we fix $u$, $P_1$ is still connected to $4$ vertices via flips in $G_{\mathcal{P}}^u(S)$. If any of these $4$ is not one of $P_2,P_3,\dots P_7$ we get a component of size at least $8$, contradicting our assumption. Therefore we may assume that those $4$ vertices are $P_2,P_3,P_4,P_5$, which all need to have $u$ as one of their endpoints. By a symmetric argument, we see that $4$ more of the vertices $P_2,P_3,\dots P_7$ need to have $v$ as one of their endpoints. Thus by the pigeonhole principle, we can assume that $P_1,P_2,P_3$ all have $u,v$ as endpoints.  But now we can apply the identical argument to $P_4$ which has endpoints $u,w$ where $w\neq v$. Therefore in the $7$ paths $P_1,P_2,\dots, P_7$ at least $3$ have $u,v$ as endpoints, at least $3$ have $u,w$ as endpoints and for each  $x\in \{u,v,w\}$ at least $4$ of the paths have $x$ as one the endpoints. This is clearly impossible so the result follows. $\qed$
\end{proof}

As a possible step towards resolving Conjecture \ref{conj: main}, it would be interesting to determine if similar observations about the structure of $G_{\mathcal{P}}(S)$ and $G_{\mathcal{P}}^u(S)$ can be used to show nonexistence of larger sized connected components in $G_{\mathcal{P}}(S)$.

