\section{Problem Formulation}\label{prelim}

\subsection{Zero-Sum Mean-Field Team Game}\label{subsec:zs-mftg}

The zero-sum mean-field team game models a discrete-time stochastic game between two large teams of agents~\cite{guan2022shaping}.  
% that operate over a \bhavs{finite} horizon~$T$. 
%
The Blue and Red teams consist of $N_1$ and $N_2$ \emph{identical} agents for each team, with the total number of agents $N \hspace{-0.02in}=\hspace{-0.02in} N_1 \hspace{-0.02in}+\hspace{-0.02in} N_2$. 
Let \( X^{N_1}_{i,t} \in \mathcal{X} \) and \( U^{N_1}_{i,t} \in \mathcal{U} \) represent the state and action of Blue agent \( i \in [N_1] \) at time \( t \).
% , where \( [N_1] = \{1, \dots, N_1\} \)
% \footnote{We use \( X^{N_1}_{i,t} \in \mathcal{X} \) as shorthand, acknowledging that \( X^{N_1}_{i,t} \) is a function. This does not affect the results.}. 
%
Here, \(\mathcal{X}\) and \(\mathcal{U}\) are the finite state and action spaces of the Blue team. 
%
Similarly, \( Y^{N_2}_{j,t} \in \mathcal{Y} \) and \( V^{N_2}_{j,t} \in \mathcal{V} \) denote the state and action of Red agent \( j \in [N_2] \). 
%
The joint state-action variables for the Blue and Red teams are denoted as \((\mathbf{X}^{N_1}_t, \mathbf{U}^{N_1}_t)\) and \((\mathbf{Y}^{N_2}_t, \mathbf{V}^{N_2}_t)\), respectively.
%
Here, we use uppercase letters to denote random variables (e.g., $X$, $\M$) and lowercase letters to denote their realizations (e.g., $x$, $\mu$). 
%
For a set $E$, we denote the space of probability measures over $E$ as $\P({E})$.


\begin{definition} 
    \label{def:empirical-dist}
    The \textit{empirical distributions} (ED) for the Blue and Red teams are defined as
    \vspace{-0.05in}
    \begin{subequations}\label{eqn:mean-field}
        \begin{align}
            \M^{N_1}_t(x) &= \frac{1}{N_1} \sum_{i=1}^{N_1} \mathds{1}_x(X^{N_1}_{i,t}), \quad x \in \X,\\
            \N^{N_2}_t(y) &= \frac{1}{N_2} \sum_{j=1}^{N_2} \mathds{1}_y(Y^{N_2}_{j,t}), \quad y \in \Y,
        \end{align}
    \end{subequations}
\end{definition}
\noindent
where $\indicator{a}{b} = 1$ if $a = b$ and $0$ otherwise. 
%
Specifically, $\M^{N_1}_t(x)$ gives the fraction of Blue agents at state~$x$ and similarly for $\N^{N_2}_t(y)$. 
%
We use $\M_t^{N_1} =\empMu{\bfX^{N_1}_t}$ and 
$\N_t^{N_2} =\empNu{\bfY^{N_2}_t}$
to denote the EDs computed from the given joint states.
%
Note that the $\mathrm{Emp}$ operators  remove agent index information, so one \textit{cannot} determine the state of a specific Blue agent~$i$ from $\M^{N_1}_t$.

We consider weakly-coupled dynamics where the dynamics of each individual agent is coupled with other agents through the EDs \cite{guan2024zero}. 
%
For Blue agent $i$, its stochastic transition is governed by the transition kernel 
$f_t : \X \times \U \times \P(\X) \times \P(\Y) \rightarrow \P(\X)$ so that
\begin{align}
\label{ft:DEF}
    \mathbb{P}(X_{i,t+1}^{N_1}=x_{i,t+1}^{N_1} &| U_{i,t}^{N_1} = u_{i,t}^{N_1}, \bfX_{t}^{N_1} = \bfx_{t}^{N_1}, \bfY_{t}^{N_2}= \bfy_{t}^{N_2}) \nonumber \\
    &= f_t(x_{i,t+1}^{N_1}\vert x_{i,t}^{N_1}, u_{i,t}^{N_1}, \mu^{N_1}_t, \nu^{N_2}_t),   
\end{align}
where $\mu^{N_1}_t = \empMu{\bfx_t^{N_1}}$ and $\nu^{N_2}_t = \empNu{\bfy_t^{N_2}}$. Similarly, the dynamics of Red agent $j$ is governed by the transition kernel $g_t :   \Y \times \V \times \P(\X) \times \P(\Y) \rightarrow \P(\Y)$.
%
All agents in the Blue team receive an identical weakly-coupled team reward, i.e., $r_t \triangleq r_t(\mu_t, \nu_t): \P(\X) \times \P(\Y) \to \mathbb{R}$. 
%
Following the zero-sum structure, the Red team agents receive $-r_t(\mu_t, \nu_t)$ as their rewards. 
%
We assume that the Blue (Red) team is the maximizing (minimizing) team.

