\subsection{Large-Population Optimization}

We consider a mean-field sharing information structure \cite{arabneydi2015team},
% At each time step $t$, Blue agent $i$ observes its own state $X_{i,t}^{N_1}$ and the EDs $\M_t^{N_1}$ and $\N_t^{N_2}$; 
% similarly, Red agent $j$ observes $Y_{j,t}^{N_2}$, $\M_t^{N_1}$ and $\N_t^{N_2}$. 
%
where each agent observes its own state and the two team EDs, where the EDs serve as common information accessible to both teams. 
Specifically, the Blue and Red agents seek to construct mixed Markov policies with the following structure
\vspace{-0.02in}
\begin{subequations}
    \label{eqn:IS}
    \begin{align}
        \phi_{i,t}&: \U \times \X \times \P(\X) \times \P(\Y) \to [0,1],\\
        \psi_{j,t}&: \V \times \Y \times \P(\X) \times \P(\Y) \to [0,1],
    \end{align}
\end{subequations}
where the Blue policy $\phi_{i,t}(u|x_{i,t}^{N_1}, \mu^{N_1}_t, \nu^{N_2}_t)$ dictates the probability that Blue agent $i$ selects action $u$ given its state $x_{i,t}^{N_1}$ and the observed  team EDs $\mu^{N_1}_t$ and $\nu^{N_2}_t$. 
%
% The idea extends naturally to the Red policy $\psi_{i,t}(v|y_{i,t}^{N_1}, \mu^{N_1}_t, \nu^{N_2}_t)$.
Note that each agent's individual state is its private information, while the team EDs are the common information available to all $N$ agents.

Let $\Phi_t$ ($\Psi_t$) denote the set of individual Blue (Red) policies at time~$t$.
%
We define the Blue team policy $\phi^{N_1}_t \!=\! \{\phi_{i, t}\}_{i=1}^{N_1}$ as the collection of the $N_1$ Blue agent individual policies, and denote the set of Blue team policies as $\Phi^{N_1}_t \!=\! \times_{N_1} \Phi_t$.
%
Similarly, the Red team policy is denoted as $\psi_t^{N_2} \in \Psi_t^{N_2}\!=\!\times_{N_2} \Psi_t$.


\begin{definition} [Identical team policy]
    \label{def:identical-policy}
    The Blue team policy $\phi^{N_1}_t = (\phi^{N_1}_{1,t}, \ldots, \phi^{N_1}_{N_1,t})$ is an \textit{identical}, if $\phi_{i_1,t} = \phi_{i_2,t}$ for all time $t$ and $i_1,i_2 \in [N_1]$. 
    We denote the set of identical Blue team policies as $\Phi$.
\end{definition}
The definition and notation extend naturally to the Red team, and the set of identical Red team policies is denoted as $\Psi$.

% In summary, an instance of a finite-population zero-sum mean-field team game is defined as the tuple
% $ZS-MFTG=\langle \X, \Y, \U, \V, f_t, g_t, r_t, N_1, N_2, T \rangle$.


The performance of the team policy pair $(\phi^{N_1}, \psi^{N_2})$ is given by the expected cumulative reward 
\begin{align*}
    & J^{N, \phi^{N_1}, \psi^{N_2}} \big(\bfx_0^{N_1}, \bfy_0^{N_2} \big)=
    \mathbb{E}_{{\phi^{N_1}, \psi^{N_2}}}
    \Big[\sum_{t=0}^{T} r_t(\M^{N_1}_t, \N^{N_2}_t) \Big \vert \bfx_0^{N_1}, \bfy^{N_2}_0\! \Big].
\end{align*}
%where $\M_t^{N_1} = \empMu{\bfX^{N_1}_t}$ and $\N_t^{N_2} = \empNu{\bfY^{N_2}_t}$.
% and the expectation is with respect to the distribution of all system variables induced by $\phi^{N_1}$ and $\psi^{N_2}$. 
When the Blue team considers its worst-case performance, we have the following max-min optimization:
\begin{equation}\label{eq:blue-max-min}
    \hspace{-0.01in}
    \underline{J}^{N*}(\bfx_0^{N_1} , \bfy_0^{N_2})  = \max_{\mathbf{\phi}^{N_1} \in \Phi^{N_1}} \min_{\mathbf{\psi}^{N_2} \in \Psi^{N_2}} J^{N, \phi^{N_1}, \psi^{N_2}}\hspace{-0.02in}(\bfx_0^{N_1}\hspace{-0.05in}, \bfy_0^{N_2}), \hspace{-0.1in}
\end{equation}
where $\underline{J}^{N*}$ is the lower game value for the finite-population game. Similarly, the minimizing Red team considers a min-max optimization problem, which leads to the upper game value.
%
Note that we allow both teams to follow \textit{non-identical} team policies in~\eqref{eq:blue-max-min}.

\subsection{Infinite-Population Solution}

To reduce the complexity of team policy optimization domains in~\eqref{eq:blue-max-min}, the authors of \cite{guan2024zero} proposed to examine team behaviors under \textit{identical team policies} at the \textit{infinite-population} limit. 
%
It was shown that the team joint states can be represented using the team population distribution, which 
coincides with the state distribution of a \textit{typical agent}.
%
Such distributions are referred to as the mean-fields (MFs), and we denoted them as $\mu_t$ and $\nu_t$ for the Blue and Red teams, respectively. 
%
As proved in~\cite{guan2024zero}, MFs induced by identical team policies in an infinite-population game closely approximate the \ED{}s induced by \emph{non-identical} team policies in the corresponding finite-population game, which justifies the simplification of the optimization domain in~\eqref{eq:blue-max-min} to identical team policies.
%

For the infinite-population game, the performance of the \textit{identical} team policies $(\phi, \psi) \in \Phi \times \Psi$ is measured by 
\begin{equation}
\label{eqn:mf-performance}
    J^{\phi, \psi}(\mu_0, \nu_0) = \sum_{t=0}^{T} r_t(\mu_t, \nu_t),
\end{equation}
where $\mu_t$ and $\nu_t$ follow a \textit{deterministic} dynamics~\cite{guan2024zero} similar to the state distribution propagation of a controlled Markov chain.
%
The worst-case performance of the Blue team in this infinite-population game is then given by the lower game value
\begin{equation}\label{eqn:mf-optimization-lower}
    \underline{J}^{*} (\mu_0, \nu_0) = \max_{\phi\in \Phi} \; \min_{\psi \in \Psi} ~ J^{\phi, \psi}(\mu_0, \nu_0),
\end{equation}  
where the optimization domain is restricted to identical team policies.
%
Reference~\cite{guan2024zero} exploited the simplified optimization domain in~\eqref{eqn:mf-optimization-lower} and proposed to transform the optimization to an equivalent zero-sum game between two fictitious coordinators.
%
The optimal identical team policies can then be solved via dynamic programming.
%
The following performance guarantees was established in~\cite{guan2024zero}.
%

%where non-identical policies are allowed to exploit the obtained identical policy. 

\begin{theorem}
    \label{thm:performance-guarantees}
    The optimal identical Blue team policy $\phi^*$ obtained from the equivalent zero-sum coordinator game is an $\epsilon$-optimal Blue team policy. 
    Formally, for all joint states $\bfx^{N_1}$ and $\bfy^{N_2}$,
    \begin{align}
        \label{eqn:performance-bounds}
        \min_{\psi^{N_2} \in \Psi^{N_2}} 
        J^{N,\phi^*,\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \geq \underline{J}^{N*}(\bfx^{N_1}, \bfy^{N_2})-\Residue
    \end{align}
    where $\underline{N} = \min \{N_1, N_2\}$.
\end{theorem}

This result ensures that identical team policies resulting from the solution of the equivalent zero-sum coordinator game are still $\epsilon$-optimal for the original max-min optimization problem in~\eqref{eq:blue-max-min}.
%
From Theorem~\ref{thm:performance-guarantees} we can further show that the performance of the optimal identical policy learned from the finite population ZS-MFTG remains within an $\epsilon$-bound of the identical policies derived from the optimal coordinator game.

\begin{restatable}{theorem}{maintheorem}\label{thm:finite-population-training}
 The value of the optimal identical Blue team policy $\phi^*_{\mathrm{finite}}$ obtained from the finite population game is within  $\epsilon$ of the value of the optimal identical Blue team policy $\phi^*$ obtained from the equivalent zero-sum coordinator game. Formally, for all joint states $\bfx^{N_1}$ and $\bfy^{N_2}$,
    \begin{align}
        \label{eqn:finite-training-bound}
        \min_{\psi^{N_2}} 
       J^{N,\phi^*_{\mathrm{finite}},\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) -  \min_{\psi^{N_2}} J^{N,\phi^*,\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \leq \epsilon,
    \end{align}
    where $\epsilon = \mathcal{O}({1}/{\sqrt{\subN}})$ and $\underline{N} = \min \{N_1, N_2\}$.
\end{restatable}

% \begin{definition}  \label{def:nash-trajectory}
% A mean-field trajectory \((\{\mu_t\}, \{\nu_t\})\), initialized at \((\mu_0, \nu_0)\) and governed by \textit{deterministic} dynamics \cite{guan2024zero} under identical team policies \(\phi^* \in \Phi\) and \(\psi^* \in \Psi\), is a \textit{Nash Trajectory} if there exist \(\phi^*\) and \(\psi^*\) that constitute a Nash Equilibrium for \eqref{eqn:mf-performance}.
