\subsection{Minimally-Informed Critic}

The MF-MAPPO critic network of the Blue team evaluates the value function $V_\text{Blue}(\mu, \nu)$, which depends only on the common information, and is
\textit{independent} of the joint agent states and actions. 
%
We use the parameter vector $\zeta_\text{Blue}$ to parameterize the critic network while minimizing the MSE loss
\begin{equation}
\label{eq:critic network}
    L_{\text{critic}}(\zeta_\text{Blue}) = \frac{1}{|B|}\sum_{k=1}^{|B|}\Bigl(V_\text{Blue}(\mu_k, \nu_k| \zeta_\text{Blue}) - \hat{R}_{\text{Blue}, k}\Bigr)^2,
\end{equation}
where the optimization is performed over a mini-batch of size $B$ and $\hat{R}_{\text{Blue}, k}$ is the discounted reward-to-go for sample $k$. 
%
The reward-to-go for sample $k$ obtained at a time step $t$ is computed using Monte-Carlo roll-outs starting at $t$ until the episode ends, and is given by
$\hat{R}_{\text{Blue}, k} = \sum_{t' = t}^{T}\gamma^{t' - t}r_t(\mu_t, \nu_t)$~\cite{tamar2016learning}.
Similar learning rules apply to the Red team critic $V_\text{Red}(\mu, \nu| \zeta_\text{Red})$ with the negative reward $\hat{R}_{\text{Red}, k} = -\hat{R}_{\text{Blue}, k}$ due to the zero-sum structure.
%

The following proposition follows immediately from the expression of the team reward~\eqref{eqn:mf-performance} and the use of identical team policies, and justifies the deployment of a minimally-informed critic network with only the mean-fields as inputs.

\begin{proposition}\label{thm:minimal-critic}
Let 
%$\bfx^{N_1}_t$, $\bfy^{N_2}_t$, 
$\mu^{N_1}_t$, and 
$\nu^{N_2}_t$ denote the 
%joint agent states and the corresponding 
EDs of a finite-population game obtained from identical Blue and Red team policies $\phi_t \in \Phi_t$ and $\psi_t \in \Psi_t$, respectively.
The team reward structure admits a critic that depends only on $\mu^{N_1}_t$ and $\nu^{N_2}_t$.
% , removing the need for local agent-specific information.
%
 Specifically, for each Blue team agent $i \in \{1, 2, \ldots, N_1\}$, the individual critic value function $V_{i, t}^{N_1, \phi_{t}}(x_{i, t}, \mu^{N_1}_t, \nu^{N_2}_t)$ satisfies
    \begin{align}
       V_{i, t}^{N_1, \phi_{t}}(x_{i, t}, \mu^{N_1}_t, \nu^{N_2}_t) = V^{N_1, \phi_t}_{{\rm Blue}, t}(\mu^{N_1}_t, \nu^{N_2}_t), 
    \end{align}
where $V^{N_1, \phi_t}_{{\rm Blue}, t}(\mu_t, \nu_t)$ is the team-level critic.
%
\end{proposition}


The above proposition extends to the Red team critic network. 
%
Importantly, it reduces the learning problem to one critic network per team.
%
Specifically, the shared team reward structure along with the assumption of homogeneous agents in each team enables us to evaluate the performance of a team's agent using the minimally-informed critic---even if the individual agent has additional local observations such as their actions and private states. 
%

\subsection{Shared-Team Actor}

We consider a single-actor network for each team to learn the identical team policies. 
%
According to \cite{guan2024zero}, identical policies derived from an equivalent coordinator game 
can approximate team behaviors induced by non-identical ones.
%
{A single coordinator policy corresponds to the probability distribution over actions for each state, conditioned on a given mean-field. 
%
As a result, its dimensionality scales with the joint state-action space, leading to substantial computational overhead and degraded empirical performance of the policy network. 
%
Notably, DDPG-MFTG adopts this formulation, but, as demonstrated later in the numerical examples section, its performance is suboptimal.


Furthermore, while the coordinator game serves as a valuable theoretical construct, we found it more practical and computationally efficient to learn finite-population local identical policies in place of coordinator policies. 
%
These policies continue to respect the underlying mean-field information-sharing structure, while significantly reducing complexity and improving tractability in practice.}
%
Theorem~\ref{thm:finite-population-training} ensures performance guarantees.
% 

The actor network maximizes a PPO-based objective with an entropy term to encourage exploration~\cite{schulman2017proximal, shengyi2022the37implementation}, which decays during training as teams learn reward-maximizing policies. 
It has also been shown in the mean-field game literature that entropy regularization stabilizes the learning process~\cite{cui2021approximately, guan2022shaping}.
% A key point to note is that although the coordinator game plays an instrumental role in the theoretical analysis, we found it more practical and tractable to learn finite population local policies instead of coordinator policies, while respecting the mean-field information-sharing structure. 
%
 % The one-to-one correspondence between the learned team policies and the coordinator policies \cite{guan2024zero} ensures consistency in this approach.
%
Since the agents are permutation invariant and an identical policy is being learned for each team, a single buffer per team suffices for storing observations and actions, {thereby reducing memory overhead and simplifying the experience collection pipeline.}

The PPO-based objective function of the Blue actor is given by:
\begin{align}     \label{eq:actor network}
    L(\theta_{\text{Blue}}) =  \frac{1}{|B|} & \sum_{k=1}^{|B|} \Big[\text{min}\Bigl(g_k(\theta_{\text{Blue}})A_k, \operatorname{clip}_{[1-\epsilon, 1+\epsilon]}(g_k(\theta_{\text{Blue}}) )A_k\Bigr) \nonumber \\
    & \qquad \qquad\qquad \qquad + \omega S(\phi_{\theta_{\text{Blue}}}(x_k, \mu_k, \nu_k))\Big], 
 \end{align}   
where,
\begin{align*}
    g(\theta) = \frac{\phi_{\theta}(u|x, \mu, \nu)}{\phi_{\theta^{\text{old}}}(u|x, \mu, \nu)},
\end{align*}
and $A_k$ is the generalized advantage function estimate function \cite{schulman2015high}. 
%
The tunable parameter $\omega$  weighs the contribution of the entropy term, which is given by
\begin{align*}
    S \big( \phi_{\theta}(x, \mu, \nu)\big)  = - \mathbb{E}_{u \sim \U} \Biggl[ \sum_{u} \phi_\theta(u|x, \mu, \nu) \log \phi_\theta(u|x, \mu, \nu) \Biggr].
\end{align*}
We decay $\omega$ as training progresses. 
%
A similar learning rule is used for the Red team actor network. 
%
Algorithm~1 presents the pseudo-code of the MF-MAPPO algorithm. 


\begin{algorithm}
\caption{Mean-Field Multi-Agent Proximal Policy Optimization (\textbf{MF-MAPPO})}\label{alg:cap}
\begin{algorithmic}
    \State \textbf{Initialize:} NN parameters $\{\theta_{\text{Blue}}, \zeta_{\text{Blue}}\}$ and $\{\theta_{\text{Red}}, \zeta_{\text{Red}}\}$; step size sequences $\{\alpha_m\}$ and $\{\beta_m\}$; entropy decay sequence $\{\omega_m\}$

    \For{$i = 1,2,\ldots  $} 
    \State $(\phi_{\theta_{\text{Blue}}^{\text{old}}}, \psi_{\theta_{\text{Red}}^{\text{old}}}) \leftarrow (\phi_{\theta_{\text{Blue}}}, \psi_{\theta_{\text{Red}}})$
        \For{$t = 0, 1, \ldots, T_{\text{rollout}}$} 
            \State Sample joint actions
            \State $u_{i,t} \sim \phi_{\theta_{\text{Blue}}^{\text{old}}}(x_{i,t}, \mu_t^{N_1}, \nu_t^{N_2})$,
            $v_{j,t} \sim \psi_{\theta_{\text{Red}}^{\text{old}}}(y_{j,t}, \mu_t^{N_1}, \nu_t^{N_2})$
            \State Step environment according to kernels $(f_t, g_t)$
            \State Collect samples $(\bfx_{t+1}^{N_1}, \bfy_{t+1}^{N_2}, \mu^{N_1}_{t+1}, \nu^{N_2}_{t+1}, \bfu_t^{N_1}, \bfv_t^{N_2}, r_t)$
        \EndFor

        \For{$K$ epochs} 
            \State Update $\{\theta_{\text{Blue}}, \zeta_{\text{Blue}}\}$ and $\{\theta_{\text{Red}}, \zeta_{\text{Red}}\}$ using (\ref{eq:critic network}-\ref{eq:actor network})
            % , $\alpha_i, \beta_i, \omega_i$
        \EndFor
    \EndFor  
    \State \textbf{Return: $(\phi_{\theta_{\text{Blue}}}, \psi_{\theta_{\text{Red}}})$}
\end{algorithmic}
\end{algorithm}

\subsection{Scalability of MF-MAPPO}

We further demonstrate the scalability of MF-MAPPO as a direct consequence of Theorem~\ref{thm:performance-guarantees}, by showing that, under certain conditions, the learned team policies generalize to varying population sizes $(\tilde{N}_1,\tilde{N}_2)$ while maintaining performance guarantees.

\begin{remark}    \label{thm:extend-to-many}
