\begin{restatable}{proposition}{mainproposition}
    \label{prop:two-step-convergence}
    With initial conditions ${\mu}_{t=0} = [1, 0, 0]\t$ and ${\nu}_{t=0} = [0, 1, 0]\t$, all mean-field optimal trajectories satisfy
    ${\mu}_t^* = {\nu}_t^* = [\frac{1}{3}, \frac{1}{3}, \frac{1}{3}]\t$ for all $t\geq2$, and ${\mu}^*_{1} = [0, 1-\eta, \eta]\t$ where $\eta \in [\frac{1}{3}, 
    \frac{2}{3}]$ and ${\nu}^*_{1} = [0, \frac{2}{3}, \frac{1}{3}]\t$.
    Furthermore,
    the unique game value is given by~$-\frac{1}{3}$.
\end{restatable} 

