\subsection{Proof of Theorem~\ref{thm:finite-population-training}}\label{proof-thm-1}
\maintheorem*
We have the following definition of the lower game value for the 
finite-population ZS-MFTG:
\begin{equation}\label{eq:max-min-general-case}
    \underline{J}^{N*}(\bfx^{N_1} , \bfy^{N_2})  = \max_{\mathbf{\phi}^{N_1} \in \Phi^{N_1}} \min_{\mathbf{\psi}^{N_2} \in \Psi^{N_2}} J^{N, \phi^{N_1}, \psi^{N_2}}(\bfx^{N_1}, \bfy^{N_2}).
\end{equation}
%
Note that the maximization for the Blue team is being performed over the set of all team policies $\Phi^{N_1}$, including identical as well non-identical team policies. 
%
If we restrict ourselves to the set of identical team policies $\Phi \subseteq \Phi^{N_1}$ it follows immediately that
\begin{align}
%    \max_{\mathbf{\phi}^{N_1} \in \Phi^{N_1}} &\min_{\mathbf{\psi}^{N_2} \in \Psi^{N_2}} J^{N, \phi^{N_1}, \psi^{N_2}}(\bfx^{N_1}, \bfy^{N_2}) \nonumber\\&\
\underline{J}^{N*}(\bfx^{N_1} , \bfy^{N_2})
\geq \max_{\mathbf{\phi}^{N_1} \in \Phi} \min_{\mathbf{\psi}^{N_2} \in \Psi^{N_2}} J^{N, \phi^{N_1}, \psi^{N_2}}(\bfx^{N_1}, \bfy^{N_2}).
\end{align}
%
Suppose that  $\phi^*_{\mathrm{finite}}$ is the optimal identical Blue team policy obtained from the finite population game. 
%
It follows from \eqref{eq:max-min-general-case} that
\begin{equation}\label{eq:true-finite-id}
   \underline{J}^{N*}(\bfx^{N_1} , \bfy^{N_2})   \geq \min_{\psi^{N_2} \in \Psi^{N_2}} 
       J^{N,\phi^*_{\mathrm{finite}},\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}).
\end{equation}
%
Furthermore,  let $\phi^* \in \Phi$ be the optimal identical Blue team policy obtained from the equivalent zero-sum (infinite-population) coordinator game and
\begin{align}\label{eq:finite-infinite-relation}
    \min_{\mathbf{\psi}^{N_2} \in \Psi^{N_2}} J^{N,\phi^*_{\mathrm{finite}},\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \geq \min_{\psi^{N_2} \in \Psi^{N_2}} 
       J^{N,\phi^*,\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}).
\end{align}
%
Using Theorem~\ref{thm:performance-guarantees},
and using \eqref{eq:finite-infinite-relation}, yields
\begin{align*}
    \underline{J}^{N*}(\bfx^{N_1} , \bfy^{N_2})   &\geq \min_{\psi^{N_2} \in \Psi^{N_2}} 
       J^{N,\phi^*_{\mathrm{finite}},\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \nonumber\\
       &\geq \min_{\psi^{N_2} \in \Psi^{N_2}} 
       J^{N,\phi^*,\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \nonumber\\
       &\geq \underline{J}^{N*}(\bfx^{N_1}, \bfy^{N_2})-\Residue,
\end{align*}
%
where $\underline{N} = \min \{N_1, N_2\}$. 
Upon rearranging terms, we finally have,
\begin{align}
        \min_{\psi^{N_2} \in \Psi^{N_2}} 
       J^{N,\phi^*_{\mathrm{finite}},\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) - \min_{\psi^{N_2} \in \Psi^{N_2}} J^{N,\phi^*,\psi^{N_2}} (\bfx^{N_1}, \bfy^{N_2}) \leq \epsilon \nonumber,
    \end{align}
    where $\epsilon = \mathcal{O}({1}/{\sqrt{\subN}})$ .



