\section{RPS and \texorpdfstring{\lowercase{c}}{c}RPS Setup}\label{AppendixB}


\subsection{State Space}
We have three states in this representation of the game: rock, paper and scissors. 
%
We denote this state space as $\mathcal{S} =  \{\texttt{R,P,S}\}$. 
%
The empirical distribution of the Blue team is denoted by ${\mu} \in \mathcal{P(S)}$ and that of the Red team is denoted by ${\nu} \in \mathcal{P(S)}$. 
%
Since we have three states for each team, both EDs lie in a three-dimensional simplex denoted by $\mathcal{P(S)}$.

\subsection{Action Space}
\subsubsection{RPS}
At each state, we define three actions denoted by $\mathcal{A} = \{\texttt{CW}, \texttt{CCW}, \texttt{Stay}\}$. 
%
These actions represent the ability of the agents to move from one state to the other in the following fashion:
%
\begin{enumerate}
    \item \texttt{CW} denotes a clockwise cyclic action from one state to the other, i.e., from $\texttt{R} \rightarrow \texttt{P}$, $\texttt{P} \rightarrow \texttt{S}$, $\texttt{S} \rightarrow \texttt{R}$.
    \item \texttt{CCW} denotes a counterclockwise cyclic movement, i.e., from $\texttt{R} \rightarrow \texttt{S}$, $\texttt{S} \rightarrow \texttt{P}$, $\texttt{P} \rightarrow \texttt{R}$.
    \item $\texttt{Stay}$ denotes the idle action (remain in the same state as before).
\end{enumerate}

\subsubsection{cRPS}
At each state we have two actions denoted by $\mathcal{A} = \{\texttt{CW},  \texttt{Stay}\}$. 
%
These actions represent the ability of the agents to move from one state to the other in the following fashion:
\begin{enumerate}
    \item \texttt{CW} denotes a clockwise cyclic action from one state to the other, i.e., from $\texttt{R} \rightarrow \texttt{P}$, $\texttt{P} \rightarrow \texttt{S}$, $\texttt{S} \rightarrow \texttt{R}$.
    \item $\texttt{Stay}$ denotes the idle action (remain in the same state as before).
\end{enumerate}
Thus, we cannot directly jump from \texttt{R}  to \texttt{S} within a single step, but must go via \texttt{P}. 
%
Mathematically,  \texttt{S} does not lie in the reachable set of \texttt{R}. 
%
The reachable set $\mathcal{R}(s)$ for each state $s$ at a given time step under this modified action space is as follows
\begin{align*}
    \mathcal{R}(\texttt{R}) = \{\texttt{R}, \texttt{P}\}, \quad
    \mathcal{R}(\texttt{P}) = \{\texttt{P}, \texttt{S}\}, \quad
    \mathcal{R}(\texttt{S}) = \{\texttt{S}, \texttt{R}\}. 
\end{align*}


\subsection{Dynamics and Transition Probabilities}

For both RPS and cRPS, we consider deterministic transitions $\mathcal{T}(s, a, s')$, which implies that given a state-action pair $(s, a)$, the agent reaches a unique next state $s'$ with certainty (no distribution over the reachable states). 
%
Thus, for state $\texttt{R}$ and action $\texttt{Stay}$, the transition function $\mathcal{T}:\mathcal{S}\times\mathcal{A}\times \mathcal{S}\rightarrow \{0, 1\}$ is given as: 
\begin{align*}
    \mathcal{T}(\texttt{R}, \texttt{Stay}, \texttt{R}) = 1,\quad
    \mathcal{T}(\texttt{R}, \texttt{Stay}, \texttt{P}) = 0,\quad
    \mathcal{T}(\texttt{R}, \texttt{Stay}, \texttt{S}) = 0.
\end{align*}
This implies that an agent in the state \texttt{R}  upon taking the \texttt{Stay}  action remains in state \texttt{R}. 
Similarly, 
\begin{align*}
    \mathcal{T}(\texttt{R}, \texttt{CW}, \texttt{R}) = 0,\quad
    \mathcal{T}(\texttt{R}, \texttt{CW}, \texttt{P}) = 1,\quad
    \mathcal{T}(\texttt{R}, \texttt{CW}, \texttt{S}) = 0.
\end{align*}
represent the method to transition from \texttt{R}  to \texttt{P} .


\subsection{Reward Structure}

In a two player RPS game, the reward matrix for Player 1 is defined as:
\begin{align*}
    A = \begin{bmatrix}
        \begin{array}{rrr}
         0 & -1 &  1 \\
         1 &  0 & -1 \\
        -1 &  1 &  0
        \end{array}
    \end{bmatrix}.
\end{align*}
We extend this two-player framework to the multi-agent team game formulation. 
%
Define the pairwise reward for an agent at state $x\in \mathcal{S}$ within the Blue team and at state $y \in \mathcal{S}$ from the Red team as 
\begin{equation*}
    r(x, y) \triangleq A_{xy},
\end{equation*}
where $A_{xy}$ represents the element from the reward matrix $A$ corresponding to the states $x$ (row player) and $y$ (column player). 
%
In lieu of the zero-sum structure, the reward for the agent at $y$ with respect to $x$ becomes $-r(x, y)$. 
%
%\pt{is the index $i$ a superscript or a subscript? You seem to be mixing them. Same for index $j$. Please check and fix}
Thus, for each player $x_i \in \mathcal{S} \text{ and } i=1, 2,\ldots, N_1$ in the Blue team and $y_j  \in \mathcal{S}  \text{ and } j=1, 2,\ldots, N_2$ in the Red team, the reward for the Blue team can be defined as
\begin{equation*}
R_\mathrm{Blue}(\mathbf{x}, \mathbf{y}) = \frac{1}{N_1} \sum_{i=1}^{N_1} \underbrace{\Big[\frac{1}{N_2} \sum_{j=1}^{N_2} r(x_i, y_j) \Big]}_{\text{reward for agent $i$}}.
\end{equation*}

Rewriting the term inside the square brackets as 
\begin{align}\label{eq:reward-simplification-rps}
    \frac{1}{N_2}\sum_{j=1}^{N_2} r(x_i, y_j) &=\frac{1}{N_2}\sum_{y\in \mathcal{S}} \sum_{j=1}^{N_2} r(x_i, y) \mathbf{1}_{y_j=y}\nonumber \\
    &= A_{x_is_0}\sum_{j=1}^{N_2}\frac{1}{N_2}\mathbf{1}_{y_j=s_0} + A_{x_is_1}\sum_{j=1}^{N_2}\frac{1}{N_2}\mathbf{1}_{y_j=s_1} \nonumber\\ &+ A_{x_is_2}\sum_{j=1}^{N_2}\frac{1}{N_2}\mathbf{1}_{y_j=s_2}\nonumber\\
    &= A_{x_is_0}{\nu}(s_0)+A_{x_is_1}{\nu}(s_1)+A_{x_is_2}{\nu}(s_2)\nonumber\\
    &= A(x_i){\nu},
\end{align}
where $A(x_i)$ is the row of the reward matrix corresponding to state $x_i$. 
%
Using \eqref{eq:reward-simplification-rps}, the total Blue reward can be expressed as 
\begin{align*}
    R_\mathrm{Blue}(\mathbf{x}, \mathbf{y}) &= \frac{1}{N_1} \sum_{i=1}^{N_1}  A(x_i){\nu}\\
    &= \Bigl( \frac{1}{N_1}\sum_{x\in \mathcal{S}} \sum_{i=1}^{N_1} A(x_i) \mathbf{1}_{x_i=x} \Bigr){\nu}\\
    &= \Bigl(A(s_0){\mu}(s_0)+A(s_1){\mu}(s_1)+A(s_2){\mu}(s_2)\Bigr){\nu}\\
    &= {\mu}\t A{\nu}.
\end{align*}

\subsection{Implementation Details and Hyperparameters}

The state distributions are represented as arrays that are concatenated together to form the global observation. 
%
This becomes the input to the critic network which consists of a single hidden layer of 64 neurons and two \textsf{tanh} activation functions. 
%
The output is a single value that is equal to the estimated value function.
%
% On the other hand, the actor-network (Figure~\ref{fig:actor-network-1d}) consists of a single MLP layer of 64 neurons that is concatenated with the local agent observation. 
