\section{Methodology}

%We propose a dNL based RRL agent which we believe is the first instance, as far as we are aware, of applying ILP agents in dynamic continuous RL environments. 
%The dNL architecture used for the agent is derived from the dNL-NL architecture (see Appendix D) with the key difference being a dynamic batch size input, as various RL algorithms rely on experience relays for training the agent \cite{DQN}.
%input matrix(predicate action policy, discrete action predicate function
%(Boolean predicates mapped to discrete features)
%(Boolean predicates mapped to continuous feature ranges)
Developing a neuro-symbolic RL agent that incorporates continuous predicate functions posed several non-trivial challenges. Firstly, the work of Payani et al. \cite{payanidNL, payani2020incorporating}, which our model extends, did not explore non-linear predicate functions, so we had to develop new functions to capture more complex relationships in the data (see equation \ref{trnpred}). Additionally, while Payani et al. did introduce continuous predicates in a supervised setting, they only tested dNL-ILP on two datasets (Wine and Sonar datasets \cite{payanidNL, Dua:2019}), whereas we made the integration of continuous predicates a focus of our work. \footnote{Moreover, from an engineering standpoint, the dNL code was originally written in TensorFlow 1, which had to be converted to TensorFlow 2 for use in the RL environment.} {Another challenge was the fact that the original dNL-RRL model explicitly dealt with discrete predicates, so we had to adapt the model to incorporate continuous predicates.} Finally, while Payani et al. used the REINFORCE RL algorithm \cite{reinforceSutton}, we had to test out various other RL algorithms, including SAC \cite{SAC}, to find the most effective implementation for our model.\footnote{Extensive coding was required to convert the SAC algorithm, which typically has a discrete action space, to TensorFlow 2, as all available examples online were coded in PyTorch.}




In the dNL-RL interpretation, the Boolean target predicate function $\mathcal{F}_p$ is referred to as a \textit{discrete action predicate function}. The actions of the agent are the target predicates and so must remain discrete. For example, an agent that can take an action $turnLeft()$, has the corresponding \textit{discrete action predicate function} $\mathcal{F}_{turnLeft}$. Each \textit{discrete action predicate function} is defined by an input matrix $\mathbf{I}$, which is composed of continuous lower and upper bound predicate functions as well as discrete Boolean predicate functions, all with associated weights. The set of the continuous state features $cnt_p$ and the set of the discrete state features $dsc_p$ for the associated RL environment are given Boolean interpretations after being passed through the input matrix, as seen in equation \ref{inputmatrix}.{ The row dimensions of $\mathbf{I}$ are defined by the batch size $\mathbf{b}$ and the column dimensions are defined by $N_e = (2\times k \times |cnt_p|) + (2 \times |dsc_p|)$ (assuming discrete features are Boolean)}. { The state feature ranges used to define the Boolean predicate functions} are determined by equal-width binning, and we define the batch size as $\mathbf{b}$. The $\mathcal{F}_{{e}}$ function takes in a one-hot encoded Boolean discrete input.


\begin{equation}\label{inputmatrix}
\mathbf{I} = \begin{bmatrix}
\mathcal{F}_{gt^1_{e_1}},\mathcal{F}_{lt^1_{e_1}}  & \cdots & \mathcal{F}_{gt^k_{e_1}},\mathcal{F}_{lt^k_{e_1}}  & \cdots & \mathcal{F}_{gt^k_{e_{|cnt_p|}}},\mathcal{F}_{lt^k_{e_{|cnt_p|}}}\\

\vdots& \vdots & \vdots & \vdots & \vdots
\end{bmatrix} \bigoplus
\begin{bmatrix}
\mathcal{F}_{{e_1}},\mathcal{F}_{\overline{e_1}} & \cdots & \mathcal{F}_{{e_{|dsc_p|}}},\mathcal{F}_{\overline{e_{|dsc_p|}}} \\
\vdots & \vdots & \vdots \

\end{bmatrix}
\end{equation}

In defining the \textit{discrete action predicate function} $\mathcal{F}_p$ for an action $p$, the function takes as input the input matrix $\mathbf{I}$ as well as the disjunction layer $F_{disj}$ and the conjunction layer $F_{conj}$ where $N_e$ is used to define the number of layers in the conjunction layer and $N_p$ is used to define the number of layers in the disjunction layer, seen in equation \ref{booltargetpredfunc}. As an agent learns rules for multiple actions, we define the set of discrete action predicates as the \textit{predicate action policy} $\pi_{\mathcal{F}}$ which is the set $\{ \mathcal{F}_{p^1}, \mathcal{F}_{p^2}, \cdots, \mathcal{F}_{p^n}  \}$ for all actions in the action space $p \in \mathcal{A}$ for the RL environment. 

{To prevent the gradient from becoming excessively small during training, initial weights $\mathbf{W}$ are initialised using a negative mean random Gaussian distribution, which ensures that they are close to zero. To keep membership weights $\textbf{m}$ between 0 and 1, a constant $c \geq 1$ is applied, followed by a sigmoid function. In equations} \ref{congj} and \ref{disj}, {we apply the conjunction function to the input matrix using the corresponding membership weights. Note that $\textbf{W}^{conj}$ is a matrix with dimensions $N_p$ and $N_e$ while $\textbf{W}^{disj}$ is a vector of size $N_p$. The disjunction function takes the output of the conjunction function as input as we cascade our neural architecture.}

\begin{equation}\label{booltargetpredfunc}
\qquad \quad \mathcal{F}_p|_{\mathbf{I},N_e,N_p} = F_{disj}(N_p, F_{conj}(N_e, \mathbf{I} ))      
\end{equation}

\begin{subequations}
\begin{equation}\label{congj}
  \quad {F}_{conj} = \sum_{i=1}^{N_e} [1 - m^{conj}_i(1- \mathbf{I}_i) ] \quad 
\text{where} \quad  \mathbf{m}^{conj} = \sigma(c\mathbf{W}^{conj}), \ \mathbf{W}^{conj}_{N_p, N_e} \sim \mathcal{N}   
\end{equation}


\begin{equation}\label{disj}
 \quad {F}_{disj} = 1 - \sum_{i=1}^{N_p} [1 - m_i^{disj}{F}_{conj}^i ] \quad 
\text{where} \quad  \mathbf{m}^{disj} = \sigma(c\mathbf{W}^{disj}), \ \mathbf{W}^{disj}_{1, N_p} \sim \mathcal{N}
\end{equation}
\end{subequations}

%non-linear preds
We incorporate non-linear transformations on some of the state features. As in the case of various control problems in RL, the calculation of state transitions is based on non-linear transformations from the current state. We define the following $k$ upper-boundary and lower-boundary functions as non-linear transformation predicates in equation \ref{trnpred}.
\begin{equation}\label{trnpred}
    \mathcal{F}_{gt^i_{f(x)}} = \sigma(c(f(x)-u_{xi})), \: \mathcal{F}_{lt^i_{f(x)}} = \sigma(-c(f(x)-l_{xi})) \: \text{where} \: f(x) \in \{sqr(x), sin(x), \cdots\}
\end{equation}


%We further differentiate between our dNL based agents. As the logical dNL agent will be applied on various RL algorithms, the core agent changes based only on the prior information given to the agent. The baseline dNL agent uses continuous and discrete Boolean predicates, referred to as a dNL RL continuous (dNLRLc) agent, and reflects a dNL agent which is learning the continuous state features as given without using any prior information in the KB. In cases where we use prior information, such as the non-linear equations or transformations between features, this involves including non-linear continuous Boolean predicates in the input matrix as new predicate functions in $\pi_{\mathcal{F}}$ can be defined using a transformation on a state feature or possibly by a non-linear transformation between features. We refer to this agent with prior information as dNL RL non-linear continuous (dNLRLnlc) agent. In the experiment section, we list which non-linear transformations are included for the dNLRLnlc agent with regards to the specific RL environment it is training on.

Our dNL based agents can be differentiated by the type of prior information used. The baseline dNL agent uses only continuous and discrete Boolean predicates and is referred to as a dNL RL continuous (dNLRLc) agent. It learns the continuous state features without using any prior information from a knowledge base $\mathsf{KB}_{T}$ which contains transformation functions mapped to specific continuous state features. However, when prior information such as non-linear equations or transformations between features is included, the agent becomes a dNL RL non-linear continuous (dNLRLnlc) agent. This involves adding non-linear continuous Boolean predicates to the input matrix as new predicate functions in $\pi_{\mathcal{F}}$. In the experiment section, we specify which non-linear transformations were used for the dNLRLnlc agent in each RL environment.


In Algorithm \ref{dNLagent} we provide a pseudo-code implementation for a dNL-RL agent. The agent takes in a state  $\mathbf{s}_t$,  at time step $t$ and returns an action $\mathbf{a}_t$ for that time step. The algorithm iterates through each feature of the state, $s_t^{(i)}$, and separates the elements into two cases: discrete and continuous. If the element is discrete, it adds the mapping of the discrete predicate $dsc_p[i]$ to the state element $s_t^{(i)}$ in a processed state set $\mathbb{S}_t$. If the element is continuous, it checks if a transformation function for the feature exists in the knowledge base $\mathsf{KB}_{T}[i]$. If it does, it adds the mapping of the continuous predicate $cnt_p[i]$ to the function applied to the state feature $s_t^{(i)}$ in the state set $\mathbb{S}_t$. If the knowledge base does not exist, it adds the mapping of the continuous predicate $cnt_p[i]$ to the state feature $s_t^{(i)}$ instead. After iterating through all state features, the policy is returned by applying the dNLRL policy function to the set $\mathbb{S}_t$, and then sampling an action $\textbf{a}_t$ from the \textit{predicate action policy}. 


	\begin{algorithm} \scriptsize
	\caption{dNL-RL agent} 
 \scriptsize
	\begin{algorithmic}[1]
	\State \textbf{Input}: $\mathbf{s}_t$-state at time step $t$
	\State \textbf{Output}: $\mathbf{a}_t$-action at time step $t$

	\For{$s_t^{(i)} \in \mathbf{s}_t$}
                \If{ $s_t^{(i)}$ is discrete }
                    \State $\mathbb{S}_t
                    \cup \{ dsc_p[i] \mapsto  s_t^{(i)}\}$
                \EndIf

                \If{ $s_t^{(i)}$ is continuous}
                    \If{$\mathsf{KB}_{T}[i]$ exists}
                        \State $\mathbb{S}_t \cup \{ cnt_p[i] \mapsto  \mathsf{KB}_{T}[i](s_t^{(i)})\}$
                    \Else
                        \State $\mathbb{S}_t \cup \{ cnt_p[i] \mapsto  s_t^{(i)}\}$
                    \EndIf
                \EndIf


	\EndFor
        \State $\mathbb{\pi}_\mathcal{F} \leftarrow \mathrm{dNLRL}(\mathbb{S}_t)$ 
        \State $\mathbf{a}_t \sim \mathbb{\pi}_\mathcal{F}(\mathcal{F}_{a_t}|\mathbb{S}_t)$ 


	\end{algorithmic} \label{dNLagent}
\end{algorithm}

To derive the predicate action policy $\mathbb{\pi}_\mathcal{F}$, we perform Boolean reasoning on the set of processed state features with associated predicates as seen in Algorithm \ref{dNLRLpolicy}.  Here we take as input a set of discrete predicates $dsc_p$, a set of continuous predicates $cnt_p$, a set of target action predicates $\mathbb{P}$, and a set of processed state feature predicates $\mathbb{S}_t$. We loop through each target action predicate in the set $\mathbb{P}$ and for each predicate, it creates two empty sets used for constructing the input matrix, one for the continuous predicates $\mathbf{I}_c$ and one for the discrete predicates $\mathbf{I}_d$. The dNLRL policy then loops through each continuous predicate in $cnt_p$ and for each predicate, it creates a disjunction of predicates, which are added to the continuous input matrix set $\mathbf{I}_c$. Then it does the same for each discrete predicate in $dsc_p$ but instead, the discrete predicates are added to the discrete input matrix set $\mathbf{I}_d$. We take the union of these two sets to get the final input matrix $\mathbf{I}$. Finally, it creates an evaluated target action predicate $\mathcal{X}_p$ by reasoning on target predicate function $\mathcal{F}_p$ as defined in equation \ref{booltargetpredfunc}. This target action predicate $\mathcal{X}_p$ is then added to the predicate action policy $\mathbb{\pi}_\mathcal{F}$.


\begin{algorithm}
	\caption{Single Step Forward Chain Model/ dNLRL policy} 
  \scriptsize
	\begin{algorithmic}[1]
	\State \textbf{Input}: $dsc_p$-set of discrete predicates, $cnt_p$-set of continuous predicates, $\mathbb{P}$-set of target action predicates, $\mathbb{S}_t$-set of state feature predicates at time step $t$
	\State \textbf{Output}: $\mathbb{\pi}_\mathcal{F}$-predicate action policy

	    \For {$p \in \mathbb{P}$}

	        \State $\mathbf{I}_c$=[]
                \State $\mathbf{I}_d$=[]
	        \For {$e \in cnt_p$}

	                \State $\mathbf{I}_c \cup \bigvee^{k}_{i=1} \Big( \mathcal{F}_{gt^i_{e}}(\mathbb{S}_t[e]) \vee \mathcal{F}_{lt^i_{e}}(\mathbb{S}_t[e]) \Big)$


	       \EndFor

                \For {$e \in dsc_p$}

	                \State $\mathbf{I}_d \cup  \Big( \mathcal{F}_{e}(\mathbb{S}_t[e]) \vee \mathcal{F}_{\overline{e}}(\mathbb{S}_t[e]) \Big)$


	       \EndFor
              \State $\mathbf{I} \leftarrow \mathbf{I}_d \cup \mathbf{I}_c$

	       \State $\mathcal{X}_p \leftarrow \mathcal{F}_p|_{\mathbf{I},N_e,N_p}$

	       \State $\mathbb{\pi}_\mathcal{F} \cup (\mathcal{X}_p)$
	    \EndFor




	\end{algorithmic}  \label{dNLRLpolicy}
\end{algorithm}


