\section{Preliminaries}
\label{sec:prelim}
\phantom{}

\myparagraph{Notation for matrices} %\label{sec:matrices}
All norms $||\cdot||$ for vectors and matrices used in this paper are 2-norms.
The Frobenius norm for matrices is denoted by $||\cdot||_F$.


For a matrix $A\in\mathbb R^{p\times q}$ we denote by
$\sigma_i(A)\ge 0$ the $i$-th singular value of $A$; if $i>\min\{p,q\}$ then $\sigma_i(A)=0$ by definition.
We denote by $\sym^p_{\mathbb F}$ the set of $p\times p$ symmetric matrices with coefficients in a field ${\mathbb F}$ and for ${\mathbb F}=\R$ we simply write $\sym^p$.
If $A$ is real symmetric of size $p$ ($A \in \sym^p$) then $\lambda_i(A)$ denotes the $i$-th largest eigenvalue of $A$.
A matrix $A \in \sym^p$ is positive semidefinite ($A \succeq 0$) if $\lambda_p(A) \geq 0$ and positive
definite ($A \succ 0$) if $\lambda_p(A)>0$. Recall that if $A \succeq 0$ then $\lambda_i(A)=\sigma_i(A)$ for all $i$.

The following inequalities are well known (see e.g.~\cite[Section 8]{golub2013matrix}):
\begin{subequations}
\begin{eqnarray}
|\sigma_i(A)-\sigma_i(B)| & \le & ||A-B||\qquad \forall A,B\in \mathbb R^{p\times q},\; \forall i \label{eq:sigmaInequality} \\
|\lambda_i(A)-\lambda_i(B)| & \le & ||A-B||\qquad \forall A,B\in \sym^p,\; \forall i \label{eq:lambdaInequality}
\end{eqnarray}
\end{subequations}
We will also denote $\rho(A)=\sigma_r(A)$ where $r=\text{rank}(A)$.
Clearly, for every non-zero matrix $A$ we have $\rho(A)>0$.

For a set of rows $I\subseteq[p]$ let $A_I\in\mathbb R^{|I|\times q}$ be the submatrix of $A$ formed by the rows in $I$. 
Similarly, for a set of columns $J\subseteq[q]$ let $A^J\in\mathbb R^{p\times|J|}$ be the submatrix of $A$ formed by the columns in $J$.

The transpose of matrix $A$ is denoted by $A^\top$.
In this paper this operation is applied only to matrices with real entries. We never use conjugate transpose for complex matrices, and accordingly we reserve the symbol ``$^\ast$'' for a different purpose ($X^\ast$ will denote an exact solution of the SDP system).

\myparagraph{Semidefinite programming}
Let us equip the vector space $\sym^\size$ of real symmetric matrices of size $\size$ with the Frobenius inner product:
\[
\la M, N \ra_{F} := \text{Trace}(MN)=\sum_{i,j} M_{ij}N_{ij}.
\]
for $M=(M_{ij}), \, N=(N_{ij}) \in \sym^\size$. The cone of positive semidefinite matrices (PSD cone) is $\sym^\size_+ = \{M \in \sym^\size : M \succeq 0\}$ is a convex closed basic semialgebraic set in $\sym^\size$, and its interior is the open convex cone of positive definite matrices: $\sym^\size_{++} := \text{int}(\sym^\size_+)\subseteq \sym^\size$. We denote by $\la u, v \ra_{\R} = \sum u_iv_i$ the Euclidean inner product on $\R^\cons$.

A semidefinite program in standard primal form is given by
\begin{equation}
  \label{SDPp}
\begin{array}{rcll}
  p^* & := & \inf_{X \in \sym^\size} & \la C, X \ra_{F} \\
  &    & \text{s.t.}         & \affmap(X) = b \\
  &    &                     & X \in \sym^\size_+
\end{array}
\end{equation}
%and its conic dual program is
%\begin{equation}
%  \label{SDPd}
%\begin{array}{rcll}
%  d^* & := & \sup_{y \in \R^\cons} & \la b, y \ra_{\R} \\
%  &    & \text{s.t.}         & C-\affmap^*(y) = S \\
