%\end{array}
%\end{equation}
where $\affmap \mymid \sym^\size \to \R^\cons$ is a linear map defined by $\affmap(X) = (\la A_{1},
X\ra_F, \ldots, \la A_{m}, X\ra_F)$ for some real symmetric matrices
$A_{1}, \ldots, A_{m} \in \sym^\size,$ $b \in \R^\cons$, and $C \in \sym^\size$.
%%and $\affmap^* \mymid \R^\cons \to \sym^\size$ is the adjoint map of $\affmap$. Recall that the adjoint satisfies $\la \affmap(X), y\ra_\R = \la X, \affmap^*(y)\ra_F$, that is $\affmap^*(y) = \sum_i y_i A_i$.
% \remk{Assumption: $A_i$'s are Linearly Independent.}
The feasible sets of the program \eqref{SDPp} is denoted by
\begin{equation}\label{feassetp}
\pset := \{X \in \sym^\size \mymid \affmap(X)=b, X \succeq 0\}.
\end{equation}
%\dset & = \{S \in (\sym^\size)^\vee \mymid \exists y, S = C-\affmap^*(y), S \succeq 0\} \label{feassetd}

Problem \eqref{SDPp} with $P\ne\varnothing$ is called {\em strongly feasible} if $P$ contains a matrix $X$ with $X\succ 0$, and {\em weakly feasibly}
otherwise. We will be mainly interested in weakly feasible SDPs. (Note that if~\eqref{SDPp} is strongly feasible then $P$ contains rational-valued matrices.) 

\myparagraph{Algebraic and semialgebraic geometry}
We refer to \cite{CLO} for basics of (computational) algebraic geometry, and we recall here the main definitions
needed in this work. A (complex) algebraic variety is a set of the form 
\begin{equation}\label{variety}
V = \{x \in \C^n : f_1(x) = 0, \ldots, f_s(x)=0\}
\end{equation}
for polynomials $f_1,\ldots,f_s \in {\mathbb F}[x]$ with coefficients in some subfield ${\mathbb F} \subseteq \C$ 
(we usually fix ${\mathbb F}=\Q$ or ${\mathbb F}=\R$). Of course defining $I = \langle f_1,\ldots,f_s \rangle \subseteq {\mathbb F}[x]$ the ideal generated by $f_1,\ldots,f_s$, 
remark that every $f \in I$ vanishes over $V$, in other words $V = V(I)$ with 
$$V(I) := \{x \in \C^n : f(x)=0, \forall f \in I\}.$$
The vanishing ideal of a set $W \subseteq \C^n$ is defined as
$$
I(W) := \{f \in \C[x] : f(x) = 0, \, \forall x \in W\}
$$
and by Hilbert's Nullstellensatz \cite[\S 4.1]{CLO}, one has the correspondence $I(V(J)) = \sqrt{J}$, where $\sqrt{J} := \{f \in \C[x] : 
f^m \in J, \exists m \in \mathbb{N}\}$ is the radical ideal of $J$. An ideal $I$ is called radical if $I=\sqrt{I}$.
The smallest algebraic variety containing a set $W$ is denoted by $\overline{W}$ and called its Zariski-closure. 

A variety $V \subseteq \C^n$ is called irreducible if it is not the union of two proper subvarieties, and every variety
is finite union of irreducible varieties called its irreducible components.
The dimension of an algebraic variety $V \subseteq \C^n$ is the minimum integer $d = \dim(V)$ such that the intersection 
$V \cap H_1 \cap \cdots \cap H_d$ of $V$ with $d$ generic hyperplanes $H_i$ is finite.
The degree of an irreducible variety $V \subseteq \C^n$ is the cardinality of the intersection of $V$ with $\dim(V)$
generic hyperplanes, and the degree of any variety is the sum of the degrees of its irreducible components. 
A variety whose irreducible components have the same dimension is called equidimensional.
An ideal $I$ with $V(I)\subseteq \C^n$ is in complete intersection if it can be generated by $\text{codim}(V(I))
= n - \dim(V(I))$ many polynomials, and with abuse of notation $V$ is said in complete intersection if this is the case
for $I(V)$.

Let $V \subseteq \C^n$ be a variety with $I(V)=\langle f_1, \ldots, f_s \rangle$.
For a point $p\in V$ the tangent space $T_pV$ at $p$ to $V$ is the kernel of the Jacobian matrix 
$$
J(f_1,...,f_s) := \left(\frac{\partial f_i}{\partial x_j}\right)_{\begin{smallmatrix} 1 \leq i \leq s \\ 1 \leq j \leq n \end{smallmatrix}}
$$ 
evaluated at $p$. A point \( p \in V \) is said to be a \textit{regular point} if the dimension of the tangent space \( T_p V \) at \( p \) coincides with the local dimension of \( V \) at \( p \) (the maximum of the dimensions of the irreducible components containing $p$). 
When $V$ is equidimensional of dimension $d$, the Jacobian 
$J(f_1,...,f_s)$ has rank $\leq n-d$ and equality holds exactly at regular points.
We denote the set of regular points as \( \text{Reg}(V) \), and its complement, \( \text{Sing}(V) := V \setminus \text{Reg}(V) \), is referred to as the set of singular points of \( V \). 

For ${\mathbb F}=\R$ and $V$ as in \eqref{variety}, the set $V(\R) := V \cap \R^n$ is called a real algebraic variety, and it
is defined by the vanishing of finitely many real polynomials. Given $g_1,\ldots,g_t \in \R[x]$, the set
$$
S = \{x \in \R^n : g_1(x) \geq 0, \ldots, g_t(x) \geq 0\}
$$
is called a basic closed semialgebraic set.



\myparagraph{Determinantal and incidence varieties}
We refer to \cite{eisenbud1988linear,harris1984symmetric} for the general theory of determinantal
varieties and we recall below the main definitions in the context of LMI.
%%%see \cite[Prop.1.7]{eisenbud1988linear}
%Let $\sym^\size_\C$ be the complex vector space of symmetric $\size \times \size$ complex matrices.
%Let $X = (x_{ij})$ be the generic symmetric matrix of size $\size \times \size$ (so $x_{ji} = x_{ij}$).
%One can define the locus
%$$
%\detv_\rnk = \{X \in \sym^\size_\C \mymid \rank(X) \leq r\}
%$$
%of matrices of rank at most $\rnk$. It is a complex algebraic variety of codimension
%$\binom{\size-\rnk+1}{2} = \frac{(\size-\rnk+1)(\size-\rnk)}{2}$ in $\sym^\size_\C$, thus of dimension
%$\binom{\size+1}{2}-\binom{\size-\rnk+1}{2} = \frac{\rnk(2\size-\rnk+1)}{2}$.
%Moreover, the singular locus of $\detv_\rnk$ is $\detv_{\rnk-1}$.

%\subsubsection{Affine sections of determinantal varieties}
%\label{sssec:affinesec}
Let $A_1,\ldots,A_\cons \in \sym^\size$, be the matrices defining the map $\mathscr{A}$
and $b \in \R^\cons$ the vector in \Cref{SDPp}. The set
%We assume that
%the entries of $\affmap(X)-b$ are linearly independent, and thus that the
%affine space defined by $\affmap(X)=b$ has codimension $\cons$.
$$
\detv_\rnk := \{X \in \sym^\size_\C \mymid \rank(X) \leq r, \affmap(X) = b\}
$$
is called the determinantal variety associated with $\mathscr{A},b$ and $r$.
It is the algebraic variety defined by the vanishing of the $(r+1)\times(r+1)$ minors of
the matrix $X$ (plus linear constraints $\mathscr{A}(X)=b$). 
For some $\rnk \in \{0,1,\ldots,m\}$, the real variety $\detv_\rnk(\R) := \detv_\rnk \cap \sym^n$ intersects the 
feasible set $P$.


From a computational point of view, minors are not easy to handle. Instead, the rank constraint is equivalent to the existence 
of a matrix of high rank whose columns generate the kernel of the original matrix. The following set
$$
\inc_r := \{(X,Y) \in \sym^\size_\C \times \C^{\size \times (\size-\rnk)} \mymid \affmap(X)=b, X Y = 0, \rank(Y) = \size-\rnk\}
$$
is associated with the variety $\detv_r$; indeed, $\detv_r$ is the projection of $\inc_r$ to $\sym^\size_\C$. 
Remark that $\inc_r$ is not an algebraic variety, since the constraint on
the rank of $Y$ is not closed in the Zariski topology, but instead a constructible set (an open subset of a Zariski 
closed set). We use the following view of $\inc_r$ from the coordinate charts (see \cite{HNS2015c}):
\begin{equation}\label{sssec:det_inc}
\inc_{r,\iota} := \{(X,Y) \in \sym^\size_\C \times \C^{\size \times (\size-\rnk)} \mymid \affmap(X)=b, X Y = 0, Y_{[n]-\iota} = I_{\size-\rnk}\}
\end{equation}
for $\iota \subseteq [\size]=\{1, \ldots, \size\}$, of cardinality $|\iota| = \rnk$, and $Y_{\iota'}$ is the
matrix obtained by selecting the rows of $Y$ in $\iota'=[n]-\iota$. Note that $\inc_{\rnk,\iota}$ is an algebraic set,
and  $\inc_{r} = \cup_{|\iota|=r} \inc_{r,\iota}$.
For a field ${\mathbb F}\in\{\R,\C\}$ and subset $C\subseteq \sym^\size_{\mathbb F} \times {\mathbb F}^{\size \times (\size-\rnk)}$ let us denote $\pi_{\sym^\size_{\mathbb F}}(C)=\{X\in\sym^\size_{\mathbb F}\::\:\exists Y\in {\mathbb F}^{n\times(n-r)}\mbox{ s.t.\ }(X,Y)\in C\}$ to be the projection of $C$ to $\sym^\size_{\mathbb F}$.
Using this notation, we define set
$$
\incproj_{\rnk,\iota}:=\pi_{\sym^\size_\C}(\inc_{\rnk,\iota})
$$
We also define the real traces of 
 $\inc_{\rnk,\iota}$ and $\incproj_{\rnk,\iota}$ as follows:
\begin{align*}
\inc_{\rnk,\iota}(\R) &= \inc_{\rnk,\iota} \cap (\sym^\size \times \R^{\size \times (\size-\rnk)})  \\
\incproj_{\rnk,\iota}(\R) &= \incproj_{\rnk,\iota} \cap \sym^\size 
=\pi_{\sym^\size}(\inc_{\rnk,\iota}(\R))
\end{align*}
where the last equality holds due to the following observation:
if $(X,Y)\in \inc_{r,\iota}$ with $X\in\sym^\size$ then $(X,{\mathscr Re}\, Y)\in \inc_{r,\iota}(\R)$.
Note that $\incproj_{\rnk,\iota}(\R)$ may not be algebraic; it is a constructible set. 
%[If we keep the new version, then we can remove the definition of $\pi$ in Th. 2.1(b). ]

Incidence varieties are used in \cite{HNS2015c} to solve feasibility problems of generic instances of LMI, and the following Theorem is a refinement of results in \cite{HNS2015c}.

\begin{theorem}\label{th:HNS2}
Assume $P \neq \varnothing$. Let $X^\ast\in \sym^n_+$ be a minimum-rank solution of~\eqref{feassetp}, and let $\iota\subseteq[n]$
be a maximal set of linearly independent columns of $X^\ast$, with $r=|\iota|$. 
\begin{itemize}
    \item[(a)] The constructible set $\incproj_{\rnk,\iota}(\R)$ has a connected component $C$ with $X^\ast\in C\subseteq \pset$.
    \item[(b)] The real variety $\inc_{r,\iota}(\R)$ has a connected component $C'$ with $X^\ast\in\pi_{\sym^n}(C')\subseteq \pset$
%%%where  $\pi_{\sym^n}(C')=\{X\::\:\exists Y\mbox{ s.t.\ }(X,Y)\in C'\}$ is the projection of $C'$ to $\sym^n$.
\end{itemize}
\end{theorem}
\begin{proof}
The definition of $\iota$ implies that there exists $Y^\ast\in\mathbb R^{n\times(n-r)}$ with $X^\ast Y^\ast=0$ and $Y^\ast_{[n]-\iota}=I_{n-r}$.
Clearly, we have $(X^\ast,Y^\ast)\in \inc_{r,\iota}(\R)$ and hence $X^\ast \in \incproj_{\rnk,\iota}(\mathbb{R})$.
Let $C$ be the component of $\incproj_{\rnk,\iota}(\mathbb{R})$ containing $X^\ast$.

\myparagraph{(a)} We need to show that $C\subseteq P$.
If $r=0$ then all points $(X,Y) \in \inc_{r,\varnothing}(\R)$ satisfy $X=0$, hence $C=\{X^\ast\}=\{0\}$ and the claim is straightforward. Suppose that $r>0$
and the claim is false, then there exists continuous curve $\{X^{(t)}\}_{t\in[0,1]}\subseteq C\subseteq \incproj_{\rnk,\iota}(\mathbb{R})$
with $X^{(0)}=X^\ast$ and $X^{(1)}=X\notin P$. For each $t\in[0,1]$ there must exist matrix $Y^{(t)}$ with
$(X^{(t)},Y^{(t)})\in \inc_{r,\iota}(\R)$.
Denote $\lambda^{(t)}_i=\lambda_i(X^{(t)})$ for $t\in[0,1]$, so that $\lambda^{(t)}_1\ge\ldots\ge\lambda^{(t)}_n$. These values satisfy the following properties for each $t\in[0,1]$:
\begin{itemize}
\item[(i)] At least $n-r$ values in $\lambda^{(t)}_1,\ldots,\lambda^{(t)}_n$ are zeros,
or equivalently $\rank(X^{(t)})\le r$.
This follows from conditions $X^{(t)}Y^{(t)}=0$ and $\rank(Y^{(t)})=n-r$, which imply that $\rank(X^{(t)})\le n-\rank(Y^{(t)})\le n-(n-r)=r$.
\item[(ii)] If $\lambda^{(t)}_n\ge 0$ then $\lambda^{(t)}_{r+1}=\ldots=\lambda^{(t)}_{n}=0$ and $\lambda^{(t)}_r>0$.
The first claim follows from~(i); if $\lambda^{(t)}_r=0$ then $\rank(X^{(t)})\le r-1$ contradicting the minimality of $r$
(note that $X^{(t)}\succeq 0$ and hence $X^{(t)}\in P$).
\item[(iii)] For each $i\in[n]$, $\lambda^{(t)}_i$ is a continuous function of $t$. This holds by continuity of the curve and by eq.~\eqref{eq:lambdaInequality}.
\end{itemize}
Conditions $X^{(0)}\in P$ and $X^{(1)}\notin P$ give $\lambda_n^{(0)}\ge 0$ and $\lambda_n^{(1)}< 0$.
Denote $s=\sup \{t\in[0,1]\::\:\lambda_n^{(t)}\ge 0\}$,
then $\lambda_n^{(s)}\ge 0$ by continuity and hence $s<1$. 
By (ii) we have $\mu := \lambda_r^{(s)}>0$.
By continuity, there exists $u\in(s,1]$ such that $\lambda_r^{(t)}>\mu/2$ for all $t\in[s,u]$.
Condition (i) thus gives  $\lambda_{r+1}^{(t)}=\ldots=\lambda_{n}^{(t)}=0$ for all $t\in[s,u]$,
and thus $\sup \{t\in[0,1]\::\:\lambda_n^{(t)}\ge 0\}\ge u>s$, which is a contradiction.


\myparagraph{(b)} Let $C'$ be the connected component of $\inc_{r,\iota}(\mathbb{R})$ containing $(X^\ast,Y^\ast)$.
Clearly, we have $\pi_{\sym^n}(C')\subseteq C$, and so the claim holds by part (a).
\end{proof}

