\section{Incidence varieties and facial reduction}
\label{sec:incidence}

We consider the feasibility problem of the primal SDP in \eqref{SDPp}, that is the system:
\begin{equation}
\label{FEASp}
\affmap(X) = b, \,\,\,\,\,\,\,\, X \succeq 0.
\end{equation}
%From now on we assume $P\ne\varnothing$.
%Let $r$ be the maximum rank of matrix $X\in P$. From now on we assume that $P\ne\varnothing$ and $r>0$.
%Any matrix $X\in P$ of rank $r$ will be called a {\em maximum rank solution}.
Let $P = \{X \in \sym^\size \mymid \affmap(X)=b, X \succeq 0\}$ be the set of feasible solutions as in~\eqref{feassetp},
and let $\rnk$ be the maximum rank of a matrix in $P$.
From now on, we assume that $P\ne\varnothing$ and $r>0$.
A matrix $X\in P$ of rank $r$ will be called a {\em maximum-rank solution}.

Below we recall some basic facts about facial reduction for SDPs, see e.g.~\cite{drusvyatskiy2017many}.
Let~$\face$ be the minimal face of the SDP cone $\sym^\size_+$ containing $P$. 
It can be represented by a full-rank
matrix $U \in \R^{\size \times \rnk}$ as follows: 
\begin{equation}\label{eq:face-range}
\face = \{X \in \sym^\size_+\::\: \text{range}(X)\subseteq \text{range}(U)\}=\{U Z U^\top\::\: Z \in \sym^r_+\}.
\end{equation}
In other words, $\face$ is linearly isomorphic (through $UZU^\top \to Z$) to a copy of the cone
$\sym^\rnk_+$, and in particular it has dimension $\binom{\rnk+1}{2}$. Any matrix in the relative
interior of $P$ is in the relative interior of $\face$ and hence has rank $\rnk$; every other
matrix in $P$ has rank $< \rnk$.

Let $\iota\subseteq[n]$ be a maximal set of linearly independent rows of $U$, with $|\iota|=r$.
We assume for notational convenience that $\iota=[r]$
(this can be achieved by renaming rows and columns of $X$).
Since $U$ is full-rank, we can apply Gaussian elimination to compute the column reduced
echelon form of $U$, without changing its range. 
%Indeed, assume without loss of generality , thus multiplying by the inverse of the corresponding sub-matrix yields the reduced form. Thus we can assume
Accordingly, we can assume w.l.o.g.\ that
\begin{equation}
U=\pmtx{I_r \\ U_0},\qquad \text{with } U_0\in \R^{(n-r) \times r}. \label{eq:Uform}
\end{equation}

% $
% \left(
% \begin{smallmatrix} I_{\rnk} \\
% -Y_U^T
% \end{smallmatrix}
% \right)
% $
% for some $Y_U \in \R^{\rnk \times (\size-\rnk)}$. 
Then for the matrix $Y_U := -{U_0}^\top$ we have
\begin{subequations}
  \label{eq:face}
  \begin{align}
    \face =\{X \in \sym^\size_+ \mymid \text{range}(X) \subseteq \text{range}(U)\}
    &=\{X\in \sym^\size_+ \mymid \smtx{Y_U^\top & I_{\size-\rnk}}
    X = 0^{(\size-\rnk)\times \size}\} \label{eq:face:a} \\
    &=\{X\in \sym^\size_+ \mymid X \smtx{Y_U \\ I_{\size-\rnk}}=0^{\size
      \times (\size-\rnk)}\} \label{eq:face:b}
  \end{align}
\end{subequations}

Now  consider the following system of equations (in variables $X \in \sym^\size_\C$ and $Y \in \C^{\size \times (\size-\rnk)}$):
\begin{subequations}\label{eq:GHOAISFH}
\begin{align}
 \affmap(X)&=b \\
 X \left(\begin{matrix} Y \\ I_{\size-\rnk}\end{matrix}\right) & = 0^{\size \times (\size-\rnk)} \label{eq:GALHDGKA}
\end{align}
\end{subequations}

%\begin{remark}
%Substituting $Y=Y_U$ in \eqref{eq:GHOAISFH} and then solving in $X$, gives a set containing the face $\face$.
%\end{remark}

Let $\inc_{\rnk,\iota}\subseteq \sym^\size_\C \times \C^{\size \times (\size-\rnk)}$ be the set of complex solutions of~\eqref{eq:GHOAISFH}.
Note that it is essentially the same incidence variety defined in the previous section (for $\iota = [r]$),
modulo notation: matrix $Y$ in eq.~\eqref{sssec:det_inc} has a larger size, but all additional entries are fixed to constants.
We define $\incproj_{\rnk,\iota}$, $\inc_{\rnk,\iota}(\R)$ and $\incproj_{\rnk,\iota}(\R)$ in the same way as before:
\begin{subequations}
\begin{align}
  \incproj_{\rnk,\iota}  := \pi_{\sym^n_\C}(\inc_{\rnk,\iota}) 
  & = \{X \in \sym^\size_\C \mymid \exists Y \in \C^{\rnk \times (\size-\rnk)} \;\mbox{s.t.}\; (X,Y) \in \inc_{\rnk,\iota}\} \\
                        & = \{X \in \sym^\size_\C \mymid \exists Y \in \C^{\rnk \times (\size-\rnk)} \;\mbox{s.t.}\; \affmap(X)=b, X \left(\begin{smallmatrix} Y \\ I_{\size-\rnk}\end{smallmatrix}\right) = 0^{\size \times (\size-\rnk)}\} 
\end{align}
\end{subequations}
\begin{equation}
\inc_{\rnk,\iota}(\R)  = (\sym^\size \times \R^{\size \times (\size-\rnk)}) \cap \inc_{\rnk,\iota} \hspace{40pt} 
\incproj_{\rnk,\iota}(\R) = \sym^\size \cap \incproj_{\rnk,\iota}=\pi_{\sym^n}(\inc_{\rnk,\iota}(\R))
\end{equation}
By construction, $P\subseteq \face \cap \{X \in \sym^\size \mymid \affmap(X)=b\} \subseteq \incproj_{\rnk,\iota}(\R)$.

%\begin{remark}
%The set $\incproj_{\rnk,\iota}(\R)$ is not algebraic, it is a constructible set.
%\end{remark}

% \remark{Note}

%\begin{remark}
%By construction, $\face \cap \{X \in \sym^\size \mymid \affmap(X)=b\} \subseteq \incproj_{\rnk,\iota}(\R)$.
%\end{remark}




\begin{lemma}\label{prop:OmegaExists}
%Suppose that system~\eqref{eq:P} has face $\face$ of the form~\eqref{eq:face}
Let $P \neq \varnothing$ and let $X^* = UZ^* U^\top\in P$ be a maximum-rank solution, with $U$ as in~\eqref{eq:Uform} and $Z^*\in \sym^\rnk_{++}$ positive definite.
Define open neighborhood $\Omega^*$ of $X^\ast$ via $\Omega^\ast=\{X\in \sym^\size\::\:||X-X^\ast||<\rho(X^\ast)\}$.
The following holds:
%Then $X^*$ has an (Euclidean) open neighborhood $\Omega^* \subset \sym^\size$ with the following properties:
\begin{itemize}
\item[(a)] $P \cap \Omega^* = \incproj_{\rnk,\iota}(\R) \cap \Omega^*$.
\item[(b)] For every $X \in \incproj_{\rnk,\iota}(\R) \cap \Omega^*$ there exists a unique matrix $Y$ such that $(X,Y) \in \inc_{\rnk,\iota}$. This matrix is $Y=Y_U$.  
%\item[(c)] $\incproj_{\rnk,\iota}(\R) \cap \Omega^*$ is a smooth manifold of dimension $\dim(P)$.
\end{itemize}
\end{lemma}
\begin{proof} %We will use the notation and inequalities from Section~\ref{sec:matrices}. 
  {\it Part (a)}. 
   If $X \in P$ then $\affmap(X) = b$ and $(X,Y_U) \in \inc_{\rnk,\iota}$ (since $P\subseteq\calF$), and thus $X \in \incproj_{\rnk,\iota}(\R)$.
  This shows that $P \subseteq \incproj_{\rnk,\iota}(\R)$ and hence $P \cap \Omega^* \subseteq \incproj_{\rnk,\iota}(\R) \cap \Omega^*$.

  Now suppose that $X \in \incproj_{\rnk,\iota}(\R) \cap \Omega^*$. Then there exists $Y$ such that
  $(X,Y) \in \inc_{\rnk,\iota}$, i.e. $(X,Y)$ satisfies system~\eqref{eq:GHOAISFH}.
  Eq.~\eqref{eq:GALHDGKA} implies that $X$ has at least $\size-\rnk$ zero eigenvalues. 
  Since $\text{rank}(X^\ast)=r$,
  we have $\lambda_r(X^\ast)=\rho(X^\ast)>0$.
  By~\eqref{eq:lambdaInequality}, for all $X\in\Omega^\ast$ we have $|\lambda_r(X)-\lambda_r(X^\ast)|\le || X-X^\ast || < \rho(X^\ast)=\lambda_r(X^\ast)$
  and thus $\lambda_r(X) > 0$, i.e.\ $X$ has at least $r$ strictly positive eigenvalues.
  We conclude that $X$ has exactly $n-r$ zero eigenvalues and exactly $r$ strictly positive eigenvalues,
  therefore $X\succeq 0$
  and $\text{rank}(X)=r$.
  Combined with the fact that $\affmap(X)=b$, this implies that $X \in P$. We showed that 
  converse inclusion $\incproj_{\rnk,\iota}(\R) \cap \Omega^* \subseteq P \cap \Omega^*$ is also true.

  {\it Part (b)}. As shown in (a), we have $X\in P\subseteq\face$.
  Therefore, $(X,Y_U)\in \inc_{\rnk,\iota}$, i.e.\ it satisfies~\eqref{eq:GHOAISFH}.
  Suppose that there exists $Y \neq Y'$ such that $(X,Y)$ and $(X,Y')$ satisfy~\eqref{eq:GHOAISFH}.
  Denote 
  $$
  C := \begin{pmatrix} Y & Y' \\ I_{\size-\rnk} & I_{\size-\rnk} \end{pmatrix},$$ 
  then
  $XC=0^{\size\times 2(\size-\rnk)}$. Clearly, we have $\text{rank}(C) \geq \size-\rnk+1$: indeed,
  the first $\size-\rnk$ columns of $C$ are linearly independent, and there exists a column among
  the remaining ones which is not in the range of the first $\size-\rnk$ columns, by the assumption
  $Y \neq Y'$. This implies that $\text{rank}(X) \leq \size-\text{rank}(C) \le \size-(\size-\rnk+1)=
  \rnk-1$, which contradicts condition $\text{rank}(X)=r$ shown in part (a).
  %  {\it Part (c)}.
%  By part (a), $\incproj_{\rnk,\iota}(\R) \cap \Omega^* = P \cap \Omega^*$. By property of the set $\Omega^\ast$, every $X \in P \cap \Omega^{\ast}$ lies in the relative interior of the face $\mathcal{F}$ of the cone $\mathbb{S}^{n}_{+}$ and we know such face is diffeomorphic to $\mathbb{S}^{r}_{++}$  for some $r$ through the map $\phi:Z \mapsto U^\top Z U$ with $Z \in \mathbb{S}^{r}_{++}$.  Thus, $\phi(\Omega^{\ast})$ is an open set contained in the interior of $\mathbb{S}^{r}_{+}$ . In particular, $P \cap\Omega^{\ast}$ is diffeomorphic to the intersection of an open set and an affine subspace i.e., an open subset of a smooth manifold.
\end{proof}







