\section{Description of the method}\label{sec:descMethod}
Motivated by Lemma~\ref{prop:OmegaExists}, we propose the following hybrid method for certifying the feasibility of system~\eqref{FEASp} (see Algorithm~\ref{alg:method}). (We assume that the system is feasible, i.e.\ $P \neq \varnothing$).
Note that some steps of Algorithm~\ref{alg:method} require approximate computations. First, we need to compute approximate solution $\tilde X$ which is close to some maximum-rank solution $X^\ast$; 
Theorems~\ref{th:method} and~\ref{th:numerical} given later will characterize how close we need to be for the method to work correctly. Second, steps 2 and 4 invoke a procedure for {\bf numerically} computing a maximal set of linearly independent columns of a given matrix. Such procedure will be described later in Section~\ref{sec:rank-revealing}.

An illustration of Algorithm~\ref{alg:method} on a small numerical example is given in Section~\ref{sec:DruWoExample}.



\begin{algorithm}[h] 
%\DontPrintSemicolon
%\SetNoFillComment
{\bf 1}. Solve system~\eqref{FEASp} numerically to get solution $\tilde X\in \sym^\size$ which is close to some maximum-rank solution $X^\ast$.
\\
{\bf 2}. Find numerically a maximal set $\iota\subseteq[n]$ of linearly independent columns of $\tilde X$, let $r=|\iota|$. Assume for notational convenience that $\iota=[r]$ (this can be achieved by renaming variables). Write 
$$
\tilde X:=\begin{pmatrix} \tilde S & \tilde R^\top \\ \tilde R & \tilde W \end{pmatrix}
$$ where $\tilde S =\tilde X^\iota_\iota\in \sym^\rnk$. If $\tilde S$ is singular then terminate with failure, otherwise define 
$\tilde Y := -\tilde S^{-1}\tilde R^\top\in\mathbb R^{r\times(n-r)}$. (Note, \Cref{lemma:SymSubmatrix} implies that $\tilde X\left(\begin{smallmatrix} \tilde Y \\ I_{n-r} \end{smallmatrix}\right)\approx 0^{n\times(n-r)}$). \\
{\bf 3}. Write system~\eqref{eq:GHOAISFH} as
\begin{equation}\label{eq:sysQYXq}
\mathcal{Q}(Y)X_{\text{hvec}}=q
\end{equation}
where $X_{\text{hvec}}$ is a  vector of dimension $k=\frac{{n(n+1)}}{2}$ obtained by vectorizing the lower triangular part of $X$, $\mathcal{Q}(Y)$ is a matrix that depends linearly on $Y$, and $q$ is fixed vector. \\ 
{\bf 4}. Find numerically a maximal set $J\subseteq[k]$ of linearly independent columns of $\mathcal{Q}(\tilde Y)$. \\
{\bf 5}. Augment system~\eqref{eq:GHOAISFH} by fixing variables in $J':=[n]-J$:
\begin{subequations}\label{eq:fixed-variables}
\begin{align}
 \affmap(X)&=b \label{eq:fixed-variables:a} \\
 X \left(\begin{matrix} Y \\ I_{\size-\rnk}\end{matrix}\right) & = 0^{\size \times (\size-\rnk)} \label{eq:fixed-variables:b} \\
 (X_{\text{hvec}})_j & =(\tilde X_{\text{hvec}})_j \qquad \forall j\in J' \label{eq:fixed-variables:c}
\end{align}
\end{subequations}
Compute one point per connected component of the real algebraic variety defined by \Cref{eq:fixed-variables}
as in \cite{HNS2015c} (cf. \Cref{ssec:lagrange}). By \cite[Lemma 3.2]{HNS2015c}, the equations in 
\eqref{eq:fixed-variables:b} at positions $i,j$ 
with $i-j>r$ are implied by other equations and thus can be omitted.
\caption{Hybrid algorithm for system $\affmap(X) = b, \,\,\, X \succeq 0$.}\label{alg:method}
\end{algorithm}

\vspace{0.5cm}

The next observation justifies Step 2.
\begin{lemma}\label{lemma:SymSubmatrix}
Consider a PSD matrix $X = \left(\begin{smallmatrix} S & R^\top \\ R &  W \end{smallmatrix}\right)\in \sym^\size_+$ with $ S \in \sym^\rnk$,
and suppose that $\iota=[r]$ is a maximal set of linearly independent columns (so that the rank of $X$ is $r$).
Then $S$ is non-singular (and thus positive definite), and matrix 
 $Y=-S^{-1} R^\top$ satisfies 
 $X\left(\begin{smallmatrix} Y \\ I_{n-r} \end{smallmatrix}\right) = 0^{n\times(n-r)}$.
\end{lemma}
\begin{proof}
By hypothesis, the last $n-r$ columns of $X$ are linearly dependent on the first $r$ columns. Therefore, we can write
$$ \begin{pmatrix} R^\top \\ W \end{pmatrix} = \begin{pmatrix} S \\ R \end{pmatrix} Z $$
for some matrix $Z \in \mathbb{R}^{r \times (n-r)}$, which means $R^\top = SZ$ and $W = RZ$.  \rev{Hence, $R = Z^\top S$ and $W = Z^\top S Z$. Thus, we can write $X = \begin{pmatrix} I & Z \end{pmatrix}^\top S \begin{pmatrix} I & Z \end{pmatrix}$.  This implies that $r = \text{rank}(X) \leq \text{rank}(S)$, and the first claim holds.}

Since $S$ is non-singular, we have $Z = S^{-1}R^\top$ and $W = RS^{-1}R^\top$.  Using these equations, we can check that $SY + R^\top = 0^{r \times (n-r)}$ and $RY + W = 0^{(n-r) \times (n-r)}$, which yields the second claim.
\end{proof}

% \begin{proof}
% The first claim holds e.g.\ by \cite[Lemma 2.3.14]{Truemper}. Alternatively, it will follow from Lemma~\ref{lemma:PSDsubmatrix} given later.
% Since the last $n-r$ columns of $X$ linearly depend on the first $r$ columns,
% we must have $$\pmtx{ R^\top \\ W}=\pmtx{ S \\ R}Z$$ for some matrix $Z\in\mathbb R^{r\times(n-r)}$,
% i.e.\ $R^\top=SZ$ and $W=RZ$. Hence $Z=S^{-1}R^\top$ and $W=RS^{-1}R^\top$.
% Using these equations, one can now check that $SY+R^\top=0^{r\times(n-r)}$ and $RY+W=0^{(n-r)\times(n-r)}$,
% which yields the second claim.
