\begin{definition}
We say that sets $\iota \subseteq [n]$ and $J \subseteq [k]$ are {\em{valid}} for a maximum-rank solution $X^\ast$ if they can be outputs of steps 2 and 4, respectively, assuming that step 1 computes the vector $X^\ast$, and the computations in steps 2 and 4 are performed exactly
(i.e.\ a maximal set of linearly independent columns is computed {\em exactly} rather than numerically).
\end{definition}

\begin{theorem}\label{th:method}
Each maximum-rank solution $X^\ast$ has an open neighborhood $\tilde\Omega\subset\sym^\size$ 
with the following property.
%Let $\Omega^\ast$ be the neighborhood of a maximum-rank solution $X^\ast$ as in Lemma~\ref{prop:OmegaExists}. 
Suppose that step 1 produces point $\tilde{X}\in\tilde\Omega$,
 and lines 2 and 4 output sets $\iota$ and $J$, respectively, which are valid for $X^\ast$. Then 
 the set of real solutions of system~\eqref{eq:fixed-variables} has a zero-dimensional component with a solution $(X, Y)$ where $X \in \sym^\size_+$.
\end{theorem}
Note, the theorem's precondition essentially requires that approximate computations output the same sets $\iota,J$ as the exact computations would. Later in Section~\ref{sec:rank-revealing} we will show that this can be achieved even if $X^\ast$ is known only approximately.
\begin{proof}
    By assumption, set $\iota$ is valid for $X^\ast$, i.e.\ $\iota$ is a maximal set of linearly independent columns in $X^\ast$ (and so $|\iota|=r$).
    Assume for notational convenience that $\iota=[r]$.
    By Lemma~\ref{lemma:SymSubmatrix}, $\iota$ is also a maximal set of linearly independent rows in $X^\ast$.
    Choose matrix $U\in\mathbb R^{n\times r}$ characterizing the face $\calF$ as in~\eqref{eq:face-range}.
    Since $\text{range}(X^\ast)\subseteq\text{range}(U)$ and $\text{rank}(X^\ast)=r$,
    set $\iota$ is a maximal set of linearly independent rows in $U$. Thus, we can choose $U$ as in~\eqref{eq:Uform}.

    Denote $\Omega^\ast=\{X\in\sym^\size\::\:||X-X^\ast||<\rho(X^\ast)\}$. By Lemma~\ref{prop:OmegaExists}(a,b), for any $(X,Y)$ we have 
\begin{equation}\label{eq:equivProp1}
\begin{array}{c}
    \mathcal{Q}(Y) X_{\text{hvec}} = q  \\
    X \in \Omega^\ast
\end{array}
\;\;\Longleftrightarrow\;\;
\begin{array}{c}
    \mathcal{Q}(Y_U) X_{\text{hvec}} = q  \\
    X \in \Omega^\ast \\
    Y = Y_U
\end{array}
\;\;\Longrightarrow\;\;
X\in\sym^\size_+
\end{equation}
To simplify notation, let us write 
$$
X_\text{hvec} =: \begin{pmatrix}X^{J}\\X^{J'}\end{pmatrix}
$$
and $\mathcal{Q}(Y_U)=:\mathcal{Q}=:\begin{pmatrix}Q^{J} & Q^{J'}\end{pmatrix}$.
By assumption, $J$ is a maximal set of linearly independent columns for matrix $\mathcal{Q}$.
Let $I$ be a maximal set of linearly independent rows of $\mathcal{Q}$, then $|I|=|J|=\text{rank}(\mathcal{Q})$.
The linear system $\mathcal{Q}X_{\text{hvec}}=q$ has at least one solution, namely $X_{\text{hvec}}=X^\ast_{\text{hvec}}$.
Thus, removing equations corresponding to rows $i\notin I$ will not affect the set of feasible solutions.
This implies that system $\mathcal{Q}X_{\text{hvec}}=q=\mathcal{Q}X^\ast_{\text{hvec}}$ is equivalent
to the system $$\begin{pmatrix}Q^{J}_I & Q^{J'}_I\end{pmatrix} \begin{pmatrix}X^{J}-(X^\ast)^J\\X^{J'}-(X^\ast)^{J'}\end{pmatrix}=0,$$
which is in turn equivalent to  % $X^J=(\mathcal{Q}^J_\iota)^{-1}(q_\iota-\mathcal{Q}^{J'}_\iota X^{J'})$ or to 
$X^J-(X^\ast)^J=-(\mathcal{Q}^J_I)^{-1}\mathcal{Q}^{J'}_I (X^{J'}-(X^\ast)^{J'})$
since matrix $\mathcal{Q}^J_I$ is nonsingular. Let us denote $\mathcal{R}^J_I=-(\mathcal{Q}^J_I)^{-1}\mathcal{Q}^{J'}_I$.

By adding constraint $X^{J'}=\tilde X^{J'}$ to~\eqref{eq:equivProp1}
we can now conclude the following for any $(X,Y)$:
\begin{equation}\label{eq:equivProp2}
\begin{array}{c}
    (X,Y)\mbox{ satisfies~\eqref{eq:fixed-variables}}  \\
    X \in \Omega^\ast
\end{array}
\;\;\Longleftrightarrow\;\;
\begin{array}{c}
    X^J-(X^\ast)^J=\mathcal{R}^J_I (\tilde X^{J'}-(X^\ast)^{J'})  \\
    X^{J'}=\tilde X^{J'} \\
    X \in \Omega^\ast \\
    Y = Y_U
\end{array}
\;\;\Longrightarrow\;\;
X\in\sym^\size_+
\end{equation}

Let us define 
$$
\delta_{\iota,J,I} := \frac{\rho(X^\ast)}{4\max\{||\mathcal{R}^J_I ||,1\}}.
$$
We claim that for any $\tilde X\in\sym^\size$ with $||\tilde X-X^\ast||_F<\delta_{\iota,J,I}$ the system in the middle of~\eqref{eq:equivProp2}
has exactly one feasible solution $(X,Y)$.
Indeed, we only need to verify that $X$ defined by the equalities in this system satisfies
$X\in \Omega^\ast$. This holds since $||X^J-(X^\ast)^J||\le ||\mathcal{R}^J_I||\cdot ||\tilde X^{J'}-(X^\ast)^{J'}|| < \frac 14 \rho(X^\ast) $
and $||X^{J'}-(X^\ast)^{J'}|| < \frac 14 \rho(X^\ast)$, implying $||X-X^\ast|| \le ||X-X^\ast||_F \le 2||X^{J}-(X^\ast)^{J}||+2||X^{J'}-(X^\ast)^{J'}|| <  \rho(X^\ast)$.


We can now define set $\tilde\Omega$ in Theorem~\ref{th:method} as follows:
$\tilde\Omega=\{\tilde X\in\sym^\size\::\:||\tilde X-X^\ast||_F<\delta\}$
where $\delta=\min_{\iota,J,I}\delta_{\iota,J,I}$ and the minimum is taken over (finitely many) valid choices of $\iota,J,I$.
\end{proof}



