\subsection{Numerical algorithms: implementing steps 2 and 4}\label{sec:rank-revealing}
To implement Algorithm~\ref{alg:method}, we need a procedure for numerically computing a maximal set of linearly
independent columns of a given matrix. This can be done, for example, 
by a rank-revealing Gaussian elimination algorithm~\cite{Pan:00,SchorkGondzio:20}.
Such algorithm takes a matrix $A\in\mathbb R^{p\times q}$ and a tolerance value $\epsilon$ as input,
and produces an integer $r$ and a subset $J\subseteq[q]$ of size $r$
with the following guarantees:~\footnote{The algorithm actually
produces subsets $I\subseteq[p]$ and $J\subseteq[q]$ of size $r$ such that $\sigma_{r}(A_I^J)  \ge  \sigma_r(A)/c_{pq}$.
(This follows by combining Lemma 3.1 and Theorem 4.1 in~\cite{SchorkGondzio:20}.)
This implies~\eqref{eq:RankRevealing:c} since $\sigma_r(A^J)\ge \sigma_r(A^J_I)$ by a well-known property of singular values, see e.g.~\cite[Corollary 8.6.3]{golub2013matrix}.}
\begin{subequations}\label{eq:RankRevealing}
\begin{eqnarray}
\sigma_r(A) & \ge & \epsilon \label{eq:RankRevealing:a} \\
\sigma_{r+1}(A) & \le & c_{pq} \epsilon \label{eq:RankRevealing:b} \\
\sigma_{r}(A^J) & \ge & \sigma_r(A) / c_{pq}  \label{eq:RankRevealing:c}
%\\ \sigma_{1}(A_\iota^J)\ldots \sigma_{r}(A_\iota^J) & \ge & \sigma_1(A) \ldots \sigma_r(A) / c^r_{pq} 
\end{eqnarray}
\end{subequations}
where constant $c_{pq}>1$ depends polynomially on dimensions $p,q$.
Below we analyze Algorithm~\ref{alg:method} assuming
that steps 2 and 4 use the method above with tolerance values $\epsilon_1$ and $\epsilon_2$, respectively.
The next result shows that if $||\tilde X-X^\ast||$ is sufficiently small
then from $\tilde X$ it is possible to compute sets $\iota,J$ which are valid for $X^\ast$.

\begin{theorem}\label{th:numerical}
(a) Suppose that $\delta<\epsilon_1<(\rho^\ast-\delta)/c_{nn}$ where $\delta=||\tilde X-X^\ast||$ and $\rho^\ast=\rho(X^\ast)$.
Then set $\iota$ computed in step 2 is a maximal set of linearly independent columns for $X^\ast$.
Furthermore, 
\begin{equation}\label{eq:phi}
\lambda_r(\tilde S)\;\;\ge\;\; \phi(\delta)\;\;:=\;\;\frac {((\rho^\ast-\delta)/c_{nn}-\delta)^2}{n||X^\ast||} - \delta
\end{equation}
(b) Suppose the precondition in (a) holds and $\phi(\delta)>\delta$. 
Write 
$$
X^\ast=\pmtx{S^\ast &  (R^\ast)^\top \\ R^\ast &  W^\ast}
$$ where $S^\ast=(X^\ast)^\iota_\iota$, and let $Y^\ast=-(S^\ast)^{-1} (R^\ast)^\top$.
Let $||\mathcal{Q}||$ be the 2-norm of linear operator $\mathcal{Q}:\mathbb R^{r\times(n-r)}\rightarrow\mathbb R^{p\times q}$,
and denote
\begin{equation}
\psi(\delta)=||\mathcal{Q}||\cdot\left[\frac{||X^\ast||}{\phi(\delta)-\delta}+1\right]\cdot\frac{\delta}{\phi(\delta)}
\end{equation}
If $\psi(\delta)<\epsilon_2<(\rho(\mathcal{Q}(Y^\ast))-\psi(\delta))/c_{pq}$ then set $J$ computed in step 4 is a maximal set of linearly independent columns for $\mathcal{Q}(Y^\ast)$. 
\end{theorem}
Note that $\lim_{\delta\rightarrow 0}\phi(\delta)=const>0$ and $\lim_{\delta\rightarrow 0}\psi(\delta)=0$.
Thus, the preconditions in (a,b) can be satisfied for sufficiently small $\delta>0$
as long as $\rho(\mathcal{Q}(Y^\ast))>0$. (The case when $\rho(\mathcal{Q}(Y^\ast))=0$ is not interesting:
we then have $\mathcal{Q}(Y^\ast)=0$ and thus $\calA(X)=0$ for all $X$). 
We remark that linear operator $\mathcal{Q}$, function $\psi(\cdot)$ and value $\rho(\mathcal{Q}(Y^\ast))-\psi(\delta)$ depend on $\iota$, but there are only finitely many subsets $\iota\subseteq[n]$
which give maximal linearly independent columns for $X^\ast$, so we could take the minimum value over such $\iota$'s 
when formulating the final condition.

In the remainder of this section we prove Theorem~\ref{th:numerical}. We start with part (a).
Let $r^\ast=\text{rank}(X^\ast)$ be the true rank and $r$ be the rank computed by the numerical procedure in step~2.
Condition~\eqref{eq:RankRevealing:c} gives 
$$
\sigma_r(\tilde X^\iota)\ge \frac{\sigma_r(\tilde X)}{c_{nn}} \ge 
\frac{\sigma_r(X^\ast)-||\tilde X-X^\ast||}{c_{nn}} = \frac{\rho^\ast-\delta}{c_{nn}}.
$$
Therefore, $\sigma_r((X^\ast)^\iota)\ge \sigma_r(\tilde X^\iota) - ||X^\ast-\tilde X||\ge (\rho^\ast-\delta)/c_{nn} -\delta > 0$,
implying that columns in $\iota$ are linearly independent in~$X^\ast$ (and so $r\le r^\ast$).
If $r<r^\ast$ then $\sigma_{r+1}(\tilde X)\le c_{nn}\epsilon_1$ by condition~\eqref{eq:RankRevealing:b}
and $\sigma_{r+1}(\tilde X)\ge \sigma_{r^\ast}(\tilde X)\ge \sigma_{r^\ast}(X^\ast) - ||\tilde X-X^\ast||=\rho^\ast-\delta$ by~\eqref{eq:sigmaInequality},
which is a contradiction. This shows that $r=r^\ast$. % and $\iota$ is a maximal set of linearly independent columns in~$X^\ast$.

The last claim~\eqref{eq:phi} will follow from the result below for matrix $X=\tilde X$
and value $\tau=\sigma_r(\tilde X^\iota)\ge (\rho^\ast-\delta)/c_{nn}>\delta$.

\begin{lemma}\label{lemma:PSDsubmatrix}
Consider symmetric matrices $X^\ast\in\sym^\size_+$, $X\in\sym^\size$ with $||X^\ast-X||=\delta$.
Let  $\iota\subseteq[n]$ be a subset of size $r$
with $\sigma_r(X^\iota)=\tau\ge\delta$. Then 
$$
\lambda_r(X^\iota_\iota)\ge \frac {(\tau-\delta)^2}{n||X^\ast||} - \delta.$$
\end{lemma}
Note that this lemma also implies the first part of Lemma~\ref{lemma:SymSubmatrix} (by setting $X=X^\ast$).

\begin{proof}
We will use a well-known fact that for any matrix $A\in\mathbb R^{p\times q}$ with $p\ge q$ we have $\sigma_q(A)=\min\{||Au||\::\:u\in\mathbb R^q,||u||=1\}$.

Consider vector $u\in \mathbb R^\iota$ with $||u||=1$, then $||X^\iota u|| \ge \tau$.
Let $v\in\mathbb R^n$ be the vector with $v_i=u_i$ for $i\in \iota$ and $v_i=0$ for $i\in[n]-\iota$.
We have $||Xv||=||X^\iota u||\ge \tau$, and hence
$$
||X^\ast v||\ge ||Xv||-||(X^\ast-X)v|| \ge \tau - ||X^\ast-X||\cdot 1=\tau-\delta
$$
Let us write $X^\ast=\sum_{i=1}^n \lambda_i v_i v_i^\top=\sum_{i=1}^nw_iw_i^\top$ where $||X^\ast||=\lambda_1\ge\lambda_2\ge\ldots\ge\lambda_n\ge 0$,
$v_1,\ldots,v_n$ are orthonormal vectors, and
$w_i=\sqrt{\lambda_i}v_i$ (then $||w_i||\le \sqrt{\lambda_1}$).
Denote $\alpha_i=|v^\top w_i|$, then $v^\top X^\ast v=\sum_{i=1}^n\alpha_i^2$. We can write
\begin{align*}
\tau-\delta&\le||X^\ast v||=||\sum_{i=1}^n w_i(v^\top w_i)||\le \sum_{i=1}^n \alpha_i ||w_i|| \\ 
& \le \sqrt{\lambda_1}\cdot\sum_{i=1}^n\alpha_i 
\le \sqrt{\lambda_1}\cdot\sqrt{n\sum_{i=1}^n\alpha_i^2}
= \sqrt{\lambda_1 n(v^\top X^\ast v)}
\end{align*}
where the last inequality is tight if and only if $\alpha_1=\ldots=\alpha_n$. Therefore,
$$
u^\top X^\iota_\iota u = v^\top X v = v^\top X^\ast v + v^\top (X-X^\ast) v 
\ge \frac {(\tau-\delta)^2}{n\lambda_1} - ||v||^2 \cdot ||X-X^\ast||
= \frac {(\tau-\delta)^2}{n\lambda_1} - \delta
$$
\hbox{}
\end{proof}

Next, we prove part (b) of Theorem~\ref{th:numerical}. 
We will need the following result.

\begin{theorem}[{\cite[Theorem 7.12]{Atkinson}}]\label{th:InverseStability}
Let $A, B$ be square matrices of the same size such that $A$ is nonsingular and $||A-B||\le \frac{1}{||A^{-1}||}$.
Then $B$ is also nonsingular and
$$
||B^{-1}||\le \frac{||A^{-1}||}{1-||A^{-1}||\cdot ||A-B||}
$$ 
$$
||A^{-1}-B^{-1}||\le \frac{||A^{-1}||^2\cdot ||A-B||}{1-||A^{-1}||\cdot ||A-B||}
$$
\end{theorem}

For brevity, let us denote  $S=S^\ast$ and $R=R^\ast$.
We can write 
$$
\tilde Y-Y
=S^{-1}R^\top - \tilde S^{-1}\tilde R^\top
=(S^{-1}-\tilde S^{-1}) R^\top + \tilde S^{-1}(R^\top - \tilde R^\top)
$$
From part (a) we know that $||\tilde S^{-1}||\le 1/{\phi(\delta)}$,
and so $||\tilde S^{-1}-S||\le||\tilde X-X^\ast||=\delta<\phi(\delta)\le{1}/{||\tilde S^{-1}||} $. Using Theorem~\ref{th:InverseStability}
with $A=\tilde S$, $B=S$ we get
\begin{align*}
||\tilde Y-Y^\ast||&\le ||S^{-1}-\tilde S^{-1}||\cdot|| R^\top|| + ||\tilde S^{-1}||\cdot ||R^\top - \tilde R^\top|| \\
& \le \frac{(\frac 1 {\phi(\delta)})^2\cdot \delta}{1-\frac 1 {\phi(\delta)}\cdot \delta}\cdot ||X^\ast|| + \frac{1}{\phi(\delta)}\cdot \delta
=\left[\frac{||X^\ast||}{\phi(\delta)-\delta}+1\right]\cdot\frac{\delta}{\phi(\delta)}
\end{align*}

Denote $\mathcal{Q}^\ast=\mathcal{Q}(X^\ast)$ and $\tilde{\mathcal{Q}}= \mathcal{Q}(\tilde X)$,
then $||\tilde{\mathcal{Q}}-\mathcal{Q}^\ast||\le||\mathcal{Q}||\cdot ||\tilde Y-Y^\ast||\le \psi(\delta)$.
We now conclude that $J$ is a maximal set of linearly independent columns of $\mathcal{Q}^\ast$
by the same argument as in part (a).

